(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("herodotus-2-e", [{"sp": "HDR", "t": "Ἱστοριῶν Δ· Μελπομένη", "st": "4"}, {"sp": "N", "t": "μετὰ δὲ τὴν Βαβυλῶνος αἵρεσιν ἐγένετο ἐπὶ Σκύθας αὐτοῦ Δαρείου ἔλασις· ἀνθεύσης γὰρ τῆς Ἀσίης ἀνδράσι καὶ χρημάτων μεγάλων συνιόντων, ἐπεθύμησε ὁ Δαρεῖος τίσασθαι Σκύθας, ὅτι ἐκεῖνοι πρότεροι ἐσβαλόντες ἐς τὴν Μηδικὴν καὶ νικήσαντες μάχῃ τοὺς ἀντιουμένους ὑπῆρξαν ἀδικίης. τῆς γὰρ ἄνω Ἀσίης ἦρξαν, ὡς καὶ πρότερον μοι εἴρηται, Σκύθαι ἔτεα δυῶν δέοντα τριήκοντα. Κιμμερίους γὰρ ἐπιδιώκοντες ἐσέβαλον ἐς τὴν Ἀσίην, καταπαύσαντες τῆς ἀρχῆς Μήδους· οὗτοι γὰρ πρὶν ἢ Σκύθας ἀπικέσθαι ἦρχον τῆς Ἀσίης. τοὺς δὲ Σκύθας ἀποδημήσαντας ὀκτὼ καὶ εἴκοσι ἔτεα καὶ διὰ χρόνου τοσούτου κατιόντας ἐς τὴν σφετέρην ἐξεδέξατο οὐκ ἐλάσσων πόνος τοῦ Μηδικοῦ· εὗρον γὰρ ἀντιουμένην σφίσι στρατιήν οὐκ ὀλίγην. αἱ γὰρ τῶν Σκυθέων γυναῖκες, ὥς σφι οἱ ἄνδρες ἀπῆσαν χρόνον πολλόν, ἐφοίτεον παρὰ τοὺς δούλους.", "st": "4.1"}, {"sp": "N", "t": "τοὺς δὲ δούλους οἱ Σκύθαι πάντας τυφλοῦσι τοῦ γάλακτος εἵνεκεν τοῦ πίνουσι ποιεῦντες ὧδε. ἐπεάν φυσητῆρας λάβωσι ὀστεΐνους αὐλοῖσι προσεμφερεστάτους, τούτους ἐσθέντες ἐς τῶν θηλέων ἵππων τά ἄρθρα φυσῶσι τοῖσι στόμασι, ἄλλοι δὲ ἄλλων φυσώντων ἀμέλγουσι. φασὶ δὲ τοῦδε εἵνεκα τοῦτο ποιέειν· τὰς φλέβας τε πίμπλασθαι φυσωμένας τῆς ἵππου καὶ τὸ οὖθαρ κατίεσθαι. ἐπεὰν δὲ ἀμέλξωσι τὸ γάλα, ἐσχέαντες ἐς ξύλινα ἀγγήια κοῖλα καὶ περιστίξαντες κατὰ τὰ ἀγγήια τοὺς τυφλοὺς δονέουσι τὸ γάλα, καὶ τὸ μὲν αὐτοῦ ἐπιστάμενον ἀπαρύσαντες ἡγεῦνται εἶναι τιμιώτερον, τό δ’ ὑπιστάμενον ἧσσον τοῦ ἑτέρου. τούτων μὲν εἵνεκα ἅπαντα τὸν ἂν λάβωσι οἱ Σκύθαι ἐκτυφλοῦσι. οὐ γὰρ ἀρόται εἰσὶ ἀλλὰ νομάδες.", "st": "4.2"}, {"sp": "N", "t": "ἐκ τούτων δὴ ὦν σφι τῶν δούλων καὶ τῶν γυναικῶν ἐτράφη νεότης· οἳ ἐπείτε ἔμαθον τὴν σφετέρην γένεσιν, ἠντιοῦντο αὐτοῖσι κατιοῦσι ἐκ τῶν Μήδων. καὶ πρῶτα μὲν τὴν χώρην ἀπετάμοντο, τάφρον ὀρυξάμενοι εὐρέαν κατατείνουσαν ἐκ τῶν Ταυρικῶν ὀρέων ἐς τὴν Μαιῆτιν λίμνην, τῇ περ ἐστὶ μεγίστη· μετά γε πειρωμένοισι ἐσβάλλειν τοῖσι Σκύθῃσι ἀντικατιζόμενοι ἐμάχοντο. γινομένης δὲ μάχης πολλάκις καί οὐ δυναμένων οὐδὲν πλέον ἔχειν τῶν Σκυθέων τῇ μάχῃ, εἷς αὐτῶν ἔλεξε τάδε. οἷα ποιεῦμεν, ἄνδρες Σκύθαι· δούλοισι τοῖσι ἡμετέροισι μαχόμενοι αὐτοί τε κτεινόμενοι ἐλάσσονες γινόμεθα καὶ ἐκείνους κτείνοντες ἐλασσόνων τὸ λοιπὸν ἄρξομεν. νῦν ὦν μοι δοκέει αἰχμὰς μὲν καὶ τόξα μετεῖναι, λαβόντα δὲ ἕκαστον τοῦ ἵππου τὴν μάστιγα ἰέναι ἆσσον αὐτῶν. μέχρι μὲν γὰρ ὥρων ἡμέας ὅπλα ἔχοντας, οἳ δὲ ἐνόμιζον ὅμοιοί τε καί ἐξ ὁμοίων ἡμῖν εἶναι· ἐπεὰν δὲ ἴδωνται μάστιγας ἀντὶ ὅπλων ἔχοντας, μαθόντες ὡς εἰσὶ ἡμέτεροι δοῦλοι καὶ συγγνόντες τοῦτο, οὐκ ὑπομενέουσι.", "st": "4.3"}, {"sp": "N", "t": "ταῦτα ἀκούσαντες οἱ Σκύθαι ἐποίευν ἐπιτελέα· οἳ δὲ ἐκπλαγέντες τῷ γινομένῳ τῆς μάχης τε ἐπελάθοντο καὶ ἔφευγον. οὕτω οἱ Σκύθαι τῆς τε Ἀσίης ἧρξαν καὶ ἐξελασθέντες αὖτις ὑπὸ Μήδων κατῆλθον τρόπῳ τοιούτῳ ἐς τὴν σφετέρην. τῶνδε εἵνεκα ὁ Δαρεῖυς τίσασθαι βουλόμενος συνήγειρε ἐπ’ αὐτοὺς στράτευμα.", "st": "4.4"}, {"sp": "N", "t": "ὣς δὲ Σκύθαι λέγουσι, νεώτατον πάντων ἐθνέων εἶναι τὸ σφέτερον, τοῦτο δὲ γενέσθαι ὧδε. ἄνδρα γενέσθαι πρῶτον ἐν τῇ γῇ ταύτῃ ἐούσῃ ἐρήμῳ τῳ οὔνομα εἶναι Ταργιτάον· τοῦ δὲ Ταργιτάου τούτου τοὺς τοκέας λέγουσι εἶναι, ἐμοὶ μὲν οὐ πιστὰ λέγοντες, λέγουσι δ’ ὦν, Δία τε καὶ Βορυσθένεος τοῦ ποταμοῦ θυγατέρα. γένεος μὲν τοιούτου δὴ τινος γενέσθαι τὸν Ταργιτάον, τούτου δὲ γενέσθαι παῖδας τρεῖς, Λιπόξαϊν καὶ Ἀρπόξαϊν καὶ νεώτατον Κολάξαιν. ἐπὶ τούτων ἀρχόντων ἐκ τοῦ οὐρανοῦ φερομένα χρύσεα ποιήματα, ἄροτρόν τε καὶ ζυγόν καὶ σάγαριν καὶ φιάλην, πεσεῖν ἐς τὴν Σκυθικήν· καὶ τῶν ἰδόντα πρῶτον τὸν πρεσβύτατον ἆσσον ἰέναι βουλόμενον αὐτὰ λαβεῖν, τὸν δὲ χρυσόν ἐπιόντος καίεσθαι. ἀπαλλαχθέντος δὲ τούτου προσιέναι τὸν δεύτερον, καὶ τὸν αὖτις ταὐτὰ ποιέειν. τοὺς μὲν δὴ καιόμενον τὸν χρυσὸν ἀπώσασθαι, τρίτῳ δὲ τῷ νεωτάτῳ ἐπελθόντι κατασβῆναι, καὶ μιν ἐκεῖνον κομίσαι ἐς ἑωυτοῦ· καὶ τοὺς πρεσβυτέρους ἀδελφεοὺς πρὸς ταῦτα συγγνόντας τὴν βασιληίην πᾶσαν παραδοῦναι τῷ νεωτάτῳ.", "st": "4.5"}, {"sp": "N", "t": "ἀπὸ μὲν δὴ Λιποξάιος γεγονέναι τούτους τῶν Σκυθέων οἳ Αὐχάται γένος καλέονται, ἀπὸ δὲ τοῦ μέσου Ἀρποξάιος οἳ Κατίαροί τε καὶ Τράσπιες καλέονται, ἀπὸ δὲ τοῦ νεωτάτου αὐτῶν τοῦ βασιλέος οἳ καλέονται Παραλάται· σύμπασι δὲ εἶναι οὔνομα Σκολότους, τοῦ βασιλέος ἐπωνυμίην. Σκύθας δὲ Ἕλληνες ὠνόμασαν.", "st": "4.6"}, {"sp": "N", "t": "γεγονέναι μέν νυν σφέας ὧδε λέγουσι οἱ Σκύθαι, ἔτεα δὲ σφίσι ἐπείτε γεγόνασι τὰ σύμπαντα λέγουσι εἶναι ἀπὸ τοῦ πρώτου βασιλέος Ταργιτάου ἐς τὴν Δαρείου διάβασιν τὴν ἐπὶ σφέας χιλίων οὐ πλέω ἀλλὰ τοσαῦτα. τὸν δὲ χρυσόν τοῦτον τὸν ἱρὸν φυλάσσουσι οἱ βασιλέες ἐς τὰ μάλιστα, καὶ θυσίῃσι μεγάλῃσι ἱλασκόμενοι μετέρχονται ἀνὰ πᾶν ἔτος. ὃς δ’ ἂν ἔχων τὸν χρυσὸν τὸν ἱρὸν ἐν τῇ ὁρτῇ ὑπαίθριος κατακοιμηθῇ, οὗτος λέγεται ὑπὸ Σκυθέων οὐ διενιαυτίζειν. δίδοσθαι δέ οἱ διὰ τοῦτο ὅσα ἂν ἵππῳ ἐν ἡμέρῃ μιῇ περιελάσῃ αὐτὸς. τῆς δὲ χώρης ἐούσης μεγάλης τριφασίας τὰς βασιληίας τοῖσι παισὶ τοῖσι ἑωυτοῦ καταστήσασθαι Κολάξαιν, καὶ τουτέων μίαν ποιῆσαι μεγίστην, ἐν τῇ τὸν χρυσὸν φυλάσσεσθαι. τὰ δὲ κατύπερθε πρὸς βορέην λέγουσι ἄνεμον τῶν ὑπεροίκων τῆς χώρης οὐκ οἷά τε εἶναι ἔτι προσωτέρω οὔτε ὁρᾶν οὔτε διεξιέναι ὑπὸ πτερῶν κεχυμένων· πτερῶν γὰρ καὶ τήν γῆν καὶ τὸν ἠέρα εἶναι πλέον, καὶ ταῦτα εἶναι τὰ ἀποκληίοντα τὴν ὄψιν.", "st": "4.7"}, {"sp": "N", "t": "Σκύθαι μὲν ὧδε ὕπερ σφέων τε αὐτῶν καὶ τῆς χώρης τῆς κατύπερθε λέγουσι, Ἑλλήνων δὲ οἱ τὸν Πόντον οἰκέοντες ὧδε. Ἡρακλέα ἐλαύνοντα τὰς Γηρυόνεω βοῦς ἀπικέσθαι ἐς γῆν ταύτην ἐοῦσαν ἐρήμην, ἥντινα νῦν Σκύθαι νέμονται. Γηρυόνεα δὲ οἰκέειν ἔξω τοῦ Πόντου, κατοικημένον τὴν Ἕλληνές λέγουσι Ἐρύθειαν νῆσον τὴν πρὸς Γαδείροισι τοῖσι ἔξω Ἡρακλέων στηλέων ἐπὶ τῷ Ὠκεανῷ. τὸν δὲ Ὠκεανὸν λόγῳ μὲν λέγουσι ἀπὸ ἡλίου ἀνατολέων ἀρξάμενον γῆν περὶ πᾶσαν ῥέειν, ἔργῳ δὲ οὐκ ἀποδεικνῦσι. ἐνθεῦτεν τόν Ἡρακλέα ἀπικέσθαι ἐς τὴν νῦν Σκυθίην χώρην καλεομένην, καὶ καταλαβεῖν γὰρ αὐτὸν χειμῶνα τε καὶ κρυμὸν, ἐπειρυσάμενον τὴν λεοντέην κατυπνῶσαι, τὰς δὲ οἱ ἵππους τὰς ὑπὸ τοῦ ἅρματος νεμομένας ἐν τούτῳ τῳ χρόνῳ ἀφανισθῆναι θείῃ τύχῃ.", "st": "4.8"}, {"sp": "N", "t": "ὥς δ’ ἐγερθῆναι τὸν Ἡρακλέα, δίζησθαι, πάντα δὲ τῆς χώρης ἐπεξελθόντα τέλος ἀπικέσθαι ἐς τὴν Ὑλαίην καλεομένην γῆν· ἐνθαῦτα δὲ αὐτὸν εὑρεῖν ἐν ἄντρῳ μιξοπάρθενον τινά, ἔχιδναν διφυέα, τῆς τὰ μὲν ἄνω ἀπὸ τῶν γλουτῶν εἶναι γυναικός, τὰ δὲ ἔνερθε ὄφιος. ἰδόντα δὲ καὶ θωμάσαντα ἐπειρέσθαι μιν εἴ κου ἴδοι ἵππους πλανωμένας· τὴν δὲ φάναι ἑωυτήν ἔχειν καὶ οὐκ ἀποδώσειν ἐκείνῳ πρὶν ἢ οἱ μιχθῇ· τὸν δὲ Ἡρακλέα μιχθῆναι ἐπὶ τῷ μισθῷ τούτῳ. κείνην τε δὴ ὑπερβάλλεσθαι τὴν ἀπόδοσιν τῶν ἵππων, βουλομένην ὡς πλεῖστον χρόνον συνεῖναι τῷ Ἡρακλεῖ, καὶ τὸν κομισάμενον ἐθέλειν ἀπαλλάσσεσθαι· τέλος δὲ ἀποδιδοῦσαν αὐτὴν εἰπεῖν Ἵππους μὲν δὴ ταύτας ἀπικομένας ἐνθάδε ἔσωσα τοὶ ἐγώ, σῶστρά τε σὺ παρέσχες· ἐγὼ γὰρ ἐκ σεῦ τρεῖς παῖδας ἔχω. τούτους, ἐπεὰν γένωνται τρόφιες, ὃ τι χρὴ ποιέειν, ἐξηγέο σύ, εἴτε αὐτοῦ κατοικίζω (χώρης γὰρ τῆσδε ἔχω τὸ κράτος αὕτη) εἴτε ἀποπέμπω παρὰ σέ. τὴν μὲν δὴ ταῦτα ἐπειρωτᾶν, τὸν δὲ λέγουσι πρὸς ταῦτα εἰπεῖν ἐπεὰν ἀνδρωθέντας ἴδῃ τοὺς παῖδας, τάδε ποιεῦσα οὐκ ἂν ἁμαρτάνοις· τὸν μὲν ἂν ὁρᾷς αὐτῶν τόδε τὸ τόξον ὧδε διατεινόμενον καὶ τῳ ζωστῆρι τῷδε κατὰ τάδε ζωννύμενον, τοῦτον μὲν τῆσδε τῆς χώρης οἰκήτορα ποιεῦ· ὃς δ’ ἂν τούτων τῶν ἔργων τῶν ἐντέλλομαι λείπηται, ἔκπεμπε ἐκ τῆς χώρης. καὶ ταῦτα ποιεῦσα αὐτή τε εὐφρανέαι καὶ τὰ ἐντεταλμένα ποιήσεις.", "st": "4.9"}, {"sp": "N", "t": "τὸν μὲν δὴ εἰρύσαντα τῶν τόξων τὸ ἕτερον (δύο γὰρ δὴ φορέειν τέως Ἡρακλέα) καὶ τὸν ζωστῆρα προδέξαντα, παραδοῦναι τὸ τόξον τε καὶ τὸν ζωστῆρα ἔχοντα ἐπ’ ἄκρης τῆς συμβολῆς φιάλην χρυσέην, δόντα δὲ ἀπαλλάσσεσθαι. τὴν δ’, ἐπεὶ οἱ γενομένους τοὺς παῖδας ἀνδρωθῆναι, τοῦτο μὲν σφι οὐνόματα θέσθαι, τῷ μὲν Ἀγάθυρσον αὐτῶν, τῷ δ’ ἑπομένῳ Γελωνόν, Σκύθην δὲ τῷ νεωτάτῳ, τοῦτο δὲ τῆς ἐπιστολῆς μεμνημένην αὐτὴν ποιῆσαι τά ἐντεταλμένα. καὶ δὴ δύο μὲν οἱ τῶν παίδων, τόν τε Ἀγάθυρσον καὶ τὸν Γελωνόν, οὐκ οἵους τε γενομένους ἐξικέσθαι πρὸς τὸν προκείμενον ἄεθλον, οἴχεσθαι ἐκ τῆς χώρης ἐκβληθέντας ὑπὸ τῆς γειναμένης, τὸν δὲ νεώτατον αὐτῶν Σκύθην ἐπιτελέσαντα καταμεῖναι ἐν τῇ χωρῇ. καὶ ἀπὸ μὲν Σκύθεω τοῦ Ἡρακλέος γενέσθαι τοὺς αἰεὶ βασιλέας γινομένους Σκυθέων, ἀπὸ δὲ τῆς φιάλης ἔτι καὶ ἐς τόδε φιάλας ἐκ τῶν ζωστήρων φορέειν Σκύθας· τὸ δὴ μοῦνον μηχανήσασθαι τὴν μητέρα Σκύθῃ. ταῦτα δὲ Ἑλλήνων οἱ τὸν Πόντον οἰκέοντες λέγουσι.", "st": "4.10"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλος λόγος ἔχων ὧδε, τῷ μάλιστα λεγομένῳ αὐτός πρόσκειμαι, Σκύθας τοὺς νομάδας οἰκέοντας ἐν τῇ Ἀσίῃ, πολέμῳ πιεσθέντας ὑπὸ Μασσαγετέων, οἴχεσθαι διαβάντας ποταμὸν Ἀράξην ἐπὶ γῆν τὴν Κιμμερίην (τὴν γὰρ νῦν νέμονται Σκύθαι, αὕτη λέγεται τὸ παλαιὸν εἶναι Κιμμερίων), τοὺς δὲ Κιμμερίους ἐπιόντων Σκυθέων βουλεύεσθαι ὡς στρατοῦ ἐπιόντος μεγάλου, καὶ δὴ τὰς γνώμας σφέων κεχωρισμένας, ἐντόνους μὲν ἀμφοτέρας, ἀμείνω δὲ τὴν τῶν βασιλέων· τὴν μὲν γὰρ δὴ τοῦ δήμου φέρειν γνώμην ὡς ἀπαλλάσσεσθαι πρῆγμα εἴη μηδὲ πρὸ σποδοῦ μένοντας κινδυνεύειν, τὴν δὲ τῶν βασιλέων διαμάχεσθαι περὶ τῆς χώρης τοῖσι ἐπιοῦσι. οὔκων δὴ ἐθέλειν πείθεσθαι οὔτε τοῖσι βασιλεῦσι τὸν δῆμον οὔτε τῷ δήμῳ τοὺς βασιλέας· τοὺς μὲν δὴ ἀπαλλάσσεσθαι βουλεύεσθαι ἀμαχητὶ τὴν χωρῆν παραδόντας τοῖσι ἐπιοῦσι· τοῖσι δὲ βασιλεῦσι δόξαι ἐν τῇ ἑωυτῶν κεῖσθαι ἀποθανόντας μηδὲ συμφεύγειν τῷ δήμῳ, λογισαμένους ὅσα τε ἀγαθὰ πεπόνθασι καὶ ὅσα φεύγοντας ἐκ τῆς πατρίδος κακὰ ἐπίδοξα καταλαμβάνειν. ὡς δὲ δόξαι σφι ταῦτα, διαστάντας καὶ ἀριθμὸν ἴσους γενομένους μάχεσθαι πρὸς ἀλλήλους. καὶ τοὺς μὲν ἀποθανόντας πάντας ὑπ’ ἑωυτῶν θάψαι τὸν δῆμον τῶν Κιμμερίων παρὰ ποταμὸν Τύρην (καί σφεων ἔτι δῆλος ἐστὶ ὁ τάφος), θάψαντας δὲ οὕτω τὴν ἔξοδον ἐκ τῆς χώρης ποιέεσθαι· Σκύθας δὲ ἐπελθόντας λαβεῖν τὴν χώρην ἐρήμην.", "st": "4.11"}, {"sp": "N", "t": "καὶ νῦν ἔστι μὲν ἐν τῇ Σκυθικῇ Κιμμέρια τείχεα, ἔστι δὲ πορθμήια Κιμμέρια, ἔστι δὲ καὶ χώρη οὔνομα Κιμμερίη, ἔστι δὲ Βόσπορος Κιμμέριος καλεόμενος· φαίνονται δὲ οἱ Κιμμέριοι φεύγοντες ἐς τὴν Ἀσίην τοὺς Σκύθας καὶ τὴν χερσόνησον κτίσαντες, ἐν τῇ νῦν Σινώπη πόλις Ἑλλὰς οἴκισται. φανεροὶ δὲ εἰσὶ καὶ οἱ Σκύθαι διώξαντες αὐτοὺς καὶ ἐσβαλόντες ἐς γῆν τὴν Μηδικὴν, ἁμαρτόντες τῆς ὁδοῦ· οἱ μὲν γὰρ Κιμμέριοι αἰεὶ τὴν παρὰ θάλασσαν ἔφευγον, οἱ δὲ Σκύθαι ἐν δεξιῇ τὸν Καύκασον ἔχοντες ἐδίωκον ἐς οὗ ἐσέβαλον ἐς γῆν τὴν Μηδικήν, ἐς μεσόγαιαν τῆς ὁδοῦ τραφθέντες. οὗτος δὲ ἄλλος ξυνὸς Ἑλλήνων τε καὶ βαρβάρων λεγόμενος λόγος εἴρηται.", "st": "4.12"}, {"sp": "N", "t": "ἔφη δὲ Ἀριστέης ὁ Καϋστροβίου ἀνὴρ Προκοννήσιος ποιέων ἔπεα, ἀπικέσθαι ἐς Ἰσσηδόνας φοιβόλαμπτος γενόμενος, Ἰσσηδόνων δὲ ὑπεροικέειν Ἀριμασποὺς ἄνδρας μουνοφθάλμους ὕπερ δὲ τούτων τοὺς χρυσοφύλακας γρῦπας, τούτων δὲ τοὺς Ὑπερβορέους κατήκοντας ἐπὶ θάλασσαν. τούτους ὦν πάντας πλὴν Ὑπερβορέων, ἀρξάντων Ἀριμασπῶν, αἰεὶ τοῖσι πλησιοχώροισι ἐπιτίθεσθαι, καὶ ὑπὸ μὲν Ἀριμασπῶν ἐξωθέεσθαι ἐκ τῆς χώρης Ἰσσηδόνας, ὑπὸ δὲ Ἰσσηδόνων Σκύθας, Κιμμερίους δὲ οἰκέοντας ἐπὶ τῇ νοτίῃ θαλάσσῃ ὑπὸ Σκυθέων πιεζομένους ἐκλείπειν τὴν χώρην. οὕτω οὐδὲ οὗτος συμφέρεται περὶ τῆς χώρης ταύτης Σκύθῃσι.", "st": "4.13"}, {"sp": "N", "t": "καὶ ὅθεν μὲν ἦν Ἀριστέης ὁ ταῦτα εἴπας, εἴρηκα, τὸν δὲ περὶ αὐτοῦ ἤκουον λόγον ἐν Προκοννήσῳ καί Κυζίκῳ, λέξω. Ἀριστέην γὰρ λέγουσι, ἐόντα τῶν ἀστῶν οὐδενὸς γένος ὑποδεέστερον, ἐσελθόντα ἐς κναφήιον ἐν Προκοννήσῳ ἀποθανεῖν, καὶ τόν κναφέα κατακληίσαντα τὸ ἐργαστήριον οἴχεσθαι ἀγγελέοντα τοῖσι προσήκουσι τῷ νεκρῷ. ἐσκεδασμένου δὲ ἤδη τοῦ λόγου ἀνὰ τὴν πόλιν ὡς τεθνεώς εἴη ὁ Ἀριστέης, ἐς ἀμφισβασίας τοῖσι λέγουσι ἀπικνέεσθαι ἄνδρα Κυζικηνὸν ἥκοντα ἐξ Ἀρτάκης πόλιος, φάντα συντυχεῖν τε οἱ ἰόντι ἐπὶ Κυζίκου καὶ ἐς λόγους ἀπικέσθαι. καὶ τοῦτον μὲν ἐντεταμένως ἀμφισβατέειν, τοὺς δὲ προσήκοντας τῷ νεκρῷ ἐπὶ τὸ κναφήιον παρεῖναι ἔχοντας τὰ πρόσφορα ὡς ἀναιρησομένους· ἀνοιχθέντος δὲ τοῦ οἰκήματος οὔτε τεθνεῶτα οὔτε ζῶντα φαίνεσθαι Ἀριστέην. μετὰ δὲ ἑβδόμῳ ἔτει φανέντα αὐτὸν ἐς Προκόννησον ποιῆσαι τὰ ἔπεα ταῦτα τὰ νῦν ὑπ’ Ἑλλήνων Ἀριμάσπεα καλέεται, ποιήσαντα δὲ ἀφανισθῆναι τὸ δεύτερον.", "st": "4.14"}, {"sp": "N", "t": "ταῦτα μὲν αἱ πόλιες αὗται λέγουσι, τάδε δὲ οἶδα Μεταποντίνοισι τοῖσι ἐν Ἰταλίῃ συγκυρήσαντα μετὰ τὴν ἀφάνισιν τὴν δευτέρην Ἀριστέω ἔτεσι τεσσεράκοντα καὶ διηκοσίοισι, ὡς ἐγὼ συμβαλλόμενος ἐν Προκοννήσῳ τε καὶ Μεταποντίῳ εὕρισκον. Μεταποντῖνοι φασὶ αὐτὸν Ἀριστέην φανέντα σφι ἐς τὴν χώρην κελεῦσαι βωμὸν Ἀπόλλωνος ἱδρύσασθαι καὶ Ἀριστέω τοῦ Προκοννησίου ἐπωνυμίην ἔχοντα ἀνδριάντα πὰρ’ αὐτὸν ἱστάναι· φάναι γὰρ σφι τὸν Ἀπόλλωνα Ἰταλιωτέων μούνοισι δὴ ἀπικέσθαι ἐς τὴν χώρην, καὶ αὐτὸς οἱ ἕπεσθαι ὁ νῦν ἐὼν Ἀριστέης· τότε δὲ, ὅτε εἵπετο τῷ θεῷ, εἶναι κόραξ. καὶ τὸν μὲν εἰπόντα ταῦτα ἀφανισθῆναι, σφέας δὲ Μεταποντῖνοι λέγουσι ἐς Δελφοὺς πέμψαντας τὸν θεὸν ἐπειρωτᾶν ὃ τι τὸ φάσμα τοῦ ἀνθρώπου εἴη. τὴν δὲ Πυθίην σφέας κελεύειν πείθεσθαι τῷ φάσματι, πειθομένοισι δὲ ἄμεινον συνοίσεσθαι. καὶ σφέας δεξαμένους ταῦτα ποιῆσαι ἐπιτελέα. καὶ νῦν ἔστηκε ἀνδριὰς ἐπωνυμίην ἔχων Ἀριστέω παρ’ αὐτῷ τῷ ἀγάλματι τοῦ Ἀπόλλωνος, πέριξ δὲ αὐτὸν δάφναι ἑστᾶσι· τὸ δὲ ἄγαλμα ἐν τῇ ἀγορῇ ἵδρυται. Ἀριστέω μέν νυν πέρι τοσαῦτα εἰρήσθω.", "st": "4.15"}, {"sp": "N", "t": "τῆς δὲ γῆς, τῆς πέρι ὅδε ὁ λόγος ὅρμηται λέγεσθαι, οὐδεὶς οἶδε ἀτρεκέως ὃ τι τὸ κατύπερθε ἐστί· οὐδενὸς γὰρ δὴ αὐτόπτεω εἰδέναι φαμένου δύναμαι πυθέσθαι· οὐδὲ γὰρ οὐδὲ Ἀριστέης, τοῦ περ ὀλίγῳ πρότερον τούτων μνήμην ἐποιεύμην, οὐδὲ οὗτος προσωτέρω Ἰσσηδόνων ἐν αὐτοῖσι τοῖσι ἔπεσι ποιέων ἔφησε ἀπικέσθαι, ἀλλὰ τὰ κατύπερθε ἔλεγε ἀκοῇ, φὰς Ἰσσηδόνας εἶναι τοὺς ταῦτα λέγοντας. ἀλλ’ ὅσον μὲν ἡμεῖς ἀτρεκέως ἐπὶ μακρότατον οἷοι τε ἐγενόμεθα ἀκοῇ ἐξικέσθαι, πᾶν εἰρήσεται.", "st": "4.16"}, {"sp": "N", "t": "ἀπὸ τοῦ Βορυσθενειτέων ἐμπορίου (τοῦτο γὰρ τῶν παραθαλασσίων μεσαίτατον ἐστὶ πάσης τῆς Σκυθίης), ἀπὸ τούτου πρῶτοι Καλλιππίδαι νέμονται ἐόντες Ἕλληνές Σκύθαι, ὕπερ δὲ τούτων ἄλλο ἔθνος οἳ Ἀλαζόνες καλέονται. οὗτοι δὲ καὶ οἱ Καλλιππίδαι τὰ μὲν ἄλλα κατὰ ταὐτὰ Σκύθῃσι ἐπασκέουσι, σῖτον δὲ καὶ σπείρουσι καὶ σιτέονται, καὶ κρόμμυα καὶ σκόροδα καὶ φακούς καὶ κέγχρους. ὕπερ δὲ Ἀλαζόνων οἰκέουσι Σκύθαι ἀροτῆρες, οἳ οὐκ ἐπὶ σιτήσι σπείρουσι τὸν σῖτον ἀλλ’ ἐπὶ πρήσι.", "st": "4.17"}, {"sp": "N", "t": "τούτων δὲ κατύπερθε οἰκέουσι Νευροί. Νευρῶν δὲ τὸ πρὸς βορέην ἄνεμον ἔρημον ἀνθρώπων, ὅσον ἡμεῖς ἴδμεν. ταῦτα μὲν παρὰ τὸν Ὕπανιν ποταμὸν ἐστι ἔθνεα πρὸς ἑσπέρης τοῦ Βορυσθένεος· ἀτὰρ διαβάντι τὸν Βορυσθένεα ἀπὸ θαλάσσης πρῶτον μὲν ᾗ Ὑλαίη, ἀπὸ δὲ ταύτης ἄνω ἰόντι οἰκέουσι Σκύθαι γεωργοί, τοὺς Ἕλληνές οἱ οἰκέοντες ἐπὶ τῷ Ὑπάνι ποταμῷ καλέουσι Βορυσθενεΐτας, σφέας δὲ αὐτοὺς Ὀλβιοπολίτας. οὗτοι ὦν οἱ γεωργοὶ Σκύθαι νέμονται τὸ μὲν πρὸς τὴν ἠῶ ἐπὶ τρεῖς ἡμέρας ὁδοῦ, κατήκοντες ἐπὶ ποταμὸν τῷ οὔνομα κεῖται Παντικάπης, τὸ δὲ πρὸς βορέην ἄνεμον πλόον ἀνὰ τὸν Βορυσθένεα ἡμερέων ἕνδεκα. ἤδη δὲ κατύπερθε τούτων ἡ ἔρημος ἐστὶ ἐπὶ πολλὸν. μετὰ δὲ τὴν ἔρημον Ἀνδροφάγοι οἰκέουσι, ἔθνος ἐὸν ἴδιον καὶ οὐδαμῶς Σκυθικόν. τὸ δὲ τούτων κατύπερθε ἔρημον ἤδη ἀληθέως καὶ ἔθνος ἀνθρώπων οὐδέν, ὅσον ἡμεῖς ἴδμεν.", "st": "4.18"}, {"sp": "N", "t": "τὸ δὲ πρὸς τὴν ἠῶ τῶν γεωργῶν τούτων Σκυθέων, διαβάντι τὸν Παντικάπην ποταμόν, νομάδες ἤδη Σκύθαι νέμονται, οὔτε τι σπείροντες οὐδέν οὔτε ἀροῦντες· ψιλή δέ δενδρέων ἡ πᾶσα αὕτη πλήν τῆς Ὑλαίης. οἱ δὲ νομάδες οὗτοι τὸ πρὸς τὴν ἠῶ ἡμερέων τεσσέρων καὶ δέκα ὁδὸν νέμονται χώρην κατατείνουσαν ἐπὶ ποταμὸν Γέρρον.", "st": "4.19"}, {"sp": "N", "t": "πέρην δὲ τοῦ Γέρρου ταῦτα δὴ τὰ καλεύμενα βασιλήια ἐστὶ καὶ Σκύθαι οἱ ἄριστοί τε καὶ πλεῖστοι καὶ τοὺς ἄλλους νομίζοντες Σκύθας δούλους σφετέρους εἶναι· κατήκουσι δὲ οὗτοι τὸ μὲν πρὸς μεσαμβρίην ἐς τὴν Ταυρικήν, τὸ δὲ πρὸς ἠῶ ἐπί τε τάφρον, τὴν δὴ οἱ ἐκ τῶν τυφλῶν γενόμενοι ὤρυξαν, καὶ ἐπὶ τῆς λίμνης τῆς Μαιήτιδος τὸ ἐμπόριον τὸ καλέεται Κρημνοί· τὰ δὲ αὐτῶν κατήκουσι ἐπὶ ποταμὸν Τάναϊν. τὰ δὲ κατύπερθε πρὸς βορέην ἄνεμον τῶν βασιληίων Σκυθέων οἰκέουσι Μελάγχλαινοι, ἄλλο ἔθνος καὶ οὐ Σκυθικὸν. Μελαγχλαίνων δὲ τὸ κατύπερθε λίμναι καὶ ἔρημος ἐστὶ ἀνθρώπων, κατ’ ὅσον ἡμεῖς ἴδμεν.", "st": "4.20"}, {"sp": "N", "t": "Τάναϊν δὲ ποταμὸν διαβάντι οὐκέτι Σκυθική, ἀλλ’ ἡ μὲν πρώτη τῶν λαξίων Σαυροματέων ἐστί, οἳ ἐκ τοῦ μυχοῦ ἀρξάμενοι τῆς Μαιήτιδος λίμνης νέμονται τὸ πρὸς βορέην ἄνεμον ἡμερέων πεντεκαίδεκα ὁδόν, πᾶσαν ἐοῦσαν ψιλὴν καὶ ἀγρίων καὶ ἡμέρων δενδρέων· ὑπεροικέουσι δὲ τούτων δευτέρην λάξιν ἔχοντες Βουδῖνοι, γῆν νεμόμενοι πᾶσαν δασέαν ὕλῃ παντοίῃ.", "st": "4.21"}, {"sp": "N", "t": "Βουδίνων δὲ κατύπερθε πρὸς βορέην ἐστὶ πρώτη μὲν ἔρημος ἐπ’ ἡμερέων ἑπτὰ ὁδόν, μετὰ δὲ τὴν ἔρημον ἀποκλίνοντι μᾶλλον πρὸς ἀπηλιώτην ἄνεμον νέμονται Θυσσαγέται, ἔθνος πολλὸν καὶ ἴδιον· ζῶσι δὲ ἀπὸ θήρης. συνεχέες δὲ τούτοισι ἐν τοῖσι αὐτοῖσι τόποισι κατοικημένοι εἰσὶ τοῖσι οὔνομα κεῖται Ἰύρκαι, καὶ οὗτοι ἀπὸ θήρης ζῶντες τρόπῳ τοιῷδε· λοχᾷ ἐπὶ δένδρεον ἀναβάς, τὰ δὲ ἐστὶ πυκνὰ ἀνὰ πᾶσαν τὴν χώρην· ἵππος δὲ ἑκάστῳ δεδιδαγμένος ἐπὶ γαστέρα κεῖσθαι ταπεινότητος εἵνεκα ἕτοιμος ἐστὶ καὶ κύων· ἐπεὰν δὲ ἀπίδῃ τὸ θηρίον ἀπὸ τοῦ δενδρέου, τοξεύσας ἐπιβὰς ἐπὶ τὸν ἵππον διώκει, καὶ ὁ κύων ἔχεται, ὑπὲρ δὲ τούτων τὸ πρὸς τὴν ἠῶ ἀποκλίνοντι οἰκέουσι Σκύθαι ἄλλοι, ἀπὸ τῶν βασιληίων Σκυθέων ἀποστάντες καὶ οὕτω ἀπικόμενοι ἐς τοῦτον τὸν χῶρον.", "st": "4.22"}, {"sp": "N", "t": "μέχρι μὲν δὴ τῆς τούτων τῶν Σκυθέων χώρης ἐστὶ ἡ καταλεχθεῖσα πᾶσα πεδιάς τε γῆ καὶ βαθύγαιος, τὸ δ’ ἀπὸ τούτου λιθώδης τ’ ἐστὶ καὶ τρηχέα. διεξελθόντι δὲ καὶ τῆς τρηχέης χώρης πολλὸν οἰκέουσι ὑπώρεαν ὀρέων ὑψηλῶν ἄνθρωποι λεγόμενοι εἶναι πάντες φαλακροὶ ἐκ γενετῆς γινόμενοι, καὶ ἔρσενες καὶ θήλεαι ὁμοίως, καὶ σιμοὶ καὶ γένεια ἔχοντες μεγάλα, φωνὴν δὲ ἰδίην ἱέντες, ἐσθῆτι δὲ χρεώμενοι Σκυθικῇ, ζῶντες δὲ ἀπὸ δενδρέων. ποντικὸν μὲν οὔνομα τῷ δενδρέῳ ἀπ’ οὗ ζῶσι, μέγαθος δὲ κατὰ συκέην μάλιστά κῃ. καρπὸν δὲ φορέει κυάμῳ ἴσον, πυρῆνα δὲ ἔχει. τοῦτο ἐπεὰν γένηται πέπον, σακκέουσι ἱματίοισι, ἀπορρέει δὲ ἀπ’ αὐτοῦ παχὺ καὶ μέλαν· οὔνομα δὲ τῷ ἀπορρέοντι ἐστὶ ἄσχυ· τοῦτο καὶ λείχουσι καὶ γάλακτι συμμίσγοντες πίνουσι, καὶ ἀπὸ τῆς παχύτητος αὐτοῦ τῆς τρυγὸς παλάθας συντιθεῖσι καὶ ταύτας σιτέονται. πρόβατα γάρ σφι οὐ πολλά ἐστι. οὐ γάρ τι σπουδαῖαι αἱ νομαὶ αὐτόθι εἰσί. ὑπὸ δενδρέῳ δὲ ἕκαστος κατοίκηται, τὸν μὲν χειμῶνα ἐπεὰν τὸ δένδρεον περικαλύψῃ πίλῳ στεγνῷ λευκῷ, τὸ δὲ θέρος ἄνευ πίλου. τούτους οὐδεὶς ἀδικέει ἀνθρώπων· ἱροὶ γὰρ λέγονται εἶναι· οὐδέ τι ἀρήιον ὅπλον ἐκτέαται. καὶ τοῦτο μὲν τοῖσι περιοικέουσι οὗτοι εἰσὶ οἱ τὰς διαφορὰς διαιρέοντες, τοῦτο δὲ ὃς ἂν φεύγων καταφύγῃ ἐς τούτους, ὑπ’ οὐδενὸς ἀδικέεται· οὔνομα δέ σφι ἐστὶ Ἀργιππαῖοι.", "st": "4.23"}, {"sp": "N", "t": "μέχρι μέν νυν τῶν φαλακρῶν τούτων πολλὴ περιφανείη τῆς χώρης ἐστὶ καὶ τῶν ἔμπροσθε ἐθνέων· καὶ γὰρ Σκυθέων τινὲς ἀπικνέονται ἐς αὐτούς, τῶν οὐ χαλεπόν ἐστι πυθέσθαι καὶ Ἑλλήνων τῶν ἐκ Βορυσθένεος τε ἐμπορίου καὶ τῶν ἄλλων Ποντικῶν ἐμπορίων· Σκυθέων δὲ οἳ ἂν ἔλθωσι ἐς αὐτούς, δι’ ἑπτὰ ἑρμηνέων καὶ δι’ ἑπτὰ γλωσσέων διαπρήσσονται.", "st": "4.24"}, {"sp": "N", "t": "μέχρι μὲν δὴ τούτων γινώσκεται, τὸ δὲ τῶν φαλακρῶν κατύπερθε οὐδεὶς ἀτρεκέως οἶδε φράσαι. ὄρεα γὰρ ὑψηλὰ ἀποτάμνει ἄβατα καὶ οὐδείς σφεα ὑπερβαίνει. οἱ δὲ φαλακροὶ οὗτοι λέγουσι, ἐμοὶ μὲν οὐ πιστὰ λέγοντες, οἰκέειν τὰ ὄρεα αἰγίποδας ἄνδρας, ὑπερβάντι δὲ τούτους ἀνθρώπους ἄλλους οἳ τὴν ἑξάμηνον κατεύδουσι. τοῦτο δὲ οὐκ ἐνδέκομαι τὴν ἀρχήν, ἀλλὰ τὸ μὲν πρὸς ἠῶ τῶν φαλακρῶν γινώσκεται ἀτρεκέως ὑπὸ Ἰσσηδόνων οἰκεόμενον, τὸ μέντοι κατύπερθε πρὸς βορέην ἄνεμον οὐ γινώσκεται οὔτε τῶν φαλακρῶν οὔτε τῶν Ἰσσηδόνων, εἰ μὴ ὅσα αὐτῶν τούτων λεγόντων.", "st": "4.25"}, {"sp": "N", "t": "νόμοισι δὲ Ἰσσηδόνες τοῖσιδε λέγονται χρᾶσθαι. ἐπεὰν ἀνδρὶ ἀποθάνῃ πατήρ, οἱ προσήκοντες πάντες προσάγουσι πρόβατα, καὶ ἔπειτα ταῦτα θύσαντες καὶ καταταμόντες τὰ κρέα κατατάμνουσι καὶ τὸν τοῦ δεκομένου τεθνεῶτα γονέα, ἀναμίξαντες δὲ πάντα τὰ κρέα δαῖτα προτίθενται· τὴν δὲ κεφαλὴν αὐτοῦ ψιλώσαντες καὶ ἐκκαθήραντες καταχρυσοῦσι καὶ ἔπειτα ἅτε ἀγάλματι χρέωνται, θυσίας μεγάλας ἐπετείους ἐπιτελέοντες. παῖς δὲ πατρὶ τοῦτο ποιέει, κατά περ Ἕλληνες τὰ γενέσια. ἄλλως δὲ δίκαιοι καὶ οὗτοι λέγονται εἶναι, ἰσοκρατέες δὲ ὁμοίως αἱ γυναῖκες τοῖσι ἀνδράσι.", "st": "4.26"}, {"sp": "N", "t": "γινώσκονται μὲν δὴ καὶ οὗτοι, τὸ δὲ ἀπὸ τούτων τὸ κατύπερθε Ἰσσηδόνες εἰσὶ οἱ λέγοντες μουνοφθάλμους ἀνθρώπους καὶ χρυσοφύλακας γρῦπας εἶναι· παρὰ δὲ τούτων Σκύθαι παραλαβόντες λέγουσι, παρὰ δὲ Σκυθέων ἡμεῖς οἱ ἄλλοι νενομίκαμεν καὶ ὀνομάζομεν αὐτοὺς σκυθιστὶ Ἀριμασπούς· ἄριμα γὰρ ἓν καλέουσι Σκύθαι, σποῦ δὲ ὀφθαλμόν.", "st": "4.27"}, {"sp": "N", "t": "δυσχείμερος δὲ αὕτη ἡ καταλεχθεῖσα πᾶσα χώρη οὕτω δή τι ἐστί, ἔνθα τοὺς μὲν ὀκτὼ τῶν μηνῶν ἀφόρητος οἷος γίνεται κρυμός, ἐν τοῖσι ὕδωρ ἐκχέας πηλὸν οὐ ποιήσεις, πῦρ δὲ ἀνακαίων ποιήσεις πηλόν· ἡ δὲ θάλασσα πήγνυται καὶ ὁ Βόσπορος πᾶς ὁ Κιμμέριος, καὶ ἐπὶ τοῦ κρυστάλλου οἱ ἐντὸς τάφρου Σκύθαι κατοικημένοι στρατεύονται καὶ τὰς ἁμάξας ἐπελαύνουσι πέρην ἐς τοὺς Σίνδους. οὕτω μὲν δὴ τοὺς ὀκτὼ μῆνας διατελέει χειμὼν ἐών, τοὺς δ’ ἐπιλοίπους τέσσερας ψύχεα αὐτόθι ἐστί. κεχώρισται δὲ οὗτος ὁ χειμὼν τοὺς τρόπους πᾶσι τοῖσι ἐν ἄλλοισι χωρίοισι γινομένοισι χειμῶσι, ἐν τῷ τὴν μὲν ὡραίην οὐκ ὕει λόγου ἄξιον οὐδέν, τὸ δὲ θέρος ὕων οὐκ ἀνιεῖ· βρονταί τε ἦμος τῇ ἄλλῃ γίνονται, τηνικαῦτα μὲν οὐ γίνονται, θέρεος δὲ ἀμφιλαφέες· ἢν δὲ χειμῶνος βροντὴ γένηται, ὡς τέρας νενόμισται θωμάζεσθαι. ὣς δὲ καὶ ἢν σεισμὸς γένηται ἤν τε θέρεος ἤν τε χειμῶνος ἐν τῇ Σκυθικῇ, τέρας νενόμισται. ἵπποι δὲ ἀνεχόμενοι φέρουσι τὸν χειμῶνα τοῦτον, ἡμίονοι δὲ οὐδὲ ὄνοι οὐκ ἀνέχονται ἀρχήν· τῇ δὲ ἄλλῃ ἵπποι μὲν ἐν κρυμῷ ἑστεῶτες ἀποσφακελίζουσι, ὄνοι δὲ καὶ ἡμίονοι ἀνέχονται.", "st": "4.28"}, {"sp": "N", "t": "δοκέει δέ μοι καὶ τὸ γένος τῶν βοῶν τὸ κόλον διὰ ταῦτα οὐ φύειν κέρεα αὐτόθι· μαρτυρέει δέ μοι τῇ γνώμῃ καὶ Ὁμήρου ἔπος ἐν Ὀδυσσείῃ ἔχον ὧδε,", "st": "4.29"}, {"sp": "N", "t": "καὶ Λιβύην, ὅθι τ’ ἄρνες ἄφαρ κεραοὶ τελέθουσι,", "st": "4.29b"}, {"sp": "N", "t": "ὀρθῶς εἰρημένον, ἐν τοῖσι θερμοῖσι ταχὺ παραγίνεσθαι τὰ κέρεα, ἐν δὲ τοῖσι ἰσχυροῖσι ψύχεσι ἢ οὐ φύειν κέρεα τὰ κτήνεα ἀρχὴν ἡ φύοντα φύειν μόγις.", "st": "4.29c"}, {"sp": "N", "t": "ἐνθαῦτα μέν νυν διὰ τὰ ψύχεα γίνεται ταῦτα. θωμάζω δέ (προσθήκας γὰρ δή μοι ὁ λόγος ἐξ ἀρχῆς ἐδίζητο) ὅτι ἐν τῇ Ἠλείῃ πάσῃ χώρῃ οὐ δυνέαται γίνεσθαι ἡμίονοι, οὔτε ψυχροῦ τοῦ χώρου ἐόντος οὔτε ἄλλου φανεροῦ αἰτίου οὐδενός. φασὶ δὲ αὐτοὶ Ἠλεῖοι ἐκ κατάρης τευ οὐ γίνεσθαι σφίσι ἡμιόνους, ἀλλ’ ἐπεὰν προσίῃ ἡ ὥρη κυΐσκεσθαι τὰς ἵππους, ἐξελαύνουσι ἐς τοὺς πλησιοχώρους αὐτάς, καὶ ἔπειτά σφι ἐν τῇ τῶν πέλας ἐπιεῖσι τοὺς ὄνους, ἐς οὗ ἂν σχῶσι αἱ ἵπποι ἐν γαστρί· ἔπειτα δὲ ἀπελαύνουσι.", "st": "4.30"}, {"sp": "N", "t": "περὶ δὲ τῶν πτερῶν τῶν Σκύθαι λέγουσι ἀνάπλεον εἶναι τὸν ἠέρα, καὶ τούτων εἵνεκα οὐκ οἷοί τε εἶναι οὔτε ἰδεῖν τὸ πρόσω τῆς ἠπείρου οὔτε διεξιέναι, τήνδε ἔχω περὶ αὐτῶν γνώμην· τὰ κατύπερθε ταύτης τῆς χώρης αἰεὶ νίφεται, ἐλάσσονι δὲ τοῦ θέρεος ἢ τοῦ χειμῶνος, ὥσπερ καὶ οἰκός. ἤδη ὦν ὅστις ἀγχόθεν χιόνα ἁδρὴν πίπτουσαν εἶδε οἶδε τὸ λέγω· ἔοικε γὰρ ἡ χιὼν πτεροῖσι καὶ διὰ τὸν χειμῶνα τοῦτον ἐόντα τοιοῦτον ἀνοίκητα τὰ πρὸς βορέην ἐστὶ τῆς ἠπείρου ταύτης. τὰ ὦν πτερὰ εἰκάζοντας τὴν χιόνα τοὺς Σκύθας τε καὶ τοὺς περιοίκους δοκέω λέγειν. ταῦτα μέν νυν τὰ λέγεται μακρότατα εἴρηται.", "st": "4.31"}, {"sp": "N", "t": "Ὑπερβορέων δὲ πέρι ἀνθρώπων οὔτε τι Σκύθαι λέγουσι οὐδὲν οὔτε τινὲς ἄλλοι τῶν ταύτῃ οἰκημένων, εἰ μὴ ἄρα Ἰσσηδόνες. ὡς δὲ ἐγὼ δοκέω, οὐδ’ οὗτοι λέγουσι οὐδέν· ἔλεγον γὰρ ἂν καὶ Σκύθαι, ὡς περὶ τῶν μουνοφθάλμων λέγουσι. ἀλλ’ Ἡσιόδῳ μὲν ἐστὶ περὶ Ὑπερβορέων εἰρημένα, ἔστι δὲ καὶ Ὁμήρῳ ἐν Ἐπιγόνοισι, εἰ δὴ τῷ ἐόντι γε Ὅμηρος ταῦτα τὰ ἔπεα ἐποίησε.", "st": "4.32"}, {"sp": "N", "t": "πολλῷ δέ τι πλεῖστα περὶ αὐτῶν Δήλιοι λέγουσι, φάμενοι ἱρὰ ἐνδεδεμένα ἐν καλάμῃ πυρῶν ἐξ Ὑπερβορέων φερόμενα ἀπικνέεσθαι ἐς Σκύθας, ἀπὸ δὲ Σκυθέων ἤδη δεκομένους αἰεὶ τοὺς πλησιοχώρους ἑκάστους κομίζειν αὐτὰ τὸ πρὸς ἑσπέρης ἑκαστάτω ἐπὶ τὸν Ἀδρίην, ἐνθεῦτεν δὲ πρὸς μεσαμβρίην προπεμπόμενα πρώτους Δωδωναίους Ἑλλήνων δέκεσθαι, ἀπὸ δὲ τούτων καταβαίνειν ἐπὶ τὸν Μηλιέα κόλπον καὶ διαπορεύεσθαι ἐς Εὔβοιαν, πόλιν τε ἐς πόλιν πέμπειν μέχρι Καρύστου, τὸ δ’ ἀπὸ ταύτης ἐκλιπεῖν Ἄνδρον· Καρυστίους γὰρ εἶναι τοὺς κομίζοντας ἐς Τῆνον, Τηνίους δὲ ἐς Δῆλον. ἀπικνέεσθαι μέν νυν οὕτω ταῦτα τὰ ἱρὰ λέγουσι ἐς Δῆλον· πρῶτον δὲ τοὺς Ὑπερβορέους πέμψαι φερούσας τὰ ἱρὰ δύο κόρας, τὰς ὀνομάζουσι Δήλιοι εἶναι Ὑπερόχην τε καὶ Λαοδίκην· ἅμα δὲ αὐτῇσι ἀσφαλείης εἵνεκεν πέμψαι τοὺς Ὑπερβορέους τῶν ἀστῶν ἄνδρας πέντε πομπούς, τούτους οἳ νῦν Περφερέες καλέονται τιμὰς μεγάλας ἐν Δήλῳ ἔχοντες. ἐπεὶ δὲ τοῖσι Ὑπερβορέοισι τοὺς ἀποπεμφθέντας ὀπίσω οὐκ ἀπονοστέειν, δεινὰ ποιευμένους εἰ σφέας αἰεὶ καταλάμψεται ἀποστέλλοντας μὴ ἀποδέκεσθαι, οὕτω δὴ φέροντας ἐς τοὺς οὔρους τὰ ἱρὰ ἐνδεδεμένα ἐν πυρῶν καλάμῃ τοὺς πλησιοχώρους ἐπισκήπτειν κελεύοντας προπέμπειν σφέα ἀπὸ ἑωυτῶν ἐς ἄλλο ἔθνος. καὶ ταῦτα μὲν οὕτω προπεμπόμενα ἀπικνέεσθαι λέγουσι ἐς Δῆλον. οἶδα δὲ αὐτὸς τούτοισι τοῖσι ἱροῖσι τόδε ποιεύμενον προσφερές, τὰς Θρηικίας καὶ τὰς Παιονίδας γυναῖκας, ἐπεὰν θύωσι τῇ Ἀρτέμιδι τῇ βασιλείῃ, οὐκ ἄνευ πυρῶν καλάμης ἐχούσας τὰ ἱρά.", "st": "4.33"}, {"sp": "N", "t": "καὶ ταῦτα μὲν δὴ ταύτας οἶδα ποιεύσας· τῇσι δὲ παρθένοισι ταύτῃσι τῇσι ἐξ Ὑπερβορέων τελευτησάσῃσι ἐν Δήλῳ κείρονται καὶ αἱ κόραι καὶ οἱ παῖδες οἱ Δηλίων· αἱ μὲν πρὸ γάμου πλόκαμον ἀποταμνόμεναι καὶ περὶ ἄτρακτον εἱλίξασαι ἐπὶ τὸ σῆμα τιθεῖσι (τὸ δὲ σῆμα ἐστὶ ἔσω ἐς τὸ Ἀρτεμίσιον ἐσιόντι ἀριστερῆς χειρός, ἐπιπέφυκε δέ οἱ ἐλαίη), ὅσοι δὲ παῖδες τῶν Δηλίων, περὶ χλόην τινὰ εἱλίξαντες τῶν τριχῶν τιθεῖσι καὶ οὗτοι ἐπὶ τὸ σῆμα.", "st": "4.34"}, {"sp": "N", "t": "αὗται μὲν δὴ ταύτην τιμὴν ἔχουσι πρὸς τῶν Δήλου οἰκητόρων. φασὶ δὲ οἱ αὐτοὶ οὗτοι καὶ τὴν Ἄργην τε καὶ τὴν Ὦπιν ἐούσας παρθένους ἐξ Ὑπερβορέων κατὰ τοὺς αὐτοὺς τούτους ἀνθρώπους πορευομένας ἀπικέσθαι ἐς Δῆλον ἔτι πρότερον Ὑπερόχης τε καὶ Λαοδίκης. ταύτας μέν νυν τῇ Εἰλειθυίῃ ἀποφερούσας ἀντὶ τοῦ ὠκυτόκου τὸν ἐτάξαντο φόρον ἀπικέσθαι, τὴν δὲ Ἄργην τε καὶ τὴν Ὦπιν ἅμα αὐτοῖσι θεοῖσι ἀπικέσθαι λέγουσι καὶ σφι τιμὰς ἄλλας δεδόσθαι πρὸς σφέων· καὶ γὰρ ἀγείρειν σφι τὰς γυναῖκας ἐπονομαζούσας τὰ οὐνόματα ἐν τῷ ὕμνῳ τόν σφι Ὠλὴν ἀνὴρ Λύκιος ἐποίησε, παρὰ δὲ σφέων μαθόντας νησιώτας τε καὶ Ἴωνας ὑμνέειν Ὦπίν τε καὶ Ἄργην ὀνομάζοντάς τε καὶ ἀγείροντας (οὗτος δὲ ὁ Ὠλὴν καὶ τοὺς ἄλλους τοὺς παλαιοὺς ὕμνους ἐποίησε ἐκ Λυκίης ἐλθὼν τοὺς ἀειδομένους ἐν Δήλῳ), καὶ τῶν μηρίων καταγιζομένων ἐπὶ τῷ βωμῷ τὴν σποδὸν ταύτην ἐπὶ τὴν θήκην τῆς Ὤπιός τε καὶ Ἄργης ἀναισιμοῦσθαι ἐπιβαλλομένην. ἡ δὲ θήκη αὐτέων ἐστὶ ὄπισθε τοῦ Ἀρτεμισίου, πρὸς ἠῶ τετραμμένη, ἀγχοτάτω τοῦ Κηίων ἱστιητορίου.", "st": "4.35"}, {"sp": "N", "t": "καὶ ταῦτα μὲν Ὑπερβορέων πέρι εἰρήσθω· τὸν γὰρ περὶ Ἀβάριος λόγον τοῦ λεγομένου εἶναι Ὑπερβορέου οὐ λέγω, ὡς τὸν ὀιστὸν περιέφερε κατὰ πᾶσαν γῆν οὐδὲν σιτεόμενος. εἰ δὲ εἰσὶ ὑπερβόρεοι τινὲς ἄνθρωποι, εἰσὶ καὶ ὑπερνότιοι ἄλλοι. γελῶ δὲ ὁρέων γῆς περιόδους γράψαντας πολλοὺς ἤδη καὶ οὐδένα νοονεχόντως ἐξηγησάμενον· οἳ Ὠκεανόν τε ῥέοντα γράφουσι πέριξ τὴν γῆν ἐοῦσαν κυκλοτερέα ὡς ἀπὸ τόρνου, καὶ τὴν Ἀσίην τῇ Εὐρώπῃ ποιεύντων ἴσην. ἐν ὀλίγοισι γὰρ ἐγὼ δηλώσω μέγαθός τε ἑκάστης αὐτέων καὶ οἵη τις ἐστὶ ἐς γραφὴν ἑκάστη.", "st": "4.36"}, {"sp": "N", "t": "Πέρσαι οἰκέουσι κατήκοντες ἐπὶ τὴν νοτίην θάλασσαν τὴν Ἐρυθρὴν καλεομένην, τούτων δὲ ὑπεροικέουσι πρὸς βορέην ἄνεμον Μῆδοι, Μήδων δὲ Σάσπειρες, Σασπείρων δὲ Κόλχοι κατήκοντες ἐπὶ τὴν βορηίην θάλασσαν, ἐς τὴν Φᾶσις ποταμὸς ἐκδιδοῖ. ταῦτα τέσσερα ἔθνεα οἰκέει ἐκ θαλάσσης ἐς θάλασσαν.", "st": "4.37"}, {"sp": "N", "t": "ἐνθεῦτεν δὲ τὸ πρὸς ἑσπέρης ἀκταὶ διφάσιαι ἀπ’ αὐτῆς κατατείνουσι ἐς θάλασσαν, τὰς ἐγὼ ἀπηγήσομαι· ἔνθεν μὲν ἡ ἀκτὴ ἡ ἑτέρη τὰ πρὸς βορέην ἀπὸ Φάσιος ἀρξαμένη παρατέταται ἐς θάλασσαν παρά τε τὸν Πόντον καὶ τὸν Ἑλλήσποντον μέχρι Σιγείου τοῦ Τρωικοῦ· τὰ δὲ πρὸς νότου ἡ αὐτὴ αὕτη ἀκτὴ ἀπὸ τοῦ Μυριανδικοῦ κόλπου τοῦ πρὸς Φοινίκῃ κειμένου τείνει τὰ ἐς θάλασσαν μέχρι Τριοπίου ἄκρης. οἰκέει δὲ ἐν τῇ ἀκτῇ ταύτῃ ἔθνεα ἀνθρώπων τριήκοντα.", "st": "4.38"}, {"sp": "N", "t": "αὕτη μέν νυν ἡ ἑτέρη τῶν ἀκτέων, ἡ δὲ δὴ ἑτέρη ἀπὸ Περσέων ἀρξαμένη παρατέταται ἐς τὴν Ἐρυθρὴν θάλασσαν, ἥ τε Περσικὴ καὶ ἀπὸ ταύτης ἐκδεκομένη ἡ Ἀσσυρίη καὶ ἀπὸ Ἀσσυρίης ἡ Ἀραβίη· λήγει δὲ αὕτη, οὐ λήγουσα εἰ μὴ νόμῳ, ἐς τὸν κόλπον τὸν Ἀράβιον, ἐς τὸν Δαρεῖος ἐκ τοῦ Νείλου διώρυχα ἐσήγαγε. μέχρι μέν νυν Φοινίκης ἀπὸ Περσέων χῶρος πλατὺς καὶ πολλός ἐστι· τὸ δὲ ἀπὸ Φοινίκης παρήκει διὰ τῆσδε τῆς θαλάσσης ἡ ἀκτὴ αὕτη παρά τε Συρίην τὴν Παλαιστίνην καὶ Αἴγυπτον, ἐς τὴν τελευτᾷ· ἐν τῇ ἔθνεα ἐστὶ τρία μοῦνα.", "st": "4.39"}, {"sp": "N", "t": "ταῦτα μὲν ἀπὸ Περσέων τὰ πρὸς ἑσπέρην τῆς Ἀσίης ἔχοντα ἐστί· τὰ δὲ κατύπερθε Περσέων καὶ Μήδων καὶ Σασπείρων καὶ Κόλχων, τὰ πρὸς ἠῶ τε καὶ ἥλιον ἀνατέλλοντα, ἔνθεν μὲν ἡ Ἐρυθρὴ παρήκει θάλασσα, πρὸς βορέω δὲ ἡ Κασπίη τε θάλασσα καὶ ὁ Ἀράξης ποταμός, ῥέων πρὸς ἥλιον ἀνίσχοντα. μέχρι δὲ τῆς Ἰνδικῆς οἰκέεται Ἀσίη· τὸ δὲ ἀπὸ ταύτης ἔρημος ἤδη τὸ πρὸς τὴν ἠῶ, οὐδὲ ἔχει οὐδεὶς φράσαι οἷον δή τι ἐστί.", "st": "4.40"}, {"sp": "N", "t": "τοιαύτη μὲν καὶ τοσαύτη ἡ Ἀσίη ἐστί, ἡ δὲ Λιβύη ἐν τῇ ἀκτῇ τῇ ἑτέρῃ ἐστί· ἀπὸ γὰρ Αἰγύπτου Λιβύη ἤδη ἐκδέκεται. κατὰ μέν νυν Αἴγυπτον ἡ ἀκτὴ αὕτη στεινή ἐστι· ἀπὸ γὰρ τῆσδε τῆς θαλάσσης ἐς τὴν Ἐρυθρὴν θάλασσαν δέκα μυριάδες εἰσὶ ὀργυιέων, αὗται δ’ ἂν εἶεν χίλιοι στάδιοι· τὸ δὲ ἀπὸ τοῦ στεινοῦ τούτου κάρτα πλατέα τυγχάνει ἐοῦσα ἡ ἀκτὴ ἥτις Λιβύη κέκληται.", "st": "4.41"}, {"sp": "N", "t": "θωμάζω ὦν τῶν διουρισάντων καὶ διελόντων Λιβύην τε καὶ Ἀσίην καὶ Εὐρώπην· οὐ γὰρ σμικρὰ τὰ διαφέροντα αὐτέων ἐστί· μήκεϊ μὲν γὰρ παρ’ ἀμφοτέρας παρήκει ἡ Εὐρώπη, εὔρεος δὲ πέρι οὐδὲ συμβάλλειν ἀξίη φαίνεταί μοι εἶναι. Λιβύη μὲν γὰρ δηλοῖ ἑωυτὴν ἐοῦσα περίρρυτος, πλὴν ὅσον αὐτῆς πρὸς τὴν Ἀσίην οὐρίζει, Νεκῶ τοῦ Αἰγυπτίων βασιλέος πρώτου τῶν ἡμεῖς ἴδμεν καταδέξαντος· ὃς ἐπείτε τὴν διώρυχα ἐπαύσατο ὀρύσσων τὴν ἐκ τοῦ Νείλου διέχουσαν ἐς τὸν Ἀράβιον κόλπον, ἀπέπεμψε Φοίνικας ἄνδρας πλοίοισι, ἐντειλάμενος ἐς τὸ ὀπίσω δι’ Ἡρακλέων στηλέων ἐκπλέειν ἕως ἐς τὴν βορηίην θάλασσαν καὶ οὕτω ἐς Αἴγυπτον ἀπικνέεσθαι. ὁρμηθέντες ὦν οἱ Φοίνικες ἐκ τῆς Ἐρυθρῆς θαλάσσης ἔπλεον τὴν νοτίην θάλασσαν· ὅκως δὲ γίνοιτο φθινόπωρον προσσχόντες ἂν σπείρεσκον τὴν γῆν, ἵνα ἑκάστοτε τῆς Λιβύης πλέοντες γινοίατο, καὶ μένεσκον τὸν ἄμητον· θερίσαντες δ’ ἂν τὸν σῖτον ἔπλεον, ὥστε δύο ἐτέων διεξελθόντων τρίτῳ ἔτεϊ κάμψαντες Ἡρακλέας στήλας ἀπίκοντο ἐς Αἴγυπτον. καὶ ἔλεγον ἐμοὶ μὲν οὐ πιστά, ἄλλῳ δὲ δή τεῳ, ὡς περιπλώοντες τὴν Λιβύην τὸν ἥλιον ἔσχον ἐς τὰ δεξιά.", "st": "4.42"}, {"sp": "N", "t": "οὕτω μὲν αὕτη ἐγνώσθη τὸ πρῶτον, μετὰ δὲ Καρχηδόνιοι εἰσὶ οἱ λέγοντες· ἐπεὶ Σατάσπης γε ὁ Τεάσπιος ἀνὴρ Ἀχαιμενίδης οὐ περιέπλωσε Λιβύην, ἐπ’ αὐτὸ τοῦτο πεμφθείς, ἀλλὰ δείσας τό τε μῆκος τοῦ πλόου καὶ τὴν ἐρημίην ἀπῆλθε ὀπίσω, οὐδ’ ἐπετέλεσε τὸν ἐπέταξε οἱ ἡ μήτηρ ἄεθλον. θυγατέρα γὰρ Ζωπύρου τοῦ Μεγαβύζου ἐβιήσατο παρθένον· ἔπειτα μέλλοντος αὐτοῦ διὰ ταύτην τὴν αἰτίην ἀνασκολοπιεῖσθαι ὑπὸ Ξέρξεω βασιλέος, ἡ μήτηρ τοῦ Σατάσπεος ἐοῦσα Δαρείου ἀδελφεὴ παραιτήσατο, φᾶσά οἱ αὐτὴ μέζω ζημίην ἐπιθήσειν ἤ περ ἐκεῖνον· Λιβύην γάρ οἱ ἀνάγκην ἔσεσθαι περιπλώειν, ἐς ὃ ἂν ἀπίκηται περιπλέων αὐτὴν ἐς τὸν Ἀράβιον κόλπον. συγχωρήσαντος δὲ Ξέρξεω ἐπὶ τούτοισι, ὁ Σατάσπης ἀπικόμενος ἐς Αἴγυπτον καὶ λαβὼν νέα τε καὶ ναύτας παρὰ τούτων ἔπλεε ἐπὶ Ἡρακλέας στήλας· διεκπλώσας δὲ καὶ κάμψας τὸ ἀκρωτήριον τῆς Λιβύης τῷ οὔνομα Σολόεις ἐστί, ἔπλεε πρὸς μεσαμβρίην· περήσας δὲ θάλασσαν πολλὴν ἐν πολλοῖσι μησί, ἐπείτε τοῦ πλεῦνος αἰεὶ ἔδεε, ἀποστρέψας ὀπίσω ἀπέπλεε ἐς Αἴγυπτον. ἐκ δὲ ταύτης ἀπικόμενος παρὰ βασιλέα Ξέρξεα ἔλεγε φὰς τὰ προσωτάτω ἀνθρώπους μικροὺς παραπλέειν ἐσθῆτι φοινικηίῃ διαχρεωμένους, οἳ ὅκως σφεῖς καταγοίατο τῇ νηὶ φεύγεσκον πρὸς τὰ ὄρεα λείποντες τὰς πόλιας· αὐτοὶ δὲ ἀδικέειν οὐδὲν ἐσιόντες, βρωτὰ δὲ μοῦνα ἐξ αὐτέων λαμβάνειν. τοῦ δὲ μὴ περιπλῶσαι Λιβύην παντελέως αἴτιον τόδε ἔλεγε, τὸ πλοῖον τὸ πρόσω οὐ δυνατὸν ἔτι εἶναι προβαίνειν ἀλλ’ ἐνίσχεσθαι. Ξέρξης δὲ οὔ οἱ συγγινώσκων λέγειν ἀληθέα οὐκ ἐπιτελέσαντά τε τὸν προκείμενον ἄεθλον ἀνεσκολόπισε, τὴν ἀρχαίην δίκην ἐπιτιμῶν. τούτου δὲ τοῦ Σατάσπεος εὐνοῦχος ἀπέδρη ἐς Σάμον, ἐπείτε ἐπύθετο τάχιστα τὸν δεσπότεα τετελευτηκότα, ἔχων χρήματα μεγάλα, τὰ Σάμιος ἀνὴρ κατέσχε, τοῦ ἐπιστάμενος τὸ οὔνομα ἑκὼν ἐπιλήθομαι.", "st": "4.43"}, {"sp": "N", "t": "τῆς δὲ Ἀσίης τὰ πολλὰ ὑπὸ Δαρείου ἐξευρέθη, ὃς βουλόμενος Ἰνδὸν ποταμόν, ὃς κροκοδείλους δεύτερος οὗτος ποταμῶν πάντων παρέχεται, τοῦτον τὸν ποταμὸν εἰδέναι τῇ ἐς θάλασσαν ἐκδιδοῖ, πέμπει πλοίοισι ἄλλους τε τοῖσι ἐπίστευε τὴν ἀληθείην ἐρέειν καὶ δὴ καὶ Σκύλακα ἄνδρα Καρυανδέα. οἳ δὲ ὁρμηθέντες ἐκ Κασπατύρου τε πόλιος καὶ τῆς Πακτυικῆς γῆς ἔπλεον κατὰ ποταμὸν πρὸς ἠῶ τε καὶ ἡλίου ἀνατολὰς ἐς θάλασσαν, διὰ θαλάσσης δὲ πρὸς ἑσπέρην πλέοντες τριηκοστῷ μηνὶ ἀπικνέονται ἐς τοῦτον τὸν χῶρον ὅθεν ὁ Αἰγυπτίων βασιλεὺς τοὺς Φοίνικας τοὺς πρότερον εἶπα ἀπέστειλε περιπλώειν Λιβύην. μετὰ δὲ τούτους περιπλώσαντας Ἰνδούς τε κατεστρέψατο Δαρεῖος καὶ τῇ θαλάσσῃ ταύτῃ ἐχρᾶτο. οὕτω καὶ τῆς Ἀσίης, πλὴν τὰ πρὸς ἥλιον ἀνίσχοντα, τὰ ἄλλα ἀνεύρηται ὅμοια παρεχομένη τῇ Λιβύῃ.", "st": "4.44"}, {"sp": "N", "t": "ἡ δὲ Εὐρώπη πρὸς οὐδαμῶν φανερή ἐστι γινωσκομένη, οὔτε τὰ πρὸς ἥλιον ἀνατέλλοντα οὔτε τὰ πρὸς βορέην, εἰ περίρρυτος ἐστί· μήκεϊ δὲ γινώσκεται παρ’ ἀμφοτέρας παρήκουσα. οὐδ’ ἔχω συμβαλέσθαι ἐπ’ ὅτευ μιῇ ἐούσῃ γῇ οὐνόματα τριφάσια κέεται ἐπωνυμίας ἔχοντα γυναικῶν, καὶ οὐρίσματα αὐτῇ Νεῖλός τε ὁ Αἰγύπτιος ποταμὸς ἐτέθη καὶ Φᾶσις ὁ Κόλχος (οἳ δὲ Τάναιν ποταμὸν τὸν Μαιήτην καὶ πορθμήια τὰ Κιμμέρια λέγουσι), οὐδὲ τῶν διουρισάντων τὰ οὐνόματα πυθέσθαι, καὶ ὅθεν ἔθεντο τὰς ἐπωνυμίας. ἤδη γὰρ Λιβύη μὲν ἐπὶ Λιβύης λέγεται ὑπὸ τῶν πολλῶν Ἑλλήνων ἔχειν τὸ οὔνομα γυναικὸς αὐτόχθονος, ἡ δὲ Ἀσίη ἐπὶ τῆς Προμηθέος γυναικὸς τὴν ἐπωνυμίην. καὶ τούτου μὲν μεταλαμβάνονται τοῦ οὐνόματος Λυδοί, φάμενοι ἐπὶ Ἀσίεω τοῦ Κότυος τοῦ Μάνεω κεκλῆσθαι τὴν Ἀσίην, ἀλλ’ οὐκ ἐπὶ τῆς Προμηθέος Ἀσίης· ἀπ’ ὅτευ καὶ τὴν ἐν Σάρδισι φυλὴν κεκλῆσθαι Ἀσιάδα. ἡ δὲ δὴ Εὐρώπη οὔτε εἰ περίρρυτος ἐστὶ γινώσκεται πρὸς οὐδαμῶν ἀνθρώπων, οὔτε ὁκόθεν τὸ οὔνομα ἔλαβε τοῦτο, οὔτε ὅστις οἱ ἦν ὁ θέμενος φαίνεται, εἰ μὴ ἀπὸ τῆς Τυρίης φήσομεν Εὐρώπης λαβεῖν τὸ οὔνομα τὴν χώρην· πρότερον δὲ ἦν ἄρα ἀνώνυμος ὥσπερ αἱ ἕτεραι. ἀλλ’ αὕτη γε ἐκ τῆς Ἀσίης τε φαίνεται ἐοῦσα καὶ οὐκ ἀπικομένη ἐς τὴν γῆν ταύτην ἥτις νῦν ὑπὸ Ἑλλήνων Εὐρώπη καλέεται, ἀλλ’ ὅσον ἐκ Φοινίκης ἐς Κρήτην, ἐκ Κρήτης δὲ ἐς Λυκίην. ταῦτα μέν νυν ἐπὶ τοσοῦτον εἰρήσθω· τοῖσι γὰρ νομιζομένοισι αὐτῶν χρησόμεθα.", "st": "4.45"}, {"sp": "N", "t": "ὁ δὲ Πόντος ὁ Εὔξεινος, ἐπ’ ὃν ἐστρατεύετο ὁ Δαρεῖος, χωρέων πασέων παρέχεται ἔξω τοῦ Σκυθικοῦ ἔθνεα ἀμαθέστατα. οὔτε γὰρ ἔθνος τῶν ἐντὸς τοῦ Πόντου οὐδὲν ἔχομεν προβαλέσθαι σοφίης πέρι οὔτε ἄνδρα λόγιον οἴδαμεν γενόμενον, πάρεξ τοῦ Σκυθικοῦ ἔθνεος καὶ Ἀναχάρσιος. τῷ δὲ Σκυθικῷ γένει ἓν μὲν τὸ μέγιστον τῶν ἀνθρωπηίων πρηγμάτων σοφώτατα πάντων ἐξεύρηται τῶν ἡμεῖς ἴδμεν, τὰ μέντοι ἄλλα οὐκ ἄγαμαι· τὸ δὲ μέγιστον οὕτω σφι ἀνεύρηται ὥστε ἀποφυγεῖν τε μηδένα ἐπελθόντα ἐπὶ σφέας, μὴ βουλομένους τε ἐξευρεθῆναι καταλαβεῖν μὴ οἷον τε εἶναι. τοῖσι γὰρ μήτε ἄστεα μήτε τείχεα ᾖ ἐκτισμένα, ἀλλὰ φερέοικοι ἐόντες πάντες ἔωσι ἱπποτοξόται, ζῶντες μὴ ἀπ’ ἀρότου ἀλλ’ ἀπὸ κτηνέων, οἰκήματα τε σφι ᾖ ἐπὶ ζευγέων, κῶς οὐκ ἂν εἴησαν οὗτοι ἄμαχοί τε καὶ ἄποροι προσμίσγειν;", "st": "4.46"}, {"sp": "N", "t": "ἐξεύρηται δέ σφι ταῦτα τῆς τε γῆς ἐούσης ἐπιτηδέης καὶ τῶν ποταμῶν ἐόντων σφι συμμάχων. ἥ τε γὰρ γῆ ἐοῦσα πεδιὰς αὕτη ποιώδης τε καὶ εὔυδρος ἐστί, ποταμοί τε δι’ αὐτῆς ῥέουσι οὐ πολλῷ τεῳ ἀριθμὸν ἐλάσσονες τῶν ἐν Αἰγύπτῳ διωρύχων. ὅσοι δὲ ὀνομαστοί τε εἰσὶ αὐτῶν καὶ προσπλωτοὶ ἀπὸ θαλάσσης, τούτους ὀνομανέω … Ἴστρος μὲν πεντάστομος, μετὰ δὲ Τύρης τε καὶ Ὕπανις καὶ Βορυσθένης καὶ Παντικάπης καὶ Ὑπάκυρις καὶ Γέρρος καὶ Τάναϊς. ῥέουσι δὲ οἵδε κατὰ τάδε.", "st": "4.47"}, {"sp": "N", "t": "Ἴστρος μέν, ἐὼν μέγιστος ποταμῶν πάντων τῶν ἡμεῖς ἴδμεν, ἴσος αἰεὶ αὐτὸς ἑωυτῷ ῥέει καὶ θέρεος καὶ χειμῶνος, πρῶτος δὲ τὸ ἀπ’ ἑσπέρης τῶν ἐν τῇ Σκυθικῇ ῥέων κατὰ τοιόνδε μέγιστος γέγονε· ποταμῶν καὶ ἄλλων ἐς αὐτὸν ἐκδιδόντων εἰσὶ δὴ οἵδε οἱ μέγαν αὐτὸν ποιεῦντες, διὰ μέν γε τῆς Σκυθικῆς χώρης πέντε μὲν οἱ ῥέοντες, τὸν τε Σκύθαι Πόρατα καλέουσι Ἕλληνες δὲ Πυρετόν, καὶ ἄλλος Τιάραντος καὶ Ἄραρος τε καὶ Νάπαρις καὶ Ὀρδησσός. ὁ μὲν πρῶτος λεχθεὶς τῶν ποταμῶν μέγας καὶ πρὸς ἠῶ ῥέων ἀνακοινοῦται τῷ Ἴστρῳ τὸ ὕδωρ, ὁ δὲ δεύτερος λεχθεὶς Τιάραντος πρὸς ἑσπέρης τε μᾶλλον καὶ ἐλάσσων, ὁ δὲ δὴ Ἄραρός τε καὶ ὁ Νάπαρις καὶ ὁ Ὀρδησσὸς καὶ μέσου τούτων ἰόντες ἐσβάλλουσι ἐς τὸν Ἴστρον.", "st": "4.48"}, {"sp": "N", "t": "οὗτοι μὲν αὐθιγενέες Σκυθικοὶ ποταμοὶ συμπληθύουσι αὐτόν, ἐκ δὲ Ἀγαθύρσων Μάρις ποταμὸς ῥέων συμμίσγεται τῷ Ἴστρῳ, ἐκ δὲ τοῦ Αἵμου τῶν κορυφέων τρεῖς ἄλλοι μεγάλοι ῥέοντες πρὸς βορέην ἄνεμον ἐσβάλλουσι ἐς αὐτόν, Ἄτλας καὶ Αὔρας καὶ Τίβισις. διὰ δὲ Θρηίκης καὶ Θρηίκων τῶν Κροβύζων ῥέοντες Ἄθρυς καὶ Νόης καὶ Ἀρτάνης ἐκδιδοῦσι ἐς τὸν Ἴστρον· ἐκ δὲ Παιόνων καὶ ὄρεος Ῥοδόπης Κίος ποταμὸς μέσον σχίζων τὸν Αἷμον ἐκδιδοῖ ἐς αὐτόν. ἐξ Ἰλλυριῶν δὲ ῥέων πρὸς βορέην ἄνεμον Ἄγγρος ποταμὸς ἐσβάλλει ἐς πεδίον τὸ Τριβαλλικὸν καὶ ἐς ποταμὸν Βρόγγον, ὁ δὲ Βρόγγος ἐς τὸν Ἴστρον· οὕτω ἀμφοτέρους ἐόντας μεγάλους ὁ Ἴστρος δέκεται. ἐκ δὲ τῆς κατύπερθε χώρης Ὀμβρικῶν Κάρπις ποταμὸς καὶ ἄλλος Ἄλπις ποταμὸς πρὸς βορέην ἄνεμον καὶ οὗτοι ῥέοντες ἐκδιδοῦσι ἐς αὐτόν· ῥέει γὰρ δὴ διὰ πάσης τῆς Εὐρώπης ὁ Ἴστρος, ἀρξάμενος ἐκ Κελτῶν, οἳ ἔσχατοι πρὸς ἡλίου δυσμέων μετὰ Κύνητας οἰκέουσι τῶν ἐν τῇ Εὐρώπη· ῥέων δὲ διὰ πάσης τῆς Εὐρώπης ἐς τὰ πλάγια τῆς Σκυθίης ἐσβάλλει.", "st": "4.49"}, {"sp": "N", "t": "τούτων ὦν τῶν καταλεχθέντων καὶ ἄλλων πολλῶν συμβαλλομένων τὸ σφέτερον ὕδωρ γίνεται ὁ Ἴστρος ποταμῶν μέγιστος, ἐπεὶ ὕδωρ γε ἓν πρὸς ἓν συμβάλλειν ὁ Νεῖλος πλήθει ἀποκρατέει. ἐς γὰρ δὴ τοῦτον οὔτε ποταμὸς οὔτε κρήνη οὐδεμία ἐσδιδοῦσα ἐς πλῆθός οἱ συμβάλλεται. ἴσος δὲ αἰεὶ ῥέει ἐν τε θέρει καὶ χειμῶνι ὁ Ἴστρος κατὰ τοιόνδε τι, ὡς ἐμοὶ δοκέει· τοῦ μὲν χειμῶνος ἐστὶ ὅσος περ ἐστι, ὀλίγῳ τε μέζων τῆς ἑωυτοῦ φύσιος γίνεται· ὕεται γὰρ ἡ γῆ αὕτη τοῦ χειμῶνος πάμπαν ὀλίγῳ, νιφετῷ δὲ πάντα χρᾶται· τοῦ δὲ θέρεος ἡ χιὼν ἡ ἐν τῷ χειμῶνι πεσοῦσα, ἐοῦσα ἀμφιλαφής, τηκομένη πάντοθεν ἐσδιδοῖ ἐς τὸν Ἴστρον. αὕτη τε δὴ ἡ χιὼν ἐσδιδοῦσα ἐς αὐτὸν συμπληθύει καὶ ὄμβροι πολλοί τε καὶ λάβροι σὺν αὐτῇ· ὕει γὰρ δὴ τὸ θέρος. ὅσῳ δὲ πλέον ἐπ’ ἑωυτὸν ὕδωρ ὁ ἥλιος ἐπέλκεται ἐν τῶ θέρει ἢ ἐν τῷ χειμῶνι, τοσούτῳ τὰ συμμισγόμενα τῷ Ἴστρῳ πολλαπλήσια ἐστὶ τοῦ θέρεος ἤ περ τοῦ χειμῶνος· ἀντιτιθέμενα δὲ ταῦτα ἀντισήκωσις γίνεται, ὥστε ἴσον μιν αἰεὶ φαίνεσθαι ἐόντα.", "st": "4.50"}, {"sp": "N", "t": "εἷς μὲν δὴ τῶν ποταμῶν τοῖσι Σκύθῃσι ἐστὶ ὁ Ἴστρος, μετὰ δὲ τοῦτον Τύρης, ὃς ἀπὸ βορέω μὲν ἀνέμου ὁρμᾶται, ἄρχεται δὲ ῥέων ἐκ λίμνης μεγάλης ἣ οὐρίζει τήν τε Σκυθικὴν καὶ Νευρίδα γῆν. ἐπὶ δὲ τῷ στόματι αὐτοῦ κατοίκηνται Ἕλληνες οἳ Τυρῖται καλέονται.", "st": "4.51"}, {"sp": "N", "t": "τρίτος δὲ Ὕπανις ποταμὸς ὁρμᾶται μὲν ἐκ τῆς Σκυθικῆς, ῥέει δὲ ἐκ λίμνης μεγάλης τὴν πέριξ νέμονται ἵπποι ἄγριοι λευκοί· καλέεται δὲ ἡ λίμνη αὕτη ὀρθῶς μήτηρ Ὑπάνιος. ἐκ ταύτης ὦν ἀνατέλλων ὁ Ὕπανις ποταμὸς ῥέει ἐπὶ μὲν πέντε ἡμερέων πλόον βραχὺς καὶ γλυκύς ἐστι, ἀπὸ δὲ τούτου πρὸς θαλάσσης τεσσέρων ἡμερέων πλόον πικρὸς δεινῶς· ἐκδιδοῖ γὰρ ἐς αὐτὸν κρήνη πικρή, οὕτω δή τι ἐοῦσα πικρή, ἣ μεγάθεϊ σμικρὴ ἐοῦσα κιρνᾷ τὸν Ὕπανιν ἐόντα ποταμὸν ἐν ὀλίγοισι μέγαν. ἔστι δὲ ἡ κρήνη αὕτη ἐν οὔροισι χώρης τῆς τε ἀροτήρων Σκυθέων καὶ Ἀλαζόνων· οὔνομα δὲ τῇ κρήνῃ καὶ ὅθεν ῥέει τῷ χώρῳ σκυθιστὶ μὲν Ἐξαμπαῖος, κατὰ δὲ τὴν Ἑλλήνων γλῶσσαν Ἱραὶ ὁδοί. συνάγουσι δὲ τὰ τέρματα ὅ τε Τύρης καὶ ὁ Ὕπανις κατὰ Ἀλαζόνας, τὸ δὲ ἀπὸ τούτου ἀποστρέψας ἑκάτερος ῥέει εὐρύνων τὸ μέσον.", "st": "4.52"}, {"sp": "N", "t": "τέταρτος δὲ Βορυσθένης ποταμός, ὃς ἐστί τε μέγιστος μετὰ Ἴστρον τούτων καὶ πολυαρκέστατος κατὰ γνώμας τὰς ἡμετέρας οὔτι μοῦνον τῶν Σκυθικῶν ποταμῶν ἀλλὰ καὶ τῶν ἄλλων ἁπάντων, πλὴν Νείλου τοῦ Αἰγυπτίου· τούτῳ γὰρ οὐκ οἷά τε ἐστὶ συμβαλεῖν ἄλλον ποταμόν· τῶν δὲ λοιπῶν Βορυσθένης ἐστὶ πολυαρκέστατος, ὃς νομάς τε καλλίστας καὶ εὐκομιδεστάτας κτήνεσι παρέχεται ἰχθύας τε ἀρίστους διακριδὸν καὶ πλείστους, πίνεσθαι τε ἥδιστος ἐστί, ῥέει τε καθαρὸς παρὰ θολεροῖσι, σπόρος τε παρ’ αὐτὸν ἄριστος γίνεται, ποίη τε, τῇ οὐ σπείρεται ἡ χώρη, βαθυτάτη· ἅλες τε ἐπὶ τῷ στόματι αὐτοῦ αὐτόματοι πήγνυνται ἄπλετοι· κήτεά τε μεγάλα ἀνάκανθα, τὰ ἀντακαίους καλέουσι, παρέχεται ἐς ταρίχευσιν, ἄλλα τε πολλὰ θωμάσαι ἄξια. μέχρι μέν νυν Γερρέων χώρου, ἐς τὸν τεσσεράκοντα ἡμερέων πλόος ἐστί, γινώσκεται ῥέων ἀπὸ βορέω ἀνέμου· τὸ δὲ κατύπερθε δι’ ὧν ῥέει ἀνθρώπων οὐδεὶς ἔχει φράσαι· φαίνεται δὲ ῥέων δι’ ἐρήμου ἐς τῶν γεωργῶν Σκυθέων τὴν χώρην· οὗτοι γὰρ οἱ Σκύθαι παρ’ αὐτὸν ἐπὶ δέκα ἡμερέων πλόον νέμονται. μούνου δὲ τούτου τοῦ ποταμοῦ καὶ Νείλου οὐκ ἔχω φράσαι τὰς πηγάς, δοκέω δέ, οὐδὲ οὐδεὶς Ἑλλήνων. ἀγχοῦ τε δὴ θαλάσσης ὁ Βορυσθένης ῥέων γίνεται καὶ οἱ συμμίσγεται ὁ Ὕπανις ἐς τὠυτὸ ἕλος ἐκδιδούς. τὸ δὲ μεταξὺ τῶν ποταμῶν τούτων, ἐὸν ἔμβολον τῆς χώρης, Ἱππόλεω ἄκρη καλέεται, ἐν δὲ αὐτῷ, ἱρὸν Δήμητρος ἐνίδρυται· πέρην δὲ τοῦ ἱροῦ ἐπὶ τῷ Ὑπάνι Βορυσθενεῗται κατοίκηνται.", "st": "4.53"}, {"sp": "N", "t": "ταῦτα μὲν τὰ ἀπὸ τούτων τῶν ποταμῶν, μετὰ δὲ τούτους πέμπτος ποταμὸς ἄλλος, τῷ οὔνομα Παντικάπης, ῥέει μὲν καὶ οὗτος ἀπὸ βορέω τε καὶ ἐκ λίμνης, καὶ τὸ μεταξὺ τούτου τε καὶ τοῦ Βορυσθένεος νέμονται οἱ γεωργοὶ Σκύθαι, ἐκδιδοῖ δὲ ἐς τὴν Ὑβλαίην, παραμειψάμενος δὲ ταύτην τῷ Βορυσθένεϊ συμμίσγεται.", "st": "4.54"}, {"sp": "N", "t": "ἕκτος δὲ Ὑπάκυρις ποταμός, ὃς ὁρμᾶται μὲν ἐκ λίμνης, διὰ μέσων δὲ τῶν νομάδων Σκυθέων ῥέων ἐκδιδοῖ κατὰ Καρκινῖτιν πόλιν, ἐς δεξιὴν ἀπέργων τήν τε Ὑλαίην καὶ τὸν Ἀχιλλήιον δρόμον καλεόμενον.", "st": "4.55"}, {"sp": "N", "t": "ἕβδομος δὲ Γέρρος ποταμὸς ἀπέσχισται μὲν ἀπὸ τοῦ Βορυσθένεος κατὰ τοῦτο τῆς χώρης ἐς ὃ γινώσκεται ὁ Βορυσθένης· ἀπέσχισται μέν νυν ἐκ τούτου τοῦ χώρου, οὔνομα δὲ ἔχει τό περ ὁ χῶρος αὐτός, Γέρρος, ῥέων δὲ ἐς θάλασσαν οὐρίζει τήν τε τῶν νομάδων χώρην καὶ τὴν τῶν βασιληίων Σκυθέων, ἐκδιδοῖ δὲ ἐς τὸν Ὑπάκυριν.", "st": "4.56"}, {"sp": "N", "t": "ὄγδοος δὲ δὴ Τάναϊς ποταμός, ὃς ῥέει τἀνέκαθεν ἐκ λίμνης μεγάλης ὁρμώμενος, ἐκδιδοῖ δὲ ἐς μέζω ἔτι λίμνην καλεόμενον Μαιῆτιν, ἣ οὐρίζει Σκύθας τε τοὺς βασιληίους καὶ Σαυρομάτας. ἐς δὲ Τάναϊν τοῦτον ἄλλος ποταμὸς ἐσβάλλει τῷ οὔνομα ἐστὶ Ὕργις.", "st": "4.57"}, {"sp": "N", "t": "τοῖσι μὲν δὴ ὀνομαστοῖσι ποταμοῖσι οὕτω δή τι οἱ Σκύθαι ἐσκευάδαται, τοῖσι δὲ κτήνεσι ἡ ποίη ἀναφυομένη ἐν τῇ Σκυθικῆ ἐστι ἐπιχολωτάτη πασέων ποιέων τῶν ἡμεῖς ἴδμεν· ἀνοιγομένοισι δὲ τοῖσι κτήνεσι ἐστὶ σταθμώσασθαι ὅτι τοῦτο οὕτω ἔχει.", "st": "4.58"}, {"sp": "N", "t": "τὰ μὲν δὴ μέγιστα οὕτω σφι εὔπορα ἐστί, τὰ δὲ λοιπὰ νόμαια κατὰ τάδε σφι διακέεται. θεοὺς μὲν μούνους τούσδε ἱλάσκονται, Ἱστίην μὲν μάλιστα, ἐπὶ δὲ Δία καὶ Γῆν, νομίζοντες τὴν Γῆν τοῦ Διὸς εἶναι γυναῖκα, μετὰ δὲ τούτους, Ἀπόλλωνά τε καὶ οὐρανίην Ἀφροδίτην καὶ Ἡρακλέα καὶ Ἄρεα. τούτους μὲν πάντες Σκύθαι νενομίκασι, οἱ δὲ καλεόμενοι βασιλήιοι Σκύθαι καὶ τῷ Ποσειδέωνι θύουσι. ὀνομάζεται δὲ σκυθιστὶ Ἱστίη μὲν Ταβιτί, Ζεὺς δὲ ὀρθότατα κατὰ γνώμην γε τὴν ἐμὴν καλεόμενος Παπαῖος, Γῆ δὲ Ἀπί. Ἀπόλλων δὲ Γοιτόσυρος, οὐρανίη δὲ Ἀφροδίτη Ἀργίμπασα, Ποσειδέων δὲ Θαγιμασάδας. ἀγάλματα δὲ καὶ βωμοὺς καὶ νηοὺς οὐ νομίζουσι ποιέειν πλὴν Ἄρεϊ. τούτῳ δὲ νομίζουσι.", "st": "4.59"}, {"sp": "N", "t": "θυσίη δὲ ἡ αὐτὴ πᾶσι κατέστηκε περὶ πάντα τὰ ἱρὰ ὁμοίως, ἐρδομένη ὧδε· τὸ μὲν ἱρήιον αὐτὸ ἐμπεποδισμένον τοὺς ἐμπροσθίους πόδας ἔστηκε, ὁ δὲ θύων ὄπισθε τοῦ κτήνεος ἑστεὼς σπάσας τὴν ἀρχὴν τοῦ στρόφου καταβάλλει μιν, πίπτοντος δὲ τοῦ ἱρηίου ἐπικαλέει τὸν θεὸν τῷ ἂν θύῃ, καὶ ἔπειτα βρόχῳ περὶ ὦν ἔβαλε τὸν αὐχένα, σκυταλίδα δὲ ἐμβαλὼν περιάγει καὶ ἀποπνίγει, οὔτε πῦρ ἀνακαύσας οὔτε καταρξάμενος οὔτ’ ἐπισπείσας· ἀποπνίξας δὲ καὶ ἀποδείρας τρέπεται πρὸς ἕψησιν.", "st": "4.60"}, {"sp": "N", "t": "τῆς δὲ γῆς τῆς Σκυθικῆς αἰνῶς ἀξύλου ἐούσης ὧδε σφι ἐς τὴν ἕψησιν τῶν κρεῶν ἐξεύρηται· ἐπειδὰν ἀποδείρωσι τὰ ἱρήια, γυμνοῦσι τὰ ὀστέα τῶν κρεῶν, ἔπειτα ἐσβάλλουσι, ἢν μὲν τύχωσι ἔχοντες, ἐς λέβητας ἐπιχωρίους, μάλιστα Λεσβίοισι κρητῆρσι προσεικέλους, χωρὶς ἢ ὅτι πολλῷ μέζονας· ἐς τούτους ἐσβάλλοντες ἕψουσι ὑποκαίοντες τὰ ὀστέα τῶν ἱρηίων. ἢν δὲ μή σφι παρῇ ὁ λέβης, οἳ δὲ ἐς τὰς γαστέρας τῶν ἱρηίων ἐσβάλλοντες τὰ κρέα πάντα καὶ παραμίξαντες ὕδωρ ὑποκαίουσι τὰ ὀστέα· τὰ δὲ αἴθεται κάλλιστα, αἱ δὲ γαστέρες χωρέουσι εὐπετέως τὰ κρέα ἐψιλωμένα τῶν ὀστέων· καὶ οὕτω βοῦς τε ἑωυτὸν ἐξέψει καὶ τἆλλα ἱρήια ἑωυτὸ ἕκαστον. ἐπεὰν δὲ ἑψηθῇ τὰ κρέα, ὁ θύσας τῶν κρεῶν καὶ τῶν σπλάγχνων ἀπαρξάμενος ῥίπτει ἐς τὸ ἔμπροσθε. θύουσι δὲ καὶ τὰ ἄλλα πρόβατα καὶ ἵππους μάλιστα.", "st": "4.61"}, {"sp": "N", "t": "τοῖσι μὲν δὴ ἄλλοισι τῶν θεῶν οὕτω θύουσι καὶ ταῦτα τῶν κτηνέων, τῷ δὲ Ἄρεϊ ὧδε. κατὰ νομοὺς ἑκάστους τῶν ἀρχέων ἐσίδρυται σφι Ἄρεος ἱρὸν· τοιόνδε φρυγάνων φάκελοι συννενέαται ὅσον τ’ ἐπὶ σταδίους τρεῖς μῆκος καὶ εὖρος, ὕψος δὲ ἔλασσον· ἄνω δὲ τούτου τετράγωνον ἄπεδον πεποίηται, καὶ τὰ μὲν τρία τῶν κώλων ἐστὶ ἀπότομα, κατὰ δὲ τὸ ἓν ἐπιβατόν. ἔτεος δὲ ἑκάστου ἁμάξας πεντήκοντα καὶ ἑκατὸν ἐπινέουσι φρυγάνων· ὑπονοστέει γὰρ δὴ αἰεὶ ὑπὸ τῶν χειμώνων. ἐπὶ τούτου δὴ τοῦ σηκοῦ ἀκινάκης σιδήρεος ἵδρυται ἀρχαῖος ἑκάστοισι, καὶ τοῦτ’ ἐστὶ τοῦ Ἄρεος τὸ ἄγαλμα. τούτῳ δὲ τῷ ἀκινάκῃ θυσίας ἐπετείους προσάγουσι προβάτων καὶ ἵππων, καὶ δὴ καὶ τοῖσιδ’ ἔτι πλέω θύουσι ἢ τοῖσι ἄλλοισι θεοῖσι· ὅσους ἂν τῶν πολεμίων ζωγρήσωσι, ἀπὸ τῶν ἑκατὸν ἀνδρῶν ἄνδρα θύουσι τρόπῳ οὐ τῷ αὐτῷ καὶ τὰ πρόβατα, ἀλλ’ ἑτεροίῳ. ἐπεὰν γὰρ οἶνον ἐπισπείσωσι κατὰ τῶν κεφαλέων, ἀποσφάζουσι τοὺς ἀνθρώπους ἐς ἄγγος καὶ ἔπειτα ἀνενείκαντες ἄνω ἐπὶ τὸν ὄγκον τῶν φρυγάνων καταχέουσι τὸ αἷμα τοῦ ἀκινάκεω. ἄνω μὲν δὴ φορέουσι τοῦτο, κάτω δὲ παρὰ τὸ ἱρὸν ποιεῦσι τάδε· τῶν ἀποσφαγέντων ἀνδρῶν τοὺς δεξιοὺς ὤμους πάντας ἀποταμόντες σὺν τῇσι χερσὶ ἐς τὸν ἠέρα ἱεῖσι, καὶ ἔπειτα καὶ τὰ ἄλλα ἀπέρξαντες ἱρήια ἀπαλλάσσονται. χεὶρ δὲ τῇ ἂν πέσῃ κέεται, καὶ χωρὶς ὁ νεκρός.", "st": "4.62"}, {"sp": "N", "t": "θυσίαι μέν νυν αὗταί σφι κατεστᾶσι. ὑσὶ δὲ οὗτοι οὐδὲν νομίζουσι, οὐδὲ τρέφειν ἐν τῇ χώρῃ τὸ παράπαν θέλουσι.", "st": "4.63"}, {"sp": "N", "t": "τὰ δ’ ἐς πόλεμον ἔχοντα ὧδέ σφι διακέαται· ἐπεὰν τὸν πρῶτον ἄνδρα καταβάλῃ ἀνὴρ Σκύθης, τοῦ αἵματος ἐμπίνει, ὅσους δ’ ἂν φονεύσῃ ἐν τῇ μάχῃ, τούτων τὰς κεφαλὰς ἀποφέρει τῷ βασιλέι. ἀπενείκας μὲν γὰρ κεφαλὴν τῆς ληίης μεταλαμβάνει τὴν ἂν λάβωσι, μὴ ἐνείκας δὲ οὔ. ἀποδείρει δὲ αὐτὴν τρόπῳ τοιῷδε· περιταμὼν κύκλῳ περὶ τὰ ὦτα καὶ λαβόμενος τῆς κεφαλῆς ἐκσείει, μετὰ δὲ σαρκίσας βοὸς πλευρῇ δέψει τῇσι χερσί, ὀργάσας δὲ αὐτὸ ἅτε χειρόμακτρον ἔκτηται, ἐκ δὲ τῶν χαλινῶν τοῦ ἵππου τὸν αὐτὸς ἐλαύνει, ἐκ τούτου ἐξάπτει καὶ ἀγάλλεται· ὃς γὰρ ἂν πλεῖστα δέρματα χειρόμακτρα ἔχῃ, ἀνὴρ ἄριστος οὗτος κέκριται. πολλοὶ δὲ αὐτῶν ἐκ τῶν ἀποδερμάτων καὶ χλαίνας ἐπείνυσθαι ποιεῦσι, συρράπτοντες κατά περ βαίτας. πολλοὶ δὲ ἀνδρῶν ἐχθρῶν τὰς δεξιὰς χεῖρας νεκρῶν ἐόντων ἀποδείραντες αὐτοῖσι ὄνυξι καλύπτρας τῶν φαρετρέων ποιεῦνται. δέρμα δὲ ἀνθρώπου καὶ παχὺ καὶ λαμπρὸν ἦν ἄρα, σχεδὸν δερμάτων πάντων λαμπρότατον λευκότητι. πολλοὶ δὲ καὶ ὅλους ἄνδρας ἐκδείραντες καὶ διατείναντες ἐπὶ ξύλων ἐπ’ ἵππων περιφέρουσι.", "st": "4.64"}, {"sp": "N", "t": "ταῦτα μὲν δὴ οὕτω σφι νενόμισται, αὐτὰς δὲ τὰς κεφαλάς, οὔτι πάντων ἀλλὰ τῶν ἐχθίστων, ποιεῦσι τάδε· ἀποπρίσας ἕκαστος πᾶν τὸ ἔνερθε τῶν ὀφρύων ἐκκαθαίρει· καὶ ἢν μὲν ᾖ πένης, ὁ δὲ ἔξωθεν ὠμοβοέην μούνην περιτείνας οὕτω χρᾶται, ἢν δὲ ᾖ πλούσιος, τὴν μὲν ὠμοβοέην περιτείνει, ἔσωθεν δὲ καταχρυσώσας οὕτω χρᾶται ποτηρίῳ. ποιεῦσι δὲ τοῦτο καὶ ἐκ τῶν οἰκηίων ἤν σφι διάφοροι γένωνται καὶ ἢν ἐπικρατήσῃ αὐτοῦ παρὰ τῷ βασιλέι, ξείνων δέ οἱ ἐλθόντων τῶν ἂν λόγον ποιέηται, τὰς κεφαλὰς ταύτας παραφέρει καὶ ἐπιλέγει ὡς οἱ ἐόντες οἰκήιοι πόλεμον προσεθήκαντο καί σφεων αὐτὸς ἐπεκράτησε, ταύτην ἀνδραγαθίην λέγοντες.", "st": "4.65"}, {"sp": "N", "t": "ἅπαξ δὲ τοῦ ἐνιαυτοῦ ἑκάστου ὁ νομάρχης ἕκαστος ἐν τῷ ἑωυτοῦ νομῷ κιρνᾷ κρητῆρα οἴνου, ἀπ’ οὗ πίνουσι τῶν Σκυθέων τοῖσι ἂν ἄνδρες πολέμιοι ἀραιρημένοι ἔωσι. τοῖσι δ’ ἂν μὴ κατεργασμένον ᾖ τοῦτο, οὐ γεύονται τοῦ οἴνου τούτου, ἀλλ’ ἠτιμωμένοι ἀποκατέαται· ὄνειδος δέ σφι ἐστὶ μέγιστον τοῦτο. ὅσοι δὲ ἂν αὐτῶν καὶ κάρτα πολλοὺς ἄνδρας ἀραιρηκότες ἔωσι, οὗτοι δὲ σύνδυο κύλικας ἔχοντες πίνουσι ὁμοῦ.", "st": "4.66"}, {"sp": "N", "t": "μάντιες δὲ Σκυθέων εἰσὶ πολλοί, οἳ μαντεύονται ῥάβδοισι ἰτεΐνῃσι πολλῇσι ὧδε· ἐπεὰν φακέλους ῥάβδων μεγάλους ἐνείκωνται, θέντες χαμαὶ διεξειλίσσουσι αὐτούς, καὶ ἐπὶ μίαν ἑκάστην ῥάβδον τιθέντες θεσπίζουσι, ἅμα τε λέγοντες ταῦτα συνειλέουσι τὰς ῥάβδους ὀπίσω καὶ αὖτις κατὰ μίαν συντιθεῖσι. αὕτη μὲν σφι ἡ μαντικὴ πατρωίη ἐστί. οἱ δὲ Ἐνάρεες οἱ ἀνδρόγυνοι τὴν Ἀφροδίτην σφίσι λέγουσι μαντικὴν δοῦναι· φιλύρης δ’ ὦν φλοιῷ μαντεύονται· ἐπεὰν τὴν φιλύρην τρίχα σχίσῃ, διαπλέκων ἐν τοῖσι δακτύλοισι τοῖσι ἑωυτοῦ καὶ διαλύων χρᾷ.", "st": "4.67"}, {"sp": "N", "t": "ἐπεὰν δὲ βασιλεὺς ὁ Σκυθέων κάμῃ, μεταπέμπεται τῶν μαντίων ἄνδρας τρεῖς τοὺς εὐδοκιμέοντας μάλιστα, οἳ τρόπῳ τῷ εἰρημένῳ μαντεύονται· καὶ λέγουσι οὗτοι ὡς τὸ ἐπίπαν μάλιστα τάδε, ὡς τὰς βασιληίας ἱστίας ἐπιώρκηκε ὃς καὶ ὅς, λέγοντες τῶν ἀστῶν τὸν ἂν δὴ λέγωσι. τὰς δὲ βασιληίας ἱστίας νόμος Σκύθῃσι τὰ μάλιστα ἐστὶ ὀμνύναι τότε ἐπεὰν τὸν μέγιστον ὅρκον ἐθέλωσι ὀμνύναι. αὐτίκα δὲ διαλελαμμένος ἄγεται οὗτος τὸν ἂν δὴ φῶσι ἐπιορκῆσαι, ἀπιγμένον δὲ ἐλέγχουσι οἱ μάντιες ὡς ἐπιορκήσας φαίνεται ἐν τῇ μαντικῇ τὰς βασιληίας ἱστίας καὶ διὰ ταῦτα ἀλγέει ὁ βασιλεύς· ὁ δὲ ἀρνέεται, οὐ φάμενος ἐπιορκῆσαι, καὶ δεινολογέεται. ἀρνεομένου δὲ τούτου ὁ βασιλεὺς μεταπέμπεται ἄλλους διπλησίους μάντιας· καὶ ἢν μὲν καὶ οὗτοι ἐσορῶντες ἐς τὴν μαντικὴν καταδήσωσι ἐπιορκῆσαι, τοῦ δὲ ἰθέως τὴν κεφαλὴν ἀποτάμνουσι, καὶ τὰ χρήματα αὐτοῦ διαλαγχάνουσι οἱ πρῶτοι τῶν μαντίων· ἢν δὲ οἱ ἐπελθόντες μάντιες ἀπολύσωσι, ἄλλοι πάρεισι μάντιες καὶ μάλα ἄλλοι. ἢν ὦν οἱ πλεῦνες τὸν ἄνθρωπον ἀπολύσωσι, δέδοκται τοῖσι πρώτοισι τῶν μαντίων αὐτοῖσι ἀπόλλυσθαι.", "st": "4.68"}, {"sp": "N", "t": "ἀπολλῦσι δῆτα αὐτοὺς τρόπῳ τοιῷδε· ἐπεὰν ἅμαξαν φρυγάνων πλήσωσι καὶ ὑποζεύξωσι βοῦς, ἐμποδίσαντες τοὺς μάντιας καὶ χεῖρας ὀπίσω δήσαντες καὶ στομώσαντες κατεργνῦσι ἐς μέσα τὰ φρύγανα. ὑποπρήσαντες δὲ αὐτὰ ἀπιεῖσι φοβήσαντες τοὺς βοῦς. πολλοὶ μὲν δὴ συγκατακαίονται τοῖσι μάντισι βόες, πολλοὶ δὲ περικεκαυμένοι ἀποφεύγουσι, ἐπεὰν αὐτῶν ὁ ῥυμὸς κατακαυθῇ. κατακαίουσι δὲ τρόπῳ τῷ εἰρημένῳ καὶ δι’ ἄλλας αἰτίας τοὺς μάντιας, ψευδομάντιας καλέοντες. τοὺς δ’ ἂν ἀποκτείνῃ βασιλεύς, τούτων οὐδὲ τοὺς παῖδας λείπει, ἀλλὰ πάντα τὰ ἔρσενα κτείνει, τὰ δὲ θήλεα οὐκ ἀδικέει.", "st": "4.69"}, {"sp": "N", "t": "ὅρκια δὲ ποιεῦνται Σκύθαι ὧδε πρὸς τοὺς ἂν ποιέωνται· ἐς κύλικα μεγάλην κεραμίνην οἶνον ἐγχέαντες αἷμα συμμίσγουσι τῶν τὸ ὅρκιον ταμνομένων, τύψαντες ὑπέατι ἢ ἐπιταμόντες μαχαίρῃ σμικρὸν τοῦ σώματος, καὶ ἔπειτα ἀποβάψαντες ἐς τὴν κύλικα ἀκινάκην καὶ ὀιστοὺς καὶ σάγαριν καὶ ἀκόντιον· ἐπεὰν δὲ ταῦτα ποιήσωσι, κατεύχονται πολλὰ καὶ ἔπειτα ἀποπίνουσι αὐτοί τε οἱ τὸ ὅρκιον ποιεύμενοι καὶ τῶν ἑπομένων οἱ πλείστου ἄξιοι.", "st": "4.70"}, {"sp": "N", "t": "ταφαὶ δὲ τῶν βασιλέων ἐν Γέρροισι εἰσὶ ἐς ὃ ὁ Βορυσθένης ἐστὶ προσπλωτός· ἐνθαῦτα, ἐπεάν σφι ἀποθάνῃ ὁ βασιλεύς, ὄρυγμα γῆς μέγα ὀρύσσουσι τετράγωνον, ἕτοιμον δὲ τοῦτο ποιήσαντες ἀναλαμβάνουσι τὸν νεκρόν, κατακεκηρωμένον μὲν τὸ σῶμα, τὴν δὲ νηδὺν ἀνασχισθεῖσαν καὶ καθαρθεῖσαν, πλέην κυπέρου κεκομμένου καὶ θυμιήματος καὶ σελίνου σπέρματος καὶ ἀννήσου, συνερραμμένην ὀπίσω, καὶ κομίζουσι ἐν ἁμάξῃ ἐς ἄλλο ἔθνος. οἳ δὲ ἂν παραδέξωνται κομισθέντα τὸν νεκρόν, ποιεῦσι τά περ οἱ βασιλήιοι Σκύθαι· τοῦ ὠτὸς ἀποτάμνονται, τρίχας περικείρονται, βραχίονας περιτάμνονται, μέτωπον καὶ ῥῖνα καταμύσσονται, διὰ τῆς ἀριστερῆς χειρὸς ὀιστοὺς διαβυνέονται. ἐνθεῦτεν δὲ κομίζουσι ἐν τῇ ἀμάξῃ τοῦ βασιλέος τὸν νέκυν ἐς ἄλλο ἔθνος τῶν ἄρχουσι· οἳ δέ σφι ἕπονται ἐς τοὺς πρότερον ἦλθον. ἐπεὰν δὲ πάντας περιέλθωσι τὸν νέκυν κομίζοντες, ἔν τε Γέρροισι ἔσχατα κατοικημένοισι εἰσὶ τῶν ἐθνέων τῶν ἄρχουσι καὶ ἐν τῇσι ταφῇσι. καὶ ἔπειτα, ἐπεὰν θέωσι τὸν νέκυν ἐν τῇσι θήκῃσι ἐπὶ στιβάδος, παραπήξαντες αἰχμὰς ἔνθεν καὶ ἔνθεν τοῦ νεκροῦ ξύλα ὑπερτείνουσι καὶ ἔπειτα ῥιψὶ καταστεγάζουσι, ἐν δὲ τῇ λοιπῇ εὐρυχωρίῃ τῆς θήκης τῶν παλλακέων τε μίαν ἀποπνίξαντες θάπτουσι καὶ τὸν οἰνοχόον καὶ μάγειρον καὶ ἱπποκόμον καὶ διήκονον καὶ ἀγγελιηφόρον καὶ ἵππους καὶ τῶν ἄλλων πάντων ἀπαρχὰς καὶ φιάλας χρυσέας· ἀργύρῳ δὲ οὐδὲν οὐδὲ χαλκῷ χρέωνται. ταῦτα δὲ ποιήσαντες χοῦσι πάντες χῶμα μέγα, ἁμιλλώμενοι καὶ προθυμεόμενοι ὡς μέγιστον ποιῆσαι.", "st": "4.71"}, {"sp": "N", "t": "ἐνιαυτοῦ δὲ περιφερομένου αὖτις ποιεῦσι τοιόνδε· λαβόντες τῶν λοιπῶν θεραπόντων τοὺς ἐπιτηδεοτάτους (οἳ δὲ εἰσὶ Σκύθαι ἐγγενέες· οὗτοι γὰρ θεραπεύουσι τοὺς ἂν αὐτὸς ὁ βασιλεὺς κελεύσῃ ἀργυρώνητοι δὲ οὐκ εἰσί σφι θεράποντες), τούτων ὦν τῶν διηκόνων ἐπεὰν ἀποπνίξωσι πεντήκοντα καὶ ἵππους τοὺς καλλίστους πεντήκοντα, ἐξελόντες αὐτῶν τὴν κοιλίην καὶ καθήραντες ἐμπιπλᾶσι ἀχύρων καὶ συρράπτουσι. ἁψῖδος δὲ ἥμισυ ἐπὶ δύο ξύλα στήσαντες ὕπτιον καὶ τὸ ἕτερον ἥμισυ τῆς ἁψῖδος ἐπ’ ἕτερα δύο, καταπήξαντες τρόπῳ τοιούτῳ πολλὰ ταῦτα, ἔπειτα τῶν ἵππων κατὰ τὰ μήκεα ξύλα παχέα διελάσαντες μέχρι τῶν τραχήλων ἀναβιβάζουσι αὐτοὺς ἐπὶ τὰς ἁψῖδας· τῶν δὲ αἱ μὲν πρότεραι ἀψῖδες ὑπέχουσι τοὺς ὤμους τῶν ἵππων, αἱ δὲ ὄπισθε παρὰ τοὺς μηροὺς τὰς γαστέρας ὑπολαμβάνουσι· σκέλεα δὲ ἀμφότερα κατακρέμαται μετέωρα. χαλινοὺς δὲ καὶ στόμια ἐμβαλόντες ἐς τοὺς ἵππους κατατείνουσι ἐς τὸ πρόσθε αὐτῶν καὶ ἔπειτα ἐκ πασσάλων δέουσι. τῶν δὲ δὴ νεηνίσκων τῶν ἀποπεπνιγμένων τῶν πεντήκοντα ἕνα ἕκαστον ἀναβιβάζουσι ἐπὶ τὸν ἵππον, ὧδε ἀναβιβάζοντες, ἐπεὰν νεκροῦ ἑκάστου παρὰ τὴν ἄκανθαν ξύλον ὀρθὸν διελάσωσι μέχρι τοῦ τραχήλου· κάτωθεν δὲ ὑπερέχει τοῦ ξύλου τούτου τὸ ἐς τόρμον πηγνύουσι τοῦ ἑτέρου ξύλου τοῦ διὰ τοῦ ἵππου. ἐπιστήσαντες δὲ κύκλῳ τὸ σῆμα ἱππέας τοιούτους ἀπελαύνουσι.", "st": "4.72"}, {"sp": "N", "t": "οὕτω μὲν τοὺς βασιλέας θάπτουσι· τοὺς δὲ ἄλλους Σκύθας, ἐπεὰν ἀποθάνωσι, περιάγουσι οἱ ἀγχοτάτω προσήκοντες κατὰ τοὺς φίλους ἐν ἀμάξῃσι κειμένους. τῶν δὲ ἕκαστος ὑποδεκόμενος εὐωχέει τοὺς ἑπομένους, καὶ τῷ νεκρῷ ἁπάντων παραπλησίως παρατίθησι ὅσα τοῖσι ἄλλοισι. ἡμέρας δὲ τεσσεράκοντα οὕτω οἱ ἰδιῶται περιάγονται, ἔπειτα θάπτονται. θάψαντες δὲ οἱ Σκύψαι καθαίρονται τρόπῳ τοιῷδε. σμησάμενοι τὰς κεφαλὰς καὶ ἐκπλυνάμενοι ποιεῦσι περὶ τὸ σῶμα τάδε ἐπεὰν ξύλα στήσωσι τρία ἐς ἄλληλα κεκλιμένα, περὶ ταῦτα πίλους εἰρινέους περιτείνουσι, συμφράξαντες δὲ ὡς μάλιστα λίθους ἐκ πυρὸς διαφανέας ἐσβάλλουσι ἐς σκάφην κειμένην ἐν μέσῳ τῶν ξύλων τε καὶ τῶν πίλων.", "st": "4.73"}, {"sp": "N", "t": "ἔστι δέ σφι κάνναβις φυομένη ἐν τῇ χώρῃ πλὴν παχύτητος καὶ μεγάθεος τῷ λίνῳ ἐμφερεστάτη· ταύτῃ δὲ πολλῷ ὑπερφέρει ἡ κάνναβις. αὕτη καὶ αὐτομάτη καὶ σπειρομένη φύεται, καὶ ἐξ αὐτῆς Θρήικες μὲν καὶ εἵματα ποιεῦνται τοῖσι λινέοισι ὁμοιότατα· οὐδ’ ἄν, ὅστις μὴ κάρτα τρίβων εἴη αὐτῆς, διαγνοίη λίνου ἢ καννάβιος ἐστί· ὃς δὲ μὴ εἶδε κω τὴν κανναβίδα, λίνεον δοκήσει εἶναι τὸ εἷμα.", "st": "4.74"}, {"sp": "N", "t": "ταύτης ὦν οἱ Σκύθαι τῆς καννάβιος τὸ σπέρμα ἐπεὰν λάβωσι, ὑποδύνουσι ὑπὸ τοὺς πίλους, καὶ ἔπειτα ἐπιβάλλουσι τὸ σπέρμα ἐπὶ τοὺς διαφανέας λίθους τῷ πυρί· τὸ δὲ θυμιᾶται ἐπιβαλλόμενον καὶ ἀτμίδα παρέχεται τοσαύτην ὥστε Ἑλληνικὴ οὐδεμία ἄν μιν πυρίη ἀποκρατήσειε. οἱ δὲ Σκύθαι ἀγάμενοι τῇ πυρίῃ ὠρύονται. τοῦτό σφι ἀντὶ λουτροῦ ἐστι. οὐ γὰρ δὴ λούονται ὕδατι τὸ παράπαν τὸ σῶμα. αἱ δὲ γυναῖκες αὐτῶν ὕδωρ παραχέουσαι κατασώχουσι περὶ λίθον τρηχὺν τῆς κυπαρίσσου καὶ κέδρου καὶ λιβάνου ξύλου, καὶ ἔπειτα τὸ κατασωχόμενον τοῦτο παχὺ ἐὸν καταπλάσσονται πᾶν τὸ σῶμα καὶ τὸ πρόσωπον· καὶ ἅμα μὲν εὐωδίη σφέας ἀπὸ τούτου ἴσχει, ἅμα δὲ ἀπαιρέουσαι τῇ δευτέρῃ ἡμέρῃ τὴν καταπλαστὺν γίνονται καθαραὶ καὶ λαμπραί.", "st": "4.75"}, {"sp": "N", "t": "ξεινικοῖσι δὲ νομαίοισι καὶ οὗτοι φεύγουσι αἰνῶς χρᾶσθαι, μήτε τεῶν ἄλλων, Ἑλληνικοῖσι δὲ καὶ ἥκιστα, ὡς διέδεξαν Ἀνάχαρσις τε καὶ δεύτερα αὖτις Σκύλης. τοῦτο μὲν γὰρ Ἀνάχαρσις ἐπείτε γῆν πολλὴν θεωρήσας καὶ ἀποδεξάμενος κατ’ αὐτὴν σοφίην πολλὴν ἐκομίζετο ἐς ἤθεα τὰ Σκυθέων, πλέων δι’ Ἑλλησπόντου προσίσχει ἐς Κύζικον. καὶ εὗρε γὰρ τῇ μητρὶ τῶν θεῶν ἀνάγοντας τοὺς Κυζικηνοὺς ὁρτὴν μεγαλοπρεπέως κάρτα, εὔξατο τῇ μητρὶ ὁ Ἀνάχαρσις, ἢν σῶς καὶ ὑγιὴς ἀπονοστήσῃ ἐς ἑωυτοῦ, θύσειν τε κατὰ ταὐτὰ κατὰ ὥρα τοὺς Κυζικηνοὺς ποιεῦντας καὶ παννυχίδα στήσειν. ὡς δὲ ἀπίκετο ἐς τὴν Σκυθικήν καταδὺς ἐς τὴν καλεομένην Ὑλαίην (ἡ δ’ ἔστι μὲν παρὰ τὸν Ἀχιλλήιον δρόμον, τυγχάνει δὲ πᾶσα ἐοῦσα δενδρέων παντοίων πλέη), ἐς ταύτην δὴ καταδὺς ὁ Ἀνάχαρσις τὴν ὁρτὴν ἐπετέλεε πᾶσαν τῇ θεῷ, τύμπανον τε ἔχων καὶ ἐκδησάμενος ἀγάλματα. καὶ τῶν τις Σκυθέων καταφρασθεὶς αὐτὸν ταῦτα ποιεῦντα ἐσήμηνε τῷ βασιλέι Σαυλίω· ὁ δὲ καὶ αὐτὸς ἀπικόμενος ὡς εἶδε τὸν Ἀνάχαρσιν ποιεῦντα ταῦτα, τοξεύσας αὐτὸν ἀπέκτεινε. καὶ νῦν ἤν τις εἴρηται περὶ Ἀναχάρσιος, οὐ φασί μιν Σκύθαι γινώσκειν, διὰ τοῦτο ὅτι ἐξεδήμησέ τε ἐς τὴν Ἑλλάδα καὶ ξεινικοῖσι ἔθεσι διεχρήσατο. ὡς δ’ ἐγὼ ἤκουσα Τύμνεω τοῦ Ἀριαπείθεος ἐπιτρόπου, εἶναι αὐτὸν Ἰδανθύρσου τοῦ Σκυθέων βασιλέος πάτρων, παῖδα δὲ εἶναι Γνούρου τοῦ Λύκου τοῦ Σπαργαπείθεος. εἰ ὦν ταύτης ἦν τῆς οἰκίης ὁ Ἀνάχαρσις, ἴστω ὑπὸ τοῦ ἀδελφεοῦ ἀποθανών· Ἰδάνθυρσος γὰρ ἦν παῖς Σαυλίου, Σαύλιος δὲ ἦν ὁ ἀποκτείνας Ἀνάχαρσιν.", "st": "4.76"}, {"sp": "N", "t": "καίτοι τινὰ ἤδη ἤκουσα λόγον ἄλλον ὑπὸ Πελοποννησίων λεγόμενον, ὡς ὑπὸ τοῦ Σκυθέων βασιλέος Ἀνάχαρσις ἀποπεμφθεὶς τῆς Ἑλλάδος μαθητὴς γένοιτο, ὀπίσω τε ἀπονοστήσας φαίη πρὸς τὸν ἀποπέμψαντα Ἕλληνας πάντας ἀσχόλους εἶναι ἐς πᾶσαν σοφίην πλὴν Λακεδαιμονίων, τούτοισι δὲ εἶναι μούνοισι σωφρόνως δοῦναι τε καὶ δέξασθαι λόγον. ἀλλ’ οὗτος μὲν ὁ λόγος ἄλλως πέπλασται ὑπ’ αὐτῶν Ἑλλήνων, ὁ δ’ ὦν ἀνὴρ ὥσπερ πρότερον εἰρέθη διεφθάρη.", "st": "4.77"}, {"sp": "N", "t": "οὗτος μέν νυν οὕτω δὴ ἔπρηξε διὰ ξεινικά τε νόμαια καὶ Ἑλληνικὰς ὁμιλίας. πολλοῖσι δὲ κάρτα ἔτεσι ὕστερον Σκύλης ὁ Ἀριαπείθεος ἔπαθε παραπλήσια τούτῳ. Ἀριαπείθεϊ γὰρ τῷ Σκυθέων βασιλέι γίνεται μετ’ ἄλλων παίδων Σκύλης· ἐξ Ἰστριηνῆς δὲ γυναικὸς οὗτος γίνεται καὶ οὐδαμῶς ἐγχωρίης· τὸν ἡ μήτηρ αὕτη γλῶσσάν τε Ἑλλάδα καὶ γράμματα ἐδίδαξε. μετὰ δὲ χρόνῳ ὕστερον Ἀριαπείθης μὲν τελευτᾷ δόλῳ ὑπὸ Σπαργαπείθεος τοῦ Ἀγαθύρσων βασιλέος, Σκύλης δὲ τήν τε βασιληίην παρέλαβε καὶ τὴν γυναῖκα τοῦ πατρός, τῇ οὔνομα ἦν Ὀποίη· ἦν δὲ αὕτη ἡ Ὀποίη ἀστή, ἐξ ἧς ἦν Ὄρικος Ἀριαπείθεϊ παῖς. βασιλεύων δὲ Σκυθέων ὁ Σκύλης διαίτῃ οὐδαμῶς ἠρέσκετο Σκυθικῇ, ἀλλὰ πολλὸν πρὸς τὰ Ἑλληνικὰ μᾶλλον τετραμμένος ἦν ἀπὸ παιδεύσιος τῆς ἐπεπαίδευτο, ἐποίεέ τε τοιοῦτο· εὖτε ἀγάγοι τὴν στρατιὴν τὴν Σκυθέων ἐς τὸ Βορυσθενειτέων ἄστυ (οἱ δὲ Βορυσθενεῗται οὗτοι λέγουσι σφέας αὐτοὺς εἶναι Μιλησίους), ἐς τούτους ὅκως ἔλθοι ὁ Σκύλης, τὴν μὲν στρατιὴν καταλίπεσκε ἐν τῷ προαστείῳ, αὐτὸς δὲ ὅκως ἔλθοι ἐς τὸ τεῖχος καὶ τὰς πύλας ἐγκλῄσειε, τὴν στολὴν ἀποθέμενος τὴν Σκυθικὴν λάβεσκε ἂν Ἑλληνίδα ἐσθῆτα, ἔχων δ’ ἂν ταύτην ἠγόραζε οὔτε δορυφόρων ἑπομένων οὔτε ἄλλου οὐδενός· τὰς δὲ πύλας ἐφύλασσον, μή τίς μιν Σκυθέων ἴδοι ἔχοντα ταύτην τὴν στολήν· καὶ τά τε ἄλλα ἐχρᾶτο διαίτῃ Ἑλληνικῇ καὶ θεοῖσι ἱρὰ ἐποίεε κατὰ νόμους τοὺς Ἑλλήνων. ὅτε δὲ διατρίψειε μῆνα ἢ πλέον τούτου, ἀπαλλάσσετο ἐνδὺς τὴν Σκυθικὴν στολήν. ταῦτα ποιέεσκε πολλάκις καὶ οἰκία τε ἐδείματο ἐν Βορυσθένεϊ καὶ γυναῖκα ἔγημε ἐς αὐτὰ ἐπιχωρίην.", "st": "4.78"}, {"sp": "N", "t": "ἐπείτε δὲ ἔδεέ οἱ κακῶς γενέσθαι, ἐγίνετο ἀπὸ προφάσιος τοιῆσδε. ἐπεθύμησε Διονύσῳ Βακχείῳ τελεσθῆναι· μέλλοντι δέ οἱ ἐς χεῖρας ἄγεσθαι τὴν τελετὴν ἐγένετο φάσμα μέγιστον. ἦν οἱ ἐν Βορυσθενεϊτέων τῇ πόλι οἰκίης μεγάλης καὶ πολυτελέος περιβολή, τῆς καὶ ὀλίγῳ τι πρότερον τούτων μνήμην εἶχον, τὴν πέριξ λευκοῦ λίθου σφίγγες τε καὶ γρῦπες ἕστασαν· ἐς ταύτην ὁ θεὸς ἐνέσκηψε βέλος. καὶ ἣ μὲν κατεκάη πᾶσα, Σκύλης δὲ οὐδὲν τούτου εἵνεκα ἧσσον ἐπετέλεσε τὴν τελετήν. Σκύθαι δὲ τοῦ βακχεύειν πέρι Ἕλλησι ὀνειδίζουσι· οὐ γὰρ φασὶ οἰκὸς εἶναι θεὸν ἐξευρίσκειν τοῦτον ὅστις μαίνεσθαι ἐνάγει ἀνθρώπους. ἐπείτε δὲ ἐτελέσθη τῷ Βακχείῳ ὁ Σκύλης, διεπρήστευσε τῶν τις Βορυσθενειτέων πρὸς τοὺς Σκύθας λέγων ἡμῖν γὰρ καταγελᾶτε, ὦ Σκύθαι, ὅτι βακχεύομεν καὶ ἡμέας ὁ θεὸς λαμβάνει· νῦν οὗτος ὁ δαίμων καὶ τὸν ὑμέτερον βασιλέα λελάβηκε, καὶ βακχεύει τε καὶ ὑπὸ τοῦ θεοῦ μαίνεται. εἰ δέ μοι ἀπιστέετε, ἕπεσθε, καὶ ὑμῖν ἐγὼ δέξω. εἵποντο τῶν Σκύθεων οἱ προεστεῶτες, καὶ αὐτοὺς ἀναγαγὼν ὁ Βορυσθενεΐτης λάθρῃ ἐπὶ πύργον κατεῖσε. ἐπείτε δὲ παρήιε σὺν τῷ θιάσῳ ὁ Σκύλης καὶ εἶδόν μιν βακχεύοντα οἱ Σκύθαι, κάρτα συμφορὴν μεγάλην ἐποιήσαντο, ἐξελθόντες δὲ ἐσήμαινον πάσῃ τῇ στρατιῇ τὰ ἴδοιεν.", "st": "4.79"}, {"sp": "N", "t": "ὡς δὲ μετὰ ταῦτα ἐξήλαυνε ὁ Σκύλης ἐς ἤθεα τὰ ἑωυτοῦ, οἱ Σκύθαι προστησάμενοι τὸν ἀδελφεὸν αὐτοῦ Ὀκταμασάδην, γεγονότα ἐκ τῆς Τήρεω θυγατρός, ἐπανιστέατο τῷ Σκύλῃ. ὁ δὲ μαθὼν τὸ γινόμενον ἐπ’ ἑωυτῷ καὶ τὴν αἰτίην δι’ ἣν ἐποιέετο, καταφεύγει ἐς τὴν Θρηίκην. πυθόμενος δὲ ὁ Ὀκταμασάδης ταῦτα ἐστρατεύετο ἐπὶ τὴν Θρηίκην. ἐπείτε δὲ ἐπὶ τῷ Ἴστρῳ ἐγένετο, ἠντίασάν μιν οἱ Θρήικες, μελλόντων δὲ αὐτῶν συνάψειν ἔπεμψε Σιτάλκης παρὰ τὸν Ὀκταμασάδην λέγων τοιάδε. τι δεῖ ἡμέας ἀλλήλων πειρηθῆναι; εἶς μέν μευ τῆς ἀδελφεῆς παῖς, ἔχεις δέ μευ ἀδελφεόν. σὺ δέ μοι ἀπόδος τοῦτον, καὶ ἐγὼ σοὶ τὸν σὸν Σκύλην παραδίδωμι· στρατιῇ δὲ μήτε σὺ κινδυνεύσῃς μήτ’ ἐγώ. ταῦτά οἱ πέμψας ὁ Σιτάλκης ἐπεκηρυκεύετο· ἦν γὰρ παρὰ τῷ Ὀκταμασάδη ἀδελφεὸς Σιτάλκεω πεφευγώς. ὁ δὲ Ὀκταμασάδης καταινέει ταῦτα, ἐκδοὺς δὲ τὸν ἑωυτοῦ μήτρωα Σιτάλκῃ ἔλαβε τὸν ἀδελφεὸν Σκύλην. καὶ Σιτάλκης μὲν παραλαβὼν τὸν ἀδελφεὸν ἀπήγετο, Σκύλεω δὲ Ὀκταμασάδης αὐτοῦ ταύτῃ ἀπέταμε τὴν κεφαλήν. οὕτω μὲν περιστέλλουσι τὰ σφέτερα νόμαια Σκύθαι, τοῖσι δὲ παρακτωμένοισι ξεινικοὺς νόμους τοιαῦτα ἐπιτίμια διδοῦσι.", "st": "4.80"}, {"sp": "N", "t": "πλῆθος δὲ τὸ Σκυθέων οὐκ οἷος τε ἐγενόμην ἀτρεκέως πυθέσθαι, ἀλλὰ διαφόρους λόγους περὶ τοῦ ἀριθμοῦ ἤκουον· καὶ γὰρ κάρτα πολλοὺς εἶναι σφέας καὶ ὀλίγους ὡς Σκύθας εἶναι. τοσόνδε μέντοι ἀπέφαινόν μοι ἐς ὄψιν. ἔστι μεταξὺ Βορυσθένεός τε ποταμοῦ καὶ Ὑπάνιος χῶρος, οὔνομα δέ οἱ ἐστὶ Ἐξαμπαῖος· τοῦ καὶ ὀλίγῳ τι πρότερον τούτων μνήμην εἶχον, φάμενος ἐν αὐτῷ κρήνην ὕδατος πικροῦ εἶναι, ἀπ’ ἧς τὸ ὕδωρ ἀπορρέον τὸν Ὕπανιν ἄποτον ποιέειν. ἐν τούτῳ τῷ χώρῳ κέεται χαλκήιον, μεγάθει καὶ ἑξαπλήσιον τοῦ ἐπὶ στόματι τοῦ Πόντου κρητῆρος, τὸν Παυσανίης ὁ Κλεομβρότου ἀνέθηκε. ὃς δὲ μὴ εἶδε κω τοῦτον, ὧδε δηλώσω. ἑξακοσίους ἀμφορέας εὐπετέως χωρέει τὸ ἐν Σκύθῃσι χαλκήιον, πάχος δὲ τὸ Σκυθικὸν τοῦτο χαλκήιον ἐστὶ δακτύλων ἕξ. τοῦτο ὦν ἔλεγον οἱ ἐπιχώριοι ἀπὸ ἀρδίων γενέσθαι. βουλόμενον γὰρ τὸν σφέτερον βασιλέα, τῶ οὔνομα εἶναι Ἀριάνταν, τοῦτον εἰδέναι τὸ πλῆθος τὸ Σκυθέων κελεύειν μιν πάντας Σκύθας ἄρδιν ἕκαστον μίαν ἀπὸ τοῦ ὀιστοῦ κομίσαι. ὃς δ’ ἄν μὴ κομίσῃ, θάνατον ἀπείλεε. κομισθῆναι τε δὴ χρῆμα πολλὸν ἀρδίων καί οἱ δόξαι ἐξ αὐτέων μνημόσυνον ποιήσαντι λιπέσθαι. ἐκ τουτέων δή μιν τὸ χαλκήιον ποιῆσαι τοῦτο καὶ ἀναθεῖναι ἐς τὸν Ἐξαμπαῖον τοῦτον. ταῦτα δὲ περὶ τοῦ πλήθεος τοῦ Σκυθέων ἤκουον.", "st": "4.81"}, {"sp": "N", "t": "θωμάσια δὲ ἡ χώρη αὕτη οὐκ ἔχει, χωρὶς ἢ ὅτι ποταμούς τε πολλῷ μεγίστους καὶ ἀριθμὸν πλείστους. τὸ δὲ ἀποθωμάσαι ἄξιον καὶ πάρεξ τῶν ποταμῶν καὶ τοῦ μεγάθεος τοῦ πεδίου παρέχεται, εἰρήσεται. ἴχνος Ἡρακλέος φαίνουσι ἐν πέτρῃ ἐνεόν, τὸ ἔοικε μὲν βήματι ἀνδρός, ἔστι δὲ τὸ μέγαθος δίπηχυ, παρὰ τὸν Τύρην ποταμόν. τοῦτο μέν νυν τοιοῦτο ἐστί, ἀναβήσομαι δὲ ἐς τὸν κατ’ ἀρχὰς ἤια λέξων λόγον.", "st": "4.82"}, {"sp": "N", "t": "παρασκευαζομένου Δαρείου ἐπὶ τοὺς Σκύθας καὶ ἐπιπέμποντος ἀγγέλους ἐπιτάξοντας τοῖσι μὲν πεζὸν στρατόν, τοῖσι δὲ νέας παρέχειν, τοῖσι δὲ ζεύγνυσθαι τὸν Θρηίκιον Βόσπορον Ἀρτάβανος ὁ Ὑστάσπεος, ἀδελφεὸς ἐὼν Δαρείου, ἐχρήιζε μηδαμῶς αὐτὸν στρατηίην ἐπὶ Σκύθας ποιέεσθαι, καταλέγων τῶν Σκυθέων τὴν ἀπορίην. ἀλλ’ οὐ γὰρ ἔπειθε συμβουλεύων οἱ χρηστά, ὃ μὲν ἐπέπαυτο, ὁ δέ, ἐπειδή οἱ τὰ ἅπαντα παρεσκεύαστο, ἐξήλαυνε τὸν στρατὸν ἐκ Σούσων.", "st": "4.83"}, {"sp": "N", "t": "ἐνθαῦτα τῶν Περσέων Οἰόβαζος ἐδεήθη Δαρείου τριῶν ἐόντων οἱ παίδων καὶ πάντων στρατευομένων ἕνα αὐτῷ καταλειφθῆναι. ὁ δὲ ἔφη ὡς φίλῳ ἐόντι καὶ μετρίων δεομένῳ πάντας τοὺς παῖδας καταλείψειν. ὁ μὲν δὴ Οἰόβαζος περιχαρὴς ἦν, ἐλπίζων τοὺς υἱέας στρατηίης ἀπολελύσθαι. ὁ δὲ ἐκέλευσε τοὺς ἐπὶ τούτων ἐπεστεῶτας ἀποκτεῖναι πάντας τοὺς Οἰοβάζου παῖδας.", "st": "4.84"}, {"sp": "N", "t": "καὶ οὗτοι μὲν ἀποσφαγέντες αὐτοῦ ταύτῃ ἐλείποντο· Δαρεῖος δὲ ἐπείτε πορευόμενος ἐκ Σούσων ἀπίκετο τῆς Καλχηδονίης ἐπὶ τὸν Βόσπορον ἵνα ἔζευκτο ἡ γέφυρα, ἐνθεῦτεν ἐσβὰς ἐς νέα ἔπλεε ἐπὶ τὰς Κυανέας καλευμένας, τὰς πρότερον πλαγκτὰς Ἕλληνες φασὶ εἶναι, ἑζόμενος δὲ ἐπὶ ῥίῳ ἐθηεῖτο τὸν Πόντον ἐόντα ἀξιοθέητον. πελαγέων γὰρ ἁπάντων πέφυκε θωμασιώτατος· τοῦ τὸ μὲν μῆκος στάδιοι εἰσὶ ἑκατὸν καὶ χίλιοι καὶ μύριοι, τὸ δὲ εὖρος, τῇ εὐρύτατος αὐτὸς ἑωυτοῦ, στάδιοι τριηκόσιοι καὶ τρισχίλιοι. τούτου τοῦ πελάγεος τὸ στόμα ἐστὶ εὖρος τέσσερες στάδιοι· μῆκος δὲ, τοῦ στόματος ὁ αὐχήν, τὸ δὴ Βόσπορος κέκληται, κατ’ ὃ δὴ ἔζευκτο ἡ γέφυρα, ἐπὶ σταδίους εἴκοσι καὶ ἑκατόν ἐστι. τείνει δ’ ἐς τὴν Προποντίδα ὁ Βόσπορος· ἡ δὲ Προποντὶς ἐοῦσα εὖρος μὲν σταδίων πεντακοσίων, μῆκος δὲ τετρακοσίων καὶ χιλίων, καταδιδοῖ ἐς τὸν Ἑλλήσποντον ἐόντα στεινότητα μὲν ἑπτὰ σταδίους, μῆκος δὲ τετρακοσίους. ἐκδιδοῖ δὲ ὁ Ἑλλήσποντος ἐς χάσμα πελάγεος τὸ δὴ Αἰγαῖον καλέεται.", "st": "4.85"}, {"sp": "N", "t": "μεμέτρηται δὲ ταῦτα ὧδε. νηῦς ἐπίπαν μάλιστα κῃ κατανύει ἐν μακρημερίῃ ὀργυιὰς ἑπτακισμυρίας, νυκτὸς δὲ ἑξακισμυρίας. ἤδη ὦν ἐς μὲν Φᾶσιν ἀπὸ τοῦ στόματος (τοῦτο γὰρ ἐστὶ τοῦ Πόντου μακρότατον) ἡμερέων ἐννέα πλόος ἐστὶ καὶ νυκτῶν ὀκτώ· αὗται ἕνδεκα μυριάδες καὶ ἑκατὸν ὀργυιέων γίνονται, ἐκ δὲ τῶν ὀργυιέων τουτέων στάδιοι ἑκατὸν καὶ χίλιοι καὶ μύριοι εἰσί. ἐς δὲ Θεμισκύρην τὴν ἐπὶ Θερμώδοντι ποταμῷ ἐκ τῆς Σινδικῆς (κατὰ τοῦτο γὰρ ἐστὶ τοῦ Πόντου εὐρύτατον) τριῶν τε ἡμερέων καὶ δύο νυκτῶν πλόος· αὗται δὲ τρεῖς μυριάδες καὶ τριήκοντα ὀργυιέων γίνονται, στάδιοι δὲ τριηκόσιοι καὶ τρισχίλιοι. ὁ μέν νυν Πόντος οὗτος καὶ Βόσπορός τε καὶ Ἑλλήσποντος οὕτω τέ μοι μεμετρέαται καὶ κατὰ τὰ εἰρημένα πεφύκασι, παρέχεται δὲ καὶ λίμνην ὁ Πόντος οὗτος ἐκδιδοῦσαν ἐς αὐτὸν οὐ πολλῷ τεῳ ἐλάσσω ἑωυτοῦ, ἣ Μαιῆτίς τε καλέεται καὶ μήτηρ τοῦ Πόντου.", "st": "4.86"}, {"sp": "N", "t": "ὁ δὲ Δαρεῖος ὡς ἐθεήσατο τὸν Πόντον, ἔπλεε ὀπίσω ἐπὶ τὴν γέφυραν, τῆς ἀρχιτέκτων ἐγένετο Μανδροκλέης Σάμιος· θεησάμενος δὲ καὶ τὸν Βόσπορον στήλας ἔστησε δύο ἐπ’ αὐτοῦ λίθου λευκοῦ, ἐνταμὼν γράμματα ἐς μὲν τὴν Ἀσσύρια ἐς δὲ τὴν Ἑλληνικά, ἔθνεα πάντα ὅσα περ ἦγε· ἦγε δὲ πάντα τῶν ἦρχε. τούτων μυριάδες ἐξηριθμήθησαν, χωρὶς τοῦ ναυτικοῦ, ἑβδομήκοντα σὺν ἱππεῦσι, νέες δὲ ἑξακόσιαι συνελέχθησαν. τῇσι μέν νυν στήλῃσι ταύτῃσι Βυζάντιοι κομίσαντες ἐς τὴν πόλιν ὕστερον τούτων ἐχρήσαντο πρὸς τὸν βωμὸν τῆς Ὀρθωσίης Ἀρτέμιδος, χωρὶς ἑνὸς λίθου· οὗτος δὲ κατελείφθη παρὰ τοῦ Διονύσου τὸν νηὸν ἐν Βυζαντίῳ, γραμμάτων Ἀσσυρίων πλέος. τοῦ δὲ Βοσπόρου ὁ χῶρος τὸν ἔζευξε βασιλεὺς Δαρεῖος, ὡς ἐμοὶ δοκέει συμβαλλομένῳ, μέσον ἐστὶ Βυζαντίου τε καὶ τοῦ ἐπὶ στόματι ἱροῦ.", "st": "4.87"}, {"sp": "N", "t": "Δαρεῖος δὲ μετὰ ταῦτα ἡσθεὶς τῇ σχεδίῃ τὸν ἀρχιτέκτονα αὐτῆς Μανδροκλέα τὸν Σάμιον ἐδωρήσατο πᾶσι δέκα· ἀπ’ ὧν δὴ Μανδροκλέης ἀπαρχὴν ζῷα γραψάμενος πᾶσαν τὴν ζεῦξιν τοῦ Βοσπόρου καὶ βασιλέα τε Δαρεῖον ἐν προεδρίῃ κατήμενον καὶ τὸν στρατὸν αὐτοῦ διαβαίνοντα ταῦτα γραψάμενος ἀνέθηκε ἔς τὸ Ἥραιον, ἐπιγράψας τάδε.", "st": "4.88"}, {"sp": "N", "t": "Βόσπορον ἰχθυόεντα γεφυρώσας ἀνέθηκε<br>Μανδροκλέης Ἥρῃ μνημόσυνον σχεδίης,<br>αὑτῷ μὲν στέφανον περιθείς, Σαμίοισι δὲ κῦδος,<br>Δαρείου βασιλέος ἐκτελέσας κατὰ νοῦν.", "st": "4.88.2"}, {"sp": "N", "t": "ταῦτα μέν νυν τοῦ ζεύξαντος τὴν γέφυραν μνημόσυνα ἐγένετο. Δαρεῖος δὲ δωρησάμενος Μανδροκλέα διέβαινε ἐς τὴν Εὐρώπην, τοῖσι Ἴωσι παραγγείλας πλέειν ἐς τὸν Πόντον μέχρι Ἴστρου ποταμοῦ, ἐπεὰν δὲ ἀπίκωνται ἐς τὸν Ἴστρον, ἐνθαῦτα αὐτὸν περιμένειν ζευγνύντας τὸν ποταμόν. τὸ γὰρ δὴ ναυτικὸν ἦγον Ἴωνές τε καὶ Αἰολέες καὶ Ἑλλησπόντιοι. ὁ μὲν δὴ ναυτικὸς στρατὸς Κυανέας διεκπλώσας ἔπλεε ἰθὺ τοῦ Ἴστρου, ἀναπλώσας δὲ ἀνὰ ποταμὸν δυῶν ἡμερέων πλόον ἀπὸ θαλάσσης, τοῦ ποταμοῦ τὸν αὐχένα, ἔκ τοῦ σχίζεται τὰ στόματα τοῦ Ἴστρου, ἐζεύγνυε. Δαρεῖος δὲ ὡς διέβη τὸν Βόσπορον κατὰ τὴν σχεδίην, ἐπορεύετο διὰ τῆς Θρηίκης, ἀπικόμενος δὲ ἐπὶ Τεάρου ποταμοῦ τὰς πηγὰς ἐστρατοπεδεύσατο ἡμέρας τρεῖς.", "st": "4.89"}, {"sp": "N", "t": "ὁ δὲ Τέαρος λέγεται ὑπὸ τῶν περιοίκων εἶναι ποταμῶν ἄριστος τὰ τε ἄλλα τὰ ἐς ἄκεσιν φέροντα καὶ δὴ καὶ ἀνδράσι καὶ ἵπποισι ψώρην ἀκέσασθαι. εἰσὶ δὲ αὐτοῦ αἱ πηγαὶ δυῶν δέουσαι τεσσεράκοντα, ἐκ πέτρης τῆς αὐτῆς ῥέουσαι, καὶ αἳ μὲν αὐτέων εἰσὶ ψυχραὶ αἳ δὲ θερμαί. ὁδὸς δ’ ἐπ’ αὐτάς ἐστι ἴση ἐξ Ἡραίου τε πόλιος τῆς παρὰ Περίνθῳ καὶ ἐξ Ἀπολλωνίης τῆς ἐν τῷ Εὐξείνῳ πόντῳ, δυῶν ἡμερέων ἑκατέρη. ἐκδιδοῖ δὲ ὁ Τέαρος οὗτος ἐς τὸν Κοντάδεσδον ποταμόν, ὁ δὲ Κοντάδεσδος ἐς τὸν Ἀγριάνην, ὁ δὲ Ἀγριάνης ἐς τὸν Ἕβρον, ὁ δὲ ἐς θάλασσαν τὴν παρ’ Αἴνῳ πόλι.", "st": "4.90"}, {"sp": "N", "t": "ἐπὶ τοῦτον ὦν τὸν ποταμὸν ἀπικόμενος ὁ Δαρεῖος ὡς ἐστρατοπεδεύσατο, ἡσθεὶς τῷ ποταμῷ στήλην ἔστησε καὶ ἐνθαῦτα, γράμματα ἐγγράψας λέγοντα τάδε. Τεάρου ποταμοῦ κεφαλαὶ ὕδωρ ἄριστόν τε καὶ κάλλιστον παρέχονται πάντων ποταμῶν· καὶ ἐπ’ αὐτὰς ἀπίκετο ἐλαύνων ἐπὶ Σκύθας στρατὸν ἀνὴρ ἄριστος τε καὶ κάλλιστος πάντων ἀνθρώπων, Δαρεῖος ὁ Ὑστάσπεος, Περσέων τε καὶ πάσης τῆς ἠπείρου βασιλεύς. ταῦτα δὲ ἐνθαῦτα ἐγράφη.", "st": "4.91"}, {"sp": "N", "t": "Δαρεῖος δὲ ἐνθεῦτεν ὁρμηθεὶς ἀπίκετο ἐπ’ ἄλλον ποταμὸν τῷ οὔνομα Ἀρτησκός ἐστι, ὃς διὰ Ὀδρυσέων ῥέει. ἐπὶ τοῦτον δὴ τὸν ποταμὸν ἀπικόμενος ἐποίησε τοιόνδε· ἀποδέξας χωρίον τῇ στρατιῇ ἐκέλευε πάντα ἄνδρα λίθον ἕνα παρεξιόντα τιθέναι ἐς τὸ ἀποδεδεγμένον τοῦτο χωρίον. ὡς δὲ ταῦτα ἡ στρατιὴ ἐπετέλεσε, ἐνθαῦτα κολωνοὺς μεγάλους τῶν λίθων καταλιπὼν ἀπήλαυνε τὴν στρατιήν.", "st": "4.92"}, {"sp": "N", "t": "πρὶν δὲ ἀπικέσθαι ἐπὶ τὸν Ἴστρον, πρώτους αἱρέει Γέτας τοὺς ἀθανατίζοντας. οἱ μὲν γὰρ τὸν Σαλμυδησσὸν ἔχοντες Θρήικες καὶ ὑπὲρ Ἀπολλωνίης τε καὶ Μεσαμβρίης πόλιος οἰκημένοι, καλεύμενοι δὲ Κυρμιάναι καὶ Νιψαῖοι, ἀμαχητὶ σφέας αὐτοὺς παρέδοσαν Δαρείῳ· οἱ δὲ Γέται πρὸς ἀγνωμοσύνην τραπόμενοι αὐτίκα ἐδουλώθησαν, Θρηίκων ἐόντες ἀνδρηιότατοι καὶ δικαιότατοι.", "st": "4.93"}, {"sp": "N", "t": "ἀθανατίζουσι δὲ τόνδε τὸν τρόπον· οὔτε ἀποθνήσκειν ἑωυτοὺς νομίζουσι ἰέναι τε τὸν ἀπολλύμενον παρὰ Σάλμοξιν δαίμονα· οἳ δὲ αὐτῶν τὸν αὐτὸν τοῦτον ὀνομάζουσι Γεβελέιζιν· διὰ πεντετηρίδος τε τὸν πάλῳ λαχόντα αἰεὶ σφέων αὐτῶν ἀποπέμπουσι ἄγγελον παρὰ τὸν Σάλμοξιν, ἐντελλόμενοι τῶν ἂν ἑκάστοτε δέωνται, πέμπουσι δὲ ὧδε· οἳ μὲν αὐτῶν ταχθέντες ἀκόντια τρία ἔχουσι, ἄλλοι δὲ διαλαβόντες τοῦ ἀποπεμπομένου παρὰ τὸν Σάλμοξιν τὰς χεῖρας καὶ τοὺς πόδας, ἀνακινήσαντες αὐτὸν μετέωρον ῥίπτουσι ἐς τὰς λόγχας. ἢν μὲν δὴ ἀποθάνῃ ἀναπαρείς, τοῖσι δὲ ἵλεος ὁ θεὸς δοκέει εἶναι· ἢν δὲ μὴ ἀποθάνῃ, αἰτιῶνται αὐτὸν τὸν ἄγγελον, φάμενοί μιν ἄνδρα κακὸν εἶναι, αἰτιησάμενοι δὲ τοῦτον ἄλλον ἀποπέμπουσι· ἐντέλλονται δὲ ἔτι ζῶντι. οὗτοι οἱ αὐτοὶ Θρήικες καὶ πρὸς βροντήν τε καὶ ἀστραπὴν τοξεύοντες ἄνω πρὸς τὸν οὐρανὸν ἀπειλέουσι τῷ θεῷ, οὐδένα ἄλλον θεὸν νομίζοντες εἶναι εἰ μὴ τὸν σφέτερον.", "st": "4.94"}, {"sp": "N", "t": "ὡς δὲ ἐγὼ πυνθάνομαι τῶν τὸν Ἑλλήσποντον οἰκεόντων Ἑλλήνων καὶ Πόντον, τὸν Σάλμοξιν τοῦτον ἐόντα ἄνθρωπον δουλεῦσαι ἐν Σάμῳ, δουλεῦσαι δὲ Πυθαγόρῃ τῷ Μνησάρχου, ἐνθεῦτεν δὲ αὐτὸν γενόμενον ἐλεύθερον χρήματα κτήσασθαι μεγάλα, κτησάμενον δὲ ἀπελθεῖν ἐς τὴν ἑωυτοῦ. ἅτε δὲ κακοβίων τε ἐόντων τῶν Θρηίκων καὶ ὑπαφρονεστέρων, τὸν Σάλμοξιν τοῦτον ἐπιστάμενον δίαιτάν τε Ἰάδα καὶ ἤθεα βαθύτερα ἢ κατὰ Θρήικας, οἷα Ἕλλησι τε ὁμιλήσαντα καὶ Ἑλλήνων οὐ τῷ ἀσθενεστάτῳ σοφιστῇ Πυθαγόρῃ, κατασκευάσασθαι ἀνδρεῶνα, ἐς τὸν πανδοκεύοντα τῶν ἀστῶν τοὺς πρώτους καὶ εὐωχέοντα ἀναδιδάσκειν ὡς οὔτε αὐτὸς οὔτε οἱ συμπόται αὐτοῦ οὔτε οἱ ἐκ τούτων αἰεὶ γινόμενοι ἀποθανέονται, ἀλλ’ ἥξουσι ἐς χῶρον τοῦτον ἵνα αἰεὶ περιεόντες ἕξουσι τὰ πάντα ἀγαθά. ἐν ᾧ δὲ ἐποίεε τὰ καταλεχθέντα καὶ ἔλεγε ταῦτα, ἐν τούτῳ κατάγαιον οἴκημα ἐποιέετο. ὡς δέ οἱ παντελέως εἶχε τὸ οἴκημα, ἐκ μὲν τῶν Θρηίκων ἠφανίσθη, καταβὰς δὲ κάτω ἐς τὸ κατάγαιον οἴκημα διαιτᾶτο ἐπ’ ἔτεα τρία· οἳ δὲ μιν ἐπόθεόν τε καὶ ἐπένθεον ὡς τεθνεῶτα. τετάρτω δὲ ἔτεϊ ἐφάνη τοῖσι Θρήιξι, καὶ οὕτω πιθανά σφι ἐγένετο τὰ ἔλεγε ὁ Σάλμοξις. ταῦτα φασί μιν ποιῆσαι.", "st": "4.95"}, {"sp": "N", "t": "ἐγὼ δὲ περὶ μὲν τούτου καὶ τοῦ καταγαίου οἰκήματος οὔτε ἀπιστέω οὔτε ὦν πιστεύω τι λίην, δοκέω δὲ πολλοῖσι ἔτεσι πρότερον τὸν Σάλμοξιν τοῦτον γενέσθαι Πυθαγόρεω. εἴτε δὲ ἐγένετό τις Σάλμοξις ἄνθρωπος, εἴτ’ ἐστὶ δαίμων τις Γέτῃσι οὗτος ἐπιχώριος, χαιρέτω. οὗτοι μὲν δὴ τρόπῳ τοιούτῳ χρεώμενοι ὡς ἐχειρώθησαν ὑπὸ Περσέων, εἵποντο τῷ ἄλλῳ στρατῷ.", "st": "4.96"}, {"sp": "N", "t": "Δαρεῖος δὲ ὡς ἀπίκετο καὶ ὁ πεζὸς ἅμ’ αὐτῷ στρατὸς ἐπὶ τὸν Ἴστρον, ἐνθαῦτα διαβάντων πάντων Δαρεῖος ἐκέλευσε τούς τε Ἴωνας τὴν σχεδίην λύσαντας ἕπεσθαι κατ’ ἤπειρον ἑωυτῷ καὶ τὸν ἐκ τῶν νεῶν στρατόν. μελλόντων δὲ τῶν Ἰώνων λύειν καὶ ποιέειν τὰ κελευόμενα, Κώης ὁ Ἐρξάνδρου στρατηγὸς ἐὼν Μυτιληναίων ἔλεξε Δαρείῳ τάδε, πυθόμενος πρότερον εἰ οἱ φίλον εἴη γνώμην ἀποδέκεσθαι παρὰ τοῦ βουλομένου ἀποδείκνυσθαι. ὦ βασιλεῦ, ἐπὶ γῆν γὰρ μέλλεις στρατεύεσθαι τῆς οὔτε ἀρηρομένον φανήσεται οὐδὲν οὔτε πόλις οἰκεομένη· σύ νυν γέφυραν ταύτην ἔα κατὰ χώρην ἑστάναι, φυλάκους αὐτῆς λιπὼν τούτους οἵπερ μιν ἔζευξαν. καὶ ἤν τε κατὰ νόον πρήξωμεν εὑρόντες Σκύθας, ἔστι ἄποδος ἡμῖν, ἤν τε καὶ μή σφεας εὑρεῖν δυνώμεθα, ἥ γε ἄποδος ἡμῖν ἀσφαλής· οὐ γὰρ ἔδεισά κω μὴ ἑσσωθέωμεν ὑπὸ Σκυθέων μάχῃ, ἁλλὰ μᾶλλον μὴ οὐ δυνάμενοι σφέας εὑρεῖν πάθωμεν τι ἀλώμενοι. καὶ τάδε λέγειν φαίη τις ἄν με ἐμεωυτοῦ εἵνεκεν, ὡς καταμένω· ἐγὼ δὲ γνώμην μὲν τὴν εὕρισκον ἀρίστην σοί, βασιλεῦ, ἐς μέσον φέρω, αὐτὸς μέντοι ἕψομαί τοι καὶ οὐκ ἂν λειφθείην. κάρτα τε ἥσθη τῇ γνώμῃ Δαρεῖος καὶ μιν ἀμείψατο τοῖσιδε. ξεῖνε Λέσβιε, σωθέντος ἐμεῦ ὀπίσω ἐς οἶκον τὸν ἐμὸν ἐπιφάνηθί μοι πάντως, ἵνα σε ἀντὶ χρηστῆς συμβουλίης χρηστοῖσι ἔργοισι ἀμείψωμαι.", "st": "4.97"}, {"sp": "N", "t": "ταῦτα δὲ εἴπας καὶ ἀπάψας ἅμματα ἑξήκοντα ἐν ἱμάντι καλέσας ἐς λόγους τοὺς Ἰώνων τυράννους ἔλεγε τάδε. ἄνδρες Ἴωνες, ἡ μὲν πρότερον γνώμη ἀποδεχθεῖσα ἐς τὴν γέφυραν μετείσθω μοι, ἔχοντες δὲ τὸν ἱμάντα τόνδε ποιέετε τάδε. ἐπεὰν ἐμὲ ἴδητε τάχιστα πορευόμενον ἐπὶ Σκύθας, ἀπὸ τούτου ἀρξάμενοι τοῦ χρόνου λύετε ἅμμα ἓν ἑκάστης ἡμέρης· ἢν δὲ ἐν τούτῳ τῷ χρόνῳ μὴ παρέω ἀλλὰ διεξέλθωσι ὑμῖν αἱ ἡμέραι τῶν ἁμμάτων, ἀποπλέετε ἐς τὴν ὑμετέρην αὐτῶν. μέχρι δὲ τούτου, ἐπείτε οὕτω μετέδοξε, φυλάσσετε τὴν σχεδίην, πᾶσαν προθυμίην σωτηρίης τε καὶ φυλακῆς παρεχόμενοι. ταῦτα δὲ ποιεῦντες ἐμοὶ μεγάλως χαριεῖσθε. Δαρεῖος μὲν ταῦτα εἴπας ἐς τὸ πρόσω ἐπείγετο.", "st": "4.98"}, {"sp": "N", "t": "τῆς δὲ Σκυθικῆς γῆς ἡ Θρηίκη τὸ ἐς θάλασσαν πρόκειται· κόλπου δὲ ἀγομένου τῆς γῆς ταύτης, ἡ Σκυθική τε ἐκδέκεται καὶ ὁ Ἴστρος ἐκδιδοῖ ἐς αὐτήν, πρὸς εὖρον ἄνεμον τὸ στόμα τετραμμένος. τὸ δὲ ἀπὸ Ἴστρου ἔρχομαι σημανέων τὸ πρὸς θάλασσαν αὐτῆς τῆς Σκυθικῆς χώρης ἐς μέτρησιν. ἀπὸ Ἴστρου αὕτη ἤδη ἡ ἀρχαίη Σκυθίη ἐστί, πρὸς μεσαμβρίην τε καὶ νότον ἄνεμον κειμένη, μέχρι πόλιος Καρκινίτιδος καλεομένης. τὸ δὲ ἀπὸ ταύτης τὴν μὲν ἐπὶ θάλασσαν τὴν αὐτὴν φέρουσαν, ἐοῦσαν ὀρεινήν τε χώρην καὶ προκειμένην τὸ ἐς Πόντον, νέμεται τὸ Ταυρικὸν ἔθνος μέχρι χερσονήσου τῆς τρηχέης καλεομένης· αὕτη δὲ ἐς θάλασσαν τὴν πρὸς ἀπηλιώτην ἄνεμον κατήκει. ἔστι γὰρ τῆς Σκυθικῆς τὰ δύο μέρεα τῶν οὔρων ἐς θάλασσαν φέροντα, τήν τε πρὸς μεσαμβρίην καὶ τὴν πρὸς τὴν ἠῶ, κατά περ τῆς Ἀττικῆς χώρης· καὶ παραπλήσια ταύτῃ καὶ οἱ Ταῦροι νέμονται τῆς Σκυθικῆς, ὡς εἰ τῆς Ἀττικῆς ἄλλο ἔθνος καὶ μὴ Ἀθηναῖοι νεμοίατο τὸν γουνὸν τὸν Σουνιακόν, μᾶλλον ἐς τὸν πόντον τὴν ἄκρην ἀνέχοντα, τὸν ἀπὸ Θορικοῦ μέχρι Ἀναφλύστου δήμου· λέγω δὲ ὡς εἶναι ταῦτα σμικρὰ μεγάλοισι συμβάλλειν· τοιοῦτον ἡ Ταυρική ἐστι. ὃς δὲ τῆς Ἀττικῆς ταῦτα μὴ παραπέπλωκε, ἐγὼ δὲ ἄλλως δηλώσω· ὡς εἰ τῆς Ἰηπυγίης ἄλλο ἔθνος καὶ μὴ Ἰήπυγες ἀρξάμενοι ἐκ Βρεντεσίου λιμένος ἀποταμοίατο μέχρι Τάραντος καὶ νεμοίατο τὴν ἄκρην. δύο δὲ λέγων ταῦτα πολλὰ λέγω παρόμοια, τοῖσι ἄλλοισι ἔοικε ἡ Ταυρική.", "st": "4.99"}, {"sp": "N", "t": "τὸ δ’ ἀπὸ τῆς Ταυρικῆς ἤδη Σκύθαι τὰ κατύπερθε τῶν Ταύρων καὶ τὰ πρὸς θαλάσσης τῆς ἠοίης νέμονται, τοῦ τε Βοσπόρου τοῦ Κιμμερίου τὰ πρὸς ἑσπέρης καὶ τῆς λίμνης τῆς Μαιήτιδος μέχρι Τανάιδος ποταμοῦ, ὃς ἐκδιδοῖ ἐς μυχὸν τῆς λίμνης ταύτης. ἤδη ὦν ἀπὸ μὲν Ἴστρου τὰ κατύπερθε ἐς τὴν μεσόγαιαν φέροντα ἀποκληίεται ἡ Σκυθικὴ ὑπὸ πρώτων Ἀγαθύρσων, μετὰ δὲ Νευρῶν, ἔπειτα δὲ Ἀνδροφάγων, τελευταίων δὲ Μελαγχλαίνων.", "st": "4.100"}, {"sp": "N", "t": "ἔστι ὦν τῆς Σκυθικῆς ὡς ἐούσης τετραγώνου, τῶν δύο μερέων κατηκόντων ἐς θάλασσαν, πάντῃ ἴσον τό τε ἐς τὴν μεσόγαιαν φέρον καὶ τὸ παρὰ τὴν θάλασσαν. ἀπὸ γὰρ Ἴστρου ἐπὶ Βορυσθένεα δέκα ἡμερέων ὁδός ἀπὸ Βορυσθένεος τε ἐπὶ τὴν λίμνην τὴν Μαιῆτιν ἑτερέων δέκα· καὶ τὸ ἀπὸ θαλάσσης ἐς μεσόγαιαν ἐς τοὺς Μελαγχλαίνους τοὺς κατύπερθε Σκυψέων οἰκημένους εἴκοσι ἡμερέων ὁδὸς. ἡ δὲ ὁδὸς ἡ ἡμερησίη ἀνὰ διηκόσια στάδια συμβέβληταί μοι. οὕτω ἂν εἴη τῆς Σκυθικῆς τὰ ἐπικάρσια τετρακισχιλίων σταδίων καὶ τὰ ὄρθια τὰ ἐς τὴν μεσόγαιαν φέροντα ἑτέρων τοσούτων σταδίων. ἡ μέν νυν γῆ αὕτη ἐστὶ μέγαθος τοσαύτη.", "st": "4.101"}, {"sp": "N", "t": "οἱ δὲ Σκύθαι δόντες σφίσι λόγον ὡς οὐκ οἷοί τε εἰσὶ τὸν Δαρείου στρατὸν ἰθυμαχίῃ διώσασθαι μοῦνοι, ἔπεμπον ἐς τοὺς πλησιοχώρους ἀγγέλους· τῶν δὲ καὶ δὴ οἱ βασιλέες συνελθόντες ἐβουλεύοντο ὡς στρατοῦ ἐπελαύνοντος μεγάλου. ἦσαν δὲ οἱ συνελθόντες βασιλέες Ταύρων καὶ Ἀγαθύρσων καὶ Νευρῶν καὶ Ἀνδροφάγων καὶ Μελαγχλαίνων καὶ Γελωνῶν καὶ Βουδίνων καὶ Σαυροματέων.", "st": "4.102"}, {"sp": "N", "t": "τούτων Ταῦροι μὲν νόμοισι τοιοῖσιδε χρέωνται· θύουσι μὲν τῇ Παρθένῳ τούς τε ναυηγοὺς καὶ τοὺς ἂν λάβωσι Ἑλλήνων ἐπαναχθέντες τρόπῳ τοιῷδε· καταρξάμενοι ῥοπάλῳ παίουσι τὴν κεφαλήν. οἳ μὲν δὴ λέγουσι ὡς τὸ σῶμα ἀπὸ τοῦ κρημνοῦ ὠθέουσι κάτω (ἐπὶ γὰρ κρημνοῦ ἵδρυται τὸ ἱρόν), τὴν δὲ κεφαλὴν ἀνασταυροῦσι· οἳ δὲ κατὰ μὲν τὴν κεφαλὴν ὁμολογέουσι, τὸ μέντοι σῶμα οὐκ ὠθέεσθαι ἀπὸ τοῦ κρημνοῦ λέγουσι ἀλλὰ γῇ κρύπτεσθαι. τὴν δὲ δαίμονα ταύτην τῇ θύουσι λέγουσι αὐτοὶ Ταῦροι Ἰφιγένειαν τὴν Ἀγαμέμνονος εἶναι. πολεμίους δὲ ἄνδρας τοὺς ἂν χειρώσωνται ποιεῦσι τάδε· ἀποταμὼν ἕκαστος κεφαλὴν ἀποφέρεται ἐς τὰ οἰκία, ἔπειτα ἐπὶ ξύλου μεγάλου ἀναπείρας ἱστᾷ ὑπὲρ τῆς οἰκίης ὑπερέχουσαν πολλόν, μάλιστα δὲ ὑπὲρ τῆς καπνοδόκης. φασὶ δὲ τούτους φυλάκους τῆς οἰκίης πάσης ὑπεραιωρέεσθαι. ζῶσι δὲ ἀπὸ ληίης τε καὶ πολέμου.", "st": "4.103"}, {"sp": "N", "t": "Ἀγάθυρσοι δὲ ἁβρότατοι ἀνδρῶν εἰσι καὶ χρυσοφόροι τὰ μάλιστα, ἐπίκοινον δὲ τῶν γυναικῶν τὴν μῖξιν ποιεῦνται, ἵνα κασίγνητοι τε ἀλλήλων ἔωσι καὶ οἰκήιοι ἐόντες πάντες μήτε φθόνῳ μήτε ἔχθεϊ χρέωνται ἐς ἀλλήλους. τὰ δὲ ἄλλα νόμαια Θρήιξι προσκεχωρήκασι.", "st": "4.104"}, {"sp": "N", "t": "Νευροὶ δὲ νόμοισι μὲν χρέωνται Σκυθικοῖσι, γενεῇ δὲ μιῇ πρότερον σφέας τῆς Δαρείου στρατηλασίης κατέλαβε ἐκλιπεῖν τὴν χώρην πᾶσαν ὑπὸ ὀφίων· ὄφιας γάρ σφι πολλοὺς μὲν ἡ χώρη ἀνέφαινε, οἱ δὲ πλεῦνες ἄνωθέν σφι ἐκ τῶν ἐρήμων ἐπέπεσον, ἐς ὃ πιεζόμενοι οἴκησαν μετὰ Βουδίνων τὴν ἑωυτῶν ἐκλιπόντες. κινδυνεύουσι δὲ οἱ ἄνθρωποι οὗτοι γόητες εἶναι. λέγονται γὰρ ὑπὸ Σκυθέων καὶ Ἑλλήνων τῶν ἐν τῇ Σκυθικῇ κατοικημένων ὡς ἔτεος ἑκάστου ἅπαξ τῶν Νευρῶν ἕκαστος λύκος γίνεται ἡμέρας ὀλίγας καὶ αὖτις ὀπίσω ἐς τὠυτὸ κατίσταται. ἐμὲ μέν νυν ταῦτα λέγοντες οὐ πείθουσι, λέγουσι δὲ οὐδὲν ἧσσον, καὶ ὀμνῦσι δὲ λέγοντες.", "st": "4.105"}, {"sp": "N", "t": "ἀνδροφάγοι δὲ ἀγριώτατα πάντων ἀνθρώπων ἔχουσι ἤθεα, οὔτε δίκην νομίζοντες οὔτε νόμῳ οὐδενὶ χρεώμενοι· νομάδες δὲ εἰσι, ἐσθῆτά τε φορέουσι τῇ Σκυθικῇ ὁμοίην, γλῶσσαν δὲ ἰδίην, ἀνδροφαγέουσι δὲ μοῦνοι τούτων.", "st": "4.106"}, {"sp": "N", "t": "μελάγχλαινοι δὲ εἵματα μὲν μέλανα φορέουσι πάντες, ἐπ’ ὧν καὶ τὰς ἐπωνυμίας ἔχουσι, νόμοισι δὲ Σκυθικοῖσι χρέωνται.", "st": "4.107"}, {"sp": "N", "t": "Βουδῖνοι δὲ ἔθνος ἐὸν μέγα καὶ πολλὸν γλαυκόν τε πᾶν ἰσχυρῶς ἐστι καὶ πυρρόν· πόλις δὲ ἐν αὐτοῖσι πεπόλισται ξυλίνη, οὔνομα δὲ τῇ πόλι ἐστὶ Γελωνός. τοῦ δὲ τείχεος μέγαθος κῶλον ἕκαστον τριήκοντα σταδίων ἐστί, ὑψηλὸν δὲ καὶ πᾶν ξύλινον, καὶ αἱ οἰκίαι αὐτῶν ξύλιναι καὶ τὰ ἱρά. ἔστι γὰρ δὴ αὐτόθι Ἑλληνικῶν θεῶν ἱρὰ Ἑλληνικῶς κατεσκευασμένα ἀγάλμασί τε καὶ βωμοῖσι καὶ νηοῖσι ξυλίνοισι, καὶ τῷ Διονύσῳ τριετηρίδας ἀνάγουσι καὶ βακχεύουσι. εἰσὶ γὰρ οἱ Γελωνοὶ τὸ ἀρχαῖον Ἕλληνες, ἐκ τῶν δὲ ἐμπορίων ἐξαναστάντες οἴκησαν ἐν τοῖσι Βουδίνοισι· καὶ γλώσσῃ τὰ μὲν Σκυθικῇ, τὰ δὲ Ἑλληνικῇ χρέωνται. Βουδῖνοι δὲ οὐ τῇ αὐτῇ γλώσσῃ χρέωνται καὶ Γελωνοί, οὐδὲ δίαιτα ἡ αὐτή.", "st": "4.108"}, {"sp": "N", "t": "οἱ μὲν γὰρ Βουδῖνοι ἐόντες αὐτόχθονες νομάδες τε εἰσὶ καὶ φθειροτραγέουσι μοῦνοι τῶν ταύτῃ, Γελωνοὶ δὲ γῆς τε ἐργάται καὶ σιτοφάγοι καὶ κήπους ἐκτημένοι, οὐδὲν τὴν ἰδέην ὅμοιοι οὐδὲ τὸ χρῶμα. ὑπὸ μέντοι Ἑλλήνων καλέονται καὶ οἱ Βουδῖνοι Γελωνοί, οὐκ ὀρθῶς καλεόμενοι. ἡ δὲ χώρη σφέων πᾶσα ἐστὶ δασέα ἴδῃσι παντοίῃσι· ἐν δὲ τῇ ἴδῃ τῇ πλείστῃ ἐστὶ λίμνη μεγάλη τε καὶ πολλὴ καὶ ἕλος καὶ κάλαμος περὶ αὐτήν. ἐν δὲ ταύτῃ ἐνύδριες ἁλίσκονται καὶ κάστορες καὶ ἄλλα θηρία τετραγωνοπρόσωπα, τῶν τὰ δέρματα παρὰ τὰς σισύρνας παραρράπτεται, καὶ οἱ ὄρχιες αὐτοῖσι εἰσὶ χρήσιμοι ἐς ὑστερέων ἄκεσιν.", "st": "4.109.2"}, {"sp": "N", "t": "Σαυροματέων δὲ πέρι ὧδε λέγεται. ὅτε Ἕλληνες Ἀμαζόσι ἐμαχέσαντο (τὰς δὲ Ἀμαζόνας καλέουσι Σκύθαι Οἰόρπατα, δύναται δὲ τὸ οὔνομα τοῦτο κατὰ Ἑλλάδα γλῶσσαν ἀνδροκτόνοι· οἰὸρ γὰρ καλέουσι ἄνδρα, τὸ δὲ πατὰ κτείνειν), τότε λόγος τοὺς Ἕλληνας νικήσαντας τῇ ἐπὶ Θερμώδοντι μάχῃ ἀποπλέειν ἄγοντας τρισὶ πλοίοισι τῶν Ἀμαζόνων ὅσας ἐδυνέατο ζωγρῆσαι, τὰς δὲ ἐν τῷ πελάγει ἐπιθεμένας ἐκκόψαι τοὺς ἄνδρας. πλοῖα δὲ οὐ γινώσκειν αὐτὰς οὐδὲ πηδαλίοισι χρᾶσθαι οὐδὲ ἱστίοισι οὐδὲ εἰρεσίῃ· ἀλλ’ ἐπεὶ ἐξέκοψαν τοὺς ἄνδρας ἐφέροντο κατὰ κῦμα καὶ ἄνεμον, καὶ ἀπικνέονται τῆς λίμνης τῆς Μαιήτιδος ἐπὶ Κρημνούς· οἱ δὲ Κρημνοὶ εἰσὶ γῆς τῆς Σκυθέων τῶν ἐλευθέρων. ἐνθαῦτα ἀποβᾶσαι ἀπὸ τῶν πλοίων αἱ Ἀμαζόνες ὁδοιπόρεον ἐς τὴν οἰκεομένην. ἐντυχοῦσαι δὲ πρώτῳ ἱπποφορβίῳ τοῦτο διήρπασαν, καὶ ἐπὶ τούτων ἱππαζόμεναι ἐληίζοντο τὰ τῶν Σκυθέων.", "st": "4.110"}, {"sp": "N", "t": "οἱ δὲ Σκύθαι οὐκ εἶχον συμβαλέσθαι τὸ πρῆγμα· οὔτε γὰρ φωνὴν οὔτε ἐσθῆτα οὔτε τὸ ἔθνος ἐγίνωσκον, ἀλλ’ ἐν θώματι ἦσαν ὁκόθεν ἔλθοιεν, ἐδόκεον δ’ αὐτὰς εἶναι ἄνδρας τὴν αὐτὴν ἡλικίην ἔχοντας, μάχην τε δὴ πρὸς αὐτὰς ἐποιεῦντο. ἐκ δὲ τῆς μάχης τῶν νεκρῶν ἐκράτησαν οἱ Σκύθαι, καὶ οὕτω ἔγνωσαν ἐούσας γυναῖκας. βουλευομένοισι ὦν αὐτοῖσι ἔδοξε κτείνειν μὲν οὐδενὶ τρόπῳ ἔτι αὐτάς, ἑωυτῶν δὲ τοὺς νεωτάτους ἀποπέμψαι ἐς αὐτάς, πλῆθος εἰκάσαντας ὅσαι περ ἐκεῖναι ἦσαν τούτους δὲ στρατοπεδεύεσθαι πλησίον ἐκεινέων καὶ ποιέειν τὰ περ ἂν καὶ ἐκεῖναι ποιέωσι. ἢν δὲ αὐτοὺς διώκωσι, μάχεσθαι μὲν μή, ὑποφεύγειν δέ· ἐπεὰν δὲ παύσωνται, ἐλθόντας αὖτις πλησίον στρατοπεδεύεσθαι. ταῦτα ἐβουλεύσαντο οἱ Σκύθαι βουλόμενοι ἐξ αὐτέων παῖδας ἐκγενήσεσθαι. ἀποπεμφθέντες δὲ οἱ νεηνίσκοι ἐποίευν τὰ ἐντεταλμένα.", "st": "4.111"}, {"sp": "N", "t": "ἐπεὶ δὲ ἔμαθον αὐτοὺς αἱ Ἀμαζόνες ἐπ’ οὐδεμιῇ δηλήσι ἀπιγμένους, ἔων χαίρειν· προσεχώρεον δὲ πλησιαιτέρω τὸ στρατόπεδον τῷ στρατοπέδῳ ἐπ’ ἡμέρῃ ἑκάστῃ. εἶχον δὲ οὐδὲν οὐδ’ οἱ νεηνίσκοι, ὥσπερ αἱ Ἀμαζόνες, εἰ μὴ τὰ ὅπλα καὶ τοὺς ἵππους, ἀλλὰ ζόην ἔζωον τὴν αὐτὴν ἐκείνῃσι, θηρεύοντές τε καὶ ληιζόμενοι.", "st": "4.112"}, {"sp": "N", "t": "ἐποίευν δὲ αἱ Ἀμαζόνες ἐς τὴν μεσαμβρίην τοιόνδε· ἐγίνοντο σποράδες κατὰ μίαν τε καὶ δύο, πρόσω δὴ ἀπ’ ἀλληλέων ἐς εὐμαρείην ἀποσκιδνάμεναι. μαθόντες δὲ καὶ οἱ Σκύθαι ἐποίευν τὠυτὸ τοῦτο. καί τις μουνωθεισέων τινὶ αὐτέων ἐνεχρίμπτετο, καὶ ἡ Ἀμαζὼν οὐκ ἀπωθέετο ἀλλὰ περιεῖδε χρήσασθαι. καὶ φωνῆσαι μὲν οὐκ εἶχε, οὐ γὰρ συνίεσαν ἀλλήλων, τῇ δὲ χειρὶ ἔφραζε ἐς τὴν ὑστεραίην ἐλθεῖν ἐς τωὐτὸ χωρίον καὶ ἕτερον ἄγειν, σημαίνουσα δύο γενέσθαι καὶ αὐτὴ ἑτέρην ἄξειν. ὁ δὲ νεηνίσκος, ἐπεὶ ἀπῆλθε, ἔλεξε ταῦτα πρὸς τοὺς λοιπούς· τῇ δὲ δευτεραίῃ ἦλθε ἐς τὸ χωρίον αὐτός τε οὗτος καὶ ἕτερον ἦγε, καὶ τὴν Ἀμαζόνα εὗρε δευτέρην αὐτὴν ὑπομένουσαν. οἱ δὲ λοιποὶ νεηνίσκοι ὡς ἐπύθοντο ταῦτα, καὶ αὐτοὶ ἐκτιλώσαντο τὰς λοιπὰς τῶν Ἀμαζόνων.", "st": "4.113"}, {"sp": "N", "t": "μετὰ δὲ συμμίξαντες τὰ στρατόπεδα οἴκεον ὁμοῦ, γυναῖκα ἔχων ἕκαστος ταύτην τῇ τὸ πρῶτον συνεμίχθη. τὴν δὲ φωνὴν τὴν μὲν τῶν γυναικῶν οἱ ἄνδρες οὐκ ἐδυνέατο μαθεῖν, τὴν δὲ τῶν ἀνδρῶν αἱ γυναῖκες συνέλαβον. ἐπεὶ δὲ συνῆκαν ἀλλήλων, ἔλεξαν πρὸς τὰς Ἀμαζόνας τάδε οἱ ἄνδρες. ἡμῖν εἰσὶ μὲν τοκέες, εἰσὶ δὲ κτήσιες· νῦν ὦν μηκέτι πλεῦνα χρόνον ζόην τοιήνδε ἔχωμεν, ἀλλ’ ἀπελθόντες ἐς τὸ πλῆθος διαιτώμεθα. γυναῖκας δὲ ἕξομεν ὑμέας καὶ οὐδαμὰς ἄλλας. αἳ δὲ πρὸς ταῦτα ἔλεξαν τάδε. ἡμεῖς οὐκ ἂν δυναίμεθα οἰκέειν μετὰ τῶν ὑμετερέων γυναικῶν· οὐ γὰρ τὰ αὐτὰ νόμαια ἡμῖν τε κἀκείνῃσι ἐστί. ἡμεῖς μὲν τοξεύομέν τε καὶ ἀκοντίζομεν καὶ ἱππαζόμεθα, ἔργα δὲ γυναικήια οὐκ ἐμάθομεν· αἱ δὲ ὑμέτεραι γυναῖκες τούτων μὲν οὐδὲν τῶν ἡμεῖς κατελέξαμεν ποιεῦσι, ἔργα δὲ γυναικήια ἐργάζονται μένουσαι ἐν τῇσι ἁμάξῃσι, οὔτ’ ἐπὶ θήρην ἰοῦσαι οὔτε ἄλλῃ οὐδαμῇ. οὐκ ἂν ὦν δυναίμεθα ἐκείνῃσι συμφέρεσθαι. ἀλλ’ εἰ βούλεσθε γυναῖκας ἔχειν ἡμέας καὶ δοκέειν εἶναι δίκαιοι, ἐλθόντες παρὰ τοὺς τοκέας ἀπολάχετε τῶν κτημάτων τὸ μέρος, καὶ ἔπειτα ἐλθόντες οἰκέωμεν ἐπὶ ἡμέων αὐτῶν. ἐπείθοντο καὶ ἐποίησαν ταῦτα οἱ νεηνίσκοι.", "st": "4.114"}, {"sp": "N", "t": "ἐπείτε δὲ ἀπολαχόντες τῶν κτημάτων τὸ ἐπιβάλλον ἦλθον ὀπίσω παρὰ τὰς Ἀμαζόνας, ἔλεξαν αἱ γυναῖκες πρὸς αὐτοὺς τάδε. ἡμέας ἔχει φόβος τε καὶ δέος ὅκως χρὴ οἰκέειν ἐν τῷδε τῷ χώρῳ, τοῦτο μὲν ὑμέας ἀποστερησάσας πατέρων, τοῦτο δὲ γῆν τὴν ὑμετέρην δηλησαμένας πολλά. ἀλλ’ ἐπείτε ἀξιοῦτε ἡμέας γυναῖκας ἔχειν, τάδε ποιέετε ἅμα ἡμῖν· φέρετε ἐξαναστέωμεν ἐκ τῆς γῆς τῆσδε καὶ περήσαντες Τάναιν ποταμὸν οἰκέωμεν.", "st": "4.115"}, {"sp": "N", "t": "ἐπείθοντο καὶ ταῦτα οἱ νεηνίσκοι, διαβάντες δὲ τὸν Τάναϊν ὁδοιπόρεον πρὸς ἥλιον ἀνίσχοντα τριῶν μὲν ἡμερέων ἀπὸ τοῦ Τανάιδος ὁδόν, τριῶν δὲ ἀπὸ τῆς λίμνης τῆς Μαιήτιδος πρὸς βορέην ἄνεμον. ἀπικόμενοι δὲ ἐς τοῦτον τὸν χῶρον ἐν τῷ νυν κατοίκηνται, οἴκησαν τοῦτον. καὶ διαίτῃ ἀπὸ τούτου χρέωνται τῇ παλαιῇ τῶν Σαυροματέων αἱ γυναῖκες, καὶ ἐπὶ θήρην ἐπ’ ἵππων ἐκφοιτῶσαι ἅμα τοῖσι ἀνδράσι καὶ χωρὶς τῶν ἀνδρῶν, καὶ ἐς πόλεμον φοιτῶσαι καὶ στολὴν τὴν αὐτὴν τοῖσι ἀνδράσι φορέουσαι.", "st": "4.116"}, {"sp": "N", "t": "φωνῇ δὲ οἱ Σαυρομάται νομίζουσι Σκυθικῇ, σολοικίζοντες αὐτῇ ἀπὸ τοῦ ἀρχαίου, ἐπεὶ οὐ χρηστῶς ἐξέμαθον αὐτὴν αἱ Ἀμαζόνες. τὰ περὶ γάμων δὲ ὧδέ σφι διακέεται. οὐ γαμέεται παρθένος οὐδεμία πρὶν ἂν τῶν πολεμίων ἄνδρα ἀποκτείνῃ· αἳ δὲ τινὲς αὐτέων καὶ τελευτῶσι γηραιαὶ πρὶν γήμασθαι, οὐ δυνάμεναι τὸν νόμον ἐκπλῆσαι.", "st": "4.117"}, {"sp": "N", "t": "ἐπὶ τούτων ὦν τῶν καταλεχθέντων ἐθνέων τοὺς βασιλέας ἁλισμένους ἀπικόμενοι τῶν Σκυθέων οἱ ἄγγελοι ἔλεγον ἐκδιδάσκοντες ὡς ὁ Πέρσης, ἐπειδή οἱ τὰ ἐν τῇ ἠπείρῳ τῇ ἑτέρῃ πάντα κατέστραπται, γέφυραν ζεύξας ἐπὶ τῷ αὐχένι τοῦ Βοσπόρου διαβέβηκε ἐς τήνδε τὴν ἤπειρον, διαβὰς δὲ καὶ καταστρεψάμενος Θρήικας γεφυροῖ ποταμὸν Ἴστρον, βουλόμενος καὶ τάδε πάντα ὑπ’ ἑωυτῷ ποιήσασθαι. ὑμεῖς ὦν μηδενὶ τρόπῳ ἐκ τοῦ μέσου κατήμενοι περιίδητε ἡμέας διαφθαρέντας, ἀλλὰ τὠυτὸ νοήσαντες ἀντιάζωμεν τὸν ἐπιόντα. οὔκων ποιήσετε ταῦτα; ἡμεῖς μὲν πιεζόμενοι ἢ ἐκλείψομεν τὴν χώρην ἢ μένοντες ὁμολογίῃ χρησόμεθα. τί γὰρ πάθωμεν μὴ βουλομένων ὑμέων τιμωρέειν; ὑμῖν δὲ οὐδὲν ἐπὶ τούτῳ ἔσται ἐλαφρότερον. ἥκει γὰρ ὁ Πέρσης οὐδέν τι μᾶλλον ἐπ’ ἡμέας ἢ οὐ καὶ ἐπ’ ὑμέας, οὐδέ οἱ καταχρήσει ἡμέας καταστρεψαμένῳ ὑμέων ἀπέχεσθαι. μέγα δὲ ὑμῖν λόγων τῶνδε μαρτύριον ἐρέομεν. εἰ γὰρ ἐπ’ ἡμέας μούνους ἐστρατηλάτεε ὁ Πέρσης τίσασθαι τῆς πρόσθε δουλοσύνης βουλόμενος, χρῆν αὐτὸν πάντων τῶν ἄλλων ἀπεχόμενον ἰέναι οὕτω ἐπὶ τὴν ἡμετέρην, καὶ ἂν ἐδήλου πᾶσι ὡς ἐπὶ Σκύθας ἐλαύνει καὶ οὐκ ἐπὶ τοὺς ἄλλους. νῦν δὲ ἐπείτε τάχιστα διέβη ἐς τήνδε τὴν ἤπειρον, τοὺς αἰεὶ ἐμποδὼν γινομένους ἡμεροῦται πάντας· τούς τε δὴ ἄλλους ἔχει ὑπ’ ἑωυτῷ Θρήικας καὶ δὴ καὶ τοὺς ἡμῖν ἐόντας πλησιοχώρους Γέτας.", "st": "4.118"}, {"sp": "N", "t": "ταῦτα Σκυθέων ἐπαγγελλομένων ἐβουλεύοντο οἱ βασιλέες οἱ ἀπὸ τῶν ἐθνέων ἥκοντες, καί σφεων ἐσχίσθησαν αἱ γνῶμαι· ὁ μὲν γὰρ Γελωνὸς καὶ ὁ Βουδῖνος καὶ ὁ Σαυρομάτης κατὰ τὠυτὸ γενόμενοι ὑπεδέκοντο Σκύθῃσι τιμωρήσειν, ὁ δὲ Ἀγάθυρσος καὶ Νευρὸς καὶ Ἀνδροφάγος καὶ οἱ τῶν Μελαγχλαίνων καὶ Ταύρων τάδε Σκύθῃσι ὑπεκρίναντο. εἰ μὲν μὴ ὑμεῖς ἔατε οἱ πρότεροι ἀδικήσαντες Πέρσας καὶ ἄρξαντες πολέμου, τούτων δεόμενοι τῶν νῦν δέεσθε λέγειν τε ἂν ἐφαίνεσθε ἡμῖν ὀρθά, καὶ ἡμεῖς ὑπακούσαντες τὠυτὸ ἂν ὑμῖν ἐπρήσσομεν. νῦν δὲ ὑμεῖς τε ἐς τὴν ἐκείνων ἐσβαλόντες γῆν ἄνευ ἡμέων ἐπεκρατέετε Περσέων ὅσον χρόνον ὑμῖν ὁ θεὸς παρεδίδου, καὶ ἐκεῖνοι, ἐπεί σφεας ὡυτὸς θεὸς ἐγείρει, τὴν ὁμοίην ὑμῖν ἀποδιδοῦσι. ἡμεῖς δὲ οὔτε τι τότε ἠδικήσαμεν τοὺς ἄνδρας τούτους οὐδὲν οὔτε νῦν πρότεροι πειρησόμεθα ἀδικέειν. ἢν μέντοι ἐπίῃ καὶ τὴν ἡμετέρην ἄρξῃ τε ἀδικέων, καὶ ἡμεῖς οὐ πεισόμεθα, μέχρι δὲ τοῦτο ἴδωμεν, μενέομεν παρ’ ἡμῖν αὐτοῖσι· ἥκειν γὰρ δοκέομεν οὐκ ἐπ’ ἡμέας Πέρσας ἀλλ’ ἐπὶ τοὺς αἰτίους τῆς ἀδικίης γενομένους.", "st": "4.119"}, {"sp": "N", "t": "ταῦτα ὡς ἀπενειχθέντα ἐπύθοντο οἱ Σκύθαι, ἐβουλεύοντο ἰθυμαχίην μὲν μηδεμίαν ποιέεσθαι ἐκ τοῦ ἐμφανέος, ὅτε δὴ σφι οὗτοι γε σύμμαχοι οὐ προσεγίνοντο, ὑπεξιόντες δὲ καὶ ὑπεξελαύνοντες τὰ φρέατα τὰ παρεξίοιεν αὐτοὶ καὶ τὰς κρήνας συγχοῦν, τὴν ποίην τε ἐκ τῆς γῆς ἐκτρίβειν, διχοῦ σφέας διελόντες. καὶ πρὸς μὲν τὴν μίαν τῶν μοιρέων, τῆς ἐβασίλευε Σκώπασις, προσχωρέειν Σαυρομάτας· τούτους μὲν δὴ ὑπάγειν, ἢν ἐπὶ τοῦτο τράπηται ὁ Πέρσης ἰθὺ Τανάιδος ποταμοῦ παρὰ τὴν Μαιῆτιν λίμνην ὑποφεύγοντας, ἀπελαύνοντος τε τοῦ Πέρσεω ἐπιόντας διώκειν. αὕτη μέν σφι μία ἦν μοῖρα τῆς βασιληίης, τεταγμένη ταύτην τὴν ὁδὸν ἥ περ εἴρηται· τὰς δὲ δύο τῶν βασιληίων, τήν τε μεγάλην τῆς ἦρχε Ἰδάνθυρσος καὶ τὴν τρίτην τῆς ἐβασίλευε Τάξακις, συνελθούσας ἐς τὠυτὸ καὶ Γελωνῶν τε καὶ Βουδίνων προσγενομένων, ἡμέρης καὶ τούτους ὁδῷ προέχοντας τῶν Περσέων ὑπεξάγειν, ὑπιόντας τε καὶ ποιεῦντας τὰ βεβουλευμένα· πρῶτα μέν νυν ὑπάγειν σφέας ἰθὺ τῶν χωρέων τῶν ἀπειπαμένων τὴν σφετέρην συμμαχίην, ἵνα καὶ τούτους ἐκπολεμώσωσι· εἰ γὰρ μὴ ἑκόντες γε ὑπέδυσαν τὸν πόλεμον τὸν πρὸς Πέρσας, ἀλλ’ ἀέκοντας ἐκπολεμώσειν· μετὰ δὲ τοῦτο ὑποστρέφειν ἐς τὴν σφετέρην καὶ ἐπιχειρέειν, ἢν δὴ βουλευομένοισι δοκέῃ.", "st": "4.120"}, {"sp": "N", "t": "ταῦτα οἱ Σκύθαι βουλευσάμενοι ὑπηντίαζον τὴν Δαρείου στρατιήν, προδρόμους ἀποστείλαντες τῶν ἱππέων τοὺς ἀρίστους. τὰς δὲ ἁμάξας ἐν τῇσι σφι διαιτᾶτο τὰ τέκνα καὶ αἱ γυναῖκες πάσας καὶ τὰ πρόβατα πάντα, πλὴν ὅσα σφι ἐς φορβὴν ἱκανὰ ἦν τοσαῦτα ὑπολιπόμενοι, τὰ ἄλλα ἅμα τῇσι ἁμάξῃσι προέπεμψαν, ἐντειλάμενοι αἰεὶ τὸ πρὸς βορέω ἐλαύνειν.", "st": "4.121"}, {"sp": "N", "t": "ταῦτα μὲν δὴ προεκομίζετο. τῶν δὲ Σκυθέων οἱ πρόδρομοι ὡς εὗρον τοὺς Πέρσας ὅσον τε τριῶν ἡμερέων ὁδὸν ἀπέχοντας ἀπὸ τοῦ Ἴστρου, οὗτοι μὲν τούτους εὑρόντες, ἡμέρης ὁδῷ προέχοντες, ἐστρατοπεδεύοντο τὰ ἐκ τῆς γῆς φυόμενα λεαίνοντες, οἱ δὲ Πέρσαι ὡς εἶδον ἐπιφανεῖσαν τῶν Σκυθέων τὴν ἵππον, ἐπήισαν κατὰ στίβον αἰεὶ ὑπαγόντων· καὶ ἔπειτα (πρὸς γὰρ τὴν μίαν τῶν μοιρέων ἴθυσαν) οἱ Πέρσαι ἐδίωκον πρὸς ἠῶ τε καὶ ἰθὺ Τανάιδος. διαβάντων δὲ τούτων τὸν Τάναιν ποταμὸν οἱ Πέρσαι ἐπιδιαβάντες ἐδίωκον, ἐς ὃ τῶν Σαυροματέων τὴν χώρην διεξελθόντες ἀπίκοντο ἐς τὴν τῶν Βουδίνων.", "st": "4.122"}, {"sp": "N", "t": "ὅσον μὲν δὴ χρόνον οἱ Πέρσαι ἤισαν διὰ τῆς Σκυθικῆς καὶ τῆς Σαυρομάτιδος χώρης, οἳ δὲ εἶχον οὐδὲν σίνεσθαι ἅτε τῆς χώρης ἐούσης χέρσου· ἐπείτε δὲ ἐς τὴν τῶν Βουδίνων χώρην ἐσέβαλλον, ἐνθαῦτα δὴ ἐντυχόντες τῷ ξυλίνῳ τείχεϊ, ἐκλελοιπότων τῶν Βουδίνων καὶ κεκενωμένου τοῦ τείχεος πάντων, ἐνέπρησαν αὐτό. τοῦτο δὲ ποιήσαντες εἵποντο αἰεὶ τὸ πρόσω κατὰ στίβον, ἐς ὃ διεξελθόντες ταύτην ἐς τὴν ἔρημον ἀπίκοντο. ἡ δὲ ἔρημος αὕτη ὑπὸ οὐδαμῶν νέμεται ἀνδρῶν, κέεται δὲ ὑπὲρ τῆς Βουδίνων χώρης ἐοῦσα πλῆθος ἑπτὰ ἡμερέων ὁδοῦ. ὑπὲρ δὲ τῆς ἐρήμου Θυσσαγέται οἰκέουσι, ποταμοὶ δὲ ἐξ αὐτῶν τέσσερες μεγάλοι ῥέοντες διὰ Μαιητέων ἐκδιδοῦσι ἐς τὴν λίμνην τὴν καλεομένην Μαιῆτιν, τοῖσι οὐνόματα κέεται τάδε, Λύκος Ὄαρος Τάναις Σύργις.", "st": "4.123"}, {"sp": "N", "t": "ἐπεὶ ὦν ὁ Δαρεῖος ἦλθε ἐς τὴν ἔρημον, παυσάμενος τοῦ δρόμου ἵδρυσε τὴν στρατιὴν ἐπὶ ποταμῷ Ὀάρῳ. τοῦτο δὲ ποιήσας ὀκτὼ τείχεα ἐτείχεε μεγάλα, ἴσον ἀπ’ ἀλλήλων ἀπέχοντα, σταδίους ὡς ἑξήκοντα μάλιστά κῃ· τῶν ἔτι ἐς ἐμὲ τὰ ἐρείπια σόα ἦν. ἐν ᾧ δὲ οὗτος πρὸς ταῦτα ἐτράπετο, οἱ διωκόμενοι Σκύθαι περιελθόντες τὰ κατύπερθε ὑπέστρεφον ἐς τὴν Σκυθικήν. ἀφανισθέντων δὲ τούτων τὸ παράπαν, ὡς οὐκέτι ἐφαντάζοντό σφι, οὕτω δὴ ὁ Δαρεῖος τείχεα μὲν ἐκεῖνα ἡμίεργα μετῆκε, αὐτὸς δὲ ὑποστρέψας ἤιε πρὸς ἑσπέρην, δοκέων τούτους τε πάντας τοὺς Σκύθας εἶναι καὶ πρὸς ἑσπέρην σφέας φεύγειν.", "st": "4.124"}, {"sp": "N", "t": "ἐλαύνων δὲ τὴν ταχίστην τὸν στρατὸν ὡς ἐς τὴν Σκυθικὴν ἀπίκετο, ἐνέκυρσε ἀμφοτέρῃσι τῇσι μοίρῃσι τῶν Σκυθέων, ἐντυχὼν δὲ ἐδίωκε ὑπεκφέροντας ἡμέρης ὁδῷ. καὶ οὐ γὰρ ἀνίει ἐπιὼν ὁ Δαρεῖος, οἱ Σκύθαι κατὰ τὰ βεβουλευμένα ὑπέφευγον ἐς τῶν ἀπειπαμένων τὴν σφετέρην συμμαχίην, πρώτην δὲ ἐς τῶν Μελαγχλαίνων τὴν γῆν. ὡς δὲ ἐσβαλόντες τούτους ἐτάραξαν οἵ τε Σκύθαι καὶ οἱ Πέρσαι, κατηγέοντο οἱ Σκύθαι ἐς τῶν Ἀνδροφάγων τοὺς χώρους· ταραχθέντων δὲ καὶ τούτων ὑπῆγον ἐπὶ τὴν Νευρίδα· ταρασσομένων δὲ καὶ τούτων ἤισαν ὑποφεύγοντες οἱ Σκύθαι ἐς τοὺς Ἀγαθύρσους. Ἀγαθύρσοι δὲ ὁρέοντες καὶ τοὺς ὁμούρους φεύγοντας ὑπὸ Σκυθέων καὶ τεταραγμένους, πρὶν ἤ σφι ἐμβαλεῖν τοὺς Σκύθας πέμψαντες κήρυκα ἀπηγόρευον Σκύθῃσι μὴ ἐπιβαίνειν τῶν σφετέρων οὔρων, προλέγοντες ὡς εἰ πειρήσονται ἐσβαλόντες, σφίσι πρῶτα διαμαχήσονται. Ἀγάθυρσοι μὲν προείπαντες ταῦτα ἐβοήθεον ἐπὶ τοὺς οὔρους, ἐρύκειν ἐν νόῳ ἔχοντες τοὺς ἐπιόντας· Μελάγχλαινοι δὲ καὶ Ἀνδροφάγοι καὶ Νευροὶ ἐσβαλόντων τῶν Περσέων ἅμα Σκύθησι οὔτε πρὸς ἀλκὴν ἐτράποντο ἐπιλαθόμενοί τε τῆς ἀπειλῆς ἔφευγον αἰεὶ τὸ πρὸς βορέω ἐς τὴν ἔρημον τεταραγμένοι. οἱ δὲ Σκύθαι ἐς μὲν τοὺς Ἀγαθύρσους οὐκέτι ἀπείπαντας ἀπικνέοντο, οἳ δὲ ἐκ τῆς Νευρίδος χώρης ἐς τὴν σφετέρην κατηγέοντο τοῖσι Πέρσῃσι.", "st": "4.125"}, {"sp": "N", "t": "ὡς δὲ πολλὸν τοῦτο ἐγίνετο καὶ οὐκ ἐπαύετο, πέμψας Δαρεῖος ἱππέα παρὰ τὸν Σκυθέων βασιλέα Ἰδάνθυρσον ἔλεγε τάδε. δαιμόνιε ἀνδρῶν, τί φεύγεις αἰεί, ἐξεόν τοι τῶνδε τὰ ἕτερα ποιέειν; εἰ μὲν γὰρ ἀξιόχρεος δοκέεις εἶναι σεωυτῷ τοῖσι ἐμοῖσι πρήγμασι ἀντιωθῆναι, σὺ δὲ στάς τε καὶ παυσάμενος πλάνης μάχεσθαι· εἰ δὲ συγγινώσκεαι εἶναι ἥσσων, σὺ δὲ καὶ οὕτω παυσάμενος τοῦ δρόμου δεσπότῃ τῷ σῷ δῶρα φέρων γῆν τε καὶ ὕδωρ ἐλθὲ ἐς λόγους.", "st": "4.126"}, {"sp": "N", "t": "πρὸς ταῦτα ὁ Σκυθέων βασιλεὺς Ἰδάνθυρσος λέγει τάδε. οὕτω τὸ ἐμὸν ἔχει, ὦ Πέρσα. ἐγὼ οὐδένα κω ἀνθρώπων δείσας ἔφυγον οὔτε πρότερον οὔτε νῦν σὲ φεύγω, οὐδέ τι νεώτερον εἰμὶ ποιήσας νῦν ἢ καὶ ἐν εἰρήνῃ ἐώθεα ποιέειν. ὅ τι δὲ οὐκ αὐτίκα μάχομαι τοι, ἐγὼ καὶ τοῦτο σημανέω. ἡμῖν οὔτε ἄστεα οὔτε γῆ πεφυτευμένη ἐστί, τῶν πέρι δείσαντες μὴ ἁλῷ ἢ καρῇ ταχύτερον ἂν ὑμῖν συμμίσγοιμεν ἐς μάχην. εἰ δὲ δέοι πάντως ἐς τοῦτο κατὰ τάχος ἀπικνέεσθαι, τυγχάνουσι ἡμῖν ἐόντες τάφοι πατρώιοι· φέρετε, τούτους ἀνευρόντες συγχέειν πειρᾶσθε αὐτούς, καὶ γνώσεσθε τότε εἴτε ὑμῖν μαχησόμεθα περὶ τῶν τάφων εἴτε καὶ οὐ μαχησόμεθα. πρότερον δέ, ἢν μὴ ἡμέας λόγος αἱρέῃ, οὐ συμμίξομεν τοι. ἀμφὶ μὲν μάχῃ τοσαῦτα εἰρήσθω, δεσπότας δὲ ἐμοὺς ἐγὼ Δία τε νομίζω τὸν ἐμὸν πρόγονον καὶ Ἱστίην τὴν Σκυθέων βασίλειαν μούνους εἶναι. σοὶ δὲ ἀντὶ μὲν δώρων γῆς τε καὶ ὕδατος δῶρα πέμψω τοιαῦτα οἷα σοὶ πρέπει ἐλθεῖν, ἀντὶ δὲ τοῦ ὅτι δεσπότης ἔφησας εἶναι ἐμός, κλαίειν λέγω. τοῦτο ἐστὶ ἡ ἀπὸ Σκυθέων ῥῆσις.", "st": "4.127"}, {"sp": "N", "t": "ὁ μὲν δὴ κῆρυξ οἰχώκεε ἀγγελέων ταῦτα Δαρείῳ, οἱ δὲ Σκυθέων βασιλέες ἀκούσαντες τῆς δουλοσύνης τὸ οὔνομα ὀργῆς ἐπλήσθησαν. τὴν μὲν δὴ μετὰ Σαυροματέων μοῖραν ταχθεῖσαν, τῆς ἦρχε Σκώπασις, πέμπουσι Ἴωσι κελεύοντες ἐς λόγους ἀπικέσθαι, τούτοισι οἳ τὸν Ἴστρον ἐζευγμένον ἐφρούρεον· αὐτῶν δὲ τοῖσι ὑπολειπομένοισι ἔδοξε πλανᾶν μὲν μηκέτι Πέρσας, σῖτα δὲ ἑκάστοτε ἀναιρεομένοισι ἐπιτίθεσθαι. νωμῶντες ὦν σῖτα ἀναιρεομένους τοὺς Δαρείου ἐποίευν τὰ βεβουλευμένα. ἡ μὲν δὴ ἵππος τὴν ἵππον αἰεὶ τράπεσκε ἡ τῶν Σκυθέων, οἱ δὲ τῶν Περσέων ἱππόται φεύγοντες ἐσέπιπτον ἐς τὸν πεζόν, ὁ δὲ πεζὸς ἂν ἐπεκούρεε· οἱ δὲ Σκύθαι ἐσαράξαντες τὴν ἵππον ὑπέστρεφον τὸν πεζὸν φοβεόμενοι. ἐποιέοντο δὲ καὶ τὰς νύκτας παραπλησίας προσβολὰς οἱ Σκύθαι.", "st": "4.128"}, {"sp": "N", "t": "τὸ δὲ τοῖσι Πέρσῃσι τε ἦν σύμμαχον καὶ τοῖσι Σκύθῃσι ἀντίξοον ἐπιτιθεμένοισι τῷ Δαρείου στρατοπέδῳ, θῶμα μέγιστον ἐρέω, τῶν τε ὄνων ἡ φωνὴ καὶ τῶν ἡμιόνων τὸ εἶδος. οὔτε γὰρ ὄνον οὔτε ἡμίονον γῆ ἡ Σκυθικὴ φέρει, ὡς καὶ πρότερόν μοι δεδήλωται, οὐδὲ ἔστι ἐν τῇ Σκυθικῇ πάσῃ χώρῃ τὸ παράπαν οὔτε ὄνος οὔτε ἡμίονος διὰ τὰ ψύχεα. ὑβρίζοντες ὧν οἱ ὄνοι ἐτάρασσον τὴν ἵππον τῶν Σκυθέων. πολλάκις δὲ ἐπελαυνόντων ἐπὶ τοὺς Πέρσας μεταξὺ ὅκως ἀκούσειαν οἱ ἵπποι τῶν ὄνων τῆς φωνῆς, ἐταράσσοντο τε ὑποστρεφόμενοι καὶ ἐν θώματι ἔσκον, ὀρθὰ ἱστάντες τὰ ὦτα, ἅτε οὔτε ἀκούσαντες πρότερον φωνῆς τοιαύτης οὔτε ἰδόντες τὸ εἶδος.", "st": "4.129"}, {"sp": "N", "t": "ταῦτα μέν νυν ἐπὶ σμικρόν τι ἐφέροντο τοῦ πολέμου. οἱ δὲ Σκύθαι ὅκως τοὺς Πέρσας ἴδοιεν τεθορυβημένους, ἵνα παραμένοιεν τε ἐπὶ πλέω χρόνον ἐν τῇ Σκυθικῇ καὶ παραμένοντες ἀνιῴατο τῶν πάντων ἐπιδευέες ἐόντες, ἐποίεον τοιάδε· ὅκως τῶν προβάτων τῶν σφετέρων αὐτῶν καταλίποιεν μετὰ τῶν νομέων, αὐτοὶ ἂν ὑπεξήλαυνον ἐς ἄλλον χῶρον. οἱ δὲ ἂν Πέρσαι ἐπελθόντες λάβεσκον τὰ πρόβατα καὶ λαβόντες ἐπηείροντο ἂν τῷ πεποιημένῳ.", "st": "4.130"}, {"sp": "N", "t": "πολλάκις δὲ τοιούτου γινομένου, τέλος Δαρεῖος τε ἐν ἀπορίῃσι εἴχετο, καὶ οἱ Σκυθέων βασιλέες μαθόντες τοῦτο ἔπεμπον κήρυκα δῶρα Δαρείῳ φέροντα ὄρνιθά τε καὶ μῦν καὶ βάτραχον καὶ ὀιστοὺς πέντε. Πέρσαι δὲ τὸν φέροντα τὰ δῶρα ἐπειρώτεον τὸν νόον τῶν διδομένων. ὃ δὲ οὐδὲν ἔφη οἱ ἐπεστάλθαι ἄλλο ἢ δόντα τὴν ταχίστην ἀπαλλάσσεσθαι· αὐτοὺς δὲ τοὺς Πέρσας ἐκέλευε, εἰ σοφοί εἰσι, γνῶναι τὸ θέλει τὰ δῶρα λέγειν.", "st": "4.131"}, {"sp": "N", "t": "ταῦτα ἀκούσαντες οἱ Πέρσαι ἐβουλεύοντο. Δαρείου μέν νυν ἡ γνώμη ἦν Σκύθας ἑωυτῷ διδόναι σφέας τε αὐτοὺς καὶ γῆν τε καὶ ὕδωρ, εἰκάζων τῇδε, ὡς μῦς μὲν ἐν γῇ γίνεται καρπὸν τὸν αὐτὸν ἀνθρώπῳ σιτεόμενος, βάτραχος δὲ ἐν ὕδατι, ὄρνις δὲ μάλιστα ἔοικε ἵππῳ, τοὺς δὲ ὀιστοὺς ὡς τὴν ἑωυτῶν ἀλκὴν παραδιδοῦσι. αὕτη μὲν Δαρείῳ ἀπεδέδεκτο ἡ γνώμη. συνεστήκεε δὲ ταύτῃ τῇ γνώμῃ ἡ Γοβρύεω, τῶν ἀνδρῶν τῶν ἑπτὰ ἑνὸς τῶν τὸν Μάγον κατελόντων, εἰκάζοντος τὰ δῶρα λέγειν ἢν μὴ ὄρνιθες γενόμενοι ἀναπτῆσθε ἐς τὸν οὐρανόν, ὦ Πέρσαι, ἢ μύες γενόμενοι κατὰ τῆς γῆς καταδύητε, ἢ βάτραχοι γενόμενοι ἐς τὰς λίμνας ἐσπηδήσητε, οὐκ ἀπονοστήσετε ὀπίσω ὑπὸ τῶνδε τῶν τοξευμάτων βαλλόμενοι.", "st": "4.132"}, {"sp": "N", "t": "Πέρσαι μὲν δὴ τὰ δῶρα εἴκαζον. ἡ δὲ Σκυθέων μία μοῖρα ἡ ταχθεῖσα πρότερον μὲν παρὰ τὴν Μαιῆτιν λίμνην φρουρέειν, τότε δὲ ἐπὶ τὸν Ἴστρον Ἴωσι ἐς λόγους ἐλθεῖν, ὡς ἀπίκετο ἐπὶ τὴν γέφυραν, ἔλεγε τάδε. ἄνδρες Ἴωνες, ἐλευθερίην ἥκομεν ὑμῖν φέροντες, ἤν πέρ γε ἐθέλητε ἐσακούειν. πυνθανόμεθα γὰρ Δαρεῖον ἐντείλασθαι ὑμῖν ἑξήκοντα ἡμέρας μούνας φρουρήσαντας τὴν γέφυραν, αὐτοῦ μὴ παραγενομένου ἐν τούτῳ τῷ χρόνῳ, ἀπαλλάσσεσθαι ἐς τὴν ὑμετέρην. νῦν ὦν ὑμεῖς τάδε ποιεῦντες ἐκτὸς μὲν ἔσεσθε πρὸς ἐκείνου αἰτίης, ἐκτὸς δὲ πρὸς ἡμέων· τὰς προκειμένας ἡμέρας παραμείναντες τὸ ἀπὸ τούτου ἀπαλλάσσεσθε. οὗτοι μέν νυν ὑποδεξαμένων Ἰώνων ποιήσειν ταῦτα ὀπίσω τὴν ταχίστην ἐπείγοντο.", "st": "4.133"}, {"sp": "N", "t": "Πέρσῃσι δὲ μετὰ τὰ δῶρα ἐλθόντα Δαρείῳ ἀντετάχθησαν οἱ ὑπολειφθέντες Σκύθαι πεζῷ καὶ ἵπποισι ὡς συμβαλέοντες. τεταγμένοισι δὲ τοῖσι Σκύθῃσι λαγὸς ἐς τὸ μέσον διήιξε. τῶν δὲ ὡς ἕκαστοι ὥρων τὸν λαγὸν ἐδίωκον. ταραχθέντων δὲ τῶν Σκυθέων καὶ βοῇ χρεωμένων, εἴρετο ὁ Δαρεῖος τῶν ἀντιπολεμίων τὸν θόρυβον· πυθόμενος δὲ σφέας τὸν λαγὸν διώκοντας, εἶπε ἄρα πρὸς τούς περ ἐώθεε καὶ τὰ ἄλλα λέγειν οὗτοι ὧνδρες ἡμέων πολλὸν καταφρονέουσι, καί μοι νῦν φαίνεται Γοβρύης εἶπαι περὶ τῶν Σκυθικῶν δώρων ὀρθῶς. ὡς ὦν οὕτω ἤδη δοκεόντων καὶ αὐτῷ μοι ἔχειν, βουλῆς ἀγαθῆς δεῖ, ὅκως ἀσφαλέως ἡ κομιδὴ ἡμῖν ἔσται τὸ ὀπίσω. πρὸς ταῦτα Γοβρύης εἶπε ὦ βασιλεῦ, ἐγὼ σχεδὸν μὲν καὶ λόγῳ ἠπιστάμην τούτων τῶν ἀνδρῶν τὴν ἀπορίην, ἐλθὼν δὲ μᾶλλον ἐξέμαθον, ὁρέων αὐτοὺς ἐμπαίζοντας ἡμῖν. νῦν ὦν μοι δοκέει, ἐπεὰν τάχιστα νὺξ ἐπέλθῃ, ἐκκαύσαντας τὰ πυρὰ ὡς ἐώθαμεν καὶ ἄλλοτε ποιέειν, τῶν στρατιωτέων τοὺς ἀσθενεστάτους ἐς τὰς ταλαιπωρίας ἐξαπατήσαντας καὶ τοὺς ὄνους πάντας καταδήσαντας ἀπαλλάσσεσθαι, πρὶν ἢ καὶ ἐπὶ τὸν Ἴστρον ἰθῦσαι Σκύθας λύσοντας τὴν γέφυραν, ἢ καί τι Ἴωσι δόξαι τὸ ἡμέας οἷον τε ἔσται ἐξεργάσασθαι.", "st": "4.134"}, {"sp": "N", "t": "Γοβρύης μὲν ταῦτα συνεβούλευε. μετὰ δὲ νύξ τε ἐγίνετο καὶ Δαρεῖος ἐχρᾶτο τῇ γνώμῃ ταύτῃ· τοὺς μὲν καματηροὺς τῶν ἀνδρῶν καὶ τῶν ἦν ἐλάχιστος ἀπολλυμένων λόγος, καὶ τοὺς ὄνους πάντας καταδήσας κατέλιπε αὐτοῦ ἐν τῷ στρατοπέδω. κατέλιπε δὲ τούς τε ὄνους καὶ τοὺς ἀσθενέας τῆς στρατιῆς τῶνδε εἵνεκεν, ἵνα οἱ μὲν ὄνοι βοὴν παρέχωνται· οἱ δὲ ἄνθρωποι ἀσθενείης μὲν εἵνεκεν κατελείποντο, προφάσιος δὲ τῆσδε δηλαδή, ὡς αὐτὸς μὲν σὺν τῷ καθαρῷ τοῦ στρατοῦ ἐπιθήσεσθαι μέλλοι τοῖσι Σκύθῃσι, οὗτοι δὲ τὸ στρατόπεδον τοῦτον τὸν χρόνον ῥυοίατο. ταῦτα τοῖσι ὑπολελειμμένοισι ὑποθέμενος ὁ Δαρεῖος καὶ πυρὰ ἐκκαύσας τὴν ταχίστην ἐπείγετο ἐπὶ τὸν Ἴστρον. οἱ δὲ ὄνοι ἐρημωθέντες τοῦ ὁμίλου οὕτω δὴ μᾶλλον πολλῷ ἵεσαν τῆς φωνῆς· ἀκούσαντες δὲ οἱ Σκύθαι τῶν ὄνων πάγχυ κατὰ χώρην ἤλπιζον τοὺς Πέρσας εἶναι.", "st": "4.135"}, {"sp": "N", "t": "ἡμέρης δὲ γενομένης γνόντες οἱ ὑπολειφθέντες ὡς προδεδομένοι εἶεν ὑπὸ Δαρείου, χεῖράς τε προετείνοντο τοῖσι Σκύθῃσι καὶ ἔλεγον τὰ κατήκοντα· οἳ δὲ ὡς ἤκουσαν ταῦτα τὴν ταχίστην συστραφέντες, αἵ τε δύο μοῖραι τῶν Σκυθέων καὶ ἡ μία καὶ Σαυρομάται καὶ Βουδῖνοι καὶ Γελωνοί, ἐδίωκον τοὺς Πέρσας ἰθὺ τοῦ Ἴστρου. ἅτε δὲ τοῦ Περσικοῦ μὲν τοῦ πολλοῦ ἐόντος πεζοῦ στρατοῦ καὶ τὰς ὁδοὺς οὐκ ἐπισταμένου, ὥστε οὐ τετμημενέων τῶν ὁδῶν, τοῦ δὲ Σκυθικοῦ ἱππότεω καὶ τὰ σύντομα τῆς ὁδοῦ ἐπισταμένου, ἁμαρτόντες ἀλλήλων, ἔφθησαν πολλῷ οἱ Σκύθαι τοὺς Πέρσας ἐπὶ τὴν γέφυραν ἀπικόμενοι. μαθόντες δὲ τοὺς Πέρσας οὔκω ἀπιγμένους ἔλεγον πρὸς τοὺς Ἴωνας ἐόντας ἐν τῇσι νηυσί ἄνδρες Ἴωνες, αἵ τε ἡμέραι ὑμῖν τοῦ ἀριθμοῦ διοίχηνται καὶ οὐ ποιέετε δίκαια ἔτι παραμένοντες. ἀλλ’ ἐπεὶ πρότερον δειμαίνοντες ἐμένετε, νῦν λύσαντες τὸν πόρον τὴν ταχίστην ἄπιτε χαίροντες ἐλεύθεροι, θεοῖσί τε καὶ Σκύθῃσι εἰδότες χάριν. τὸν δὲ πρότερον ἐόντα ὑμέων δεσπότην ἡμεῖς παραστησόμεθα οὕτω ὥστε ἐπὶ μηδαμοὺς ἔτι ἀνθρώπους αὐτὸν στρατεύσασθαι.", "st": "4.136"}, {"sp": "N", "t": "πρὸς ταῦτα Ἴωνες ἐβουλεύοντο. Μιλτιάδεω μὲν τοῦ Ἀθηναίου, στρατηγέοντος καὶ τυραννεύοντος Χερσονησιτέων τῶν ἐν Ἑλλησπόντῳ, ἦν γνώμη πείθεσθαι Σκύθῃσι καὶ ἐλευθεροῦν Ἰωνίην, Ἱστιαίου δὲ τοῦ Μιλησίου ἐναντίη ταύτῃ, λέγοντος ὡς νῦν μὲν διὰ Δαρεῖον ἕκαστος αὐτῶν τυραννεύει πόλιος· τῆς Δαρείου δὲ δυνάμιος καταιρεθείσης οὔτε αὐτὸς Μιλησίων οἷος τε ἔσεσθαι ἄρχειν οὔτε ἄλλον οὐδένα οὐδαμῶν· βουλήσεσθαι γὰρ ἑκάστην τῶν πολίων δημοκρατέεσθαι μᾶλλον ἢ τυραννεύεσθαι. Ἰστιαίου δὲ γνώμην ταύτην ἀποδεικνυμένου αὐτίκα πάντες ἦσαν τετραμμένοι πρὸς ταύτην τὴν γνώμην, πρότερον τὴν Μιλτιάδεω αἱρεόμενοι.", "st": "4.137"}, {"sp": "N", "t": "ἦσαν δὲ οὗτοι οἱ διαφέροντές τε τὴν ψῆφον καὶ ἐόντες λόγου πρὸς βασιλέος, Ἑλλησποντίων μὲν τύραννοι Δάφνις τε Ἀβυδηνὸς καὶ Ἵπποκλος Λαμψακηνὸς καὶ Ἡρόφαντος Παριηνὸς καὶ Μητρόδωρος Προκοννήσιος καὶ Ἀρισταγόρης Κυζικηνὸς καὶ Ἀρίστων Βυζάντιος. οὗτοι μὲν ἦσαν οἱ ἐξ Ἑλλησπόντου, ἀπ’ Ἰωνίης δὲ Στράττις τε Χῖος καὶ Αἰάκης Σάμιος καὶ Λαοδάμας Φωκαιεὺς καὶ Ἱστιαῖος Μιλήσιος, τοῦ ἦν γνώμη ἡ προκειμένη ἐναντίη τῇ Μιλτιάδεω. Αἰολέων δὲ παρῆν λόγιμος μοῦνος Ἀρισταγόρης, Κυμαῖος.", "st": "4.138"}, {"sp": "N", "t": "οὗτοι ὦν ἐπείτε τὴν Ἱστιαίου αἱρέοντο γνώμην, ἔδοξε σφι πρὸς ταύτῃ τάδε ἔργα τε καὶ ἔπεα προσθεῖναι, τῆς μὲν γεφύρης λύειν τὰ κατὰ τοὺς Σκύθας ἐόντα, λύειν δὲ ὅσον τόξευμα ἐξικνέεται, ἵνα καὶ ποιέειν τι δοκέωσι ποιεῦντες μηδὲν καὶ οἱ Σκύθαι μὴ πειρῴατο βιώμενοι καὶ βουλόμενοι διαβῆναι τὸν Ἴστρον κατὰ τὴν γέφυραν, εἰπεῖν τε λύοντας τῆς γεφύρης τὸ ἐς τὴν Σκυθικὴν ἔχον ὡς πάντα ποιήσουσι τὰ Σκύθησι ἐστὶ ἐν ἡδονῇ. ταῦτα μὲν προσέθηκαν τῇ γνώμῃ. μετὰ δὲ ἐκ πάντων ὑπεκρίνατο Ἱστιαῖος τάδε λέγων. Ἄνδρες Σκύθαι, χρηστὰ ἥκετε φέροντες καὶ ἐς καιρὸν ἐπείγεσθε· καὶ τά τε ἀπ’ ὑμέων ἡμῖν χρηστῶς ὁδοῦται καὶ τὰ ἀπ’ ἡμέων ἐς ὑμέας ἐπιτηδέως ὑπηρετέεται. ὡς γὰρ ὁρᾶτε, καὶ λύομεν τὸν πόρον καὶ προθυμίην πᾶσαν ἕξομεν θέλοντες εἶναι ἐλεύθεροι. ἐν ᾧ δὲ ἡμεῖς τάδε λύομεν, ὑμέας καιρός ἐστι δίζησθαι ἐκείνους, εὑρόντας δὲ ὑπέρ τε ἡμέων καὶ ὑμέων αὐτῶν τίσασθαι οὕτω ὡς κείνους πρέπει.", "st": "4.139"}, {"sp": "N", "t": "Σκύθαι μὲν τὸ δεύτερον Ἴωσι πιστεύσαντες λέγειν ἀληθέα ὑπέστρεφον ἐπὶ ζήτησιν τῶν Περσέων, καὶ ἡμάρτανον πάσης τῆς ἐκείνων διεξόδου. αἴτιοι δὲ τούτου αὐτοὶ οἱ Σκύθαι ἐγένοντο, τὰς νομὰς τῶν ἵππων τὰς ταύτῃ διαφθείραντες καὶ τὰ ὕδατα συγχώσαντες. εἰ γὰρ ταῦτα μὴ ἐποίησαν, παρεῖχε ἄν σφι, εἰ ἐβούλοντο, εὐπετέως ἐξευρεῖν τοὺς Πέρσας. νῦν δὲ τά σφι ἐδόκεε ἄριστα βεβουλεῦσθαι, κατὰ ταῦτα ἐσφάλησαν. Σκύθαι μέν νυν τῆς σφετέρης χώρης τῇ χιλός τε τοῖσι ἵπποισι καὶ ὕδατα ἦν, ταύτῃ διεξιόντες ἐδίζηντο τοὺς ἀντιπολεμίους, δοκέοντες καὶ ἐκείνους διὰ τοιούτων τὴν ἀπόδρησιν ποιέεσθαι. οἱ δὲ δὴ Πέρσαι τὸν πρότερον ἑωυτῶν γενόμενον στίβον, τοῦτον φυλάσσοντες ἤισαν, καὶ οὕτω μόγις εὗρον τὸν πόρον. οἷα δὲ νυκτός τε ἀπικόμενοι καὶ λελυμένης τῆς γεφύρης ἐντυχόντες, ἐς πᾶσαν ἀρρωδίην ἀπίκοντο μή σφεας οἱ Ἴωνες ἔωσι ἀπολελοιπότες.", "st": "4.140"}, {"sp": "N", "t": "ἦν δὲ περὶ Δαρεῖον ἀνὴρ Αἰγύπτιος φωνέων μέγιστον ἀνθρώπων· τοῦτον τὸν ἄνδρα καταστάντα ἐπὶ τοῦ χείλεος τοῦ Ἴστρου ἐκέλευε Δαρεῖος καλέειν Ἱστιαῖον Μιλήσιον. ὃ μὲν δὴ ἐποίεε ταῦτα, Ἱστιαῖος δὲ ἐπακούσας τῷ πρώτῳ κελεύσματι τάς τε νέας ἁπάσας παρεῖχε διαπορθμεύειν τὴν στρατιὴν καὶ τὴν γέφυραν ἔζευξε.", "st": "4.141"}, {"sp": "N", "t": "Πέρσαι μὲν ὦν οὕτω ἐκφεύγουσι Σκύθαι δὲ διζήμενοι καὶ τὸ δεύτερον ἥμαρτον τῶν Περσέων, καὶ τοῦτο μὲν ὡς ἐόντας Ἴωνας ἐλευθέρους κακίστους τε καὶ ἀνανδροτάτους κρίνουσι εἶναι ἁπάντων ἀνθρώπων, τοῦτο δέ, ὡς δούλων ἐόντων τὸν λόγον ποιεύμενοι, ἀνδράποδα φιλοδέσποτα φασὶ εἶναι καὶ ἄδρηστα. ταῦτα μὲν δὴ Σκύθῃσι ἐς Ἴωνας ἀπέρριπται.", "st": "4.142"}, {"sp": "N", "t": "Δαρεῖος δὲ διὰ τῆς Θρηίκης πορευόμενος ἀπίκετο ἐς Σηστὸν τῆς Χερσονήσου. ἐνθεῦτεν δὲ αὐτὸς μὲν διέβη τῇσι νηυσὶ ἐς τὴν Ἀσίην, λείπει δὲ στρατηγὸν ἐν τῇ Εὐρώπῃ Μεγάβαζον ἄνδρα Πέρσην· τῷ Δαρεῖος κοτὲ ἔδωκε γέρας, τοιόνδε εἴπας ἐν Πέρσῃσι ἔπος. ὁρμημένου Δαρείου ῥοιὰς τρώγειν, ὡς ἄνοιξε τάχιστα τὴν πρώτην τῶν ῥοιέων, εἴρετο αὐτὸν ὁ ἀδελφεὸς Ἀρτάβανος ὅ τι βούλοιτ’ ἄν οἱ τοσοῦτο πλῆθος γενέσθαι ὅσοι ἐν τῇ ῥοιῇ κόκκοι· Δαρεῖος δὲ εἶπε Μεγαβάζους ἄν οἱ τοσούτους ἀριθμὸν γενέσθαι βούλεσθαι μᾶλλον ἢ τὴν Ἑλλάδα ὑπήκοον. ἐν μὲν δὴ Πέρσησι ταῦτά μιν εἴπας ἐτίμα, τότε δὲ αὐτὸν ὑπέλιπε στρατηγὸν ἔχοντα τῆς στρατιῆς τῆς ἑωυτοῦ ὀκτὼ μυριάδας.", "st": "4.143"}, {"sp": "N", "t": "οὗτος δὲ ὁ Μεγάβαζος εἴπας τόδε τὸ ἔπος ἐλίπετο ἀθάνατον μνήμην πρὸς Ἑλλησποντίων. γενόμενος γὰρ ἐν Βυζαντίῳ ἐπύθετο ἑπτακαίδεκα ἔτεσι πρότερον Καλχηδονίους κτίσαντας τὴν χώρην Βυζαντίων, πυθόμενος δὲ ἔφη Καλχηδονίους τοῦτον τὸν χρόνον τυγχάνειν ἐόντας τυφλούς· οὐ γὰρ ἂν τοῦ καλλίονος παρεόντος κτίζειν χώρου τὸν αἰσχίονα ἑλέσθαι, εἰ μὴ ἦσαν τυφλοί. οὗτος δὴ ὦν τότε ὁ Μεγάβαζος στρατηγὸς λειφθεὶς ἐν τῇ χώρῃ Ἑλλησποντίων τοὺς μὴ μηδίζοντας κατεστρέφετο.", "st": "4.144"}, {"sp": "N", "t": "οὗτος μέν νυν ταῦτα ἔπρησσε. τὸν αὐτὸν δὲ τοῦτον χρόνον ἐγίνετο ἐπὶ Λιβύην ἄλλος στρατιῆς μέγας στόλος, διὰ πρόφασιν τὴν ἐγὼ ἀπηγήσομαι προδιηγησάμενος πρότερον τάδε. τῶν ἐκ τῆς Ἀργοῦς ἐπιβατέων παίδων παῖδες ἐξελασθέντες ὑπὸ Πελασγῶν τῶν ἐκ Βραυρῶνος ληισαμένων τὰς Ἀθηναίων γυναῖκας, ὑπὸ τούτων ἐξελασθέντες ἐκ Λήμνου οἴχοντο πλέοντες ἐς Λακεδαίμονα, ἱζόμενοι δὲ ἐν τῷ Τηϋγέτῳ πῦρ ἀνέκαιον. Λακεδαιμόνιοι δὲ ἰδόντες ἄγγελον ἔπεμπον πευσόμενοι τίνες τε καὶ ὁκόθεν εἰσί· οἳ δὲ τῷ ἀγγέλῳ εἰρωτῶντι ἔλεγον ὡς εἴησαν μὲν Μινύαι, παῖδες δὲ εἶεν τῶν ἐν τῇ Ἀργοῖ πλεόντων ἡρώων, προσσχόντας δὲ τούτους ἐς Λῆμνον φυτεῦσαι σφέας. οἱ δὲ Λακεδαιμόνιοι ἀκηκοότες τὸν λόγον τῆς γενεῆς τῶν Μινυέων, πέμψαντες τὸ δεύτερον εἰρώτων τί θέλοντες ἥκοιέν τε ἐς τὴν χώρην καὶ πῦρ αἴθοιεν. οἳ δὲ ἔφασαν ὑπὸ Πελασγῶν ἐκβληθέντες ἥκειν ἐς τοὺς πατέρας· δικαιότατον γὰρ εἶναι οὕτω τοῦτο γίνεσθαι. δέεσθαι δὲ οἰκέειν ἅμα τούτοισι μοῖράν τε τιμέων μετέχοντες καὶ τῆς γῆς ἀπολαχόντες. Λακεδαιμονίοισι δὲ ἕαδε δέκεσθαι τοὺς Μινύας ἐπ’ οἷσι θέλουσι αὐτοί. μάλιστα δὲ ἐνῆγε σφέας ὥστε ποιέειν ταῦτα τῶν Τυνδαριδέων ἡ ναυτιλίη ἐν τῇ Ἀργοῖ. δεξάμενοι δὲ τοὺς Μινύας γῆς τε μετέδοσαν καὶ ἐς φυλὰς διεδάσαντο. οἳ δὲ αὐτίκα μὲν γάμους ἔγημαν, τὰς δὲ ἐκ Λήμνου ἤγοντο ἐξέδοσαν ἄλλοισι.", "st": "4.145"}, {"sp": "N", "t": "χρόνου δὲ οὐ πολλοῦ διεξελθόντος αὐτίκα οἱ Μινύαι ἐξύβρισαν, τῆς τε βασιληίης μεταιτέοντες καὶ ἄλλα ποιέοντες οὐκ ὅσια. τοῖσι ὦν Λακεδαιμονίοισι ἔδοξε αὐτοὺς ἀποκτεῖναι, συλλαβόντες δὲ σφέας κατέβαλον ἐς ἑρκτήν. κτείνουσι δὲ τοὺς ἂν κτείνωσι Λακεδαιμόνιοι νυκτός, μετ’ ἡμέρην δὲ οὐδένα. ἐπεὶ ὦν ἔμελλον σφέας καταχρήσασθαι, παραιτήσαντο αἱ γυναῖκες τῶν Μινυέων, ἐοῦσαι ἀσταί τε καὶ τῶν πρώτων Σπαρτιητέων θυγατέρες, ἐσελθεῖν τε ἐς τὴν ἑρκτὴν καὶ ἐς λόγους ἐλθεῖν ἑκάστη τῷ ἑωυτῆς ἀνδρί. οἳ δὲ σφέας παρῆκαν, οὐδένα δόλον δοκέοντες ἐξ αὐτέων ἔσεσθαι. αἳ δὲ ἐπείτε ἐσῆλθον, ποιέουσι τοιάδε· πᾶσαν τὴν εἶχον ἐσθῆτα παραδοῦσαι τοῖσι ἀνδράσι αὐταὶ τὴν τῶν ἀνδρῶν ἔλαβον, οἱ δὲ Μινύαι ἐνδύντες τὴν γυναικηίην ἐσθῆτα ἅτε γυναῖκες ἐξήισαν ἔξω, ἐκφυγόντες δὲ τρόπῳ τοιούτῳ ἵζοντο αὖτις ἐς τὸ Τηΰγετον.", "st": "4.146"}, {"sp": "N", "t": "τὸν δὲ αὐτὸν τοῦτον χρόνον Θήρας ὁ Αὐτεσίωνος τοῦ Τισαμενοῦ τοῦ Θερσάνδρου τοῦ Πολυνείκεος ἔστελλε ἐς ἀποικίην ἐκ Λακεδαίμονος· ἦν δὲ ὁ Θήρας οὗτος, γένος ἐὼν Καδμεῖος, τῆς μητρὸς ἀδελφεὸς τοῖσι Ἀριστοδήμου παισὶ Εὐρυσθένεϊ καὶ Προκλέι. ἐόντων δὲ ἔτι τῶν παίδων τούτων νηπίων ἐπιτροπαίην εἶχε ὁ Θήρας τὴν ἐν Σπάρτῃ βασιληίην. αὐξηθέντων δὲ τῶν ἀδελφιδέων καὶ παραλαβόντων τὴν ἀρχήν, οὕτω δὴ ὁ Θήρας δεινὸν ποιεύμενος ἄρχεσθαι ὑπ’ ἄλλων ἐπείτε ἐγεύσατο ἀρχῆς, οὐκ ἔφη μένειν ἐν τῇ Λακεδαίμονι ἀλλ’ ἀποπλεύσεσθαι ἐς τοὺς συγγενέας. ἦσαν δὲ ἐν τῇ νῦν Θήρῃ καλεομένῃ νήσῳ, πρότερον δὲ Καλλίστῃ τῇ αὐτῇ ταύτῃ, ἀπόγονοι Μεμβλιάρου τοῦ Ποικίλεω ἀνδρὸς Φοίνικος. Κάδμος γὰρ ὁ Ἀγήνορος Εὐρώπην διζήμενος προσέσχε ἐς τὴν νῦν Θήρην καλεομένην· προσσχόντι δὲ εἴτε δή οἱ ἡ χώρη ἤρεσε, εἴτε καὶ ἄλλως ἠθέλησε ποιῆσαι τοῦτο· καταλείπει γὰρ ἐν τῇ νήσῳ ταύτῃ ἄλλους τε τῶν Φοινίκων καὶ δὴ καὶ τῶν ἑωυτοῦ συγγενέων Μεμβλίαρον. οὗτοι ἐνέμοντο τὴν Καλλίστην καλεομένην ἐπὶ γενεάς, πρὶν ἤ Θήραν ἐλθεῖν ἐκ Λακεδαίμονος, ὀκτὼ ἀνδρῶν.", "st": "4.147"}, {"sp": "N", "t": "ἐπὶ τούτους δὴ ὦν ὁ Θήρας λεὼν ἔχων ἀπὸ τῶν φυλέων ἔστελλε, συνοικήσων τούτοισι καὶ οὐδαμῶς ἐξελῶν αὐτοὺς ἀλλὰ κάρτα οἰκηιούμενος. ἐπείτε δὲ καὶ οἱ Μινύαι ἐκδράντες ἐκ τῆς ἑρκτῆς ἵζοντο ἐς τὸ Τηΰγετον, τῶν Λακεδαιμονίων βουλευομένων σφέας ἀπολλύναι παραιτέεται ὁ Θήρας, ὅκως μήτε φόνος γένηται, αὐτός τε ὑπεδέκετο σφέας ἐξάξειν ἐκ τῆς χώρης. συγχωρησάντων δὲ τῇ γνώμῃ τῶν Λακεδαιμονίων, τρισὶ τριηκοντέροισι ἐς τοὺς Μεμβιάρου ἀπογόνους ἔπλωσε, οὔτι πάντας ἄγων τοὺς Μινύας ἀλλ’ ὀλίγους τινάς. οἱ γὰρ πλεῦνες αὐτῶν ἐτράποντο ἐς τοὺς Παρωρεάτας καὶ Καύκωνας, τούτους δὲ ἐξελάσαντες ἐκ τῆς χώρης σφέας αὐτοὺς ἓξ μοίρας διεῖλον, καὶ ἔπειτα ἔκτισαν πόλιας τάσδε ἐν αὐτοῖσι, Λέπρεον Μάκιστον Φρίξας Πύργον Ἔπιον Νούδιον. τουτέων δὲ τὰς πλεῦνας ἐπ’ ἐμέο Ἠλεῖοι ἐπόρθησαν. τῇ δὲ νήσῳ ἐπὶ τοῦ οἰκιστέω Θήρα ἡ ἐπωνυμίη ἐγένετο.", "st": "4.148"}, {"sp": "N", "t": "ὁ δὲ παῖς οὐ γὰρ ἔφη οἱ συμπλεύσεσθαι, τοιγαρῶν ἔφη αὐτὸν καταλείψειν ὄιν ἐν λύκοισι. ἐπὶ του ἔπεος τούτου οὔνομα τῷ νεηνίσκῳ τούτῳ Οἰόλυκος ἐγένετο, καί κως τὸ οὔνομα τοῦτο ἐπεκράτησε. Οἰολύκου δὲ γίνεται Αἰγεύς, ἐπ’ οὗ Αἰγεῖδαι καλέονται φυλὴ μεγάλη ἐν Σπάρτῃ. τοῖσι δὲ ἐν τῇ φυλῇ ταύτῃ ἀνδράσι οὐ γὰρ ὑπέμειναν τὰ τέκνα, ἱδρύσαντο ἐκ θεοπροπίου Ἐρινύων τῶν Λαΐου τε καὶ Οἰδιπόδεω ἱρόν· καὶ μετὰ τοῦτο ὑπέμειναν … τὠυτὸ τοῦτο καὶ ἐν Θήρῃ τοῖσι ἀπὸ τῶν ἀνδρῶν τούτων γεγονόσι.", "st": "4.149"}, {"sp": "N", "t": "μέχρι μέν νυν τούτου τοῦ λόγου Λακεδαιμόνιοι Θηραίοισι κατὰ ταὐτὰ λέγουσι, τὸ δὲ ἀπὸ τούτου μοῦνοι Θηραῖοι ὧδε γενέσθαι λέγουσι. Γρῖννος ὁ Αἰσανίου ἐὼν Θήρα τούτου ἀπόγονος καὶ βασιλεύων Θήρης τῆς νήσου ἀπίκετο ἐς Δελφούς, ἄγων ἀπὸ τῆς πόλιος ἑκατόμβην· εἵποντο δέ οἱ καὶ ἄλλοι τῶν πολιητέων καὶ δὴ καὶ Βάττος ὁ Πολυμνήστου, ἐὼν γένος Εὐφημίδης τῶν Μινυέων. χρεωμένῳ δὲ τῷ Γρίννῳ τῷ βασιλέι τῶν Θηραίων περὶ ἄλλων χρᾷ ἡ Πυθίη κτίζειν ἐν Λιβύη πόλιν. ὁ δὲ ἀμείβετο λέγων ἐγὼ μὲν ὦναξ πρεσβύτερός τε ἤδη εἰμὶ καὶ βαρὺς ἀείρεσθαι· σὺ δὲ τινὰ τῶνδε τῶν νεωτέρων κέλευε ταῦτα ποιέειν. ἅμα τε ἔλεγε ταῦτα καὶ ἐδείκνυε ἐς τὸν Βάττον. τότε μὲν τοσαῦτα. μετὰ δὲ ἀπελθόντες ἀλογίην εἶχον τοῦ χρηστηρίου, οὔτε Λιβύην εἰδότες ὅκου γῆς εἴη οὔτε τολμῶντες ἐς ἀφανὲς χρῆμα ἀποστέλλειν ἀποικίην.", "st": "4.150"}, {"sp": "N", "t": "ἑπτὰ δὲ ἐτέων μετὰ ταῦτα οὐκ ὗε τὴν Θήρην, ἐν τοῖσι τὰ δένδρεα πάντα σφι τὰ ἐν τῇ νήσῳ πλὴν ἑνὸς ἐξαυάνθη. χρεωμένοισι δὲ τοῖσι Θηραίοισι προέφερε ἡ Πυθίη τὴν ἐς Λιβύην ἀποικίην. ἐπείτε δὲ κακοῦ οὐδὲν ἦν σφι μῆχος, πέμπουσι ἐς Κρήτην ἀγγέλους διζημένους εἴ τις Κρητῶν ἢ μετοίκων ἀπιγμένος εἴη ἐς Λιβύην. περιπλανώμενοι δὲ αὐτὴν οὗτοι ἀπίκοντο καὶ ἐς Ἴτανον πόλιν, ἐν ταύτῃ δὲ συμμίσγουσι ἀνδρὶ πορφυρέι τῷ οὕνομα ἦν Κορώβιος, ὃς ἔφη ὑπ’ ἀνέμων ἀπενειχθεὶς ἀπικέσθαι ἐς Λιβύην καὶ Λιβύης ἐς Πλατέαν νῆσον. μισθῷ δὲ τοῦτον πείσαντες ἦγον ἐς Θήρην, ἐκ δὲ Θήρης ἔπλεον κατάσκοποι ἄνδρες τὰ πρῶτα οὐ πολλοί· κατηγησαμένου δὲ τοῦ Κορωβίου ἐς τὴν νῆσον ταύτην δὴ τὴν Πλατέαν, τὸν μέν Κορώβιον λείπουσι, σιτία καταλιπόντες ὅσων δὴ μηνῶν, αὐτοὶ δὲ ἔπλεον τὴν ταχίστην ἀπαγγελέοντες Θηραίοισι περὶ τῆς νήσου.", "st": "4.151"}, {"sp": "N", "t": "ἀποδημεόντων δὲ τούτων πλέω χρόνον τοῦ συγκειμένου τὸν Κορώβιον ἐπέλιπε τὰ πάντα, μετὰ δὲ ταῦτα νηῦς Σαμίη, τῆς ναύκληρος ἦν Κωλαῖος, πλέουσα ἐπ’ Αἰγύπτου ἀπηνείχθη ἐς τὴν Πλατέαν ταύτην· πυθόμενοι δὲ οἱ Σάμιοι παρὰ τοῦ Κορωβίου τὸν πάντα λόγον, σιτία οἱ ἐνιαυτοῦ καταλείπουσι. αὐτοὶ δὲ ἀναχθέντες ἐκ τῆς νήσου καὶ γλιχόμενοι Αἰγύπτου ἔπλεον, ἀποφερόμενοι ἀπηλιώτῃ ἀνέμῳ· καὶ οὐ γὰρ ἀνίει τὸ πνεῦμα, Ἡρακλέας στήλας διεκπερήσαντες ἀπίκοντο ἐς Ταρτησσόν, θείῃ πομπῇ χρεώμενοι. τὸ δὲ ἐμπόριον τοῦτο ἦν ἀκήρατον τοῦτον τὸν χρόνον, ὥστε ἀπονοστήσαντες οὗτοι ὀπίσω μέγιστα δὴ Ἑλλήνων πάντων τῶν ἡμεῖς ἀτρεκείην ἴδμεν ἐκ φορτίων ἐκέρδησαν, μετά γε Σώστρατον τὸν Λαοδάμαντος Αἰγινήτην· τούτῳ γὰρ οὐκ οἷά τε ἐστὶ ἐρίσαι ἄλλον. οἱ δὲ Σάμιοι τὴν δεκάτην τῶν ἐπικερδίων ἐξελόντες ἓξ τάλαντα ἐποιήσαντο χαλκήιον κρητῆρος Ἀργολικοῦ τρόπον· πέριξ δὲ αὐτοῦ γρυπῶν κεφαλαὶ πρόκροσσοί εἰσι. καὶ ἀνέθηκαν ἐς τὸ Ἥραιον, ὑποστήσαντες αὐτῷ τρεῖς χαλκέους κολοσσοὺς ἑπταπήχεας τοῖσι γούνασι ἐρηρεισμένους. Κυρηναίοισι δὲ καὶ Θηραίοισι ἐς Σαμίους ἀπὸ τούτου τοῦ ἔργου πρῶτα φιλίαι μεγάλαι συνεκρήθησαν.", "st": "4.152"}, {"sp": "N", "t": "οἱ δὲ Θηραῖοι ἐπείτε τὸν Κορώβιον λιπόντες ἐν τῇ νήσῳ ἀπίκοντο ἐς τὴν Θήρην, ἀπήγγελλον ὥς σφι εἴη νῆσος ἐπὶ Λιβύῃ ἐκτισμένη. Θηραίοισι δὲ ἕαδε ἀδελφεόν τε ἀπ’ ἀδελφεοῦ πέμπειν πάλῳ λαγχάνοντα καὶ ἀπὸ τῶν χώρων ἁπάντων ἑπτὰ ἐόντων ἄνδρας, εἶναι δὲ σφέων καὶ ἡγεμόνα καὶ βασιλέα Βάττον. οὕτω δὴ στέλλουσι δύο πεντηκοντέρους ἐς τὴν Πλατέαν.", "st": "4.153"}, {"sp": "N", "t": "ταῦτα δὲ Θηραῖοι λέγουσι, τὰ δ’ ἐπίλοιπα τοῦ λόγου συμφέρονται ἤδη Θηραῖοι Κυρηναίοισι. Κυρηναῖοι γὰρ τὰ περὶ Βάττον οὐδαμῶς ὁμολογέουσι Θηραίοισι λέγουσι γὰρ οὕτω. ἔστι τῆς Κρήτης Ὀαξὸς πόλις, ἐν τῇ ἐγένετο Ἐτέαρχος βασιλεύς, ὃς ἐπὶ θυγατρὶ ἀμήτορι τῇ οὔνομα ἦν Φρονίμη, ἐπὶ ταύτῃ ἔγημε ἄλλην γυναῖκα. ἣ δὲ ἐπεσελθοῦσα ἐδικαίου καὶ τῷ ἔργῳ εἶναι μητρυιὴ τῇ Φρονίμῃ, παρέχουσα τε κακὰ καὶ πᾶν ἐπ’ αὐτῇ μηχανωμένη, καὶ τέλος μαχλοσύνην ἐπενείκασά οἱ πείθει τὸν ἄνδρα ταῦτα ἔχειν οὕτω. ὁ δὲ ἀναγνωσθεὶς ὑπὸ τῆς γυναικὸς ἔργον οὐκ ὅσιον ἐμηχανᾶτο ἐπὶ τῇ θυγατρί. ἦν γὰρ δὴ Θεμίσων ἀνὴρ Θηραῖος ἔμπορος ἐν τῇ Ὀαξῷ· τοῦτον ὁ Ἐτέαρχος παραλαβὼν ἐπὶ ξείνια ἐξορκοῖ ἦ μέν οἱ διηκονήσειν ὅ τι ἂν δεηθῇ. ἐπείτε δὴ ἐξώρκωσε, ἀγαγών οἱ παραδιδοῖ τὴν ἑωυτοῦ θυγατέρα καὶ ταύτην ἐκέλευε καταποντῶσαι ἀπαγαγόντα. ὁ δὲ Θεμίσων περιημεκτήσας τῇ ἀπάτῃ τοῦ ὅρκου καὶ διαλυσάμενος τὴν ξεινίην ἐποίεε τοιάδε· παραλαβὼν τὴν παῖδα ἀπέπλεε· ὡς δὲ ἐγίνετο ἐν τῷ πελάγεϊ, ἀποσιεύμενος τὴν ἐξόρκωσιν τοῦ Ἐτεάρχου, σχοινίοισι αὐτὴν διαδήσας κατῆκε ἐς τὸ πέλαγος, ἀνασπάσας δὲ ἀπίκετο ἐς τὴν Θήρην.", "st": "4.154"}, {"sp": "N", "t": "ἐνθεῦτεν δὲ τὴν Φρονίμην παραλαβὼν Πολύμνηστος, ἐὼν τῶν Θηραίων ἀνὴρ δόκιμος, ἐπαλλακεύετο. χρόνου δὲ περιιόντος ἐξεγένετό οἱ παῖς ἰσχόφωνος καὶ τραυλός, τῷ οὔνομα ἐτέθη Βάττος, ὡς Θηραῖοι τε καὶ Κυρηναῖοι λέγουσι, ὡς μέντοι ἐγὼ δοκέω, ἄλλο τι· Βάττος δὲ μετωνομάσθη, ἐπείτε ἐς Λιβύην ἀπίκετο, ἀπό τε τοῦ χρηστηρίου τοῦ γενομένου ἐν Δελφοῖσι αὐτῷ καὶ ἀπὸ τῆς τιμῆς τὴν ἔσχε τὴν ἐπωνυμίην ποιεύμενος. Λίβυες γὰρ βασιλέα βάττον καλέουσι, καὶ τούτου εἵνεκα δοκέω θεσπίζουσαν τὴν Πυθίην καλέσαι μιν Λιβυκῇ γλώσσῃ, εἰδυῖαν ὡς βασιλεὺς ἔσται ἐν Λιβύῃ. ἐπείτε γὰρ ἠνδρώθη οὗτος, ἦλθε ἐς Δελφοὺς περὶ τῆς φωνῆς· ἐπειρωτῶντι δέ οἱ χρᾷ ἡ Πυθίη τάδε.", "st": "4.155"}, {"sp": "N", "t": "Βάττ’ ἐπὶ φωνὴν ἦλθες. ἄναξ δέ σε Φοῖβος Ἀπόλλων<br>ἐς Λιβύην πέμπει μηλοτρόφον οἰκιστῆρα,", "st": "4.155b"}, {"sp": "N", "t": "ὥσπερ εἰ εἴποι Ἑλλάδι γλώσσῃ χρεωμένη ὦ βασιλεῦ, ἐπὶ φωνὴν ἦλθες. ὃ δ’ ἀμείβετο τοῖσιδε. ὦναξ, ἐγὼ μὲν ἦλθον παρὰ σὲ χρησάμενος περὶ τῆς φωνῆς, σὺ δέ μοι ἄλλα ἀδύνατα χρᾷς, κελεύων Λιβύην ἀποικίζειν τέῳ δυνάμι, κοίῃ χειρί; ταῦτα λέγων οὐκὶ ἔπειθε ἄλλα οἱ χρᾶν· ὡς δὲ κατὰ ταὐτὰ ἐθέσπιζέ οἱ καὶ πρότερον, οἴχετο μεταξὺ ἀπολιπὼν ὁ Βάττος ἐς τὴν Θήρην.", "st": "4.155.4"}, {"sp": "N", "t": "μετὰ δὲ αὐτῷ τε τούτῳ καὶ τοῖσι ἄλλοισι Θηραίοισι συνεφέρετο παλιγκότως. ἀγνοεῦντες δὲ τὰς συμφορὰς οἱ Θηραῖοι ἔπεμπον ἐς Δελφοὺς περὶ τῶν παρεόντων κακῶν. ἡ δὲ Πυθίη σφι ἔχρησε συγκτίζουσι Βάττῳ Κυρήνην τῆς Λιβύης ἄμεινον πρήξειν. ἀπέστελλον μετὰ ταῦτα τὸν Βάττον οἱ Θηραῖοι δύο πεντηκοντέροισι. πλώσαντες δὲ ἐς τὴν Λιβύην οὗτοι, οὐ γὰρ εἶχον ὅ τι ποιέωσι ἄλλο, ὀπίσω ἀπαλλάσσοντο ἐς τὴν Θήρην. οἱ δὲ Θηραῖοι καταγομένους ἔβαλλον καὶ οὐκ ἔων τῇ γῇ προσίσχειν, ἀλλ’ ὀπίσω πλώειν ἐκέλευον. οἳ δὲ ἀναγκαζόμενοι ὀπίσω ἀπέπλεον καὶ ἔκτισαν νῆσον ἐπὶ Λιβύῃ κειμένην, τῇ οὔνομα, ὡς καὶ πρότερον εἰρέθη, ἐστὶ Βλατέα. λέγεται δὲ ἴση εἶναι ἡ νῆσος τῇ νῦν Κυρηναίων πόλι.", "st": "4.156"}, {"sp": "N", "t": "ταύτην οἰκέοντες δύο ἔτεα, οὐδὲν γάρ σφι χρηστὸν συνεφέρετο, ἕνα αὐτῶν καταλιπόντες οἱ λοιποὶ πάντες ἀπέπλεον ἐς Δελφούς, ἀπικόμενοι δὲ ἐπὶ τὸ χρηστήριον ἐχρέωντο, φάμενοι οἰκέειν τε τὴν Λιβύην καὶ οὐδὲν ἄμεινον πρήσσειν οἰκεῦντες. ἡ δὲ Πυθίη σφι πρὸς ταῦτα χρᾷ τάδε.", "st": "4.157"}, {"sp": "N", "t": "αἰ τὺ ἐμεῦ Λιβύην μηλοτρόφον οἶδας ἄμεινον,<br>μὴ ἐλθὼν ἐλθόντος, ἄγαν ἄγαμαι σοφίην σεῦ.", "st": "4.157b"}, {"sp": "N", "t": "ἀκούσαντες δὲ τούτων οἱ ἀμφὶ τὸν Βάττον ἀπέπλωον ὀπίσω· οὐ γὰρ δή σφεας ἀπίει ὁ θεὸς τῆς ἀποικίης, πρὶν δὴ ἀπίκωνται ἐς αὐτὴν Λιβύην. ἀπικόμενοι δὲ ἐς τὴν νῆσον καὶ ἀναλαβόντες τὸν ἔλιπον, ἔκτισαν αὐτῆς τῆς Λιβύης χῶρον ἀντίον τῆς νήσου τῷ οὔνομα ἦν Ἄζιρις· τὸν νάπαι τε κάλλισται ἐπ’ ἀμφότερα συγκληίουσι καὶ ποταμὸς τὰ ἐπὶ θάτερα παραρρέει.", "st": "4.157.3"}, {"sp": "N", "t": "τοῦτον οἴκεον τὸν χῶρον ἓξ ἔτεα, ἑβδόμῳ δὲ σφέας ἔτει παραιτησάμενοι οἱ Λίβυες ὡς ἐς ἀμείνονα χῶρον ἄξουσι, ἀνέγνωσαν ἐκλιπεῖν. ἦγον δὲ σφέας ἐνθεῦτεν οἱ Λίβυες ἀναστήσαντες πρὸς ἑσπέρην, καὶ τὸν κάλλιστον τῶν χώρων ἵνα διεξιόντες οἱ Ἕλληνες μὴ ἴδοιεν, συμμετρησάμενοι τὴν ὥρην τῆς ἡμέρης νυκτὸς παρῆγον. ἔστι δὲ τῷ χώρῳ τούτῳ οὔνομα Ἴρασα. ἀγαγόντες δὲ σφέας ἐπὶ κρήνην λεγομένην εἶναι Ἀπόλλωνος εἶπαν ἄνδρες Ἕλληνες, ἐνθαῦτα ὑμῖν ἐπιτήδεον οἰκέειν. ἐνθαῦτα γὰρ ὁ οὐρανὸς τέτρηται.", "st": "4.158"}, {"sp": "N", "t": "ἐπὶ μέν νυν Βάττου τε τοῦ οἰκιστέω τῆς ζόης, ἄρξαντος ἐπὶ τεσσεράκοντα ἔτεα, καὶ τοῦ παιδὸς αὐτοῦ Ἀρκεσίλεω ἄρξαντος ἑκκαίδεκα ἔτεα, οἴκεον οἱ Κυρηναῖοι ἐόντες τοσοῦτοι ὅσοι ἀρχὴν ἐς τὴν ἀποικίην ἐστάλησαν. ἐπὶ δὲ τοῦ τρίτου, Βάττου τοῦ εὐδαίμονος καλεομένου, Ἕλληνας πάντας ὥρμησε χρήσασα ἡ Πυθίη πλέειν συνοικήσοντας Κυρηναίοισι Λιβύην· ἐπεκαλέοντο γὰρ οἱ Κυρηναῖοι ἐπὶ γῆς ἀναδασμῷ· ἔχρησε δὲ ὧδε ἔχοντα.", "st": "4.159"}, {"sp": "N", "t": "ὃς δέ κεν ἐς Λιβύην πολυήρατον ὕστερον ἔλθῃ", "st": "4.159b"}, {"sp": "N", "t": "γᾶς ἀναδαιομένας, μετὰ οἷ ποκα φαμὶ μελήσειν. συλλεχθέντος δὲ ὁμίλου πολλοῦ ἐς τὴν Κυρήνην, περιταμνόμενοι γῆν πολλὴν οἱ περίοικοι Λίβυες καὶ ὁ βασιλεὺς αὑτῶν τῷ οὔνομα ἦν Ἀδικράν, οἷα τῆς τε χώρης στερισκόμενοι καὶ περιυβριζόμενοι ὑπὸ τῶν Κυρηναίων, πέμψαντες ἐς Αἴγυπτον ἔδοσαν σφέας αὐτοὺς Ἀπρίῃ τῷ Αἰγύπτου βασιλέι. ὁ δὲ συλλέξας στρατὸν Αἰγυπτίων πολλὸν ἔπεμψε ἐπὶ τὴν Κυρήνην. οἱ δὲ Κυρηναῖοι ἐκστρατευσάμενοι ἐς Ἴρασα χῶρον καὶ ἐπὶ κρήνην Θέστην συνέβαλόν τε τοῖσι Αἰγυπτίοισι καὶ ἐνίκησαν τῇ συμβολῇ. ἅτε γὰρ οὐ πεπειρημένοι πρότερον οἱ Αἰγύπτιοι Ἑλλήνων καὶ παραχρεώμενοι διεφθάρησαν οὕτω ὥστε ὀλίγοι τινὲς αὐτῶν ἀπενόστησαν ἐς Αἴγυπτον. ἀντὶ τούτων Αἰγύπτιοι καὶ ταῦτα ἐπιμεμφόμενοι Ἀπρίῃ ἀπέστησαν ἀπ’ αὐτοῦ.", "st": "4.159.4"}, {"sp": "N", "t": "τούτου δὲ τοῦ Βάττου παῖς γίνεται Ἀρκεσίλεως. ὃς βασιλεύσας πρῶτα τοῖσι ἑωυτοῦ ἀδελφεοῖσι ἐστασίασε, ἐς ὅ μιν οὗτοι ἀπολιπόντες οἴχοντο ἐς ἄλλον χῶρον τῆς Λιβύης καὶ ἐπ’ ἑωυτῶν βαλόμενοι ἔκτισαν πόλιν ταύτην ἣ τότε καὶ νῦν Βάρκη κλέεται· κτίζοντες δὲ ἅμα αὐτὴν ἀπιστᾶσι ἀπὸ τῶν Κυρηναίων τοὺς Λίβυας. μετὰ δὲ Ἀρκεσίλεως ἐς τοὺς ὑποδεξαμένους τε τῶν Λιβύων καὶ ἀποστάντας τοὺς αὐτοὺς τούτους ἐστρατεύετο· οἱ δὲ Λίβυες δείσαντες αὐτὸν οἴχοντο φεύγοντες πρὸς τοὺς ἠοίους τῶν Λιβύων. ὁ δὲ Ἀρκεσίλεως εἵπετο φεύγουσι, ἐς οὗ ἐν Λεύκωνί τε τῆς Λιβύης ἐγίνετο ἐπιδιώκων καὶ ἔδοξε τοῖσι Λίβυσι ἐπιθέσθαι οἱ. συμβαλόντες δὲ ἐνίκησαν τοὺς Κυρηναίους τοσοῦτο ὥστε ἑπτακισχιλίους ὁπλίτας Κυρηναίων ἐνθαῦτα πεσεῖν. μετὰ δὲ τὸ τρῶμα τοῦτο Ἀρκεσίλεων μὲν κάμνοντά τε καὶ φάρμακον πεπωκότα ὁ ἀδελφεὸς Ἁλίαρχος ἀποπνίγει, Ἁλίαρχον δὲ ἡ γυνὴ ἡ Ἀρκεσίλεω δόλῳ κτείνει, τῇ οὔνομα ἦν Ἐρυξώ.", "st": "4.160"}, {"sp": "N", "t": "διεδέξατο δὲ τὴν βασιληίην τοῦ Ἀρκεσίλεω ὁ παῖς Βάττος, χωλός τε ἐὼν καὶ οὐκ ἀρτίπους. οἱ δὲ Κυρηναῖοι πρὸς τὴν καταλαβοῦσαν συμφορὴν ἔπεμπον ἐς Δελφοὺς ἐπειρησομένους ὅντινα τρόπον καταστησάμενοι κάλλιστα ἂν οἰκέοιεν. ἡ δὲ Πυθίη ἐκέλευε ἐκ Μαντινέης τῆς Ἀρκάδων καταρτιστῆρα ἀγαγέσθαι. αἴτεον ὦν οἱ Κυρηναῖοι, καὶ οἱ Μαντινέες ἔδοσαν ἄνδρα τῶν ἀστῶν δοκιμώτατον, τῷ οὔνομα ἦν Δημῶναξ. οὗτος ὦν ὡνὴρ ἀπικόμενος ἐς τὴν Κυρήνην καὶ μαθὼν ἕκαστα τοῦτο μὲν τριφύλους ἐποίησε σφεας, τῇδε διαθείς· Θηραίων μὲν καὶ τῶν περιοίκων μίαν μοῖραν ἐποίησε, ἄλλην δὲ Πελοποννησίων καὶ Κρητῶν, τρίτην δὲ νησιωτέων πάντων. τοῦτο δὲ τῷ βασιλέι Βάττῳ τεμένεα ἐξελὼν καὶ ἱρωσύνας, τὰ ἄλλα πάντα τὰ πρότερον εἶχον οἱ βασιλέες ἐς μέσον τῷ δήμῳ ἔθηκε.", "st": "4.161"}, {"sp": "N", "t": "ἐπὶ μὲν δὴ τούτου τοῦ Βάττου οὕτω διετέλεε ἐόντα, ἐπὶ δὲ τοῦ τούτου παιδὸς Ἀρκεσίλεω πολλὴ ταραχὴ περὶ τῶν τιμέων ἐγένετο. Ἀρκεσίλεως γὰρ ὁ Βάττου τε τοῦ χωλοῦ καὶ Φερετίμης οὐκ ἔφη ἀνέξεσθαι κατὰ τὰ ὁ Μαντινεὺς Δημῶναξ ἔταξε, ἀλλὰ ἀπαίτεε τὰ τῶν προγόνων γέρεα. ἐνθεῦτεν στασιάζων ἑσσώθη καὶ ἔφυγε ἐς Σάμον, ἡ δὲ μήτηρ οἱ ἐς Σαλαμῖνα τῆς Κύπρου ἔφυγε. τῆς δὲ Σαλαμῖνος τοῦτον τὸν χρόνον ἐπεκράτεε Εὐέλθων, ὃς τὸ ἐν Δελφοῖσι θυμιητήριον, ἐὸν ἀξιοθέητον ἀνέθηκε, τὸ ἐν τῷ Κορινθίων θησαυρῷ κέεται. ἀπικομένη δὲ παρὰ τοῦτον ἡ Φερετίμη ἐδέετο στρατιῆς ἣ κατάξει σφέας ἐς τὴν Κυρήνην. ὁ δὲ Εὐέλθων πᾶν μᾶλλον ἢ στρατιήν οἱ ἐδίδου· ἣ δὲ λαμβάνουσα τὸ διδόμενον καλὸν μὲν ἔφη καὶ τοῦτο εἶναι, κάλλιον δὲ ἐκεῖνο, τὸ δοῦναί οἱ δεομένῃ στρατιήν. τοῦτο ἐπὶ παντὶ γὰρ τῷ διδομένῳ ἔλεγε, τελευταῖόν οἱ ἐξέπεμψε δῶρον ὁ Εὐέλθων ἄτρακτον χρύσεον καὶ ἠλακάτην, προσῆν δὲ καὶ εἴριον. ἐπειπάσης δὲ αὖτις τῆς Φερετίμης τὠυτὸ ἔπος, ὁ Εὐέλθων ἔφη τοιούτοισι γυναῖκας δωρέεσθαι ἀλλ’ οὐ στρατιῇ.", "st": "4.162"}, {"sp": "N", "t": "ὁ δὲ Ἀρκεσίλεως τοῦτον τὸν χρόνον ἐὼν ἐν Σάμῳ συνήγειρε πάντα ἄνδρα ἐπὶ γῆς ἀναδασμῷ· συλλεγομένου δὲ στρατοῦ πολλοῦ, ἐστάλη ἐς Δελφοὺς Ἀρκεσίλεως χρησόμενος τῷ χρηστηρίῳ περὶ κατόδου. ἡ δὲ Πυθίη οἱ χρᾷ τάδε. ἐπὶ μὲν τέσσερας Βᾶττους καὶ Ἀρκεσίλεως τέσσερας, ὀκτὼ ἀνδρῶν γενεάς, διδοῖ ὑμῖν Λοξίης βασιλεύειν Κυρήνης, πλέον μέντοι τούτου οὐδὲ πειρᾶσθαι παραινέει. σὺ μέντοι ἥσυχος εἶναι κατελθὼν ἐς τὴν σεωυτοῦ. ἢν δὲ τὴν κάμινον εὕρῃς πλέην ἀμφορέων, μὴ ἐξοπτήσῃς τοὺς ἀμφορέας ἀλλ’ ἀπόπεμπε κατ’ οὖρον· εἰ δὲ ἐξοπτήσεις τὴν κάμινον, μὴ ἐσέλθῃς ἐς τὴν ἀμφίρρυτον· εἰ δὲ μὴ ἀποθανέαι καὶ αὐτὸς καὶ ταῦρος ὁ καλλιστεύων. ταῦτα ἡ Πυθίη Ἀρκεσίλεῳ χρᾷ.", "st": "4.163"}, {"sp": "N", "t": "ὁ δὲ παραλαβὼν τοὺς ἐκ τῆς Σάμου κατῆλθε ἐς τὴν Κυρήνην, καὶ ἐπικρατήσας τῶν πρηγμάτων τοῦ μαντηίου οὐκ ἐμέμνητο, ἀλλὰ δίκας τοὺς ἀντιστασιώτας αἴτεε τῆς ἑωυτοῦ φυγῆς. τῶν δὲ οἳ μὲν τὸ παράπαν ἐκ τῆς χώρης ἀπαλλάσσοντο, τοὺς δὲ τινὰς χειρωσάμενος ὁ Ἀρκεσίλεως ἐς Κύπρον ἀπέστειλε ἐπὶ διαφθορῇ. τούτους μέν νυν Κνίδιοι ἀπενειχθέντας πρὸς τὴν σφετέρην ἐρρύσαντο καὶ ἐς Θήρην ἀπέστειλαν· ἑτέρους δὲ τινὰς τῶν Κυρηναίων ἐς πύργον μέγαν Ἀγλωμάχου καταφυγόντας ἰδιωτικὸν ὕλην περινήσας ὁ Ἀρκεσίλεως ἐνέπρησε. μαθὼν δὲ ἐπ’ ἐξεργασμένοισι τὸ μαντήιον ἐὸν τοῦτο, ὅτι μιν ἡ Πυθίη οὐκ ἔα εὑρόντα ἐν τῇ καμίνῳ τοὺς ἀμφορέας ἐξοπτῆσαι, ἔργετο ἑκὼν τῆς τῶν Κυρηναίων πόλιος, δειμαίνων τε τὸν κεχρησμένον θάνατον καὶ δοκέων ἀμφίρρυτον τὴν Κυρήνην εἶναι. εἶχε δὲ γυναῖκα συγγενέα ἑωυτοῦ, θυγατέρα δὲ τῶν Βαρκαίων τοῦ βασιλέος, τῷ οὔνομα ἦν Ἀλάζειρ· παρὰ τοῦτον ἀπικνέεται, καί μιν Βαρκαῖοί τε ἄνδρες καὶ τῶν ἐκ Κυρήνης φυγάδων τινὲς καταμαθόντες ἀγοράζοντα κτείνουσι, πρὸς δὲ καὶ τὸν πενθερὸν αὐτοῦ Ἀλάζειρα. Ἀρκεσίλεως μέν νυν εἴτε ἑκὼν εἴτε ἀέκων ἁμαρτὼν τοῦ χρησμοῦ ἐξέπλησε μοῖραν τὴν ἑωυτοῦ.", "st": "4.164"}, {"sp": "N", "t": "ἡ δὲ μήτηρ Φερετίμη, ἕως μὲν ὁ Ἀρκεσίλεως ἐν τῇ Βάρκῃ διαιτᾶτο ἐξεργασμένος ἑωυτῷ κακόν, ἣ δὲ εἶχε αὐτὴ τοῦ παιδὸς τὰ γέρεα ἐν Κυρήνῃ καὶ τἆλλα νεμομένη καὶ ἐν βουλῇ παρίζουσα. ἐπείτε δὲ ἔμαθε ἐν τῇ Βάρκῃ ἀποθανόντα οἱ τὸν παῖδα, φεύγουσα οἰχώκεε ἐς Αἴγυπτον. ἦσαν γάρ οἱ ἐκ τοῦ Ἀρκεσίλεω εὐεργεσίαι ἐς Καμβύσεα τὸν Κύρου πεποιημέναι· οὗτος γὰρ ἦν ὁ Ἀρκεσίλεως ὃς Κυρήνην Καμβύσῃ ἔδωκε καὶ φόρον ἐτάξατο. ἀπικομένη δὲ ἐς τὴν Αἴγυπτον ἡ Φερετίμη Ἀρυάνδεω ἱκέτις ἵζετο, τιμωρῆσαι ἑωυτῇ κελεύουσα, προϊσχομένη πρόφασιν ὡς διὰ τὸν μηδισμὸν ὁ παῖς οἱ τέθνηκε. ὁ δὲ Ἀρυάνδης ἦν οὗτος τῆς Αἰγύπτου ὕπαρχος ὑπὸ Καμβύσεω κατεστεώς, ὃς ὑστέρῳ χρόνῳ τούτων παρισούμενος Δαρείῳ διεφθάρη. πυθόμενος γὰρ καὶ ἰδὼν Δαρεῖον ἐπιθυμέοντα μνημόσυνον ἑωυτοῦ λιπέσθαι τοῦτο τὸ μὴ ἄλλῳ εἴη βασιλέι κατεργασμένον, ἐμιμέετο τοῦτον, ἐς οὗ ἔλαβε τὸν μισθόν. Δαρεῖος μὲν γὰρ χρυσίον καθαρώτατον ἀπεψήσας ἐς τὸ δυνατώτατον νόμισμα ἐκόψατο, Ἀρυάνδης δὲ ἄρχων Αἰγύπτου ἀργύριον τὠυτὸ τοῦτο ἐποίεε, καὶ νῦν ἐστὶ ἀργύριον καθαρώτατον τὸ Ἀρυανδικόν. μαθὼν δέ μιν Δαρεῖος ταῦτα ποιεῦντα, αἰτίην οἱ ἄλλην ἐπενείκας ὥς οἱ ἐπανίσταιτο, ἀπέκτεινε.", "st": "4.165"}, {"sp": "N", "t": "τότε δὲ οὗτος ὁ Ἀρυάνδης κατοικτείρας Φερετίμην διδοῖ αὐτῇ στρατὸν τὸν ἐξ Αἰγύπτου ἅπαντα καὶ τὸν πεζὸν καὶ τὸν ναυτικόν· στρατηγὸν δὲ τοῦ μὲν πεζοῦ Ἄμασιν ἀπέδεξε ἄνδρα Μαράφιον, τοῦ δὲ ναυτικοῦ Βάδρην ἐόντα Πασαργάδην γένος. πρὶν δὲ ἢ ἀποστεῖλαι τὴν στρατιήν, ὁ Ἀρυάνδης πέμψας ἐς τὴν Βάρκην κήρυκα ἐπυνθάνετο τίς εἴη ὁ Ἀρκεσίλεων ἀποκτείνας. οἱ δὲ Βαρκαῖοι αὐτοὶ ὑπεδέκοντο πάντες· πολλά τε γὰρ καὶ κακὰ πάσχειν ὑπ’ αὐτοῦ. πυθόμενος δὲ ταῦτα ὁ Ἀρυάνδης οὕτω δὴ τὴν στρατιὴν ἀπέστειλε ἅμα τῇ Φερετίμῃ. αὕτη μέν νυν αἰτίη πρόσχημα τοῦ στόλου ἐγίνετο, ἀπεπέμπετο δὲ ἡ στρατιή, ὡς ἐμοὶ δοκέειν, ἐπὶ Λιβύης καταστροφῇ. Λιβύων γὰρ δὴ ἔθνεα πολλὰ καὶ παντοῖα ἐστι, καὶ τὰ μὲν αὐτῶν ὀλίγα βασιλέος ἦν ὑπήκοα, τὰ δὲ πλέω ἐφρόντιζε Δαρείου οὐδέν.", "st": "4.167"}, {"sp": "N", "t": "οἰκέουσι δὲ κατὰ τάδε Λίβυες. ἀπ’ Αἰγύπτου ἀρξάμενοι πρῶτοι Ἀδυρμαχίδαι Λιβύων κατοίκηνται, οἳ νόμοισι μὲν τὰ πλέω Αἰγυπτίοισι χρέωνται, ἐσθῆτα δὲ φορέουσι οἵην περ οἱ ἄλλοι Λίβυες. αἱ δὲ γυναῖκες αὐτῶν ψέλιον περὶ ἑκατέρῃ τῶν κνημέων φορέουσι χάλκεον· τὰς κεφαλὰς δὲ κομῶσαι, τοὺς φθεῖρας ἐπεὰν λάβωσι τοὺς ἑωυτῆς ἑκάστη ἀντιδάκνει καὶ οὕτω ῥίπτει. οὗτοι δὲ μοῦνοι Λιβύων τοῦτο ἐργάζονται, καὶ τῷ βασιλέι μοῦνοι τὰς παρθένους μελλούσας συνοικέειν ἐπιδεικνύουσι. ἣ δὲ ἂν τῷ βασιλέι ἀρεστὴ γένηται, ὑπὸ τούτου διαπαρθενεύεται. παρήκουσι δὲ οὗτοι οἱ Ἀδυρμαχίδαι ἀπ’ Αἰγύπτου μέχρι λιμένος τῷ οὔνομα Πλυνός ἐστι.", "st": "4.168"}, {"sp": "N", "t": "τούτων δὲ ἔχονται Γιλιγάμαι, νεμόμενοι τὸ πρὸς ἑσπέρην χώρην μέχρι Ἀφροδισιάδος νήσου. ἐν δὲ τῷ μεταξὺ τούτου χώρῳ ἥ τε Πλατέα νῆσος ἐπικέεται, τὴν ἔκτισαν οἱ Κυρηναῖοι, καὶ ἐν τῇ ἠπείρῳ Μενέλαος λιμήν ἐστι καὶ Ἄζιρις, τὴν οἱ Κυρηναῖοι οἴκεον, καὶ τὸ σίλφιον ἄρχεται ἀπὸ τούτου· παρήκει δὲ ἀπὸ Πλατέης νήσου μέχρι τοῦ στόματος τῆς Σύρτιος τὸ σίλφιον. νόμοισι δὲ χρέωνται οὗτοι παραπλησίοισι τοῖσι ἑτέροισι.", "st": "4.169"}, {"sp": "N", "t": "Γιλιγαμέων δὲ ἔχονται τὸ πρὸς ἑσπέρης Ἀσβύσται. οὗτοι ὑπὲρ Κυρήνης οἰκέουσι. ἐπὶ θάλασσαν δὲ οὐ κατήκουσι Ἀσβύσται τὸ γὰρ παρὰ θάλασσαν Κυρηναῖοι νέμονται. τεθριπποβάται δὲ οὐκ ἥκιστα ἀλλὰ μάλιστα Λιβύων εἰσί, νόμους δὲ τοὺς πλεῦνας μιμέεσθαι ἐπιτηδεύουσι τοὺς Κυρηναίων.", "st": "4.170"}, {"sp": "N", "t": "Ἀσβυστέων δὲ ἔχονται τὸ πρὸς ἑσπέρης Αὐσχίσαι· οὗτοι ὑπὲρ Βάρκης οἰκέουσι, κατήκοντες ἐπὶ θάλασσαν κατ’ Εὐεσπερίδας. Αὐσχισέων δὲ κατὰ μέσον τῆς χώρης οἰκέουσι Βάκαλες, ὀλίγον ἔθνος, κατήκοντες ἐπὶ θάλασσαν κατὰ Ταύχειρα πόλιν τῆς Βαρκαίης· νόμοισι δὲ τοῖσι αὐτοῖσι χρέωνται τοῖσι καὶ οἱ ὑπὲρ Κυρήνης.", "st": "4.171"}, {"sp": "N", "t": "Αὐσχισέων δὲ τούτων τὸ πρὸς ἑσπέρης ἔχονται Νασαμῶνες, ἔθνος ἐὸν πολλόν, οἳ τὸ θέρος καταλείποντες ἐπὶ τῇ θαλάσσῃ τὰ πρόβατα ἀναβαίνουσι ἐς Αὔγιλα χῶρον ὀπωριεῦντες τοὺς φοίνικας. οἳ δὲ πολλοὶ καὶ ἀμφιλαφέες πεφύκασι, πάντες ἐόντες καρποφόροι. τοὺς δὲ ἀττελέβους ἐπεὰν θηρεύσωσι, αὐήναντες πρὸς τὸν ἥλιον καταλέουσι καὶ ἔπειτα ἐπὶ γάλα ἐπιπάσσοντες πίνουσι. γυναῖκας δὲ νομίζοντες πολλὰς ἔχειν ἕκαστος ἐπίκοινον αὐτέων τὴν μῖξιν ποιεῦνται τρόπῳ παραπλησίῳ τῷ καὶ Μασσαγέται· ἐπεὰν σκίπωνα προστήσωνται, μίσγονται. πρῶτον δὲ γαμέοντος Νασαμῶνος ἀνδρὸς νόμος ἐστὶ τὴν νύμφην νυκτὶ τῇ πρώτῃ διὰ πάντων διεξελθεῖν τῶν δαιτυμόνων μισγομένην· τῶν δὲ ὡς ἕκαστος οἱ μιχθῇ, διδοῖ δῶρον τὸ ἂν ἔχῃ φερόμενος ἐξ οἴκου. ὁρκίοισι δὲ καὶ μαντικῇ χρέωνται τοιῇδε· ὀμνύουσι μὲν τοὺς παρὰ σφίσι ἄνδρας δικαιοτάτους καὶ ἀρίστους λεγομένους γενέσθαι, τούτους, τῶν τύμβων ἁπτόμενοι· μαντεύονται δὲ ἐπὶ τῶν προγόνων φοιτέοντες τὰ σήματα, καὶ κατευξάμενοι ἐπικατακοιμῶνται· τὸ δ’ ἂν ἴδη ἐν τῇ ὄψι ἐνύπνιον, τούτῳ χρᾶται. πίστισι δὲ τοιῇσιδε χρέωνται· ἐκ τῆς χειρὸς διδοῖ πιεῖν καὶ αὐτὸς ἐκ τῆς τοῦ ἑτέρου πίνει. ἢν δὲ μὴ ἔχωσι ὑγρὸν μηδέν, οἳ δὲ τῆς χαμᾶθεν σποδοῦ λαβόντες λείχουσι.", "st": "4.172"}, {"sp": "N", "t": "Νασαμῶσι δὲ προσόμουροι εἰσὶ Ψύλλοι. οὗτοι ἐξαπολώλασι τρόπῳ τοιῷδε· ὁ νότος σφι πνέων ἄνεμος τὰ ἔλυτρα τῶν ὑδάτων ἐξηύηνε, ἡ δὲ χώρη σφι ἅπασα ἐντὸς ἐοῦσα τῆς Σύρτιος ἦν ἄνυδρος. οἳ δὲ βουλευσάμενοι κοινῷ λόγῳ ἐστρατεύοντο ἐπὶ τὸν νότον (λέγω δὲ ταῦτα τὰ λέγουσι Λίβυες), καὶ ἐπείτε ἐγίνοντο ἐν τῇ ψάμμῳ, πνεύσας ὁ νότος κατέχωσε σφέας. ἐξαπολομένων δὲ τούτων ἔχουσι τὴν χώρην οἱ Νασαμῶνες.", "st": "4.173"}, {"sp": "N", "t": "τούτων δὲ κατύπερθε πρὸς νότον ἄνεμον ἐν τῇ θηριώδεϊ οἰκέουσι Γαράμαντες, οἳ πάντα ἄνθρωπον φεύγουσι καὶ παντὸς ὁμιλίην, καὶ οὔτε ὅπλον ἐκτέαται ἀρήιον οὐδὲν οὔτε ἀμύνεσθαι ἐπιστέαται.", "st": "4.174"}, {"sp": "N", "t": "οὗτοι μὲν δὴ κατύπερθε οἰκέουσι Νασαμώνων· τὸ δὲ παρὰ τὴν θάλασσαν ἔχονται τὸ πρὸς ἑσπέρης Μάκαι, οἳ λόφους κείρονται, τὸ μὲν μέσον τῶν τριχῶν ἀνιέντες αὔξεσθαι, τὰ δὲ ἔνθεν καὶ ἔνθεν κείροντες ἐν χροΐ, ἐς δὲ τὸν πόλεμον στρουθῶν καταγαίων δορὰς φορέουσι προβλήματα. διὰ δὲ αὐτῶν Κῖνυψ ποταμὸς ῥέων ἐκ λόφου καλευμένου Χαρίτων ἐς θάλασσαν ἐκδιδοῖ. ὁ δὲ λόφος οὗτος ὁ Χαρίτων δασὺς ἴδῃσι ἐστί, ἐούσης τῆς ἄλλης τῆς προκαταλεχθείσης Λιβύης ψιλῆς· ἀπὸ θαλάσσης δὲ ἐς αὐτὸν στάδιοι διηκόσιοι εἰσί.", "st": "4.175"}, {"sp": "N", "t": "Μακέων δὲ τούτων ἐχόμενοι Γινδᾶνες εἰσί, τῶν αἱ γυναῖκες περισφύρια δερμάτων πολλὰ ἑκάστη φορέει κατὰ τοιόνδε τι, ὡς λέγεται· κατ’ ἄνδρα ἕκαστον μιχθέντα περισφύριον περιδέεται· ἣ δὲ ἂν πλεῖστα ἔχῃ, αὕτη ἀρίστη δέδοκται εἶναι ὡς ὑπὸ πλείστων ἀνδρῶν φιληθεῖσα.", "st": "4.176"}, {"sp": "N", "t": "ἀκτὴν δὲ προέχουσαν ἐς τὸν πόντον τούτων τῶν Γινδάνων νέμονται Λωτοφάγοι, οἳ τὸν καρπὸν μοῦνον τοῦ λωτοῦ τρώγοντες ζώουσι. ὁ δὲ τοῦ λωτοῦ καρπὸς ἐστὶ μέγαθος ὅσον τε τῆς σχίνου, γλυκύτητα δὲ τοῦ φοίνικος τῷ καρπῷ προσείκελος. ποιεῦνται δὲ ἐκ τοῦ καρποῦ τούτου οἱ Λωτοφάγοι καὶ οἶνον.", "st": "4.177"}, {"sp": "N", "t": "λωτοφάγων δὲ τὸ παρὰ θάλασσαν ἔχονται Μάχλυες, τῷ λωτῷ μὲν καὶ οὗτοι χρεώμενοι, ἀτὰρ ἧσσον γε τῶν πρότερον λεχθέντων, κατήκουσι δὲ ἐπὶ ποταμὸν μέγαν τῷ οὔνομα Τρίτων ἐστί· ἐκδιδοῖ δὲ οὗτος ἐς λίμνην μεγάλην Τριτωνίδα. ἐν δὲ αὐτῇ, νῆσος ἔνι τῇ, οὔνομα Φλά. ταύτην δὲ τὴν νῆσον Λακεδαιμονίοισι φασὶ λόγιον εἶναι κτίσαι.", "st": "4.178"}, {"sp": "N", "t": "ἔστι δὲ καὶ ὅδε λόγος λεγόμενος. Ἰήσονα, ἐπείτε οἱ ἐξεργάσθη ὑπὸ τῷ Πηλίῳ ἡ Ἀργώ, ἐσθέμενον ἐς αὐτὴν ἄλλην τε ἑκατόμβην καὶ δὴ καὶ τρίποδα χάλκεον περιπλώειν Πελοπόννησον, βουλόμενον ἐς Δελφοὺς ἀπικέσθαι. καί μιν, ὡς πλέοντα γενέσθαι κατὰ Μαλέην, ὑπολαβεῖν ἄνεμον βορέην καὶ ἀποφέρειν πρὸς τὴν Λιβύην· πρὶν δὲ κατιδέσθαι γῆν, ἐν τοῖσι βράχεσι γενέσθαι λίμνης τῆς Τριτωνίδος. καί οἱ ἀπορέοντι τὴν ἐξαγωγὴν λόγος ἐστὶ φανῆναι Τρίτωνα καὶ κελεύειν τὸν Ἰήσονα ἑωυτῷ δοῦναι τὸν τρίποδα, φάμενόν σφι καὶ τὸν πόρον δέξειν καὶ ἀπήμονας ἀποστελέειν. πειθομένου δὲ τοῦ Ἰήσονος, οὕτω δὴ τόν τε διέκπλοον τῶν βραχέων δεικνύναι τὸν Τρίτωνά σφι καὶ τὸν τρίποδα θεῖναι ἐν τῷ ἑωυτοῦ ἱρῷ, ἐπιθεσπίσαντά τε τῷ τρίποδι καὶ τοῖσι σὺν Ἰήσονι σημήναντα τὸν πάντα λόγον, ὡς ἐπεὰν τὸν τρίποδα κομίσηται τῶν ἐκγόνων τις τῶν ἐν τῇ Ἀργοῖ συμπλεόντων, τότε ἑκατὸν πόλιας οἰκῆσαι περὶ τὴν Τριτωνίδα λίμνην Ἑλληνίδας πᾶσαν εἶναι ἀνάγκην. ταῦτα ἀκούσαντας τοὺς ἐπιχωρίους τῶν Λιβύων κρύψαι τὸν τρίποδα.", "st": "4.179"}, {"sp": "N", "t": "τούτων δὲ ἔχονται τῶν Μαχλύων Αὐσέες· οὗτοι δὲ καὶ οἱ Μάχλυες πέριξ τὴν Τριτωνίδα λίμνην οἰκέουσι, τὸ μέσον δέ σφι οὐρίζει ὁ Τρίτων. καὶ οἱ μὲν Μάχλυες τὰ ὀπίσω κομῶσι τῆς κεφαλῆς, οἱ δὲ Αὐσέες τὰ ἔμπροσθε. ὁρτῇ δὲ ἐνιαυσίῃ Ἀθηναίης αἱ παρθένοι αὐτῶν δίχα διαστᾶσαι μάχονται πρὸς ἀλλήλας λίθοισί τε καὶ ξύλοισι, τῷ αὐθιγενέι θεῷ λέγουσαι τὰ πάτρια ἀποτελέειν, τὴν Ἀθηναίην καλέομεν. τὰς δὲ ἀποθνησκούσας τῶν παρθένων ἐκ τῶν τρωμάτων ψευδοπαρθένους καλέουσι. πρὶν δὲ ἀνεῖναι αὐτὰς μάχεσθαι, τάδε ποιεῦσι κοινῇ. παρθένον τὴν καλλιστεύουσαν ἑκάστοτε κοσμήσαντες κυνέῃ τε Κορινθίῃ καὶ πανοπλίῃ Ἑλληνικῇ καὶ ἐπ’ ἅρμα ἀναβιβάσαντες περιάγουσι τὴν λίμνην κύκλῳ. ὁτέοισι δὲ τὸ πάλαι ἐκόσμεον τὰς παρθένους πρὶν ἤ σφι Ἕλληνας παροικισθῆναι, οὐκ ἔχω εἰπεῖν, δοκέω δ’ ὦν Αἰγυπτίοισι ὅπλοισι κοσμέεσθαι αὐτάς· ἀπὸ γὰρ Αἰγύπτου καὶ τὴν ἀσπίδα καὶ τὸ κράνος φημὶ ἀπῖχθαι ἐς τοὺς Ἕλληνας. τὴν δὲ Ἀθηναίην φασὶ Ποσειδέωνος εἶναι θυγατέρα καὶ τῆς Τριτωνίδος λίμνης, καί μιν μεμφθεῖσάν τι τῷ πατρὶ δοῦναι ἑωυτὴν τῷ Διί, τὸν δὲ Δία ἑωυτοῦ μιν ποιήσασθαι θυγατέρα. ταῦτα μὲν λέγουσι, μῖξιν δὲ ἐπίκοινον τῶν γυναικῶν ποιέονται, οὔτε συνοικέοντες κτηνηδόν τε μισγόμενοι. ἐπεὰν δὲ γυναικὶ τὸ παιδίον ἁδρὸν γένηται, συμφοιτῶσι ἐς τὠυτὸ οἱ ἄνδρες τρίτου μηνός, καὶ τῷ ἂν οἴκῃ τῶν ἀνδρῶν τὸ παιδίον, τούτου παῖς νομίζεται.", "st": "4.180"}, {"sp": "N", "t": "οὗτοι μὲν οἱ παραθαλάσσιοι τῶν νομάδων Λιβύων εἰρέαται, ὑπὲρ δὲ τούτων ἐς μεσόγαιαν ἡ θηριώδης ἐστὶ Λιβύη, ὑπὲρ δὲ τῆς θηριώδεος ὀφρύη ψάμμης κατήκει παρατείνουσα ἀπὸ Θηβέων τῶν Αἰγυπτιέων ἐπ’ Ἡρακλέας στήλας. ἐν δὲ τῇ ὀφρύῃ ταύτῃ μάλιστα διὰ δέκα ἡμερέων ὁδοῦ ἁλός ἐστι τρύφεα κατὰ χόνδρους μεγάλους ἐν κολωνοῖσι, καὶ ἐν κορυφῇσι ἑκάστου τοῦ κολωνοῦ ἀνακοντίζει ἐκ μέσου τοῦ ἁλὸς ὕδωρ ψυχρὸν καὶ γλυκύ, περὶ δὲ αὐτὸν ἄνθρωποι οἰκέουσι ἔσχατοι πρὸς τῆς ἐρήμου καὶ ὑπὲρ τῆς θηριώδεος, πρῶτοι μὲν ἀπὸ Θηβέων διὰ δέκα ἡμερέων ὁδοῦ Ἀμμώνιοι, ἔχοντες τὸ ἱρὸν ἀπὸ τοῦ Θηβαιέος Διός· καὶ γὰρ τὸ ἐν Θήβῃσι, ὡς καὶ πρότερον εἴρηταί μοι, κριοπρόσωπον τοῦ Διὸς τὤγαλμα ἐστί. τυγχάνει δὲ καὶ ἄλλο σφι ὕδωρ κρηναῖον ἐὸν, τὸ τὸν μὲν ὄρθρον γίνεται χλιαρόν, ἀγορῆς δὲ πληθυούσης ψυχρότερον, μεσαμβρίη τε ἐστὶ καὶ τὸ κάρτα γίνεται ψυχρόν· τηνικαῦτα δὲ ἄρδουσι τοὺς κήπους· ἀποκλινομένης δὲ τῆς ἡμέρης ὑπίεται τοῦ ψυχροῦ, ἐς οὗ δύεταί τε ὁ ἥλιος καὶ τὸ ὕδωρ γίνεται χλιαρόν. ἐπὶ δὲ μᾶλλον ἰὸν ἐς τὸ θερμὸν ἐς μέσας νύκτας πελάζει, τηνικαῦτα δὲ ζέει ἀμβολάδην· παρέρχονται τε μέσαι νύκτες καὶ ψύχεται μέχρι ἐς ἠῶ. ἐπίκλησιν δὲ αὕτη ἡ κρήνη καλέεται ἡλίου.", "st": "4.181"}, {"sp": "N", "t": "μετὰ δὲ Ἀμμωνίους διὰ τῆς ὀφρύης τῆς ψάμμου δι’ ἀλλέων δέκα ἡμερέων ὁδοῦ κολωνός τε ἁλός ἐστι ὅμοιος τῷ Ἀμμωνίῳ καὶ ὕδωρ, καὶ ἄνθρωποι περὶ αὐτὸν οἰκέουσι· τῷ δὲ χώρῳ τούτῳ οὔνομα Αὔγιλα ἐστί. ἐς τοῦτον τὸν χῶρον οἱ Νασαμῶνες ὀπωριεῦντες τοὺς φοίνικας φοιτῶσι.", "st": "4.182"}, {"sp": "N", "t": "ἀπὸ δὲ Αὐγίλων διὰ δέκα ἡμερέων ἀλλέων ὁδοῦ ἕτερος ἁλὸς κολωνὸς καὶ ὕδωρ καὶ φοίνικες καρποφόροι πολλοί, κατά περ καὶ ἐν τοῖσι ἑτέροισι· καὶ ἄνθρωποι οἰκέουσι ἐν αὐτῷ τοῖσι οὔνομα Γαράμαντες ἐστί, ἔθνος μέγα ἰσχυρῶς, οἳ ἐπὶ τὸν ἅλα γῆν ἐπιφορέοντες οὕτω σπείρουσι. συντομώτατον δ’ ἐστὶ ἐς τοὺς Λωτοφάγους, ἐκ τῶν τριήκοντα ἡμερέων ἐς αὐτοὺς ὁδός ἐστι· ἐν τοῖσι καὶ οἱ ὀπισθονόμοι βόες γίνονται· ὀπισθονόμοι δὲ διὰ τόδε εἰσι. τὰ κέρεα ἔχουσι κεκυφότα ἐς τὸ ἔμπροσθε· διὰ τοῦτο ὀπίσω ἀναχωρέοντες νέμονται· ἐς γὰρ τὸ ἔμπροσθε οὐκ οἷοι τε εἰσὶ προεμβαλλόντων ἐς τὴν γῆν τῶν κερέων. ἄλλο δὲ οὐδὲν διαφέρουσι τῶν ἄλλων βοῶν ὅτι μὴ τοῦτο καὶ τὸ δέρμα ἐς παχύτητά τε καὶ τρῖψιν. οἱ Γαράμαντες δὴ οὗτοι τοὺς τρωγλοδύτας Αἰθίοπας θηρεύουσι τοῖσι τεθρίπποισι· οἱ γὰρ τρωγλοδύται Αἰθίοπες πόδας τάχιστοι ἀνθρώπων πάντων εἰσὶ τῶν ἡμεῖς πέρι λόγους ἀποφερομένους ἀκούομεν. σιτέονται δὲ οἱ τρωγλοδύται ὄφις καὶ σαύρους καὶ τὰ τοιαῦτα τῶν ἑρπετῶν· γλῶσσαν δὲ οὐδεμιῇ ἄλλῃ παρομοίην νενομίκασι, ἀλλὰ τετρίγασι κατά περ αἱ νυκτερίδες.", "st": "4.183"}, {"sp": "N", "t": "ἀπὸ δὲ Γαραμάντων δι’ ἀλλέων δέκα ἡμερέων ὁδοῦ ἄλλος ἁλός τε κολωνὸς καὶ ὕδωρ, καὶ ἄνθρωποι περὶ αὐτὸν οἰκέουσι τοῖσι οὔνομα ἐστὶ Ἀτάραντες, οἳ ἀνώνυμοι εἰσὶ μοῦνοι ἀνθρώπων τῶν ἡμεῖς ἴδμεν· ἁλέσι μὲν γάρ σφι ἐστὶ Ἀτάραντες οὔνομα, ἑνὶ δὲ ἑκάστῳ αὐτῶν οὔνομα οὐδὲν κέεται. οὗτοι τῷ ἡλίῳ ὑπερβάλλοντι καταρῶνται καὶ πρὸς τούτοισι πάντα τὰ αἰσχρὰ λοιδορέονται, ὅτι σφέας καίων ἐπιτρίβει, αὐτούς τε τοὺς ἀνθρώπους καὶ τὴν χώρην αὐτῶν. μετὰ δὲ δι’ ἀλλέων δέκα ἡμερέων ἄλλος κολωνὸς ἁλὸς καὶ ὕδωρ, καὶ ἄνθρωποι περὶ αὐτὸν οἰκέουσι. ἔχεται δὲ τοῦ ἁλὸς τούτου ὄρος τῷ οὔνομα ἐστὶ Ἄτλας, ἔστι δὲ στεινὸν καὶ κυκλοτερὲς πάντῃ, ὑψηλὸν δὲ οὕτω δή τι λέγεται ὡς τὰς κορυφὰς αὐτοῦ οὐκ οἶά τε εἶναι ἰδέσθαι. οὐδέκοτε γὰρ αὐτὰς ἀπολείπειν νέφεα οὔτε θέρεος οὔτε χειμῶνος. τοῦτο τὸν κίονα τοῦ οὐρανοῦ λέγουσι οἱ ἐπιχώριοι εἶναι. ἐπὶ τούτου τοῦ ὄρεος οἱ ἄνθρωποι οὗτοι ἐπώνυμοι ἐγένοντο· καλέονται γὰρ δὴ Ἄτλαντες. λέγονται δὲ οὔτε ἔμψυχον οὐδὲν σιτέεσθαι οὔτε ἐνύπνια ὁρᾶν.", "st": "4.184"}, {"sp": "N", "t": "μέχρι μὲν δὴ τῶν Ἀτλάντων τούτων ἔχω τὰ οὐνόματα τῶν ἐν τῇ ὀφρύῃ κατοικημένων καταλέξαι, τὸ δ’ ἀπὸ τούτων οὐκέτι. διήκει δ’ ὦν ἡ ὀφρύη μέχρι Ἡρακλέων στηλέων καὶ τὸ ἔξω τουτέων. ἔστι δὲ ἁλός τε μέταλλον ἐν αὐτῇ διὰ δέκα ἡμερέων ὁδοῦ καὶ ἄνθρωποι οἰκέοντες. τὰ δὲ οἰκία τούτοισι πᾶσι ἐκ τῶν ἁλίνων χόνδρων οἰκοδομέαται. ταῦτα γὰρ ἤδη τῆς Λιβύης ἄνομβρα ἐστί· οὐ γὰρ ἂν ἠδυνέατο μένειν οἱ τοῖχοι ἐόντες ἅλινοι, εἰ ὗε. ὁ δὲ ἃλς αὐτόθι καὶ λευκὸς καὶ πορφύρεος τὸ εἶδος ὀρύσσεται. ὑπὲρ δὲ τῆς ὀφρύης τὸ πρὸς νότου καὶ ἐς μεσόγαιαν τῆς Λιβύης ἔρημος καὶ ἄνυδρος καὶ ἄθηρος καὶ ἄνομβρος καὶ ἄξυλος ἐστὶ ἡ χώρη, καὶ ἰκμάδος ἐστὶ ἐν αὐτῇ οὐδέν.", "st": "4.185"}, {"sp": "N", "t": "οὕτω μὲν μέχρι τῆς Τριτωνίδος λίμνης ἀπ’ Αἰγύπτου νομάδες εἰσὶ κρεοφάγοι τε καὶ γαλακτοπόται Λίβυες, καὶ θηλέων τε βοῶν οὔτι γευόμενοι, διότι περ οὐδὲ Αἰγύπτιοι, καὶ ὗς οὐ τρέφοντες. βοῶν μέν νυν θηλέων οὐδ’ αἱ Κυρηναίων γυναῖκες δικαιοῦσι πατέεσθαι διὰ τὴν ἐν Αἰγύπτῳ Ἶσιν, ἀλλὰ καὶ νηστηίας αὐτῇ καὶ ὁρτὰς ἐπιτελέουσι. αἱ δὲ τῶν Βαρκαίων γυναῖκες οὐδὲ ὑῶν πρὸς τῇσι βουσὶ γεύονται.", "st": "4.186"}, {"sp": "N", "t": "ταῦτα μὲν δὴ οὕτω ἔχει. τὸ δὲ πρὸς ἑσπέρης τῆς Τριτωνίδος λίμνης οὐκέτι νομάδες εἰσὶ Λίβυες οὐδὲ νόμοισι τοῖσι αὐτοῖσι χρεώμενοι, οὐδὲ κατὰ τὰ παιδία ποιεῦντες οἷον τι καὶ οἱ νομάδες ἐώθασι ποιέειν. οἱ γὰρ δὴ τῶν Λιβύων νομάδες, εἰ μὲν πάντες, οὐκ ἔχω ἀτρεκέως τοῦτο εἰπεῖν, ποιεῦσι δὲ αὐτῶν συχνοὶ τοιάδε· τῶν παιδίων τῶν σφετέρων, ἐπεὰν τετραέτεα γένηται, οἴσπῃ προβάτων καίουσι τὰς ἐν τῇσι κορυφῇσι φλέβας, μετεξέτεροι δὲ αὐτῶν τὰς ἐν τοῖσι κροτάφοισι, τοῦδε εἵνεκα ὡς μή σφεας ἐς τὸν πάντα χρόνον καταρρέον φλέγμα ἐκ τῆς κεφαλῆς δηλέηται. καὶ διὰ τοῦτο σφέας λέγουσι εἶναι ὑγιηροτάτους· εἰσὶ γὰρ ὡς ἀληθέως οἱ Λίβυες ἀνθρώπων πάντων ὑγιηρότατοι τῶν ἡμεῖς ἴδμεν, εἰ μὲν διὰ τοῦτο, οὐκ ἔχω ἀτρεκέως εἰπεῖν, ὑγιηρότατοι δ’ ὦν εἰσί. ἢν δὲ καίουσι τὰ παιδία σπασμὸς ἐπιγένηται, ἐξεύρηταί σφι ἄκος· τράγου γὰρ οὖρον σπείσαντες ῥύονται σφέα. λέγω δὲ τὰ λέγουσι αὐτοὶ Λίβυες.", "st": "4.187"}, {"sp": "N", "t": "θυσίαι δὲ τοῖσι νομάσι εἰσὶ αἵδε. ἐπεὰν τοῦ ὠτὸς ἀπάρξωνται τοῦ κτήνεος, ῥιπτέουσι ὑπὲρ τὸν δόμον, τοῦτο δὲ ποιήσαντες ἀποστρέφουσι τὸν αὐχένα αὐτοῦ· θύουσι δὲ ἡλίῳ καὶ σελήνῃ μούνοισι. τούτοισι μέν νυν πάντες Λίβυες θύουσι, ἀτὰρ οἱ περὶ τὴν Τριτωνίδα λίμνην νέμοντες τῇ Ἀθηναίῃ μάλιστα, μετὰ δὲ τῷ Τρίτωνι καὶ τῷ Ποσειδέωνι.", "st": "4.188"}, {"sp": "N", "t": "τὴν δὲ ἄρα ἐσθῆτα καὶ τὰς αἰγίδας τῶν ἀγαλμάτων τῆς Ἀθηναίης ἐκ τῶν Λιβυσσέων ἐποιήσαντο οἱ Ἕλληνες· πλὴν γὰρ ἢ ὅτι σκυτίνη ἡ ἐσθὴς τῶν Λιβυσσέων ἐστὶ καὶ οἱ θύσανοι οἱ ἐκ τῶν αἰγίδων αὐτῇσι οὐκ ὄφιες εἰσὶ ἀλλὰ ἱμάντινοι, τά γε ἄλλα πάντα κατὰ τὠυτὸ ἔσταλται. καὶ δὴ καὶ τὸ οὔνομα κατηγορέει ὅτι ἐκ Λιβύης ἥκει ἡ στολὴ τῶν Παλλαδίων· αἰγέας γὰρ περιβάλλονται ψιλὰς περὶ τὴν ἐσθῆτα θυσανωτὰς αἱ Λίβυσσαι κεχριμένας ἐρευθεδάνῳ, ἐκ δὲ τῶν αἰγέων τουτέων αἰγίδας οἱ Ἕλληνες μετωνόμασαν. δοκέει δ’ ἔμοιγε καὶ ὀλολυγὴ ἐν ἱροῖσι ἐνθαῦτα πρῶτον γενέσθαι· κάρτα γὰρ ταύτῃ χρέωνται καλῶς αἱ Λίβυσσαι. καὶ τέσσερας ἵππους συζευγνύναι παρὰ Λιβύων οἱ Ἕλληνες μεμαθήκασι.", "st": "4.189"}, {"sp": "N", "t": "θάπτουσι δὲ τοὺς ἀποθνήσκοντας οἱ νομάδες κατά περ οἱ Ἕλληνες, πλὴν Νασαμώνων· οὗτοι δὲ κατημένους θάπτουσι, φυλάσσοντες, ἐπεὰν ἀπιῇ τὴν ψυχήν, ὅκως μιν κατίσουσι μηδὲ ὕπτιος ἀποθανέεται. οἰκήματα δὲ σύμπηκτα ἐξ ἀνθερίκων ἐνειρμένων περὶ σχοίνους ἐστί, καὶ ταῦτα περιφορητά. νόμοισι μὲν τοιούτοισι οὗτοι χρέωνται.", "st": "4.190"}, {"sp": "N", "t": "τὸ δὲ πρὸς ἑσπέρης τοῦ Τρίτωνος ποταμοῦ Αὐσέων ἔχονται ἀροτῆρες ἤδη Λίβυες καὶ οἰκίας νομίζοντες ἐκτῆσθαι, τοῖσι οὔνομα κέεται Μάξυες. οἳ τὰ ἐπὶ δεξιὰ τῶν κεφαλέων κομόωσι, τὰ δ’ ἐπ’ ἀριστερὰ κείρουσι, τὸ δὲ σῶμα χρίονται μίλτῳ. φασὶ δὲ οὗτοι εἶναι τῶν ἐκ Τροίης ἀνδρῶν.", "st": "4.191"}, {"sp": "N", "t": "ἡ δὲ χώρη αὕτη τε καὶ ἡ λοιπὴ τῆς Λιβύης ἡ πρὸς ἑσπέρην πολλῷ θηριωδεστέρη τε καὶ δασυτέρη ἐστὶ τῆς τῶν νομάδων χώρης. ἡ μὲν γὰρ δὴ πρὸς τὴν ἠῶ τῆς Λιβύης, τὴν οἱ νομάδες νέμουσι, ἐστὶ ταπεινή τε καὶ ψαμμώδης μέχρι τοῦ Τρίτωνος ποταμοῦ, ἡ δὲ ἀπὸ τούτου τὸ πρὸς ἑσπέρην ἡ τῶν ἀροτήρων ὀρεινή τε κάρτα καὶ δασέα καὶ θηριώδης· καὶ γὰρ οἱ ὄφιες οἱ ὑπερμεγάθεες καὶ οἱ λέοντες κατὰ τούτους εἰσὶ καὶ οἱ ἐλέφαντές τε καὶ ἄρκτοι καὶ ἀσπίδες τε καὶ ὄνοι οἱ τὰ κέρεα ἔχοντες καὶ οἱ κυνοκέφαλοι καὶ οἱ ἀκέφαλοι οἱ ἐν τοῖσι στήθεσι τοὺς ὀφθαλμοὺς ἔχοντες, ὡς δὴ λέγονταί γε ὑπὸ Λιβύων, καὶ οἱ ἄγριοι ἄνδρες καὶ γυναῖκες ἄγριαι, καὶ ἄλλα πλήθεϊ πολλὰ θηρία ἀκατάψευστα.", "st": "4.191.2"}, {"sp": "N", "t": "κατὰ τοὺς νομάδας δὲ ἐστὶ τούτων οὐδέν, ἀλλ’ ἄλλα τοιάδε, πύγαργοι καὶ ζορκάδες καὶ βουβάλιες καὶ ὄνοι, οὐκ οἱ τὰ κέρεα ἔχοντες ἀλλ’ ἄλλοι ἄποτοι (οὐ γὰρ δὴ πίνουσι), καὶ ὄρυες, τῶν τὰ κέρεα τοῖσι φοίνιξι οἱ πήχεες ποιεῦνται (μέγαθος δὲ τὸ θηρίον τοῦτο κατὰ βοῦν ἐστι), καὶ βασσάρια καὶ ὕαιναι καὶ ὕστριχες καὶ κριοὶ ἄγριοι καὶ δίκτυες καὶ θῶες καὶ πάνθηρες καὶ βόρυες, καὶ κροκόδειλοι ὅσον τε τριπήχεες χερσαῖοι, τῇσι σαύρῃσι ἐμφερέστατοι, καὶ στρουθοὶ κατάγαιοι, καὶ ὄφιες μικροί, κέρας ἓν ἕκαστος ἔχοντες· ταῦτά τε δὴ αὐτόθι ἐστὶ θηρία καὶ τά περ τῇ ἄλλῃ, πλὴν ἐλάφου τε καὶ ὑὸς ἀγρίου· ἔλαφος δὲ καὶ ὗς ἄγριος ἐν Λιβύῃ πάμπαν οὐκ ἔστι. μυῶν δὲ γένεα τριξὰ αὐτόθι ἔστι· οἳ μὲν δίποδες καλέονται, οἳ δὲ ζεγέριες (τὸ δὲ οὔνομα τοῦτο ἐστὶ μὲν Λιβυστικόν, δύναται δὲ κατ’ Ἑλλάδα γλῶσσαν βουνοί), οἳ δὲ ἐχινέες. εἰσὶ δὲ καὶ γαλαῖ ἐν τῷ σιλφίῳ γινόμεναι τῇσι Ταρτησσίῃσι ὁμοιόταται. τοσαῦτα μέν νυν θηρία ἡ τῶν νομάδων Λιβύων γῆ ἔχει, ὅσον ἡμεῖς ἱστορέοντες ἐπὶ μακρότατον οἷοί τε ἐγενόμεθα ἐξικέσθαι.", "st": "4.192"}, {"sp": "N", "t": "Μαξύων δὲ Λιβύων Ζαύηκες ἔχονται, τοῖσι αἱ γυναῖκες ἡνιοχεῦσι τὰ ἅρματα ἐς τὸν πόλεμον.", "st": "4.193"}, {"sp": "N", "t": "τούτων δὲ Γύζαντες ἔχονται, ἐν τοῖσι μέλι πολλὸν μὲν μέλισσαι κατεργάζονται, πολλῷ δ’ ἔτι πλέον λέγεται δημιοεργοὺς ἄνδρας ποιέειν. μιλτοῦνται δ’ ὦν πάντες οὗτοι καὶ πιθηκοφαγέουσι. οἳ δὲ σφι ἄφθονοι ὅσοι ἐν τοῖσι ὄρεσι γίνονται.", "st": "4.194"}, {"sp": "N", "t": "κατὰ τούτους δὲ λέγουσι Καρχηδόνιοι κεῖσθαι νῆσον τῇ οὔνομα εἶναι Κύραυιν, μῆκος μὲν διηκοσίων σταδίων, πλάτος δὲ στεινήν, διαβατὸν ἐκ τῆς ἠπείρου, ἐλαιέων τε μεστὴν καὶ ἀμπέλων. λίμνην δὲ ἐν αὐτῇ εἶναι, ἐκ τῆς αἱ παρθένοι τῶν ἐπιχωρίων πτεροῖσι ὀρνίθων κεχριμένοισι πίσσῃ ἐκ τῆς ἰλύος ψῆγμα ἀναφέρουσι χρυσοῦ. ταῦτα εἰ μὲν ἔστι ἀληθέως οὐκ οἶδα, τὰ δὲ λέγεται γράφω· εἴη δ’ ἂν πᾶν, ὅκου καὶ ἐν Ζακύνθῳ ἐκ λίμνης καὶ ὕδατος πίσσαν ἀναφερομένην αὐτὸς ἐγὼ ὥρων. εἰσὶ μὲν καὶ πλεῦνες αἱ λίμναι αὐτόθι, ἡ δ’ ὦν μεγίστη αὐτέων ἑβδομήκοντα ποδῶν πάντῃ, βάθος δὲ διόργυιος ἐστί· ἐς ταύτην κοντὸν κατιεῖσι ἐπ’ ἄκρῳ μυρσίνην προσδήσαντες καὶ ἔπειτα ἀναφέρουσι τῇ μυρσίνῃ πίσσαν, ὀδμὴν μὲν ἔχουσαν ἀσφάλτου, τὰ δ’ ἄλλα τῆς Πιερικῆς πίσσης ἀμείνω. ἐσχέουσι δὲ ἐς λάκκον ὀρωρυγμένον ἀγχοῦ τῆς λίμνης. ἐπεὰν δὲ ἀθροίσωσι συχνήν, οὕτω ἐς τοὺς ἀμφορέας ἐκ τοῦ λάκκου καταχέουσι. ὁ τι δ’ ἂν ἐσπέσῃ ἐς τὴν λίμνην, ὑπὸ γῆν ἰὸν ἀναφαίνεται ἐν τῇ θαλάσσῃ· ἣ δὲ ἀπέχει ὡς τέσσερα στάδια ἀπὸ τῆς λίμνης. οὕτω ὦν καὶ τὰ ἀπὸ τῆς νήσου τῆς ἐπὶ Λιβύῃ κειμένης οἰκότα ἐστὶ ἀληθείῃ.", "st": "4.195"}, {"sp": "N", "t": "λέγουσι δὲ καὶ τάδε Καρχηδόνιοι. εἶναι τῆς Λιβύης χῶρόν τε καὶ ἀνθρώπους ἔξω Ἡρακλέων στηλέων κατοικημένους· ἐς τοὺς ἐπεὰν ἀπίκωνται καὶ ἐξέλωνται τὰ φορτία, θέντες αὐτὰ ἐπεξῆς παρὰ τὴν κυματωγήν, ἐσβάντες ἐς τὰ πλοῖα τύφειν καπνόν. τοὺς δ’ ἐπιχωρίους ἰδομένους τὸν καπνὸν ἰέναι ἐπὶ τὴν θάλασσαν καὶ ἔπειτα ἀντὶ τῶν φορτίων χρυσὸν τιθέναι καὶ ἐξαναχωρέειν πρόσω ἀπὸ τῶν φορτίων. τοὺς δὲ Καρχηδονίους ἐκβάντας σκέπτεσθαι, καὶ ἢν μὲν φαίνηταί σφι ἄξιος ὁ χρυσὸς τῶν φορτίων, ἀνελόμενοι ἀπαλλάσσονται, ἢν δὲ μὴ ἄξιος, ἐσβάντες ὀπίσω ἐς τὰ πλοῖα κατέαται· οἱ δὲ προσελθόντες ἄλλον πρὸς ὦν ἔθηκαν χρυσόν, ἐς οὗ ἂν πείθωσι. ἀδικέειν δὲ οὐδετέρους. οὔτε γὰρ αὐτοὺς τοῦ χρυσοῦ ἅπτεσθαι πρὶν ἄν σφι ἀπισωθῇ τῇ ἀξίῃ τῶν φορτίων, οὔτ’ ἐκείνους τῶν φορτίων ἅπτεσθαι πρότερον ἢ αὐτοὶ τὸ χρυσίον λάβωσι.", "st": "4.196"}, {"sp": "N", "t": "οὗτοι μὲν εἶσι τοὺς ἡμεῖς ἔχομεν Λιβύων ὀνομάσαι, καὶ τούτων οἱ πολλοὶ βασιλέος τοῦ Μήδων οὔτε τι νῦν οὔτε τότε ἐφρόντιζον οὐδέν. τοσόνδε δὲ ἔτι ἔχω εἰπεῖν περὶ τῆς χώρης ταύτης, ὅτι τέσσερα ἔθνεα νέμεται αὐτὴν καὶ οὐ πλέω τούτων, ὅσον ἡμεῖς ἴδμεν, καὶ τὰ μὲν δύο αὐτόχθονα τῶν ἐθνέων τὰ δὲ δύο οὔ, Λίβυες μὲν καὶ Αἰθίοπες αὐτόχθονες, οἳ μὲν τὰ πρὸς βορέω οἳ δὲ τὰ πρὸς νότου τῆς Λιβύης οἰκέοντες, Φοίνικες δὲ καὶ Ἕλληνες ἐπήλυδες.", "st": "4.197"}, {"sp": "N", "t": "δοκέει δέ μοι οὐδ’ ἀρετὴν εἶναι τις ἡ Λιβύη σπουδαίη ὥστε ἢ Ἀσίῃ ἢ Εὐρώπῃ παραβληθῆναι, πλὴν Κίνυπος μούνης· τὸ γὰρ δὴ αὐτὸ οὔνομα ἡ γῆ τῷ ποταμῷ ἔχει. αὕτη δὲ ὁμοίη τῇ ἀρίστῃ γέων Δήμητρος καρπὸν ἐκφέρειν οὐδὲ ἔοικε οὐδὲν τῇ ἄλλῃ Λιβύῃ. μελάγγαιός τε γὰρ ἐστὶ καὶ ἔπυδρος πίδαξι, καὶ οὔτε αὐχμοῦ φροντίζουσα οὐδὲν οὔτε ὄμβρον πλέω πιοῦσα δεδήληται. ὕεται γὰρ δὴ ταῦτα τῆς Λιβύης. τῶν δὲ ἐκφορίων τοῦ καρποῦ ταὐτὰ μέτρα τῇ Βαβυλωνίῃ γῇ κατίσταται. ἀγαθὴ δὲ γῆ καὶ τὴν Εὐεσπερῖται νέμονται· ἐπ’ ἑκατοστὰ γάρ, ἐπεὰν αὐτὴ ἑωυτῆς ἄριστα ἐνείκῃ, ἐκφέρει, ἣ δὲ ἐν τῇ Κίνυπι ἐπὶ τριηκόσια.", "st": "4.198"}, {"sp": "N", "t": "ἔχει δὲ καὶ ἡ Κυρηναίη χώρη, ἐοῦσα ὑψηλοτάτη ταύτης τῆς Λιβύης τὴν οἱ νομάδες νέμονται, τρεῖς ὥρας ἐν ἑωυτῇ ἀξίας θώματος. πρῶτα μὲν γὰρ τὰ παραθαλάσσια τῶν καρπῶν ὀργᾷ ἀμᾶσθαι τε καὶ τρυγᾶσθαι· τούτων τε δὴ συγκεκομισμένων τὰ ὑπὲρ τῶν θαλασσιδίων χώρων τὰ μέσα ὀργᾷ συγκομίζεσθαι, τὰ βουνοὺς καλέουσι· συγκεκόμισται τε οὗτος ὁ μέσος καρπὸς καὶ ὁ ἐν τῇ κατυπερτάτῃ τῆς γῆς πεπαίνεταί τε καὶ ὀργᾷ, ὥστε ἐκπέποται τε καὶ καταβέβρωται ὁ πρῶτος καρπὸς καὶ ὁ τελευταῖος συμπαραγίνεται. οὕτω ἐπ’ ὀκτὼ μῆνας Κυρηναίους ὀπώρη ἐπέχει. ταῦτα μέν νυν ἐπὶ τοσοῦτον εἰρήσθω.", "st": "4.199"}, {"sp": "N", "t": "οἱ δὲ Φερετίμης τιμωροὶ Πέρσαι ἐπείτε ἐκ τῆς Αἰγύπτου σταλέντες ὑπὸ Ἀρυάνδεω ἀπίκατο ἐς τὴν Βάρκην, ἐπολιόρκεον τὴν πόλιν ἐπαγγελλόμενοι ἐκδιδόναι τοὺς αἰτίους τοῦ φόνου τοῦ Ἀρκεσίλεω· τῶν δὲ πᾶν γὰρ ἦν τὸ πλῆθος μεταίτιον, οὐκ ἐδέκοντο τοὺς λόγους. ἐνθαῦτα δὴ ἐπολιόρκεον τὴν Βάρκην ἐπὶ μῆνας ἐννέα, ὀρύσσοντες τε ὀρύγματα ὑπόγαια φέροντα ἐς τὸ τεῖχος καὶ προσβολὰς καρτερὰς ποιεύμενοι. τὰ μέν νυν ὀρύγματα ἀνὴρ χαλκεὺς ἀνεῦρε ἐπιχάλκῳ ἀσπίδι, ὧδε ἐπιφρασθείς· περιφέρων αὐτὴν ἐντὸς τοῦ τείχεος προσῖσχε πρὸς τὸ δάπεδον τῆς πόλιος. τὰ μὲν δὴ ἄλλα ἔσκε κωφὰ πρὸς τὰ προσῖσχε, κατὰ δὲ τὰ ὀρυσσόμενα ἠχέεσκε ὁ χαλκὸς τῆς ἀσπίδος. ἀντορύσσοντες δ’ ἂν ταύτῃ οἱ Βαρκαῖοι ἔκτεινον τῶν Περσέων τοὺς γεωρυχέοντας. τοῦτο μὲν δὴ οὕτω ἐξευρέθη, τὰς δὲ προσβολὰς ἀπεκρούοντο οἱ Βαρκαῖοι.", "st": "4.200"}, {"sp": "N", "t": "χρόνον δὲ δὴ πολλὸν τριβομένων καὶ πιπτόντων ἀμφοτέρων πολλῶν καὶ οὐκ ἧσσον τῶν Περσέων, Ἄμασις ὁ στρατηγὸς τοῦ πεζοῦ μηχανᾶται τοιάδε. μαθὼν τοὺς Βορκαίους ὡς κατὰ μὲν τὸ ἰσχυρὸν οὐκ αἱρετοὶ εἶεν, δόλῳ δὲ αἱρετοί, ποιέει τοιάδε· νυκτὸς τάφρην ὀρύξας εὐρέαν ἐπέτεινε ξύλα ἀσθενέα ὑπὲρ αὐτῆς, κατύπερθε δὲ ἐπιπολῆς τῶν ξύλων χοῦν γῆς ἐπεφόρησε ποιέων τῇ ἄλλῃ γῇ ἰσόπεδον. ἅμα ἡμέρῃ δὲ ἐς λόγους προεκαλέετο τοὺς Βαρκαίους· οἳ δὲ ἀσπαστῶς ὑπήκουσαν, ἐς ὅ σφι ἕαδε ὁμολογίῃ χρήσασθαι. τὴν δὲ ὁμολογίην ἐποιεῦντο τοιήνδε τινά, ἐπὶ τῆς κρυπτῆς τάφρου τάμνοντες ὅρκια, ἔστ’ ἂν ἡ γῆ αὕτη οὕτω ἔχῃ, μένειν τὸ ὅρκιον κατὰ χώρην, καὶ Βαρκαίους τε ὑποτελέειν φάναι ἀξίην βασιλέι καὶ Πέρσας μηδὲν ἄλλο νεοχμοῦν κατὰ Βαρκαίους. μετὰ δὲ τὸ ὅρκιον Βαρκαῖοι μὲν πιστεύσαντες τούτοισι αὐτοί τε ἐξῄσαν ἐκ τοῦ ἄστεος καὶ τῶν πολεμίων ἔων παριέναι ἐς τὸ τεῖχος τὸν βουλόμενον, τὰς πάσας πύλας ἀνοίξαντες. οἱ δὲ Πέρσαι καταρρήξαντες τὴν κρυπτὴν γέφυραν ἔθεον ἔσω ἐς τὸ τεῖχος. κατέρρηξαν δὲ τοῦδε εἵνεκα τὴν ἐποίησαν γέφυραν, ἵνα ἐμπεδορκέοιεν, ταμόντες τοῖσι Βαρκαίοισι χρόνον μένειν αἰεὶ τὸ ὅρκιον ὅσον ἂν ἡ γῆ μένῃ κατὰ τότε εἶχε· καταρρήξασι δὲ οὐκέτι ἔμενε τὸ ὅρκιον κατὰ χώρην.", "st": "4.201"}, {"sp": "N", "t": "τοὺς μέν νυν αἰτιωτάτους τῶν Βαρκαίων ἡ Φερετίμη, ἐπείτε οἱ ἐκ τῶν Περσέων παρεδόθησαν, ἀνεσκολόπισε κύκλῳ τοῦ τείχεος, τῶν δέ σφι γυναικῶν τοὺς μαζοὺς ἀποταμοῦσα περιέστιξε καὶ τούτοισι τὸ τεῖχος· τοὺς δὲ λοιποὺς τῶν Βαρκαίων ληίην ἐκέλευε θέσθαι τοὺς Πέρσας, πλὴν ὅσοι αὐτῶν ἦσαν Βαττιάδαι τε καὶ τοῦ φόνου οὐ μεταίτιοι· τούτοισι δὲ τὴν πόλιν ἐπέτρεψε ἡ Φερετίμη.", "st": "4.202"}, {"sp": "N", "t": "τοὺς ὦν δὴ λοιποὺς τῶν Βαρκαίων οἱ Πέρσαι ἀνδραποδισάμενοι ἀπήισαν ὀπίσω· καὶ ἐπείτε ἐπὶ τῇ Κυρηναίων πόλι ἐπέστησαν, οἱ Κυρηναῖοι λόγιόν τι ἀποσιεύμενοι διεξῆκαν αὐτοὺς διὰ τοῦ ἄστεος. διεξιούσης δὲ τῆς στρατιῆς Βάδρης μὲν ὁ τοῦ ναυτικοῦ στρατοῦ στρατηγὸς ἐκέλευε αἱρέειν τὴν πόλιν, Ἄμασις δὲ ὁ τοῦ πεζοῦ οὐκ ἔα· ἐπὶ Βάρκην γὰρ ἀποσταλῆναι μούνην Ἑλληνίδα πόλιν· ἐς ὃ διεξελθοῦσι καὶ ἱζομένοισι ἐπὶ Διὸς Λυκαίου ὄχθον μετεμέλησέ σφι οὐ σχοῦσι τὴν Κυρήνην. καὶ ἐπειρῶντο τὸ δεύτερον παριέναι ἐς αὐτήν· οἱ δὲ Κυρηναῖοι οὐ περιώρων. τοῖσι δὲ Πέρσῃσι οὐδενὸς μαχομένου φόβος ἐνέπεσε, ἀποδραμόντες τε ὅσον τε ἑξήκοντα στάδια ἵζοντο· ἱδρυθέντι δὲ τῷ στρατοπέδῳ ταύτῃ ἦλθε παρὰ Ἀρυνάνδεω ἄγγελος ἀποκαλέων αὐτούς. οἱ δὲ Πέρσαι Κυρηναίων δεηθέντες ἐπόδιά σφι δοῦναι ἔτυχον, λαβόντες δὲ ταῦτα ἀπαλλάσσοντο ἐς τὴν Αἴγυπτον. παραλαβόντες δὲ τὸ ἐνθεῦτεν αὐτοὺς Λίβυες τῆς τε ἐσθῆτος εἵνεκα καὶ τῆς σκευῆς τοὺς ὑπολειπομένους αὐτῶν καὶ ἐπελκομένους ἐφόνευον, ἐς ὃ ἐς τὴν Αἴγυπτον ἀπίκοντο.", "st": "4.203"}, {"sp": "N", "t": "οὗτος ὁ Περσέων στρατὸς τῆς Λιβύης ἑκαστάτω ἐς Εὐεσπερίδας ἦλθε. τοὺς δὲ ἠνδραποδίσαντο τῶν Βαρκαίων, τούτους δὲ ἐκ τῆς Αἰγύπτου ἀνασπάστους ἐποίησαν παρὰ βασιλέα, βασιλεὺς δέ σφι Δαρεῖος ἔδωκε τῆς Βακτρίης χώρης κώμην ἐγκατοικῆσαι. οἳ δὲ τῇ κώμῃ ταύτῃ οὔνομα ἔθεντο Βάρκην, ἥ περ ἔτι καὶ ἐς ἐμὲ ἦν οἰκεομένη ἐν γῇ τῇ Βακτρίῃ.", "st": "4.204"}, {"sp": "N", "t": "οὐ μὲν οὐδὲ ἡ Φερετίμη εὖ τὴν ζόην κατέπλεξε. ὡς γὰρ δὴ τάχιστα ἐκ τῆς Λιβύης τισαμένη τοὺς Βαρκαίους ἀπενόστησε ἐς τὴν Αἴγυπτον, ἀπέθανε κακῶς· ζῶσα γὰρ εὐλέων ἐξέζεσε, ὡς ἄρα ἀνθρώποισι αἱ λίην ἰσχυραὶ τιμωρίαι πρὸς θεῶν ἐπίφθονοι γίνονται· ἐκ μὲν δὴ Φερετίμης τῆς Βάττου τοιαύτη τε καὶ τοσαύτη τιμωρίη ἐγένετο ἐς Βαρκαίους.", "st": "4.205"}, {"sp": "HDR", "t": "Ἱστοριῶν Ε· Τερψιχόρη", "st": "5"}, {"sp": "N", "t": "οἱ δὲ ἐν τῇ Εὐρώπῃ τῶν Περσέων καταλειφθέντες ὑπὸ Δαρείου, τῶν ὁ Μεγάβαζος ἦρχε, πρώτους μὲν Περινθίους Ἑλλησποντίων οὐ βουλομένους ὑπηκόους εἶναι Δαρείου κατεστρέψαντο, περιεφθέντας πρότερον καὶ ὑπὸ Παιόνων τρηχέως. οἱ γὰρ ὦν ἀπὸ Στρυμόνος Παίονες χρήσαντος τοῦ θεοῦ στρατεύεσθαι ἐπὶ Περινθίους, καὶ ἢν μὲν ἀντικατιζόμενοι ἐπικαλέσωνται σφέας οἱ Περίνθιοι ὀνομαστὶ βώσαντες, τοὺς δὲ ἐπιχειρέειν, ἢν δὲ μὴ ἐπιβώσωνται, μὴ ἐπιχειρέειν, ἐποίεον οἱ Παίονες ταῦτα. ἀντικατιζομένων δὲ τῶν Περινθίων ἐν τῷ προαστείῳ, ἐνθαῦτα μουνομαχίη τριφασίη ἐκ προκλήσιός σφι ἐγένετο· καὶ γὰρ ἄνδρα ἀνδρὶ καὶ ἵππον ἵππῳ συνέβαλον καὶ κύνα κυνί. νικώντων δὲ τὰ δύο τῶν Περινθίων, ὡς ἐπαιώνιζον κεχαρηκότες, συνεβάλοντο οἱ Παίονες τὸ χρηστήριον αὐτὸ τοῦτο εἶναι καὶ εἶπάν κου παρὰ σφίσι αὐτοῖσι νῦν ἂν εἴη ὁ χρησμὸς ἐπιτελεόμενος ἡμῖν, νῦν ἡμέτερον ἔργον. οὕτω τοῖσι Περινθίοισι παιωνίσασι ἐπιχειρέουσι οἱ Παίονες, καὶ πολλόν τε ἐκράτησαν καὶ ἔλιπον σφέων ὀλίγους.", "st": "5.1"}, {"sp": "N", "t": "τὰ μὲν δὴ ἀπὸ Παιόνων πρότερον γενόμενα ὧδε ἐγένετο· τότε δὲ ἀνδρῶν ἀγαθῶν περὶ τῆς ἐλευθερίης γινομένων τῶν Περινθίων οἱ Πέρσαι τε καὶ ὁ Μεγάβαζος ἐπεκράτησαν πλήθεϊ. ὡς δὲ ἐχειρώθη ἡ Πέρινθος, ἤλαυνε Μεγάβαζος τὸν στρατὸν διὰ τῆς Θρηίκης, πᾶσαν πόλιν καὶ πᾶν ἔθνος τῶν ταύτῃ οἰκημένων ἡμερούμενος βασιλέι. ταῦτα γάρ οἱ ἐνετέταλτο ἐκ Δαρείου, Θρηίκην καταστρέφεσθαι.", "st": "5.2"}, {"sp": "N", "t": "Θρηίκων δὲ ἔθνος μέγιστον ἐστὶ μετά γε Ἰνδοὺς πάντων ἀνθρώπων· εἰ δὲ ὑπ’ ἑνὸς ἄρχοιτο ἢ φρονέοι κατὰ τὠυτό, ἄμαχόν τ’ ἂν εἴη καὶ πολλῷ κράτιστον πάντων ἐθνέων κατὰ γνώμην τὴν ἐμήν. ἀλλὰ γὰρ τοῦτο ἄπορόν σφι καὶ ἀμήχανον μή κοτε ἐγγένηται, εἰσὶ δὴ κατὰ τοῦτο ἀσθενέες. οὐνόματα δ’ ἔχουσι πολλὰ κατὰ χώρας ἕκαστοι, νόμοισι δὲ οὗτοι παραπλησίοισι πάντες χρέωνται κατὰ πάντα, πλὴν Γετέων καὶ Τραυσῶν καὶ τῶν κατύπερθε Κρηστωναίων οἰκεόντων.", "st": "5.3"}, {"sp": "N", "t": "τούτων δὲ τὰ μὲν Γέται οἱ ἀθανατίζοντες ποιεῦσι, εἴρηταί μοι· Τραυσοὶ δὲ τὰ μὲν ἄλλα πάντα κατὰ ταὐτὰ τοῖσι ἄλλοισι Θρήιξι ἐπιτελέουσι, κατὰ δὲ τὸν γινόμενόν σφι καὶ ἀπογινόμενον ποιεῦσι τοιάδε· τὸν μὲν γενόμενον περιιζόμενοι οἱ προσήκοντες ὀλοφύρονται, ὅσα μιν δεῖ ἐπείτε ἐγένετο ἀναπλῆσαι κακά, ἀνηγεόμενοι τὰ ἀνθρωπήια πάντα πάθεα· τὸν δ’ ἀπογενόμενον παίζοντές τε καὶ ἡδόμενοι γῇ κρύπτουσι, ἐπιλέγοντες ὅσων κακῶν ἐξαπαλλαχθεὶς ἐστὶ ἐν πάσῃ εὐδαιμονίῃ.", "st": "5.4"}, {"sp": "N", "t": "οἱ δὲ κατύπερθε Κρηστωναίων ποιεῦσι τοιάδε. ἔχει γυναῖκας ἕκαστος πολλάς· ἐπεὰν ὦν τις αὐτῶν ἀποθάνῃ, κρίσις γίνεται μεγάλη τῶν γυναικῶν καὶ φίλων σπουδαὶ ἰσχυραὶ περὶ τοῦδε, ἥτις αὐτέων ἐφιλέετο μάλιστα ὑπὸ τοῦ ἀνδρός· ἣ δ’ ἂν κριθῇ καὶ τιμηθῇ, ἐγκωμιασθεῖσα ὑπό τε ἀνδρῶν καὶ γυναικῶν σφάζεται ἐς τὸν τάφον ὑπὸ τοῦ οἰκηιοτάτου ἑωυτῆς, σφαχθεῖσα δὲ συνθάπτεται τῷ ἀνδρί. αἱ δὲ ἄλλαι συμφορὴν μεγάλην ποιεῦνται· ὄνειδος γάρ σφι τοῦτο μέγιστον γίνεται.", "st": "5.5"}, {"sp": "N", "t": "τῶν δὲ δὴ ἄλλων Θρηίκων ἐστὶ ὅδε νόμος· πωλεῦσι τὰ τέκνα ἐπ’ ἐξαγωγῇ, τὰς δὲ παρθένους οὐ φυλάσσουσι, ἀλλ’ ἐῶσι τοῖσι αὐταὶ βούλονται ἀνδράσι μίσγεσθαι· τὰς δὲ γυναῖκας ἰσχυρῶς φυλάσσουσι καὶ ὠνέονται τὰς γυναῖκας παρὰ τῶν γονέων χρημάτων μεγάλων. καὶ τὸ μὲν ἐστίχθαι εὐγενὲς κέκριται, τὸ δὲ ἄστικτον ἀγεννές. ἀργὸν εἶναι κάλλιστον, γῆς δὲ ἐργάτην ἀτιμότατον· τὸ ζῆν ἀπὸ πολέμου καὶ ληιστύος κάλλιστον.", "st": "5.6"}, {"sp": "N", "t": "οὗτοι μὲν σφέων οἱ ἐπιφανέστατοι νόμοι εἰσί, θεοὺς δὲ σέβονται μούνους τούσδε, Ἄρεα καὶ Διόνυσον καὶ Ἄρτεμιν. οἱ δὲ βασιλέες αὐτῶν, πάρεξ τῶν ἄλλων πολιητέων, σέβονται Ἑρμέην μάλιστα θεῶν, καὶ ὀμνύουσι μοῦνον τοῦτον, καὶ λέγουσι γεγονέναι ἀπὸ Ἑρμέω ἑωυτούς.", "st": "5.7"}, {"sp": "N", "t": "ταφαὶ δὲ τοῖσι εὐδαίμοσι αὐτῶν εἰσὶ αἵδε· τρεῖς μὲν ἡμέρας προτιθεῖσι τὸν νεκρόν, καὶ παντοῖα σφάξαντες ἱρήια εὐωχέονται, προκλαύσαντες πρῶτον· ἔπειτα δὲ θάπτουσι κατακαύσαντες ἢ ἄλλως γῇ κρύψαντες, χῶμα δὲ χέαντες ἀγῶνα τιθεῖσι παντοῖον, ἐν τῷ τὰ μέγιστα ἄεθλα τίθεται κατὰ λόγον μουνομαχίης. ταφαὶ μὲν δὴ Θρηίκων εἰσὶ αἵδε.", "st": "5.8"}, {"sp": "N", "t": "τὸ δὲ πρὸς βορέω τῆς χώρης ἔτι ταύτης οὐδεὶς ἔχει φράσαι τὸ ἀτρεκὲς οἵτινες εἰσὶ ἄνθρωποι οἰκέοντες αὐτήν, ἀλλὰ τὰ πέρην ἤδη τοῦ Ἴστρου ἔρημος χώρη φαίνεται ἐοῦσα καὶ ἄπειρος. μούνους δὲ δύναμαι πυθέσθαι οἰκέοντας πέρην τοῦ Ἴστρου ἀνθρώπους τοῖσι οὔνομα εἶναι Σιγύννας, ἐσθῆτι δὲ χρεωμένους Μηδικῇ· τοὺς δὲ ἵππους αὐτῶν εἶναι λασίους ἅπαν τὸ σῶμα ἐπὶ πέντε δακτύλους τὸ βάθος τῶν τριχῶν, μικροὺς δὲ καὶ σιμοὺς καὶ ἀδυνάτους ἄνδρας φέρειν, ζευγνυμένους δὲ ὑπ’ ἅρματα εἶναι ὀξυτάτους· ἁρματηλατέειν δὲ πρὸς ταῦτα τοὺς ἐπιχωρίους. κατήκειν δὲ τούτων τοὺς οὔρους ἀγχοῦ Ἐνετῶν τῶν ἐν τῷ Ἀδρίῃ. εἶναι δὲ Μήδων σφέας ἀποίκους λέγουσι. ὅκως δὲ οὗτοι Μήδων ἄποικοι γεγόνασι, ἐγὼ μὲν οὐκ ἔχω ἐπιφράσασθαι, γένοιτο δ’ ἂν πᾶν ἐν τῷ μακρῷ χρόνῳ. Σιγύννας δ’ ὦν καλέουσι Δίγυες οἱ ἄνω ὑπὲρ Μασσαλίης οἰκέοντες τοὺς καπήλους, Κύπριοι δὲ τὰ δόρατα.", "st": "5.9"}, {"sp": "N", "t": "ὡς δὲ Θρήικες λέγουσι, μέλισσαι κατέχουσι τὰ πέρην τοῦ Ἴστρου, καὶ ὑπὸ τουτέων οὐκ εἶναι διελθεῖν τὸ προσωτέρω. ἐμοὶ μέν νυν ταῦτα λέγοντες δοκέουσι λέγειν οὐκ οἰκότα· τὰ γὰρ ζῷα ταῦτα φαίνεται εἶναι δύσριγα· ἀλλά μοι τὰ ὑπὸ τὴν ἄρκτον ἀοίκητα δοκέει εἶναι διὰ τὰ ψύχεα. ταῦτα μέν νυν τῆς χώρης ταύτης πέρι λέγεται· τὰ παραθαλάσσια δ’ ὦν αὐτῆς Μεγάβαζος Περσέων κατήκοα ἐποίεε.", "st": "5.10"}, {"sp": "N", "t": "Δαρεῖος δὲ ὡς διαβὰς τάχιστα τὸν Ἑλλήσποντον ἀπίκετο ἐς Σάρδις, ἐμνήσθη τῆς ἐξ Ἱστιαίου τε τοῦ Μιλησίου εὐεργεσίης καὶ τῆς παραινέσιος τοῦ Μυτιληναίου Κώεω, μεταπεμψάμενος δὲ σφέας ἐς Σάρδις ἐδίδου αὐτοῖσι αἵρεσιν. ὁ μὲν δὴ Ἱστιαῖος, ἅτε τυραννεύων τῆς Μιλήτου, τυραννίδος μὲν οὐδεμιῆς προσεχρήιζε, αἰτέει δὲ Μύρκινον τὴν Ἠδωνῶν, βουλόμενος ἐν αὐτῇ πόλιν κτίσαι. οὗτος μὲν δὴ ταύτην αἱρέεται, ὁ δὲ Κώης, οἷά τε οὐ τύραννος δημότης τε ἐών, αἰτέει Μυτιλήνης τυραννεῦσαι.", "st": "5.11"}, {"sp": "N", "t": "τελεωθέντων δὲ ἀμφοτέροισι, οὗτοι μὲν κατὰ τὰ εἵλοντο ἐτράποντο, Δαρεῖον δὲ συνήνεικε πρῆγμα τοιόνδε ἰδόμενον ἐπιθυμῆσαι ἐντείλασθαι Μεγαβάζῳ Παίονας ἑλόντα ἀνασπάστους ποιῆσαι ἐς τὴν Ἀσίην ἐκ τῆς Εὐρώπης. ἦν Πίγρης καὶ Μαντύης ἄνδρες Παίονες, οἳ ἐπείτε Δαρεῖος διέβη ἐς τὴν Ἀσίην, αὐτοὶ ἐθέλοντες Παιόνων τυραννεύειν ἀπικνέονται ἐς Σάρδις, ἅμα ἀγόμενοι ἀδελφεὴν μεγάλην τε καὶ εὐειδέα. φυλάξαντες δὲ Δαρεῖον προκατιζόμενον ἐς τὸ προάστειον τὸ τῶν Λυδῶν ἐποίησαν τοιόνδε· σκευάσαντες τὴν ἀδελφεὴν ὡς εἶχον ἄριστα, ἐπ’ ὕδωρ ἔπεμπον ἄγγος ἐπὶ τῇ κεφαλῇ ἔχουσαν καὶ ἐκ τοῦ βραχίονος ἵππον ἐπέλκουσαν καὶ κλώθουσαν λίνον. ὡς δὲ παρεξήιε ἡ γυνή, ἐπιμελὲς τῷ Δαρείῳ ἐγένετο· οὔτε γὰρ Περσικὰ ἦν οὔτε Λύδια τὰ ποιεύμενα ἐκ τῆς γυναικός, οὔτε πρὸς τῶν ἐκ τῆς Ἀσίης οὐδαμῶν. ἐπιμελὲς δὲ ὥς οἱ ἐγένετο, τῶν δορυφόρων τινὰς πέμπει κελεύων φυλάξαι ὅ τι χρήσεται τῷ ἵππῳ ἡ γυνή. οἳ μὲν δὴ ὄπισθε εἵποντο· ἣ δὲ ἐπείτε ἀπίκετο ἐπὶ τὸν ποταμόν, ἦρσε τὸν ἵππον, ἄρσασα δὲ καὶ τὸ ἄγγος τοῦ ὕδατος ἐμπλησαμένη τὴν αὐτὴν ὁδὸν παρεξήιε, φέρουσα τὸ ὕδωρ ἐπὶ τῆς κεφαλῆς καὶ ἐπέλκουσα ἐκ τοῦ βραχίονος τὸν ἵππον καὶ στρέφουσα τὸν ἄτρακτον.", "st": "5.12"}, {"sp": "N", "t": "θωμάζων δὲ ὁ Δαρεῖος τά τε ἤκουσε ἐκ τῶν κατασκόπων καὶ τὰ αὐτὸς ὥρα, ἄγειν αὐτὴν ἐκέλευε ἑωυτῷ ἐς ὄψιν. ὡς δὲ ἄχθη, παρῆσαν καὶ οἱ ἀδελφεοὶ αὐτῆς οὔ κῃ πρόσω σκοπιὴν ἔχοντες τούτων. εἰρωτῶντος δὲ τοῦ Δαρείου ὁποδαπὴ εἴη, ἔφασαν οἱ νεηνίσκοι εἶναι Παίονες καὶ ἐκείνην εἶναι σφέων ἀδελφεήν. ὃ δ’ ἀμείβετο, τίνες δὲ οἱ Παίονες ἄνθρωποι εἰσὶ καὶ κοῦ γῆς οἰκημένοι, καὶ τί κεῖνοι ἐθέλοντες ἔλθοιεν ἐς Σάρδις. οἳ δέ οἱ ἔφραζον ὡς ἔλθοιεν μὲν ἐκείνῳ δώσοντες σφέας αὐτούς, εἴη δὲ ἡ Παιονίη ἐπὶ τῷ Στρυμόνι ποταμῷ πεπολισμένη, ὁ δὲ Στρυμὼν οὐ πρόσω τοῦ Ἑλλησπόντου, εἴησαν δὲ Τευκρῶν τῶν ἐκ Τροίης ἄποικοι. οἳ μὲν δὴ ταῦτα ἕκαστα ἔλεγον, ὁ δὲ εἰρώτα εἰ καὶ πᾶσαι αὐτόθι αἱ γυναῖκες εἴησαν οὕτω ἐργάτιδες. οἳ δὲ καὶ τοῦτο ἔφασαν προθύμως οὕτω ἔχειν· αὐτοῦ γὰρ ὦν τούτου εἵνεκα καὶ ἐποιέετο.", "st": "5.13"}, {"sp": "N", "t": "ἐνθαῦτα Δαρεῖος γράφει γράμματα Μεγαβάζῳ, τὸν ἔλιπε ἐν τῇ Θρηίκῃ στρατηγόν, ἐντελλόμενος ἐξαναστῆσαι ἐξ ἠθέων Παίονας καὶ παρ’ ἑωυτὸν ἀγαγεῖν καὶ αὐτοὺς καὶ τὰ τέκνα τε καὶ τὰς γυναῖκας αὐτῶν. αὐτίκα δὲ ἱππεὺς ἔθεε φέρων τὴν ἀγγελίην ἐπὶ τὸν Ἑλλήσποντον, περαιωθεὶς δὲ διδοῖ τὸ βυβλίον τῷ Μεγαβάζῳ. ὁ δὲ ἐπιλεξάμενος καὶ λαβὼν ἡγεμόνας ἐκ τῆς Θρηίκης ἐστρατεύετο ἐπὶ τὴν Παιονίην.", "st": "5.14"}, {"sp": "N", "t": "πυθόμενοι δὲ οἱ Παίονες τοὺς Πέρσας ἐπὶ σφέας ἰέναι, ἁλισθέντες ἐξεστρατεύσαντο πρὸς θαλάσσης, δοκέοντες ταύτῃ ἐπιχειρήσειν τοὺς Πέρσας ἐμβάλλοντας. οἱ μὲν δὴ Παίονες ἦσαν ἕτοιμοι τὸν Μεγαβάζου στρατὸν ἐπιόντα ἐρύκειν· οἱ δὲ Πέρσαι πυθόμενοι συναλίσθαι τοὺς Παίονας καὶ τὴν πρὸς θαλάσσης ἐσβολὴν φυλάσσοντας, ἔχοντες ἡγεμόνας τὴν ἄνω ὁδὸν τρέπονται, λαθόντες δὲ τοὺς Παίονας ἐσπίπτουσι ἐς τὰς πόλιας αὐτῶν ἐούσας ἀνδρῶν ἐρήμους· οἷα δὲ κεινῇσι ἐπιπεσόντες εὐπετέως κατέσχον. οἱ δὲ Παίονες ὡς ἐπύθοντο ἐχομένας τὰς πόλιας, αὐτίκα διασκεδασθέντες κατ’ ἑωυτοὺς ἕκαστοι ἐτράποντο καὶ παρεδίδοσαν σφέας αὐτοὺς τοῖσι Πέρσῃσι. οὕτω δὴ Παιόνων Σιριοπαίονές τε καὶ Παιόπλαι καὶ οἱ μέχρι τῆς Πρασιάδος λίμνης ἐξ ἠθέων ἐξαναστάντες ἤγοντο ἐς τὴν Ἀσίην.", "st": "5.15"}, {"sp": "N", "t": "οἱ δὲ περί τε Πάγγαιον ὄρος καὶ Δόβηρας καὶ Ἀγριᾶνας καὶ Ὀδομάντους καὶ αὐτὴν τὴν λίμνην τὴν Πρασιάδα οὐκ ἐχειρώθησαν ἀρχὴν ὑπὸ Μεγαβάζου· ἐπειρήθη δὲ καὶ τοὺς ἐν τῇ λίμνῃ κατοικημένους ἐξαιρέειν ὧδε. ἴκρια ἐπὶ σταυρῶν ὑψηλῶν ἐζευγμένα ἐν μέσῃ ἕστηκε τῇ λίμνῃ, ἔσοδον ἐκ τῆς ἠπείρου στεινὴν ἔχοντα μιῇ γεφύρῃ. τοὺς δὲ σταυροὺς τοὺς ὑπεστεῶτας τοῖσι ἰκρίοισι τὸ μέν κου ἀρχαῖον ἔστησαν κοινῇ πάντες οἱ πολιῆται, μετὰ δὲ νόμῳ χρεώμενοι ἱστᾶσι τοιῷδε· κομίζοντες ἐξ ὄρεος τῷ οὔνομα ἐστὶ Ὄρβηλος, κατὰ γυναῖκα ἑκάστην ὁ γαμέων τρεῖς σταυροὺς ὑπίστησι· ἄγεται δὲ ἕκαστος συχνὰς γυναῖκας. οἰκέουσι δὲ τοιοῦτον τρόπον, κρατέων ἕκαστος ἐπὶ τῶν ἰκρίων καλύβης τε ἐν τῇ διαιτᾶται καὶ θύρης καταπακτῆς διὰ τῶν ἰκρίων κάτω φερούσης ἐς τὴν λίμνην. τὰ δὲ νήπια παιδία δέουσι τοῦ ποδὸς σπάρτῳ, μὴ κατακυλισθῇ δειμαίνοντες. τοῖσι δὲ ἵπποισι καὶ τοῖσι ὑποζυγίοισι παρέχουσι χόρτον ἰχθῦς· τῶν δὲ πλῆθος ἐστὶ τοσοῦτο ὥστε, ὅταν τὴν θύρην τὴν καταπακτὴν ἀνακλίνῃ, κατιεῖ σχοίνῳ σπυρίδα κεινὴν ἐς τὴν λίμνην, καὶ οὐ πολλόν τινα χρόνον ἐπισχὼν ἀνασπᾷ πλήρεα ἰχθύων. τῶν δὲ ἰχθύων ἐστὶ γένεα δύο, τοὺς καλέουσι πάπρακάς τε καὶ τίλωνας.", "st": "5.16"}, {"sp": "N", "t": "παιόνων μὲν δὴ οἱ χειρωθέντες ἤγοντο ἐς τὴν Ἀσίην. Μεγάβαζος δὲ ὡς ἐχειρώσατο τοὺς Παίονας, πέμπει ἀγγέλους ἐς Μακεδονίην ἄνδρας ἑπτὰ Πέρσας, οἳ μετ’ αὐτὸν ἐκεῖνον ἦσαν δοκιμώτατοι ἐν τῷ στρατοπέδῳ· ἐπέμποντο δὲ οὗτοι παρὰ Ἀμύντην αἰτήσοντες γῆν τε καὶ ὕδωρ Δαρείῳ βασιλέι. ἔστι δὲ ἐκ τῆς Πρασιάδος λίμνης σύντομος κάρτα ἐς τὴν Μακεδονίην· πρῶτον μὲν γὰρ ἔχεται τῆς λίμνης τὸ μέταλλον ἐξ οὗ ὕστερον τούτων τάλαντον ἀργυρίου Ἀλεξάνδρῳ ἡμέρης ἑκάστης ἐφοίτα, μετὰ δὲ τὸ μέταλλον Δύσωρον καλεόμενον ὄρος ὑπερβάντα εἶναι ἐν Μακεδονίν.", "st": "5.17"}, {"sp": "N", "t": "οἱ ὦν Πέρσαι οἱ πεμφθέντες οὗτοι παρὰ τὸν Ἀμύντην ὡς ἀπίκοντο, αἴτεον ἐλθόντες ἐς ὄψιν τὴν Ἀμύντεω Δαρείῳ βασιλέι γῆν τε καὶ ὕδωρ. ὁ δὲ ταῦτά τε ἐδίδου καὶ σφεας ἐπὶ ξείνια καλέει, παρασκευασάμενος δὲ δεῖπνον μεγαλοπρεπὲς ἐδέκετο τοὺς Πέρσας φιλοφρόνως. ὡς δὲ ἀπὸ δείπνου ἐγένοντο, διαπίνοντες εἶπαν οἱ Πέρσαι τάδε. ξεῖνε Μακεδών, ἡμῖν νόμος ἐστὶ τοῖσι Πέρσῃσι, ἐπεὰν δεῖπνον προτιθώμεθα μέγα, τότε καὶ τὰς παλλακὰς καὶ τὰς κουριδίας γυναῖκας ἐσάγεσθαι παρέδρους. σύ νυν, ἐπεί περ προθύμως μὲν ἐδέξαο μεγάλως δὲ ξεινίζεις, διδοῖς δὲ βασιλέι Δαρείῳ γῆν τε καὶ ὕδωρ, ἕπεο νόμῳ τῷ ἡμετέρῳ. εἶπε πρὸς ταῦτα Ἀμύντης ὦ Πέρσαι, νόμος μὲν ἡμῖν γε ἐστὶ οὐκ οὗτος, ἀλλὰ κεχωρίσθαι ἄνδρας γυναικῶν· ἐπείτε δὲ ὑμεῖς ἐόντες δεσπόται προσχρηίζετε τούτων, παρέσται ὑμῖν καὶ ταῦτα. εἴπας τοσαῦτα ὁ Ἀμύντης μετεπέμπετο τὰς γυναῖκας· αἳ δ’ ἐπείτε καλεόμεναι ἦλθον, ἐπεξῆς ἀντίαι ἵζοντο τοῖσι Πέρσῃσι. ἐνθαῦτα οἱ Πέρσαι ἰδόμενοι γυναῖκας εὐμόρφους ἔλεγον πρὸς Ἀμύντην φάμενοι τὸ ποιηθὲν τοῦτο οὐδὲν εἶναι σοφόν· κρέσσον γὰρ εἶναι ἀρχῆθεν μὴ ἐλθεῖν τὰς γυναῖκας ἢ ἐλθούσας καὶ μὴ παριζομένας ἀντίας ἵζεσθαι ἀλγηδόνας σφίσι ὀφθαλμῶν. ἀναγκαζόμενος δὲ ὁ Ἀμύντης ἐκέλευε παρίζειν· πειθομενέων δὲ τῶν γυναικῶν αὐτίκα οἱ Πέρσαι μαστῶν τε ἅπτοντο οἷα πλεόνως οἰνωμένοι, καί κού τις καὶ φιλέειν ἐπειρᾶτο.", "st": "5.18"}, {"sp": "N", "t": "Ἀμύντης μὲν δὴ ταῦτα ὁρέων ἀτρέμας εἶχε, καίπερ δυσφορέων, οἷα ὑπερδειμαίνων τοὺς Πέρσας· Ἀλέξανδρος δὲ ὁ Ἀμύντεω παρεών τε καὶ ὁρέων ταῦτα, ἅτε νέος τε ἐὼν καὶ κακῶν ἀπαθής, οὐδαμῶς ἔτι κατέχειν οἷος τε ἦν, ὥστε δὲ βαρέως φέρων εἶπε πρὸς Ἀμύντην τάδε. ὦ πάτερ, σὺ μὲν εἶκε τῇ ἡλικίῃ ἀπιών τε ἀναπαύεο, μηδὲ λιπάρεε τῇ πόσι· ἐγὼ δὲ προσμένων αὐτοῦ τῇδε πάντα τὰ ἐπιτήδεα παρέξω τοῖσι ξείνοισι. πρὸς ταῦτα συνιεὶς Ἀμύντης ὅτι νεώτερα πρήγματα πρήσσειν μέλλοι ὁ Ἀλέξανδρος, λέγει ὦ παῖ, σχεδὸν γάρ σευ ἀνακαιομένου συνίημι τοὺς λόγους, ὅτι ἐθέλεις ἐμὲ ἐκπέμψας ποιέειν τι νεώτερον· ἐγὼ ὦν σευ χρηίζω μηδὲν νεοχμῶσαι κατ’ ἄνδρας τούτους, ἵνα μὴ ἐξεργάσῃ ἡμέας, ἀλλὰ ἀνέχευ ὁρέων τὰ ποιεύμενα· ἀμφὶ δὲ ἀπόδῳ τῇ ἐμῇ πείσομαί τοι.", "st": "5.19"}, {"sp": "N", "t": "ὡς δὲ ὁ Ἀμύντης χρηίσας τούτων οἰχώκεε, λέγει ὁ Ἀλέξανδρος πρὸς τοὺς Πέρσας γυναικῶν τουτέων, ὦ ξεῖνοι, ἔστι ὑμῖν πολλὴ εὐπετείη, καὶ εἰ πάσῃσι βούλεσθε μίσγεσθαι καὶ ὁκόσῃσι ὦν αὐτέων. τούτου μὲν πέρι αὐτοὶ ἀποσημανέετε· νῦν δέ, σχεδὸν γὰρ ἤδη τῆς κοίτης ὥρη προσέρχεται ὑμῖν καὶ καλῶς ἔχοντας ὑμέας ὁρῶ μέθης, γυναῖκας ταύτας, εἰ ὑμῖν φίλον ἐστί, ἄπετε λούσασθαι, λουσαμένας δὲ ὀπίσω προσδέκεσθε. εἴπας ταῦτα, συνέπαινοι γὰρ ἦσαν οἱ Πέρσαι, γυναῖκας μὲν ἐξελθούσας ἀπέπεμπε ἐς τὴν γυναικηίην, αὐτὸς δὲ ὁ Ἀλέξανδρος ἴσους τῇσι γυναιξὶ ἀριθμὸν ἄνδρας λειογενείους τῇ τῶν γυναικῶν ἐσθῆτι σκευάσας καὶ ἐγχειρίδια δοὺς ἦγε ἔσω, παράγων δὲ τούτους ἔλεγε τοῖσι Πέρσῃσι τάδε. ὦ Πέρσαι, οἴκατε πανδαισίῃ τελέῃ ἱστιῆσθαι· τά τε γὰρ ἄλλα ὅσα εἴχομεν, καὶ πρὸς τὰ οἷά τε ἦν ἐξευρόντας παρέχειν, πάντα ὑμῖν πάρεστι, καὶ δὴ καὶ τόδε τὸ πάντων μέγιστον, τάς τε ἑωυτῶν μητέρας καὶ τὰς ἀδελφεὰς ἐπιδαψιλευόμεθα ὑμῖν, ὡς παντελέως μάθητε τιμώμενοι πρὸς ἡμέων τῶν περ ἐστὲ ἄξιοι, πρὸς δὲ καὶ βασιλέι τῷ πέμψαντι ἀπαγγείλητε ὡς ἀνὴρ Ἕλλην Μακεδόνων ὕπαρχος εὖ ὑμέας ἐδέξατο καὶ τραπέζῃ καὶ κοίτῃ. ταῦτα εἴπας ὁ Ἀλέξανδρος παρίζει Πέρσῃ ἀνδρὶ ἄνδρα Μακεδόνα ὡς γυναῖκα τῷ λόγῳ· οἳ δέ, ἐπείτε σφέων οἱ Πέρσαι ψαύειν ἐπειρῶντο, διεργάζοντο αὐτούς.", "st": "5.20"}, {"sp": "N", "t": "καὶ οὗτοι μὲν τούτῳ τῷ μόρῳ διεφθάρησαν, καὶ αὐτοὶ καὶ ἡ θεραπηίη αὐτῶν· εἵπετο γὰρ δή σφι καὶ ὀχήματα καὶ θεράποντες καὶ ἡ πᾶσα πολλὴ παρασκευή· πάντα δὴ ταῦτα ἅμα πᾶσι ἐκείνοισι ἠφάνιστο. μετὰ δὲ χρόνῳ οὐ πολλῷ ὕστερον ζήτησις τῶν ἀνδρῶν τούτων μεγάλη ἐκ τῶν Περσέων ἐγίνετο, καί σφεας Ἀλέξανδρος κατέλαβε σοφίῃ, χρήματά τε δοὺς πολλὰ καὶ τὴν ἑωυτοῦ ἀδελφεὴν τῇ οὔνομα ἦν Γυγαίη· δοὺς δὲ ταῦτα κατέλαβε ὁ Ἀλέξανδρος Βουβάρῃ ἀνδρὶ Πέρσῃ, τῶν διζημένων τοὺς ἀπολομένους τῷ στρατηγῷ.", "st": "5.21"}, {"sp": "N", "t": "ὁ μέν νυν τῶν Περσέων τούτων θάνατος οὕτω καταλαμφθεὶς ἐσιγήθη. Ἕλληνας δὲ εἶναι τούτους τοὺς ἀπὸ Περδίκκεω γεγονότας, κατά περ αὐτοὶ λέγουσι, αὐτός τε οὕτω τυγχάνω ἐπιστάμενος καὶ δὴ καὶ ἐν τοῖσι ὄπισθε λόγοισι ἀποδέξω ὡς εἰσὶ Ἕλληνες, πρὸς δὲ καὶ οἱ τὸν ἐν Ὀλυμπίῃ διέποντες ἀγῶνα Ἑλληνοδίκαι οὕτω ἔγνωσαν εἶναι. Ἀλεξάνδρου γὰρ ἀεθλεύειν ἑλομένου καὶ καταβάντος ἐπ’ αὐτὸ τοῦτο, οἱ ἀντιθευσόμενοι Ἑλλήνων ἐξεῖργόν μιν, φάμενοι οὐ βαρβάρων ἀγωνιστέων εἶναι τὸν ἀγῶνα ἀλλὰ Ἑλλήνων· Ἀλέξανδρος δὲ ἐπειδὴ ἀπέδεξε ὡς εἴη Ἀργεῖος, ἐκρίθη τε εἶναι Ἕλλην καὶ ἀγωνιζόμενος στάδιον συνεξέπιπτε τῷ πρώτῳ.", "st": "5.22"}, {"sp": "N", "t": "ταῦτα μέν νυν οὕτω κῃ ἐγένετο. Μεγάβαζος δὲ ἄγων τοὺς Παίονας ἀπίκετο ἐπὶ τὸν Ἑλλήποντον· ἐνθεῦτεν διαπεραιωθεὶς ἀπίκετο ἐς τὰς Σάρδις. ἅτε δὲ τειχέοντος ἤδη Ἱστιαίου τοῦ Μιλησίου τὴν παρὰ Δαρείου αἰτήσας ἔτυχε μισθὸν δωρεὴν φυλακῆς τῆς σχεδίης, ἐόντος δὲ τοῦ χώρου τούτου παρὰ Στρυμόνα ποταμὸν τῷ οὔνομα ἐστὶ Μύρκινος, μαθὼν ὁ Μεγάβαζος τὸ ποιεύμενον ἐκ τοῦ Ἱστιαίου, ὡς ἦλθε τάχιστα ἐς τὰς Σάρδις ἄγων τοὺς Παίονας, ἔλεγε Δαρείῳ τάδε. ὦ βασιλεῦ, κοῖόν τι χρῆμα ἐποίησας, ἀνδρὶ Ἕλληνι δεινῷ τε καὶ σοφῷ δοὺς ἐγκτίσασθαι πόλιν ἐν Θρηίκῃ, ἵνα ἴδη τε ναυπηγήσιμος ἐστὶ ἄφθονος καὶ πολλοὶ κωπέες καὶ μέταλλα ἀργύρεα, ὅμιλός τε πολλὸς μὲν Ἕλλην περιοικέει πολλὸς δὲ βάρβαρος, οἳ προστάτεω ἐπιλαβόμενοι ποιήσουσι τοῦτο τὸ ἂν κεῖνος ἐξηγέηται καὶ ἡμέρης καὶ νυκτός. σύ νυν τοῦτον τὸν ἄνδρα παῦσον ταῦτα ποιεῦντα, ἵνα μὴ οἰκηίῳ πολέμῳ συνέχῃ· τρόπῳ δὲ ἠπίῳ μεταπεμψάμενος παῦσον. ἐπεὰν δὲ αὐτὸν περιλάβῃς, ποιέειν ὅκως μηκέτι κεῖνος ἐς Ἕλληνας ἀπίξεται.", "st": "5.23"}, {"sp": "N", "t": "ταῦτα λέγων ὁ Μεγάβαζος εὐπετέως ἔπειθε Δαρεῖον ὡς εὖ προορῶν τὸ μέλλον γίνεσθαι. μετὰ δὲ πέμψας ἄγγελον ἐς τὴν Μύρκινον ὁ Δαρεῖος ἔλεγε τάδε. Ἱστιαῖε, βασιλεὺς Δαρεῖος τάδε λέγει. ἐγὼ φροντίζων εὑρίσκω ἐμοί τε καὶ τοῖσι ἐμοῖσι πρήγμασι εἶναι οὐδένα σεῦ ἄνδρα εὐνοέστερον· τοῦτο δὲ οὐ λόγοισι ἀλλ’ ἔργοισι οἶδα μαθών. νῦν ὦν, ἐπινοέω γὰρ πρήγματα μεγάλα κατεργάσασθαι, ἀπίκεό μοι πάντως, ἵνα τοι αὐτὰ ὑπερθέωμαι. τούτοισι τοῖσι ἔπεσι πιστεύσας ὁ Ἱστιαῖος, καὶ ἅμα μέγα ποιεύμενος βασιλέος σύμβουλος γενέσθαι, ἀπίκετο ἐς τὰς Σάρδις· ἀπικομένῳ δέ οἱ ἔλεγε Δαρεῖος τάδε. Ἱστιαῖε, ἐγώ σε μετεπεμψάμην τῶνδε εἵνεκεν. ἐπείτε τάχιστα ἐνόστησα ἀπὸ Σκυθέων καὶ σύ μοι ἐγένεο ἐξ ὀφθαλμῶν, οὐδέν κω ἄλλο χρῆμα οὕτω ἐν βραχέι ἐπεζήτησα ὡς σὲ ἰδεῖν τε καὶ ἐς λόγους μοι ἀπικέσθαι, ἐγνωκὼς ὅτι κτημάτων πάντων ἐστὶ τιμιώτατον ἀνὴρ φίλος συνετός τε καὶ εὔνοος, τά τοι ἐγὼ καὶ ἀμφότερα συνειδὼς ἔχω μαρτυρέειν ἐς πρήγματα τὰ ἐμά. νῦν ὦν, εὖ γὰρ ἐποίησας ἀπικόμενος, τάδε τοι ἐγὼ προτείνομαι· Μίλητον μὲν ἔα καὶ τὴν νεόκτιστον ἐν Θρηίκῃ πόλιν, σὺ δέ μοι ἑπόμενος ἐς Σοῦσα ἔχε τά περ ἂν ἐγὼ ἔχω, ἐμός τε σύσσιτος ἐὼν καὶ σύμβουλος.", "st": "5.24"}, {"sp": "N", "t": "ταῦτα Δαρεῖος εἴπας, καὶ καταστήσας Ἀρταφρένεα ἀδελφεὸν ἑωυτοῦ ὁμοπάτριον ὕπαρχον εἶναι Σαρδίων, ἀπήλαυνε ἐς Σοῦσα ἅμα ἀγόμενος Ἱστιαῖον, Ὀτάνεα δὲ ἀποδέξας στρατηγὸν εἶναι τῶν παραθαλασσίων ἀνδρῶν· τοῦ τὸν πατέρα Σισάμνην βασιλεὺς Καμβύσης γενόμενον τῶν βασιληίων δικαστέων, ὅτι ἐπὶ χρήμασι δίκην ἄδικον ἐδίκασε, σφάξας ἀπέδειρε πᾶσαν τὴν ἀνθρωπέην, σπαδίξας δὲ αὐτοῦ τὸ δέρμα ἱμάντας ἐξ αὐτοῦ ἔταμε καὶ ἐνέτεινε τὸν θρόνον ἐς τὸν ἵζων ἐδίκαζε· ἐντανύσας δὲ ὁ Καμβύσης ἀπέδεξε δικαστὴν εἶναι ἀντὶ τοῦ Σισάμνεω, τὸν ἀποκτείνας ἀπέδειρε, τὸν παῖδα τοῦ Σισάμνεω, ἐντειλάμενός οἱ μεμνῆσθαι ἐν τῷ κατίζων θρόνῳ δικάζει.", "st": "5.25"}, {"sp": "N", "t": "οὗτος ὦν ὁ Ὀτάνης ὁ ἐγκατιζόμενος ἐς τοῦτον τὸν θρόνον, τότε διάδοχος γενόμενος Μεγαβάζῳ τῆς στρατηγίης, Βυζαντίους τε εἷλε καὶ Καλχηδονίους, εἷλε δὲ Ἄντανδρον τὴν ἐν τῇ Τρῳάδι γῇ, εἷλε δὲ Λαμπώνιον, λαβὼν δὲ παρὰ Λεσβίων νέας εἷλε Λῆμνόν τε καὶ Ἴμβρον, ἀμφοτέρας ἔτι τότε ὑπὸ Πελασγῶν οἰκεομένας.", "st": "5.26"}, {"sp": "N", "t": "οἱ μὲν δὴ Λήμνιοι καὶ ἐμαχέσαντο εὖ καὶ ἀμυνόμενοι ἀνὰ χρόνον ἐκακώθησαν, τοῖσι δὲ περιεοῦσι αὐτῶν οἱ Πέρσαι ὕπαρχον ἐπιστᾶσι Λυκάρητον τὸν Μαιανδρίου τοῦ βασιλεύσαντος Σάμου ἀδελφεόν. οὗτος ὁ Λυκάρητος ἄρχων ἐν Λήμνῳ τελευτᾷ. αἰτίη δὲ τούτου ἥδε· πάντας ἠνδραποδίζετο καὶ κατεστρέφετο τοὺς μὲν λιποστρατίης ἐπὶ Σκύθας αἰτιώμενος, τοὺς δὲ σίνασθαι τὸν Δαρείου στρατὸν ἀπὸ Σκυθέων ὀπίσω ἀποκομιζόμενον.", "st": "5.27"}, {"sp": "N", "t": "οὗτος δὲ τοσαῦτα ἐξεργάσατο στρατηγήσας. μετὰ δὲ οὐ πολλὸν χρόνον ἄνεσις κακῶν ἦν, καὶ ἤρχετο τὸ δεύτερον ἐκ Νάξου τε καὶ Μιλήτου Ἴωσι γίνεσθαι κακά. τοῦτο μὲν γὰρ ἡ Νάξος εὐδαιμονίῃ τῶν νήσων προέφερε, τοῦτο δὲ κατὰ τὸν αὐτὸν χρόνον ἡ Μίλητος αὐτή τε ἑωυτῆς μάλιστα δὴ τότε ἀκμάσασα καὶ δὴ καὶ τῆς Ἰωνίης ἦν πρόσχημα, κατύπερθε δὲ τούτων ἐπὶ δύο γενεὰς ἀνδρῶν νοσήσασα ἐς τὰ μάλιστα στάσι, μέχρι οὗ μιν Πάριοι κατήρτισαν· τούτους γὰρ καταρτιστῆρας ἐκ πάντων Ἑλλήνων εἵλοντο οἱ Μιλήσιοι.", "st": "5.28"}, {"sp": "N", "t": "κατήλλαξαν δὲ σφέας ὧδε Πάριοι. ὡς ἀπίκοντο αὐτῶν ἄνδρες οἱ ἄριστοι ἐς τὴν Μίλητον, ὥρων γὰρ δή σφεας δεινῶς οἰκοφθορημένους, ἔφασαν αὐτῶν βούλεσθαι διεξελθεῖν τὴν χώρην· ποιεῦντες δὲ ταῦτα καὶ διεξιόντες πᾶσαν τὴν Μιλησίην, ὅκως τινὰ ἴδοιεν ἐν ἀνεστηκυίῃ τῇ χώρῃ ἀγρὸν εὖ ἐξεργασμένον, ἀπεγράφοντο τὸ οὔνομα τοῦ δεσπότεω τοῦ ἀγροῦ. διεξελάσαντες δὲ πᾶσαν τὴν χώρην καὶ σπανίους εὑρόντες τούτους, ὡς τάχιστα κατέβησαν ἐς τὸ ἄστυ, ἁλίην ποιησάμενοι ἀπέδεξαν τούτους μὲν πόλιν νέμειν τῶν εὗρον τοὺς ἀγροὺς εὖ ἐξεργασμένους· δοκέειν γὰρ ἔφασαν καὶ τῶν δημοσίων οὕτω δή σφεας ἐπιμελήσεσθαι ὥσπερ τῶν σφετέρων· τοὺς δὲ ἄλλους Μιλησίους τοὺς πρὶν στασιάζοντας τούτων ἔταξαν πείθεσθαι.", "st": "5.29"}, {"sp": "N", "t": "Πάριοι μέν νυν Μιλησίους οὕτω κατήρτισαν. τότε δὲ ἐκ τουτέων τῶν πολίων ὧδε ἤρχετο κακὰ γίνεσθαι τῇ Ἰωνίῃ. ἐκ Νάξου ἔφυγον ἄνδρες τῶν παχέων ὑπὸ τοῦ δήμου, φυγόντες δὲ ἀπίκοντο ἐς Μίλητον. τῆς δὲ Μιλήτου ἐτύγχανε ἐπίτροπος ἐὼν Ἀρισταγόρης ὁ Μολπαγόρεω, γαμβρός τε ἐὼν καὶ ἀνεψιὸς Ἱστιαίου τοῦ Λυσαγόρεω, τὸν ὁ Δαρεῖος ἐν Σούσοισι κατεῖχε· ὁ γὰρ Ἱστιαῖος τύραννος ἦν Μιλήτου καὶ ἐτύγχανε τοῦτον τὸν χρόνον ἐὼν ἐν Σούσοισι, ὅτε οἱ Νάξιοι ἦλθον ξεῖνοι πρὶν ἐόντες τῷ Ἱστιαίῳ. ἀπικόμενοι δὲ οἱ Νάξιοι ἐς τὴν Μίλητον ἐδέοντο τοῦ Ἀρισταγόρεω, εἴ κως αὐτοῖσι παράσχοι δύναμίν τινα καὶ κατέλθοιεν ἐς τὴν ἑωυτῶν. ὁ δὲ ἐπιλεξάμενος ὡς ἢν δι’ αὐτοῦ κατέλθωσι ἐς τὴν πόλιν, ἄρξει τῆς Νάξου, σκῆψιν δὲ ποιεύμενος τὴν ξεινίην τὴν Ἱστιαίου, τόνδε σφι λόγον προσέφερε. αὐτὸς μὲν ὑμῖν οὐ φερέγγυός εἰμι δύναμιν παρασχεῖν τοσαύτην ὥστε κατάγειν ἀεκόντων τῶν τὴν πόλιν ἐχόντων Ναξίων· πυνθάνομαι γὰρ ὀκτακισχιλίην ἀσπίδα Ναξίοισι εἶναι καὶ πλοῖα μακρὰ πολλά· μηχανήσομαι δὲ πᾶσαν σπουδὴν ποιεύμενος. ἐπινοέω δὲ τῇδε. Ἀρταφρένης μοι τυγχάνει ἐὼν φίλος· ὁ δὲ Ἀρταφρένης ὑμῖν Ὑστάσπεος μὲν ἐστὶ παῖς, Δαρείου δὲ τοῦ βασιλέος ἀδελφεός, τῶν δ’ ἐπιθαλασσίων τῶν ἐν τῇ Ἀσίῃ ἄρχει πάντων, ἔχων στρατιήν τε πολλὴν καὶ πολλὰς νέας. τοῦτον ὦν δοκέω τὸν ἄνδρα ποιήσειν τῶν ἂν χρηίζωμεν. ταῦτα ἀκούσαντες οἱ Νάξιοι προσέθεσαν τῷ Ἀρισταγόρῃ πρήσσειν τῇ δύναιτο ἄριστα, καὶ ὑπίσχεσθαι δῶρα ἐκέλευον καὶ δαπάνην τῇ στρατιῇ ὡς αὐτοὶ διαλύσοντες, ἐλπίδας πολλὰς ἔχοντες, ὅταν ἐπιφανέωσι ἐς τὴν Νάξον, πάντα ποιήσειν τοὺς Ναξίους τὰ ἂν αὐτοὶ κελεύωσι, ὣς δὲ καὶ τοὺς ἄλλους νησιώτας. τῶν γὰρ νήσων τουτέων τῶν Κυκλάδων οὐδεμία κω ἦν ὑπὸ Δαρείῳ.", "st": "5.30"}, {"sp": "N", "t": "ἀπικόμενος δὲ ὁ Ἀρισταγόρης ἐς τὰς Σάρδις λέγει πρὸς τὸν Ἀρταφρένεα ὡς Νάξος εἴη νῆσος μεγάθεϊ μὲν οὐ μεγάλη, ἄλλως δὲ καλή τε καὶ ἀγαθὴ καὶ ἀγχοῦ Ἰωνίης, χρήματα δὲ ἔνι πολλὰ καὶ ἀνδράποδα. σὺ ὦν ἐπὶ ταύτην τὴν χώρην στρατηλάτεε, κατάγων ἐς αὐτὴν τοὺς φυγάδας ἐξ αὐτῆς. καί τοι ταῦτα ποιήσαντι τοῦτο μὲν ἐστὶ ἕτοιμα παρ’ ἐμοὶ χρήματα μεγάλα πάρεξ τῶν ἀναισιμωμάτων τῇ στρατιῇ· ταῦτα μὲν γὰρ δίκαιον ἡμέας τοὺς ἄγοντας παρέχειν ἐστί· τοῦτο δὲ νήσους βασιλέι προσκτήσεαι αὐτήν τε Νάξον καὶ τὰς ἐκ ταύτης ἠρτημένας, Πάρον καὶ Ἄνδρον καὶ ἄλλας τὰς Κυκλάδας καλευμένας. ἐνθεῦτεν δὲ ὁρμώμενος εὐπετέως ἐπιθήσεαι Εὐβοίῃ νήσῳ μεγάλῃ τε καὶ εὐδαίμονι, οὐκ ἐλάσσονι Κύπρου καὶ κάρτα εὐπετέι αἱρεθῆναι. ἀποχρῶσι δὲ ἑκατὸν νέες ταύτας πάσας χειρώσασθαι. ὁ δὲ ἀμείβετο αὐτὸν τοῖσιδε. σὺ ἐς οἶκον τὸν βασιλέος ἐξηγητὴς γίνεαι πρηγμάτων ἀγαθῶν, καὶ ταῦτα εὖ παραινέεις πάντα, πλὴν τῶν νεῶν τοῦ ἀριθμοῦ· ἀντὶ δὲ ἑκατὸν νεῶν διηκόσιαί τοι ἕτοιμοι ἔσονται ἅμα τῷ ἔαρι. δεῖ δὲ τούτοισι καὶ αὐτὸν βασιλέα συνέπαινον γίνεσθαι.", "st": "5.31"}, {"sp": "N", "t": "ὁ μὲν δὴ Ἀρισταγόρης ὡς ταῦτα ἤκουσε, περιχαρὴς ἐὼν ἀπήιε ἐς Μίλητον. ὁ δὲ Ἀρταφρένης, ὥς οἱ πέμψαντι ἐς Σοῦσα καὶ ὑπερθέντι τὰ ἐκ τοῦ Ἀρισταγόρεω λεγόμενα συνέπαινος καὶ αὐτὸς Δαρεῖος ἐγένετο, παρεσκευάσατο μὲν διηκοσίας τριήρεας, πολλὸν δὲ κάρτα ὅμιλον Περσέων τε καὶ τῶν ἄλλων συμμάχων, στρατηγὸν δὲ τούτων ἀπέδεξε Μεγαβάτην ἄνδρα Πέρσην τῶν Ἀχαιμενιδέων, ἑωυτοῦ τε καὶ Δαρείου ἀνεψιόν, τοῦ Παυσανίης ὁ Κλεομβρότου Λακεδαιμόνιος, εἰ δὴ ἀληθής γε ἐστὶ ὁ λόγος, ὑστέρῳ χρόνῳ τούτων ἡρμόσατο θυγατέρα, ἔρωτα σχὼν τῆς Ἑλλάδος τύραννος γενέσθαι. ἀποδέξας δὲ Μεγαβάτην στρατηγὸν Ἀρταφρένης ἀπέστειλε τὸν στρατὸν παρὰ τὸν Ἀρισταγόρεα.", "st": "5.32"}, {"sp": "N", "t": "παραλαβὼν δὲ ὁ Μεγαβάτης τόν τε Ἀρισταγόρεα ἐκ τῆς Μιλήτου καὶ τὴν Ἰάδα στρατιὴν καὶ τοὺς Ναξίους ἔπλεε πρόφασιν ἐπ’ Ἑλλησπόντου, ἐπείτε δὲ ἐγένετο ἐν Χίῳ, ἔσχε τὰς νέας ἐς Καύκασα, ὡς ἐνθεῦτεν βορέῃ ἀνέμῳ ἐς τὴν Νάξον διαβάλοι. καὶ οὐ γὰρ ἔδεε τούτῳ τῷ στόλῳ Ναξίους ἀπολέσθαι, πρῆγμα τοιόνδε συνηνείχθη γενέσθαι. περιιόντος Μεγαβάτεω τὰς ἐπὶ τῶν νεῶν φυλακάς, ἐπὶ νεὸς Μυνδίης ἔτυχε οὐδεὶς φυλάσσων· ὁ δὲ δεινόν τι ποιησάμενος ἐκέλευσε τοὺς δορυφόρους ἐξευρόντας τὸν ἄρχοντα ταύτης τῆς νεός, τῷ οὔνομα ἦν Σκύλαξ, τοῦτον δῆσαι διὰ θαλαμίης διελόντας τῆς νεὸς κατὰ τοῦτο, ἔξω μὲν κεφαλὴν ποιεῦντας ἔσω δὲ τὸ σῶμα. δεθέντος δὲ τοῦ Σκύλακος, ἐξαγγέλλει τις τῷ Ἀρισταγόρῃ ὅτι τὸν ξεῖνόν οἱ τὸν Μύνδιον Μεγαβάτης δήσας λυμαίνοιτο. ὃ δ’ ἐλθὼν παραιτέετο τὸν Πέρσην, τυγχάνων δὲ οὐδενὸς τῶν ἐδέετο, αὐτὸς ἐλθὼν ἔλυσε. πυθόμενος δὲ κάρτα δεινὸν ἐποιήσατο ὁ Μεγαβάτης καὶ ἐσπέρχετο τῷ Ἀρισταγόρῃ, ὁ δὲ εἶπε σοὶ δὲ καὶ τούτοισι τοῖσι πρήγμασι τί ἐστι; οὐ σὲ ἀπέστειλε Ἀρταφρένης ἐμέο πείθεσθαι καὶ πλέειν τῇ ἂν ἐγὼ κελεύω; τί πολλὰ πρήσσεις; ταῦτα εἶπε ὁ Ἀρισταγόρης. ὁ δὲ θυμωθεὶς τούτοισι, ὡς νὺξ ἐγένετο, ἔπεμπε ἐς Νάξον πλοίῳ ἄνδρας φράσοντας τοῖσι Ναξίοισι πάντα τὰ παρεόντα σφι πρήγματα.", "st": "5.33"}, {"sp": "N", "t": "οἱ γὰρ ὦν Νάξιοι οὐδὲν πάντως προσεδέκοντο ἐπὶ σφέας τὸν στόλον τοῦτον ὁρμήσεσθαι. ἐπεὶ μέντοι ἐπύθοντο, αὐτίκα μὲν ἐσηνείκαντο τὰ ἐκ τῶν ἀγρῶν ἐς τὸ τεῖχος, παρεσκευάσαντο δὲ ὡς πολιορκησόμενοι καὶ σῖτα καὶ ποτά, καὶ τὸ τεῖχος ἐσάξαντο. καὶ οὗτοι μὲν παρεσκευάζοντο ὡς παρεσομένου σφι πολέμου· οἳ δ’ ἐπείτε διέβαλον ἐκ τῆς Χίου τὰς νέας ἐς τὴν Νάξον, πρὸς πεφραγμένους προσεφέροντο καὶ ἐπολιόρκεον μῆνας τέσσερας. ὡς δὲ τά τε ἔχοντες ἦλθον χρήματα οἱ Πέρσαι, ταῦτα κατεδεδαπάνητό σφι, καὶ αὐτῷ τῷ Ἀρισταγόρῃ προσαναισίμωτο πολλά, τοῦ πλεῦνός τε ἐδέετο ἡ πολιορκίη, ἐνθαῦτα τείχεα τοῖσι φυγάσι τῶν Ναξίων οἰκοδομήσαντες ἀπαλλάσσοντο ἐς τὴν ἤπειρον κακῶς πρήσσοντες.", "st": "5.34"}, {"sp": "N", "t": "Ἀρισταγόρης δὲ οὐκ εἶχε τὴν ὑπόσχεσιν τῷ Ἀρταφρένεϊ ἐκτελέσαι· ἅμα δὲ ἐπίεζέ μιν ἡ δαπάνη τῆς στρατιῆς ἀπαιτεομένη, ἀρρώδεέ τε τοῦ στρατοῦ πρήξαντος κακῶς καὶ Μεγαβάτῃ διαβεβλημένος, ἐδόκεέ τε τὴν βασιληίην τῆς Μιλήτου ἀπαιρεθήσεσθαι. ἀρρωδέων δὲ τούτων ἕκαστα ἐβουλεύετο ἀπόστασιν· συνέπιπτε γὰρ καὶ τὸν ἐστιγμένον τὴν κεφαλὴν ἀπῖχθαι ἐκ Σούσων παρὰ Ἱστιαίου, σημαίνοντα ἀπίστασθαι Ἀρισταγόρην ἀπὸ βασιλέος. ὁ γὰρ Ἱστιαῖος βουλόμενος τῷ Ἀρισταγόρῃ σημῆναι ἀποστῆναι ἄλλως μὲν οὐδαμῶς εἶχε ἀσφαλέως σημῆναι ὥστε φυλασσομενέων τῶν ὁδῶν, ὁ δὲ τῶν δούλων τὸν πιστότατον ἀποξυρήσας τὴν κεφαλὴν ἔστιξε καὶ ἀνέμεινε ἀναφῦναι τὰς τρίχας, ὡς δὲ ἀνέφυσαν τάχιστα, ἀπέπεμπε ἐς Μίλητον ἐντειλάμενος αὐτῷ ἄλλο μὲν οὐδέν, ἐπεὰν δὲ ἀπίκηται ἐς Μίλητον, κελεύειν Ἀρισταγόρην ξυρήσαντά μιν τὰς τρίχας κατιδέσθαι ἐς τὴν κεφαλήν. τὰ δὲ στίγματα ἐσήμαινε, ὡς καὶ πρότερόν μοι εἴρηται, ἀπόστασιν. ταῦτα δὲ ὁ Ἱστιαῖος ἐποίεε συμφορὴν ποιεύμενος μεγάλην τὴν ἑωυτοῦ κατοχὴν τὴν ἐν Σούσοισι· ἀποστάσιος ὦν γινομένης πολλὰς εἶχε ἐλπίδας μετήσεσθαι ἐπὶ θάλασσαν, μὴ δὲ νεώτερόν τι ποιεύσης τῆς Μιλήτου οὐδαμὰ ἐς αὐτὴν ἥξειν ἔτι ἐλογίζετο.", "st": "5.35"}, {"sp": "N", "t": "Ἱστιαῖος μέν νυν ταῦτα διανοεύμενος ἀπέπεμπε τὸν ἄγγελον, Ἀρισταγόρῃ δὲ συνέπιπτε τοῦ αὐτοῦ χρόνου πάντα ταῦτα συνελθόντα. ἐβουλεύετο ὦν μετὰ τῶν στασιωτέων, ἐκφήνας τήν τε ἑωυτοῦ γνώμην καὶ τὰ παρὰ τοῦ Ἱστιαίου ἀπιγμένα. οἱ μὲν δὴ ἄλλοι πάντες γνώμην κατὰ τὠυτὸ ἐξεφέροντο, κελεύοντες ἀπίστασθαι· Ἑκαταῖος δ’ ὁ λογοποιὸς πρῶτα μὲν οὐκ ἔα πόλεμον βασιλέι τῶν Περσέων ἀναιρέεσθαι, καταλέγων τά τε ἔθνεα πάντα τῶν ἦρχε Δαρεῖος καὶ τὴν δύναμιν αὐτοῦ. ἐπείτε δὲ οὐκ ἔπειθε, δεύτερα συνεβούλευε ποιέειν ὅκως ναυκρατέες τῆς θαλάσσης ἔσονται. ἄλλως μέν νυν οὐδαμῶς ἔφη λέγων ἐνορᾶν ἐσόμενον τοῦτο· ἐπίστασθαι γὰρ τὴν δύναμιν τῶν Μιλησίων ἐοῦσαν ἀσθενέα· εἰ δὲ τὰ χρήματα καταιρεθείη τὰ ἐκ τοῦ ἱροῦ τοῦ ἐν Βραγχίδῃσι, τὰ Κροῖσος ὁ Λυδὸς ἀνέθηκε, πολλὰς εἶχε ἐλπίδας ἐπικρατήσειν τῆς θαλάσσης, καὶ οὕτω αὐτούς τε ἕξειν τοῖσι χρήμασι χρᾶσθαι καὶ τοὺς πολεμίους οὐ συλήσειν αὐτά. τὰ δὲ χρήματα ἦν ταῦτα μεγάλα, ὡς δεδήλωταί μοι ἐν τῷ πρώτῳ τῶν λόγων. αὕτη μὲν δὴ οὐκ ἐνίκα ἡ γνώμη, ἐδόκεε δὲ ὅμως ἀπίστασθαι, ἕνα τε αὐτῶν πλώσαντα ἐς Μυοῦντα ἐς τὸ στρατόπεδον τὸ ἀπὸ τῆς Νάξου ἀπελθόν, ἐὸν ἐνθαῦτα, συλλαμβάνειν πειρᾶσθαι τοὺς ἐπὶ τῶν νεῶν ἐπιπλέοντας στρατηγούς.", "st": "5.36"}, {"sp": "N", "t": "ἀποπεμφθέντος δὲ Ἰητραγόρεω κατ’ αὐτὸ τοῦτο καὶ συλλαβόντος δόλῳ Ὀλίατον Ἰβανώλλιος Μυλασσέα καὶ Ἱστιαῖον Τύμνεω Τερμερέα καὶ Κώην Ἐρξάνδρου, τῷ Δαρεῖος Μυτιλήνην ἐδωρήσατο, καὶ Ἀρισταγόρην Ἡρακλείδεω Κυμαῖον καὶ ἄλλους συχνούς, οὕτω δὴ ἐκ τοῦ ἐμφανέος ὁ Ἀρισταγόρης ἀπεστήκεε, πᾶν ἐπὶ Δαρείῳ μηχανώμενος. καὶ πρῶτα μὲν λόγῳ μετεὶς τὴν τυραννίδα ἰσονομίην ἐποίεε τῇ Μιλήτῳ, ὡς ἂν ἑκόντες αὐτῷ οἱ Μιλήσιοι συναπισταίατο, μετὰ δὲ καὶ ἐν τῇ ἄλλῃ Ἰωνίῃ τὠυτὸ τοῦτο ἐποίεε, τοὺς μὲν ἐξελαύνων τῶν τυράννων, τοὺς δ’ ἔλαβε τυράννους ἀπὸ τῶν νεῶν τῶν συμπλευσασέων ἐπὶ Νάξον, τούτους δὲ φίλα βουλόμενος ποιέεσθαι τῇσι πόλισι ἐξεδίδου, ἄλλον ἐς ἄλλην πόλιν παραδιδούς, ὅθεν εἴη ἕκαστος.", "st": "5.37"}, {"sp": "N", "t": "Κώην μέν νυν Μυτιληναῖοι ἐπείτε τάχιστα παρέλαβον, ἐξαγαγόντες κατέλευσαν, Κυμαῖοι δὲ τὸν σφέτερον αὐτῶν ἀπῆκαν· ὣς δὲ καὶ ἄλλοι οἱ πλεῦνες ἀπίεσαν. τυράννων μέν νυν κατάπαυσις ἐγίνετο ἀνὰ τὰς πόλιας, Ἀρισταγόρης δὲ ὁ Μιλήσιος ὡς τοὺς τυράννους κατέπαυσε, στρατηγοὺς ἐν ἑκάστῃ τῶν πολίων κελεύσας ἑκάστους καταστῆσαι, δεύτερα αὐτὸς ἐς Λακεδαίμονα τριήρεϊ ἀπόστολος ἐγίνετο· ἔδεε γὰρ δὴ συμμαχίης τινός οἱ μεγάλης ἐξευρεθῆναι.", "st": "5.38"}, {"sp": "N", "t": "τῆς δὲ Σπάρτης Ἀναξανδρίδης μὲν ὁ Λέοντος οὐκέτι περιεὼν ἐβασίλευε ἀλλὰ ἐτετελευτήκεε, Κλεομένης δὲ ὁ Ἀναξανδρίδεω εἶχε τὴν βασιληίην, οὐ κατ’ ἀνδραγαθίην σχὼν ἀλλὰ κατὰ γένος. Ἀναξανδρίδῃ γὰρ ἔχοντι γυναῖκα ἀδελφεῆς ἑωυτοῦ θυγατέρα, καὶ ἐούσης ταύτης οἱ καταθυμίης, παῖδες οὐκ ἐγίνοντο. τούτου δὲ τοιούτου ἐόντος, οἱ ἔφοροι εἶπαν ἐπικαλεσάμενοι αὐτὸν εἴ τοι σὺ σεωυτοῦ μὴ προορᾷς, ἀλλ’ ἡμῖν τοῦτ’ ἐστὶ οὐ περιοπτέον, γένος τὸ Εὐρυσθένεος γενέσθαι ἐξίτηλον. σύ νυν τὴν μὲν ἔχεις γυναῖκα, ἐπείτε τοι οὐ τίκτει, ἔξεο, ἄλλην δὲ γῆμον· καὶ ποιέων ταῦτα Σπαρτιήτῃσι ἁδήσεις. ὃ δ’ ἀμείβετο φὰς τούτων οὐδέτερα ποιήσειν, ἐκείνους τε οὐ καλῶς συμβουλεύειν παραινέοντας, τὴν ἔχει γυναῖκα ἐοῦσαν ἀναμάρτητον ἑωυτῷ, ταύτην ἀπέντα ἄλλην ἐσαγαγέσθαι· οὐδέ σφι πείσεσθαι.", "st": "5.39"}, {"sp": "N", "t": "πρὸς ταῦτα οἱ ἔφοροι καὶ οἱ γέροντες βουλευσάμενοι προσέφερον Ἀναξανδρίδῃ τάδε. ἐπεὶ τοίνυν τοι περιεχόμενόν σε ὁρῶμεν τῆς ἔχεις γυναικός, σὺ δὲ ταῦτα ποίεε, καὶ μὴ ἀντίβαινε τούτοισι, ἵνα μή τι ἀλλοῖον περὶ σεῦ Σπαρτιῆται βουλεύσωνται· γυναικὸς μὲν τῆς ἔχεις οὐ προσδεόμεθά σευ τῆς ἐξέσιος, σὺ δὲ ταύτῃ τε πάντα ὅσα νῦν παρέχεις πάρεχε καὶ ἄλλην πρὸς ταύτῃ ἐσάγαγε γυναῖκα τεκνοποιόν. ταῦτά κῃ λεγόντων συνεχώρησε ὁ Ἀναξανδρίδης, μετὰ δὲ γυναῖκας ἔχων δύο διξὰς ἱστίας οἴκεε, ποιέων οὐδαμῶς Σπαρτιητικά.", "st": "5.40"}, {"sp": "N", "t": "χρόνου δὲ οὐ πολλοῦ διελθόντος ἡ ἐσύστερον ἐπελθοῦσα γυνὴ τίκτει τὸν δὴ Κλεομένεα τοῦτον. καὶ αὕτη τε ἔφεδρον βασιλέα Σπαρτιήτῃσι ἀπέφαινε, καὶ ἡ προτέρη γυνὴ τὸν πρότερον χρόνον ἄτοκος ἐοῦσα τότε κως ἐκύησε, συντυχίῃ ταύτῃ χρησαμένη. ἔχουσαν δὲ αὐτὴν ἀληθεῖ λόγῳ οἱ τῆς ἐπελθούσης γυναικὸς οἰκήιοι πυθόμενοι ὤχλεον, φάμενοι αὐτὴν κομπέειν ἄλλως βουλομένην ὑποβαλέσθαι. δεινὰ δὲ ποιεύντων αὐτῶν, τοῦ χρόνου συντάμνοντος, ὑπ’ ἀπιστίης οἱ ἔφοροι τίκτουσαν τὴν γυναῖκα περιιζόμενοι ἐφύλαξαν. ἣ δὲ ὡς ἔτεκε Δωριέα ἰθέως ἴσχει Λεωνίδην, καὶ μετὰ τοῦτον ἰθέως ἴσχει Κλεόμβροτον· οἳ δὲ καὶ διδύμους λέγουσι Κλεόμβροτον καὶ Λεωνίδην γενέσθαι. ἣ δὲ Κλεομένεα τεκοῦσα καὶ τὸ δεύτερον ἐπελθοῦσα γυνή, ἐοῦσα θυγάτηρ Πρινητάδεω τοῦ Δημαρμένου, οὐκέτι ἔτικτε τὸ δεύτερον.", "st": "5.41"}, {"sp": "N", "t": "ὁ μὲν δὴ Κλεομένης, ὡς λέγεται, ἦν τε οὐ φρενήρης ἀκρομανής τε, ὁ δὲ Δωριεὺς ἦν τῶν ἡλίκων πάντων πρῶτος, εὖ τε ἐπίστατο κατ’ ἀνδραγαθίην αὐτὸς σχήσων τὴν βασιληίην. ὥστε ὦν οὕτω φρονέων, ἐπειδὴ ὅ τε Ἀναξανδρίδης ἀπέθανε καὶ οἱ Λακεδαιμόνιοι χρεώμενοι τῷ νόμῳ ἐστήσαντο βασιλέα τὸν πρεσβύτατον Κλεομένεα, ὁ Δωριεὺς δεινόν τε ποιεύμενος καὶ οὐκ ἀξιῶν ὑπὸ Κλεομένεος βασιλεύεσθαι, αἰτήσας λεὼν Σπαρτιήτας ἦγε ἐς ἀποικίην, οὔτε τῷ ἐν Δελφοῖσι χρηστηρίῳ χρησάμενος ἐς ἥντινα γῆν κτίσων ἴῃ, οὔτε ποιήσας οὐδὲν τῶν νομιζομένων· οἷα δὲ βαρέως φέρων, ἀπίει ἐς τὴν Λιβύην τὰ πλοῖα· κατηγέοντο δέ οἱ ἄνδρες Θηραῖοι. ἀπικόμενος δὲ ἐς Λιβύην οἴκισε χῶρον κάλλιστον τῶν Λιβύων παρὰ Κίνυπα ποταμόν. ἐξελασθεὶς δὲ ἐνθεῦτεν τρίτῳ ἔτεϊ ὑπὸ Μακέων τε Λιβύων καὶ Καρχηδονίων ἀπίκετο ἐς Πελοπόννησον.", "st": "5.42"}, {"sp": "N", "t": "ἐνθαῦτα δέ οἱ Ἀντιχάρης ἀνὴρ Ἐλεώνιος συνεβούλευσε ἐκ τῶν Λαΐου χρησμῶν Ἡρακλείην τὴν ἐν Σικελίῃ κτίζειν, φὰς τὴν Ἔρυκος χώρην πᾶσαν εἶναι Ἡρακλειδέων αὐτοῦ Ἡρακλέος κτησαμένου. ὁ δὲ ἀκούσας ταῦτα ἐς Δελφοὺς οἴχετο χρησόμενος τῷ χρηστηρίῳ, εἰ αἱρέει ἐπ’ ἣν στέλλεται χώρην· ἡ δὲ Πυθίη οἱ χρᾷ αἱρήσειν. παραλαβὼν δὲ Δωριεὺς τὸν στόλον τὸν καὶ ἐς Λιβύην ἦγε, ἐκομίζετο παρὰ τὴν Ἰταλίην.", "st": "5.43"}, {"sp": "N", "t": "τὸν χρόνον δὲ τοῦτον, ὡς λέγουσι Συβαρῖται, σφέας τε αὐτοὺς καὶ Τῆλυν τὸν ἑωυτῶν βασιλέα ἐπὶ Κρότωνα μέλλειν στρατεύεσθαι, τοὺς δὲ Κροτωνιήτας περιδεέας γενομένους δεηθῆναι Δωριέος σφίσι τιμωρῆσαι καὶ τυχεῖν δεηθέντας· συστρατεύεσθαί τε δὴ ἐπὶ Σύβαριν Δωριέα καὶ συνελεῖν τὴν Σύβαριν. ταῦτα μέν νυν Συβαρῖται λέγουσι ποιῆσαι Δωριέα τε καὶ τοὺς μετ’ αὐτοῦ, Κροτωνιῆται δὲ οὐδένα σφίσι φασὶ ξεῖνον προσεπιλαβέσθαι τοῦ πρὸς Συβαρίτας πολέμου εἰ μὴ Καλλίην τῶν Ἰαμιδέων μάντιν Ἠλεῖον μοῦνον, καὶ τοῦτον τρόπῳ τοιῷδε· παρὰ Τήλυος τοῦ Συβαριτέων τυράννου ἀποδράντα ἀπικέσθαι παρὰ σφέας, ἐπείτε οἱ τὰ ἱρὰ οὐ προεχώρεε χρηστὰ θυομένῳ ἐπὶ Κρότωνα.", "st": "5.44"}, {"sp": "N", "t": "ταῦτα δὲ οὗτοι λέγουσι. μαρτύρια δὲ τούτων ἑκάτεροι ἀποδεικνύουσι τάδε, Συβαρῖται μὲν τέμενός τε καὶ νηὸν ἐόντα παρὰ τὸν ξηρὸν Κρᾶθιν, τὸν ἱδρύσασθαι συνελόντα τὴν πόλιν Δωριέα λέγουσι Ἀθηναίῃ ἐπωνύμῳ Κραθίῃ· τοῦτο δὲ αὐτοῦ Δωριέος τὸν θάνατον μαρτύριον μέγιστον ποιεῦνται, ὅτι παρὰ τὰ μεμαντευμένα ποιέων διεφθάρη· εἰ γὰρ δὴ μὴ παρέπρηξε μηδέν, ἐπ’ ὁ δὲ ἐστάλη ἐποίεε, εἷλε ἂν τὴν Ἐρυκίνην χώρην καὶ ἑλὼν κατέσχε, οὐδ’ ἂν αὐτός τε καὶ ἡ στρατιὴ διεφθάρη. οἱ δ’ αὖ Κροτωνιῆται ἀποδεικνῦσι Καλλίῃ μὲν τῷ Ἠλείῳ ἐξαίρετα ἐν γῇ τῇ Κροτωνιήτιδι πολλὰ δοθέντα, τὰ καὶ ἐς ἐμὲ ἔτι ἐνέμοντο οἱ Καλλίεω ἀπόγονοι, Δωριέι δὲ καὶ τοῖσι Δωριέος ἀπογόνοισι οὐδέν. καίτοι εἰ συνεπελάβετό γε τοῦ Συβαριτικοῦ πολέμου Δωριεύς, δοθῆναι ἄν οἱ πολλαπλήσια ἢ Καλλίῃ. ταῦτα μέν νυν ἑκάτεροι αὐτῶν μαρτύρια ἀποφαίνονται, καὶ πάρεστι, ὁκοτέροισί τις πείθεται αὐτῶν, τούτοισι προσχωρέειν.", "st": "5.45"}, {"sp": "N", "t": "συνέπλεον δὲ Δωριέι καὶ ἄλλοι συγκτίσται Σπαρτιητέων, Θεσσαλὸς καὶ Παραιβάτης καὶ Κελέης καὶ Εὐρυλέων· οἳ ἐπείτε ἀπίκοντο παντὶ στόλῳ ἐς τὴν Σικελίην, ἀπέθανον μάχῃ ἑσσωθέντες ὑπό τε Φοινίκων καὶ Ἐγεσταίων· μοῦνος δὲ Εὐρυλέων τῶν συγκτιστέων περιεγένετο τούτου τοῦ πάθεος. συλλαβὼν δὲ οὗτος τῆς στρατιῆς τοὺς περιγενομένους ἔσχε Μινώην τὴν Σελινουσίων ἀποικίην, καὶ συνελευθέρου Σελινουσίους τοῦ μουνάρχου Πειθαγόρεω· μετὰ δὲ ὡς τοῦτον κατεῖλε, αὐτὸς τυραννίδι ἐπεχείρησε Σελινοῦντος καὶ ἐμουνάρχησε χρόνον ἐπ’ ὀλίγον· οἱ γάρ μιν Σελινούσιοι ἐπαναστάντες ἀπέκτειναν καταφυγόντα ἐπὶ Διὸς ἀγοραίου βωμόν.", "st": "5.46"}, {"sp": "N", "t": "συνέσπετο δὲ Δωριέι καὶ συναπέθανε Φίλιππος ὁ Βουτακίδεω Κροτωνιήτης ἀνήρ, ὃς ἁρμοσάμενος Τήλυος τοῦ Συβαρίτεω θυγατέρα ἔφυγε ἐκ Κρότωνος, ψευσθεὶς δὲ τοῦ γάμου οἴχετο πλέων ἐς Κυρήνην, ἐκ ταύτης δὲ ὁρμώμενος συνέσπετο οἰκηίῃ τε τριήρεϊ καὶ οἰκηίῃ ἀνδρῶν δαπάνῃ, ἐών τε Ὀλυμπιονίκης καὶ κάλλιστος Ἑλλήνων τῶν κατ’ ἑωυτόν. διὰ δὲ τὸ ἑωυτοῦ κάλλος ἠνείκατο παρὰ Ἐγεσταίων τὰ οὐδεὶς ἄλλος· ἐπὶ γὰρ τοῦ τάφου αὐτοῦ ἡρώιον ἱδρυσάμενοι θυσίῃσι αὐτὸν ἱλάσκονται.", "st": "5.47"}, {"sp": "N", "t": "Δωριεὺς μέν νυν τρόπῳ τοιούτῳ ἐτελεύτησε· εἰ δὲ ἠνέσχετο βασιλευόμενος ὑπὸ Κλεομένεος καὶ κατέμενε ἐν Σπάρτῃ, ἐβασίλευσε ἂν Λακεδαίμονος· οὐ γάρ τινα πολλὸν χρόνον ἦρξε ὁ Κλεομένης, ἀλλ’ ἀπέθανε ἄπαις, θυγατέρα μούνην λιπών, τῇ οὔνομα ἦν Γοργώ.", "st": "5.48"}, {"sp": "N", "t": "ἀπικνέεται δὲ ὦν ὁ Ἀρισταγόρης ὁ Μιλήτου τύραννος ἐς τὴν Σπάρτην Κλεομένεος ἔχοντος τὴν ἀρχήν· τῷ δὴ ἐς λόγους ἤιε, ὡς Λακεδαιμόνιοι λέγουσι, ἔχων χάλκεον πίνακα ἐν τῷ γῆς ἁπάσης περίοδος ἐνετέτμητο καὶ θάλασσά τε πᾶσα καὶ ποταμοὶ πάντες. ἀπικνεόμενος δὲ ἐς λόγους ὁ Ἀρισταγόρης ἔλεγε πρὸς αὐτὸν τάδε. Κλεόμενες, σπουδὴν μὲν τὴν ἐμὴν μὴ θωμάσῃς τῆς ἐνθαῦτα ἀπίξιος· τὰ γὰρ κατήκοντα ἐστὶ τοιαῦτα· Ἰώνων παῖδας δούλους εἶναι ἀντ’ ἐλευθέρων ὄνειδος καὶ ἄλγος μέγιστον μὲν αὐτοῖσι ἡμῖν, ἔτι δὲ τῶν λοιπῶν ὑμῖν, ὅσῳ προέστατε τῆς Ἑλλάδος. νῦν ὦν πρὸς θεῶν τῶν Ἑλληνίων ῥύσασθε Ἴωνας ἐκ δουλοσύνης ἄνδρας ὁμαίμονας. εὐπετέως δὲ ὑμῖν ταῦτα οἷά τε χωρέειν ἐστί· οὔτε γὰρ οἱ βάρβαροι ἄλκιμοι εἰσί, ὑμεῖς τε τὰ ἐς τὸν πόλεμον ἐς τὰ μέγιστα ἀνήκετε ἀρετῆς πέρι, ἥ τε μάχη αὐτῶν ἐστὶ τοιήδε, τόξα καὶ αἰχμὴ βραχέα· ἀναξυρίδας δὲ ἔχοντες ἔρχονται ἐς τὰς μάχας καὶ κυρβασίας ἐπὶ τῇσι κεφαλῇσι. οὕτω εὐπετέες χειρωθῆναι εἰσί. ἔστι δὲ καὶ ἀγαθὰ τοῖσι τὴν ἤπειρον ἐκείνην νεμομένοισι ὅσα οὐδὲ τοῖσι συνάπασι ἄλλοισι, ἀπὸ χρυσοῦ ἀρξαμένοισι, ἄργυρος καὶ χαλκὸς καὶ ἐσθὴς ποικίλη καὶ ὑποζύγιά τε καὶ ἀνδράποδα· τὰ θυμῷ βουλόμενοι αὐτοὶ ἂν ἔχοιτε. κατοίκηνται δὲ ἀλλήλων ἐχόμενοι ὡς ἐγὼ φράσω, Ἰώνων μὲν τῶνδε οἵδε Λυδοί, οἰκέοντές τε χώρην ἀγαθὴν καὶ πολυαργυρώτατοι ἐόντες. δεικνὺς δὲ ἔλεγε ταῦτα ἐς τῆς γῆς τὴν περίοδον, τὴν ἐφέρετο ἐν τῷ πίνακι ἐντετμημένην. Λυδῶν δέ ἔφη λέγων ὁ Ἀρισταγόρης οἵδε ἔχονται Φρύγες οἱ πρὸς τὴν ἠῶ, πολυπροβατώτατοί τε ἐόντες πάντων τῶν ἐγὼ οἶδα καὶ πολυκαρπότατοι. Φρυγῶν δὲ ἔχονται Καππαδόκαι, τοὺς ἡμεῖς Συρίους καλέομεν. τούτοισι δὲ πρόσουροι Κίλικες, κατήκοντες ἐπὶ θάλασσαν τήνδε, ἐν τῇ ἥδε Κύπρος νῆσος κέεται· οἳ πεντακόσια τάλαντα βασιλέι τὸν ἐπέτειον φόρον ἐπιτελεῦσι. Κιλίκων δὲ τῶνδε ἔχονται Ἀρμένιοι οἵδε, καὶ οὗτοι ἐόντες πολυπρόβατοι, Ἀρμενίων δὲ Ματιηνοὶ χώρην τήνδε ἔχοντες. ἔχεται δὲ τούτων γῆ ἥδε Κισσίη, ἐν τῇ δὴ παρὰ ποταμὸν τόνδε Χοάσπην κείμενα ἐστὶ τὰ Σοῦσα ταῦτα, ἔνθα βασιλεύς τε μέγας δίαιταν ποιέεται, καὶ τῶν χρημάτων οἱ θησαυροὶ ἐνθαῦτα εἰσί· ἑλόντες δὲ ταύτην τὴν πόλιν θαρσέοντες ἤδη τῷ Διὶ πλούτου πέρι ἐρίζετε. ἀλλὰ περὶ μὲν χώρης ἄρα οὐ πολλῆς οὐδὲ οὕτω χρηστῆς καὶ οὔρων σμικρῶν χρεόν ἐστι ὑμέας μάχας ἀναβάλλεσθαι πρός τε Μεσσηνίους ἐόντας ἰσοπαλέας καὶ Ἀρκάδας τε καὶ Ἀργείους, τοῖσι οὔτε χρυσοῦ ἐχόμενον ἐστι οὐδὲν οὔτε ἀργύρου, τῶν πέρι καί τινα ἐνάγει προθυμίη μαχόμενον ἀποθνήσκειν· παρέχον δὲ τῆς Ἀσίης πάσης ἄρχειν εὐπετέως, ἄλλο τι αἱρήσεσθε; Ἀρισταγόρης μὲν ταῦτα ἔλεξε, Κλεομένης δὲ ἀμείβετο τοῖσιδε. ὦ ξεῖνε Μιλήσιε, ἀναβάλλομαί τοι ἐς τρίτην ἡμέρην ὑποκρινέεσθαι.", "st": "5.49"}, {"sp": "N", "t": "τότε μὲν ἐς τοσοῦτον ἤλασαν· ἐπείτε δὲ ἡ κυρίη ἡμέρη ἐγένετο τῆς ὑποκρίσιος καὶ ἦλθον ἐς τὸ συγκείμενον, εἴρετο ὁ Κλεομένης τὸν Ἀρισταγόρην ὁκοσέων ἡμερέων ἀπὸ θαλάσσης τῆς Ἰώνων ὁδὸς εἴη παρὰ βασιλέα. ὁ δὲ Ἀρισταγόρης τἆλλα ἐὼν σοφὸς καὶ διαβάλλων ἐκεῖνον εὖ ἐν τούτῳ ἐσφάλη· χρέον γάρ μιν μὴ λέγειν τὸ ἐόν, βουλόμενόν γε Σπαρτιήτας ἐξαγαγεῖν ἐς τὴν Ἀσίην, λέγει δ’ ὦν τριῶν μηνῶν φὰς εἶναι τὴν ἄνοδον. ὁ δὲ ὑπαρπάσας τὸν ἐπίλοιπον λόγον τὸν ὁ Ἀρισταγόρης ὥρμητο λέγειν περὶ τῆς ὁδοῦ, εἶπε ὦ ξεῖνε Μιλήσιε, ἀπαλλάσσεο ἐκ Σπάρτης πρὸ δύντος ἡλίου· οὐδένα γὰρ λόγον εὐεπέα λέγεις Λακεδαιμονίοισι, ἐθέλων σφέας ἀπὸ θαλάσσης τριῶν μηνῶν ὁδὸν ἀγαγεῖν.", "st": "5.50"}, {"sp": "N", "t": "ὁ μὲν Κλεομένης ταῦτα εἴπας ἤιε ἐς τὰ οἰκία, ὁ δὲ Ἀρισταγόρης λαβὼν ἱκετηρίην ἤιε ἐς τοῦ Κλεομένεος, ἐσελθὼν δὲ ἔσω ἅτε ἱκετεύων ἐπακοῦσαι ἐκέλευε τὸν Κλεομένεα ἀποπέμψαντα τὸ παιδίον· προσεστήκεε γὰρ δὴ τῷ Κλεομένεϊ ἡ θυγάτηρ, τῇ οὔνομα ἦν Γοργώ· τοῦτο δέ οἱ καὶ μοῦνον τέκνον ἐτύγχανε ἐὸν ἐτέων ὀκτὼ ἢ ἐννέα ἡλικίην. Κλεομένης δὲ λέγειν μιν ἐκέλευε τὰ βούλεται μηδὲ ἐπισχεῖν τοῦ παιδίου εἵνεκα. ἐνθαῦτα δὴ ὁ Ἀρισταγόρης ἄρχετο ἐκ δέκα ταλάντων ὑπισχνεόμενος, ἤν οἱ ἐπιτελέσῃ τῶν ἐδέετο. ἀνανεύοντος δὲ τοῦ Κλεομένεος προέβαινε τοῖσι χρήμασι ὑπερβάλλων ὁ Ἀρισταγόρης, ἐς οὗ πεντήκοντά τε τάλαντα ὑπεδέδεκτο καὶ τὸ παιδίον ηὐδάξατο πάτερ, διαφθερέει σε ὁ ξεῖνος, ἢν μὴ ἀποστὰς ἴῃς. ὅ τε δὴ Κλεομένης ἡσθεὶς τοῦ παιδίου τῇ παραινέσι ἤιε ἐς ἕτερον οἴκημα, καὶ ὁ Ἀρισταγόρης ἀπαλλάσσετο τὸ παράπαν ἐκ τῆς Σπάρτης, οὐδέ οἱ ἐξεγένετο ἐπὶ πλέον ἔτι σημῆναι περὶ τῆς ἀνόδου τῆς παρὰ βασιλέα.", "st": "5.51"}, {"sp": "N", "t": "ἔχει γὰρ ἀμφὶ τῇ ὁδῷ ταύτῃ ὧδε· σταθμοί τε πανταχῇ εἰσι βασιλήιοι καὶ καταλύσιες κάλλισται, διὰ οἰκεομένης τε ἡ ὁδὸς ἅπασα καὶ ἀσφαλέος. διὰ μέν γε Λυδίης καὶ Φρυγίης σταθμοὶ τείνοντες εἴκοσι εἰσί, παρασάγγαι δὲ τέσσερες καὶ ἐνενήκοντα καὶ ἥμισυ. ἐκδέκεται δὲ ἐκ τῆς Φρυγίης ὁ Ἅλυς ποταμός, ἐπ’ ᾧ πύλαι τε ἔπεισι, τὰς διεξελάσαι πᾶσα ἀνάγκη καὶ οὕτω διεκπερᾶν τὸν ποταμόν, καὶ φυλακτήριον μέγα ἐπ’ αὐτῷ. διαβάντι δὲ ἐς τὴν Καππαδοκίην καὶ ταύτῃ πορευομένῳ μέχρι οὔρων τῶν Κιλικίων σταθμοὶ δυῶν δέοντες εἰσὶ τριήκοντα, παρασάγγαι δὲ τέσσερες καὶ ἑκατόν. ἐπὶ δὲ τοῖσι τούτων οὔροισι διξάς τε πύλας διεξελᾷς καὶ διξὰ φυλακτήρια παραμείψεαι. ταῦτα δὲ διεξελάσαντι καὶ διὰ τῆς Κιλικίης ὁδὸν ποιευμένῳ τρεῖς εἱσι σταθμοί, παρασάγγαι δὲ πεντεκαίδεκα καὶ ἥμισυ. οὖρος δὲ Κιλικίης καὶ τῆς Ἀρμενίης ἐστὶ ποταμὸς νηυσιπέρητος, τῷ οὔνομα Εὐφρήτης. ἐν δὲ τῇ Ἀρμενίῃ σταθμοὶ μὲν εἰσὶ καταγωγέων πεντεκαίδεκα, παρασάγγαι δὲ ἓξ καὶ πεντήκοντα καὶ ἥμισυ, καὶ φυλακτήριον ἐν αὐτοῖσι. ἐκ δὲ ταύτης τῆς Ἀρμενίης ἐς βάλλοντι ἐς τὴν Ματιηνὴν γῆν σταθμοί εἰσι τέσσερες καὶ τριήκοντα, παρασάγγαι δὲ ἑπτὰ καὶ τριήκοντα καὶ ἑκατόν. ποταμοὶ δὲ νηυσιπέρητοι τέσσερες διὰ ταύτης ῥέουσι, τοὺς πᾶσα ἀνάγκη διαπορθμεῦσαι ἐστί, πρῶτος μὲν Τίγρης, μετὰ δὲ δεύτερός τε καὶ τρίτος ὡυτὸς ὀνομαζόμενος, οὐκ ὡυτὸς ἐὼν ποταμὸς οὐδὲ ἐκ τοῦ αὐτοῦ ῥέων· ὁ μὲν γὰρ πρότερον αὐτῶν καταλεχθεὶς ἐξ Ἀρμενίων ῥέει, ὁ δ’ ὕστερον ἐκ Ματιηνῶν· ὁ δὲ τέταρτος τῶν ποταμῶν οὔνομα ἔχει Γύνδης, τὸν Κῦρος διέλαβε κοτὲ ἐς διώρυχας ἑξήκοντα καὶ τριηκοσίας. ἐκ δὲ ταύτης ἐς τὴν Κισσίην χώρην μεταβαίνοντι ἕνδεκα σταθμοί, παρασάγγαι δὲ δύο καὶ τεσσεράκοντα καὶ ἥμισυ ἐστὶ ἐπὶ ποταμὸν Χοάσπην, ἐόντα καὶ τοῦτον νηυσιπέρητον· ἐπ’ ᾧ Σοῦσα πόλις πεπόλισται.", "st": "5.52"}, {"sp": "N", "t": "οὗτοι οἱ πάντες σταθμοί εἰσι ἕνδεκα καὶ ἑκατόν. καταγωγαὶ μέν νυν σταθμῶν τοσαῦται εἰσὶ ἐκ Σαρδίων ἐς Σοῦσα ἀναβαίνοντι. εἰ δὲ ὀρθῶς μεμέτρηται ἡ ὁδὸς ἡ βασιληίη τοῖσι παρασάγγῃσι καὶ ὁ παρασάγγης δύναται τριήκοντα στάδια, ὥσπερ οὗτός γε δύναται ταῦτα, ἐκ Σαρδίων στάδια ἐστὶ ἐς τὰ βασιλήια τὰ Μεμνόνια καλεόμενα πεντακόσια καὶ τρισχίλια καὶ μύρια, παρασαγγέων ἐόντων πεντήκοντα καὶ τετρακοσίων. πεντήκοντα δὲ καὶ ἑκατὸν στάδια ἐπ’ ἡμέρῃ ἑκάστῃ διεξιοῦσι ἀναισιμοῦνται ἡμέραι ἀπαρτὶ ἐνενήκοντα.", "st": "5.53"}, {"sp": "N", "t": "οὕτω τῷ Μιλησίῳ Ἀρισταγόρῃ εἴπαντι πρὸς Κλεομένεα τὸν Λακεδαιμόνιον εἶναι τριῶν μηνῶν τὴν ἄνοδον τὴν παρὰ βασιλέα ὀρθῶς εἴρητο. εἰ δέ τις τὸ ἀτρεκέστερον τούτων ἔτι δίζηται, ἐγὼ καὶ τοῦτο σημανέω· τὴν γὰρ ἐξ Ἐφέσου ἐς Σάρδις ὁδὸν δεῖ προσλογίσασθαι ταύτῃ. καὶ δὴ λέγω σταδίους εἶναι τοὺς πάντας ἀπὸ θαλάσσης τῆς Ἑλληνικῆς μέχρι Σούσων (τοῦτο γὰρ Μεμνόνειον ἄστυ καλέεται), τεσσεράκοντα καὶ τετρακισχιλίους καὶ μυρίους· οἱ γὰρ ἐξ Ἑφέσου ἐς Σάρδις εἰσὶ τεσσεράκοντα καὶ πεντακόσιοι στάδιοι, καὶ οὕτω τρισὶ ἡμέρῃσι μηκύνεται ἡ τρίμηνος ὁδός.", "st": "5.54"}, {"sp": "N", "t": "ἀπελαυνόμενος δὲ ὁ Ἀρισταγόρης ἐκ τῆς Σπάρτης ἤιε ἐς τὰς Ἀθήνας γενομένας τυράννων ὧδε ἐλευθέρας. ἐπεὶ Ἵππαρχον τὸν Πεισιστράτου, Ἱππίεω δὲ τοῦ τυράννου ἀδελφεόν, ἰδόντα ὄψιν ἐνυπνίου τῷ ἑωυτοῦ πάθεϊ ἐναργεστάτην κτείνουσι Ἀριστογείτων καὶ Ἁρμόδιος, γένος ἐόντες τὰ ἀνέκαθεν Γεφυραῖοι, μετὰ ταῦτα ἐτυραννεύοντο Ἀθηναῖοι ἐπ’ ἔτεα τέσσερα οὐδὲν ἧσσον ἀλλὰ καὶ μᾶλλον ἢ πρὸ τοῦ.", "st": "5.55"}, {"sp": "N", "t": "ἡ μέν νυν ὄψις τοῦ Ἱππάρχου ἐνυπνίου ἦν ἥδε· ἐν τῇ προτέρῃ νυκτὶ τῶν Παναθηναίων ἐδόκεε ὁ Ἵππαρχος ἄνδρα οἱ ἐπιστάντα μέγαν καὶ εὐειδέα αἰνίσσεσθαι τάδε τὰ ἔπεα.", "st": "5.56"}, {"sp": "N", "t": "τλῆθι λέων ἄτλητα παθὼν τετληότι θυμῷ·<br>οὐδεὶς ἀνθρώπων ἀδικῶν τίσιν οὐκ ἀποτίσει.", "st": "5.56b"}, {"sp": "N", "t": "ταῦτα δέ, ὡς ἡμέρη ἐγένετο τάχιστα, φανερὸς ἦν ὑπερτιθέμενος ὀνειροπόλοισι· μετὰ δὲ ἀπειπάμενος τὴν ὄψιν ἔπεμπε τὴν πομπήν, ἐν τῇ δὴ τελευτᾷ.", "st": "5.56.2"}, {"sp": "N", "t": "οἱ δὲ Γεφυραῖοι, τῶν ἦσαν οἱ φονέες οἱ Ἱππάρχου, ὡς μὲν αὐτοὶ λέγουσι, ἐγεγόνεσαν ἐξ Ἐρετρίης τὴν ἀρχήν, ὡς δὲ ἐγὼ ἀναπυνθανόμενος εὑρίσκω, ἦσαν Φοίνικες τῶν σὺν Κάδμῳ ἀπικομένων Φοινίκων ἐς γῆν τὴν νῦν Βοιωτίην καλεομένην, οἴκεον δὲ τῆς χώρης ταύτης ἀπολαχόντες τὴν Ταναγρικὴν μοῖραν. ἐνθεῦτεν δὲ Καδμείων πρότερον ἐξαναστάντων ὑπ’ Ἀργείων, οἱ Γεφυραῖοι οὗτοι δεύτερα ὑπὸ Βοιωτῶν ἐξαναστάντες ἐτράποντο ἐπ’ Ἀθηνέων. Ἀθηναῖοι δὲ σφέας ἐπὶ ῥητοῖσι ἐδέξαντο σφέων αὐτῶν εἶναι πολιήτας, πολλῶν τεῶν καὶ οὐκ ἀξιαπηγήτων ἐπιτάξαντες ἔργεσθαι.", "st": "5.57"}, {"sp": "N", "t": "οἱ δὲ Φοίνικες οὗτοι οἱ σὺν Κάδμῳ ἀπικόμενοι, τῶν ἦσαν οἱ Γεφυραῖοι, ἄλλα τε πολλὰ οἰκήσαντες ταύτην τὴν χώρην ἐσήγαγον διδασκάλια ἐς τοὺς Ἕλληνας καὶ δὴ καὶ γράμματα, οὐκ ἐόντα πρὶν Ἕλλησι ὡς ἐμοὶ δοκέειν, πρῶτα μὲν τοῖσι καὶ ἅπαντες χρέωνται Φοίνικες· μετὰ δὲ χρόνου προβαίνοντος ἅμα τῇ φωνῇ μετέβαλλον καὶ τὸν ῥυθμὸν τῶν γραμμάτων. περιοίκεον δὲ σφέας τὰ πολλὰ τῶν χώρων τοῦτον τὸν χρόνον Ἑλλήνων Ἴωνες, οἳ παραλαβόντες διδαχῇ παρὰ τῶν Φοινίκων τὰ γράμματα, μεταρρυθμίσαντες σφέων ὀλίγα ἐχρέωντο, χρεώμενοι δὲ ἐφάτισαν, ὥσπερ καὶ τὸ δίκαιον ἔφερε, ἐσαγαγόντων Φοινίκων ἐς τὴν Ἑλλάδα, Φοινικήια κεκλῆσθαι. καὶ τὰς βύβλους διφθέρας καλέουσι ἀπὸ τοῦ παλαιοῦ οἱ Ἴωνες, ὅτι κοτὲ ἐν σπάνι βύβλων ἐχρέωντο διφθέρῃσι αἰγέῃσί τε καὶ οἰέῃσι· ἔτι δὲ καὶ τὸ κατ’ ἐμὲ πολλοὶ τῶν βαρβάρων ἐς τοιαύτας διφθέρας γράφουσι.", "st": "5.58"}, {"sp": "N", "t": "εἶδον δὲ καὶ αὐτὸς Καδμήια γράμματα ἐν τῷ ἱρῷ τοῦ Ἀπόλλωνος τοῦ Ἰσμηνίου ἐν Θήβῃσι τῇσι Βοιωτῶν, ἐπὶ τρίποσι τισὶ ἐγκεκολαμμένα, τὰ πολλὰ ὅμοια ἐόντα τοῖσι Ἰωνικοῖσι. ὁ μὲν δὴ εἷς τῶν τριπόδων ἐπίγραμμα ἔχει", "st": "5.59"}, {"sp": "N", "t": "ἀμφιτρύων μ’ ἀνέθηκ’ ἐνάρων ἀπὸ Τηλεβοάων.<br>ταῦτα ἡλικίην εἴη ἂν κατὰ Λάιον τὸν Λαβδάκου τοῦ Πολυδώρου τοῦ Κάδμου.", "st": "5.59b"}, {"sp": "N", "t": "ἕτερος δὲ τρίπους ἐν ἑξαμέτρῳ τόνῳ λέγει", "st": "5.60"}, {"sp": "N", "t": "Σκαῖος πυγμαχέων με ἑκηβόλῳ Ἀπόλλωνι<br>νικήσας ἀνέθηκε τεῒν περικαλλὲς ἄγαλμα.", "st": "5.60b"}, {"sp": "N", "t": "Σκαῖος δ’ ἂν εἴη ὁ Ἱπποκόωντος, εἰ δὴ οὗτός γε ἐστὶ ὁ ἀναθεὶς καὶ μὴ ἄλλος τὠυτὸ οὔνομα ἔχων τῷ Ἱπποκόωντος, ἡλικίην κατὰ Οἰδίπουν τὸν Λαΐου.", "st": "5.60c"}, {"sp": "N", "t": "τρίτος δὲ τρίπους λέγει καὶ οὗτος ἐν ἑξαμέτρῳ", "st": "5.61"}, {"sp": "N", "t": "Λαοδάμας τρίποδ’ αὐτὸς ἐυσκόπῳ Ἀπόλλωνι<br>μουναρχέων ἀνέθηκε τεῒν περικαλλὲς ἄγαλμα.", "st": "5.61b"}, {"sp": "N", "t": "ἐπὶ τούτου δὴ τοῦ Λαοδάμαντος τοῦ Ἐτεοκλέος μουναρχέοντος ἐξανιστέαται Καδμεῖοι ὑπ’ Ἀργείων καὶ τρέπονται ἐς τοὺς Ἐγχελέας. οἱ δὲ Γεφυραῖοι ὑπολειφθέντες ὕστερον ὑπὸ Βοιωτῶν ἀναχωρέουσι ἐς Ἀθήνας· καί σφι ἱρά ἐστι ἐν Ἀθήνῃσι ἱδρυμένα, τῶν οὐδὲν μέτα τοῖσι λοιποῖσι Ἀθηναίοισι, ἄλλα τε κεχωρισμένα τῶν ἄλλων ἱρῶν καὶ δὴ καὶ Ἀχαιίης Δήμητρος ἱρόν τε καὶ ὄργια.", "st": "5.61.2"}, {"sp": "N", "t": "ἡ μὲν δὴ ὄψις τοῦ Ἱππάρχου ἐνυπνίου καὶ οἱ Γεφυραῖοι ὅθεν ἐγεγόνεσαν, τῶν ἦσαν οἱ Ἱππάρχου φονέες, ἀπήγηταί μοι· δεῖ δὲ πρὸς τούτοισι ἔτι ἀναλαβεῖν τὸν κατ’ ἀρχὰς ἤια λέξων λόγον, ὡς τυράννων ἐλευθερώθησαν Ἀθηναῖοι. Ἱππίεω τυραννεύοντος καὶ ἐμπικραινομένου Ἀθηναίοισι διὰ τὸν Ἱππάρχου θάνατον, Ἀλκμεωνίδαι γένος ἐόντες Ἀθηναῖοι καὶ φεύγοντες Πεισιστρατίδας, ἐπείτε σφι ἅμα τοῖσι ἄλλοισι Ἀθηναίων φυγάσι πειρωμένοισι κατὰ τὸ ἰσχυρὸν οὐ προεχώρεε κάτοδος, ἀλλὰ προσέπταιον μεγάλως πειρώμενοι κατιέναι τε καὶ ἐλευθεροῦν τὰς Ἀθήνας, Λειψύδριον τὸ ὑπὲρ Παιονίης τειχίσαντες, ἐνθαῦτα οἱ Ἀλκμεωνίδαι πᾶν ἐπὶ τοῖσι Πεισιστρατίδῃσι μηχανώμενοι παρ’ Ἀμφικτυόνων τὸν νηὸν μισθοῦνται τὸν ἐν Δελφοῖσι, τὸν νῦν ἐόντα τότε δὲ οὔκω, τοῦτον ἐξοικοδομῆσαι. οἷα δὲ χρημάτων εὖ ἥκοντες καὶ ἐόντες ἄνδρες δόκιμοι ἀνέκαθεν ἔτι, τόν τε νηὸν ἐξεργάσαντο τοῦ παραδείγματος κάλλιον τά τε ἄλλα καὶ συγκειμένου σφι πωρίνου λίθου ποιέειν τὸν νηόν, Παρίου τὰ ἔμπροσθε αὐτοῦ ἐξεποίησαν.", "st": "5.62"}, {"sp": "N", "t": "ὡς ὦν δὴ οἱ Ἀθηναῖοι λέγουσι, οὗτοι οἱ ἄνδρες ἐν Δελφοῖσι κατήμενοι ἀνέπειθον τὴν Πυθίην χρήμασι, ὅκως ἔλθοιεν Σπαρτιητέων ἄνδρες εἴτε ἰδίῳ στόλῳ εἴτε δημοσίῳ χρησόμενοι, προφέρειν σφι τὰς Ἀθήνας ἐλευθεροῦν. Λακεδαιμόνιοι δέ, ὥς σφι αἰεὶ τὠυτὸ πρόφαντον ἐγίνετο, πέμπουσι Ἀγχιμόλιον τὸν Ἀστέρος, ἐόντα τῶν ἀστῶν ἄνδρα δόκιμον, σὺν στρατῷ ἐξελῶντα Πεισιστρατίδας ἐξ Ἀθηνέων ὅμως καὶ ξεινίους σφι ἐόντας τὰ μάλιστα· τὰ γὰρ τοῦ θεοῦ πρεσβύτερα ἐποιεῦντο ἢ τὰ τῶν ἀνδρῶν· πέμπουσι δὲ τούτους κατὰ θάλασσαν πλοίοισι. ὃ μὲν δὴ προσσχὼν ἐς Φάληρον τὴν στρατιὴν ἀπέβησε, οἱ δὲ Πεισιστρατίδαι προπυνθανόμενοι ταῦτα ἐπεκαλέοντο ἐκ Θεσσαλίης ἐπικουρίην· ἐπεποίητο γάρ σφι συμμαχίη πρὸς αὐτούς. Θεσσαλοὶ δέ σφι δεομένοισι ἀπέπεμψαν κοινῇ γνώμῃ χρεώμενοι χιλίην τε ἵππον καὶ τὸν βασιλέα τὸν σφέτερον Κινέην ἄνδρα Κονιαῖον· τοὺς ἐπείτε ἔσχον συμμάχους οἱ Πεισιστρατίδαι, ἐμηχανῶντο τοιάδε· κείραντες τῶν Φαληρέων τὸ πεδίον καὶ ἱππάσιμον ποιήσαντες τοῦτον τὸν χῶρον ἐπῆκαν τῷ στρατοπέδῳ τὴν ἵππον· ἐμπεσοῦσα δὲ διέφθειρε ἄλλους τε πολλοὺς τῶν Λακεδαιμονίων καὶ δὴ καὶ τὸν Ἀγχιμόλιον· τοὺς δὲ περιγενομένους αὐτῶν ἐς τὰς νέας κατεῖρξαν. ὁ μὲν δὴ πρῶτος στόλος ἐκ Λακεδαίμονος οὕτω ἀπήλλαξε, καὶ Ἀγχιμολίου εἰσὶ ταφαὶ τῆς Ἀττικῆς Ἀλωπεκῆσι, ἀγχοῦ τοῦ Ἡρακλείου τοῦ ἐν Κυνοσάργεϊ.", "st": "5.63"}, {"sp": "N", "t": "μετὰ δὲ Λακεδαιμόνιοι μέζω στόλον στείλαντες ἀπέπεμψαν ἐπὶ τὰς Ἀθήνας, στρατηγὸν τῆς στρατιῆς ἀποδέξαντες βασιλέα Κλεομένεα τὸν Ἀναξανδρίδεω, οὐκέτι κατὰ θάλασσαν στείλαντες ἀλλὰ κατ’ ἤπειρον· τοῖσι ἐσβαλοῦσι ἐς τὴν Ἀττικὴν χώρην ἡ τῶν Θεσσαλῶν ἵππος πρώτη προσέμιξε καὶ οὐ μετὰ πολλὸν ἐτράπετο, καὶ σφεων ἔπεσον ὑπὲρ τεσσεράκοντα ἄνδρας· οἱ δὲ περιγενόμενοι ἀπαλλάσσοντο ὡς εἶχον εὐθὺς ἐπὶ Θεσσαλίης. Κλεομένης δὲ ἀπικόμενος ἐς τὸ ἄστυ ἅμα Ἀθηναίων τοῖσι βουλομένοισι εἶναι ἐλευθέροισι ἐπολιόρκεε τοὺς τυράννους ἀπεργμένους ἐν τῷ Πελασγικῷ τείχεϊ.", "st": "5.64"}, {"sp": "N", "t": "καὶ οὐδέν τι πάντως ἂν ἐξεῖλον Πεισιστρατίδας οἱ Λακεδαιμόνιοι· οὔτε γὰρ ἐπέδρην ἐπενόεον ποιήσασθαι, οἵ τε Πεισιστρατίδαι σίτοισι καὶ ποτοῖσι εὖ παρεσκευάδατο, πολιορκήσαντές τε ἂν ἡμέρας ὀλίγας ἀπαλλάσσοντο ἐς τὴν Σπάρτην. νῦν δὲ συντυχίη τοῖσι μὲν κακὴ ἐπεγένετο, τοῖσι δὲ ἡ αὐτὴ αὕτη σύμμαχος· ὑπεκτιθέμενοι γὰρ ἔξω τῆς χώρης οἱ παῖδες τῶν Πεισιστρατιδέων ἥλωσαν. τοῦτο δὲ ὡς ἐγένετο, πάντα αὐτῶν τὰ πρήγματα συνετετάρακτο, παρέστησαν δὲ ἐπὶ μισθῷ τοῖσι τέκνοισι, ἐπ’ οἷσι ἐβούλοντο οἱ Ἀθηναῖοι, ὥστε ἐν πέντε ἡμέρῃσι ἐκχωρῆσαι ἐκ τῆς Ἀττικῆς. μετὰ δὲ ἐξεχώρησαν ἐς Σίγειον τὸ ἐπὶ τῷ Σκαμάνδρῳ, ἄρξαντες μὲν Ἀθηναίων ἐπ’ ἔτεα ἕξ τε καὶ τριήκοντα, ἐόντες δὲ καὶ οὗτοι ἀνέκαθεν Πύλιοί τε καὶ Νηλεῖδαι, ἐκ τῶν αὐτῶν γεγονότες καὶ οἱ ἀμφὶ Κόδρον τε καὶ Μέλανθον, οἳ πρότερον ἐπήλυδες ἐόντες ἐγένοντο Ἀθηναίων βασιλέες. ἐπὶ τούτου δὲ καὶ τὠυτὸ οὔνομα ἀπεμνημόνευσε Ἱπποκράτης τῷ παιδὶ θέσθαι τὸν Πεισίστρατον, ἐπὶ τοῦ Νέστορος Πεισιστράτου ποιεύμενος τὴν ἐπωνυμίην.", "st": "5.65"}, {"sp": "N", "t": "οὕτω μὲν Ἀθηναῖοι τυράννων ἀπαλλάχθησαν· ὅσα δὲ ἐλευθερωθέντες ἔρξαν ἢ ἔπαθον ἀξιόχρεα ἀπηγήσιος, πρὶν ἢ Ἰωνίην τε ἀποστῆναι ἀπὸ Δαρείου καὶ Ἀρισταγόρεα τὸν Μιλήσιον ἀπικόμενον ἐς Ἀθήνας χρηίσαι σφέων βοηθέειν, ταῦτα πρῶτα φράσω.", "st": "5.65.5"}, {"sp": "N", "t": "Ἀθῆναι, ἐοῦσαι καὶ πρὶν μεγάλαι, τότε ἀπαλλαχθεῖσαι τυράννων ἐγίνοντο μέζονες· ἐν δὲ αὐτῇσι δύο ἄνδρες ἐδυνάστευον, Κλεισθένης τε ἀνὴρ Ἀλκμεωνίδης, ὅς περ δὴ λόγον ἔχει τὴν Πυθίην ἀναπεῖσαι, καὶ Ἰσαγόρης Τισάνδρου οἰκίης μὲν ἐὼν δοκίμου, ἀτὰρ τὰ ἀνέκαθεν οὐκ ἔχω φράσαι· θύουσι δὲ οἱ συγγενέες αὐτοῦ Διὶ Καρίῳ. οὗτοι οἱ ἄνδρες ἐστασίασαν περὶ δυνάμιος, ἑσσούμενος δὲ ὁ Κλεισθένης τὸν δῆμον προσεταιρίζεται. μετὰ δὲ τετραφύλους ἐόντας Ἀθηναίους δεκαφύλους ἐποίησε, τῶν Ἴωνος παίδων Γελέοντος καὶ Αἰγικόρεος καὶ Ἀργάδεω καὶ Ὅπλητος ἀπαλλάξας τὰς ἐπωνυμίας, ἐξευρὼν δὲ ἑτέρων ἡρώων ἐπωνυμίας ἐπιχωρίων, πάρεξ Αἴαντος· τοῦτον δὲ ἅτε ἀστυγείτονα καὶ σύμμαχον, ξεῖνον ἐόντα προσέθετο.", "st": "5.66"}, {"sp": "N", "t": "ταῦτα δέ, δοκέειν ἐμοί, ἐμιμέετο ὁ Κλεισθένης οὗτος τὸν ἑωυτοῦ μητροπάτορα Κλεισθένεα τὸν Σικυῶνος τύραννον. Κλεισθένης γὰρ Ἀργείοισι πολεμήσας τοῦτο μὲν ῥαψῳδοὺς ἔπαυσε ἐν Σικυῶνι ἀγωνίζεσθαι τῶν Ὁμηρείων ἐπέων εἵνεκα, ὅτι Ἀργεῖοί τε καὶ Ἄργος τὰ πολλὰ πάντα ὑμνέαται· τοῦτο δέ, ἡρώιον γὰρ ἦν καὶ ἔστι ἐν αὐτῇ τῇ ἀγορῇ τῶν Σικυωνίων Ἀδρήστου τοῦ Ταλαοῦ, τοῦτον ἐπεθύμησε ὁ Κλεισθένης ἐόντα Ἀργεῖον ἐκβαλεῖν ἐκ τῆς χώρης. ἐλθὼν δὲ ἐς Δελφοὺς ἐχρηστηριάζετο εἰ ἐκβάλοι τὸν Ἄδρηστον· ἡ δὲ Πυθίη οἱ χρᾷ φᾶσα Ἄδρηστον μὲν εἶναι Σικυωνίων βασιλέα, κεῖνον δὲ λευστῆρα. ἐπεὶ δὲ ὁ θεὸς τοῦτό γε οὐ παρεδίδου, ἀπελθὼν ὀπίσω ἐφρόντιζε μηχανὴν τῇ αὐτὸς ὁ Ἄδρηστος ἀπαλλάξεται. ὡς δέ οἱ ἐξευρῆσθαι ἐδόκεε, πέμψας ἐς Θήβας τὰς Βοιωτίας ἔφη θέλειν ἐπαγαγέσθαι Μελάνιππον τὸν Ἀστακοῦ· οἱ δὲ Θηβαῖοι ἔδοσαν. ἐπαγαγόμενος δὲ ὁ Κλεισθένης τὸν Μελάνιππον τέμενός οἱ ἀπέδεξε ἐν αὐτῷ τῷ πρυτανηίῳ καί μιν ἵδρυσε ἐνθαῦτα ἐν τῷ ἰσχυροτάτῳ. ἐπηγάγετο δὲ τὸν Μελάνιππον ὁ Κλεισθένης (καὶ γὰρ τοῦτο δεῖ ἀπηγήσασθαι) ὡς ἔχθιστον ἐόντα Ἀδρήστῳ, ὃς τόν τε ἀδελφεόν οἱ Μηκιστέα ἀπεκτόνεε καὶ τὸν γαμβρὸν Τυδέα. ἐπείτε δέ οἱ τὸ τέμενος ἀπέδεξε, θυσίας τε καὶ ὁρτὰς Ἀδρήστου ἀπελόμενος ἔδωκε τῷ Μελανίππῳ. οἱ δὲ Σικυώνιοι ἐώθεσαν μεγαλωστὶ κάρτα τιμᾶν τὸν Ἄδρηστον· ἡ γὰρ χώρη ἦν αὕτη Πολύβου, ὁ δὲ Ἄδρηστος ἦν Πολύβου θυγατριδέος, ἄπαις δὲ Πόλυβος τελευτῶν διδοῖ Ἀδρήστῳ τὴν ἀρχήν. τά τε δὴ ἄλλα οἱ Σικυώνιοι ἐτίμων τὸν Ἄδρηστον καὶ δὴ πρὸς τὰ πάθεα αὐτοῦ τραγικοῖσι χοροῖσι ἐγέραιρον, τὸν μὲν Διόνυσον οὐ τιμῶντες, τὸν δὲ Ἄδρηστον. Κλεισθένης δὲ χοροὺς μὲν τῷ Διονύσῳ ἀπέδωκε, τὴν δὲ ἄλλην θυσίην Μελανίππῳ.", "st": "5.67"}, {"sp": "N", "t": "ταῦτα μὲν ἐς Ἄδρηστόν οἱ ἐπεποίητο, φυλὰς δὲ τὰς Δωριέων, ἵνα δὴ μὴ αἱ αὐταὶ ἔωσι τοῖσι Σικυωνίοισι καὶ τοῖσι Ἀργείοισι, μετέβαλε ἐς ἄλλα οὐνόματα. ἔνθα καὶ πλεῖστον κατεγέλασε τῶν Σικυωνίων· ἐπὶ γὰρ ὑός τε καὶ ὄνου τὰς ἐπωνυμίας μετατιθεὶς αὐτὰ τὰ τελευταῖα ἐπέθηκε, πλὴν τῆς ἑωυτοῦ φυλῆς· ταύτῃ δὲ τὸ οὔνομα ἀπὸ τῆς ἑωυτοῦ ἀρχῆς ἔθετο. οὗτοι μὲν δὴ Ἀρχέλαοι ἐκαλέοντο, ἕτεροι δὲ Ὑᾶται, ἄλλοι δὲ Ὀνεᾶται, ἕτεροι δὲ Χοιρεᾶται. τούτοισι τοῖσι οὐνόμασι τῶν φυλέων ἐχρέωντο οἱ Σικυώνιοι καὶ ἐπὶ Κλεισθένεος ἄρχοντος καὶ ἐκείνου τεθνεῶτος ἔτι ἐπ’ ἔτεα ἑξήκοντα· μετέπειτα μέντοι λόγον σφίσι δόντες μετέβαλον ἐς τοὺς Ὑλλέας καὶ Παμφύλους καὶ Δυμανάτας, τετάρτους δὲ αὐτοῖσι προσέθεντο ἐπὶ τοῦ Ἀδρήστου παιδὸς Αἰγιαλέος τὴν ἐπωνυμίην ποιεύμενοι κεκλῆσθαι Αἰγιαλέας.", "st": "5.68"}, {"sp": "N", "t": "ταῦτα μέν νυν ὁ Σικυώνιος Κλεισθένης ἐπεποιήκεε· ὁ δὲ δὴ Ἀθηναῖος Κλεισθένης ἐὼν τοῦ Σικυωνίου τούτου θυγατριδέος καὶ τὸ οὔνομα ἐπὶ τούτου ἔχων, δοκέειν ἐμοὶ καὶ οὗτος ὑπεριδὼν Ἴωνας, ἵνα μὴ σφίσι αἱ αὐταὶ ἔωσι φυλαὶ καὶ Ἴωσι, τὸν ὁμώνυμον Κλεισθένεα ἐμιμήσατο. ὡς γὰρ δὴ τὸν Ἀθηναίων δῆμον πρότερον ἀπωσμένον τότε πάντων πρὸς τὴν ἑωυτοῦ μοῖραν προσεθήκατο, τὰς φυλὰς μετωνόμασε καὶ ἐποίησε πλεῦνας ἐξ ἐλασσόνων· δέκα τε δὴ φυλάρχους ἀντὶ τεσσέρων ἐποίησε, δέκαχα δὲ καὶ τοὺς δήμους κατένειμε ἐς τὰς φυλάς· ἦν τε τὸν δῆμον προσθέμενος πολλῷ κατύπερθε τῶν ἀντιστασιωτέων.", "st": "5.69"}, {"sp": "N", "t": "ἐν τῷ μέρεϊ δὲ ἑσσούμενος ὁ Ἰσαγόρης ἀντιτεχνᾶται τάδε· ἐπικαλέεται Κλεομένεα τὸν Λακεδαιμόνιον γενόμενον ἑωυτῷ ξεῖνον ἀπὸ τῆς Πεισιστρατιδέων πολιορκίης· τὸν δὲ Κλεομένεα εἶχε αἰτίη φοιτᾶν παρὰ τοῦ Ἰσαγόρεω τὴν γυναῖκα. τὰ μὲν δὴ πρῶτα πέμπων ὁ Κλεομένης ἐς τὰς Ἀθήνας κήρυκα ἐξέβαλλε Κλεισθένεα καὶ μετ’ αὐτοῦ ἄλλους πολλοὺς Ἀθηναίων, τοὺς ἐναγέας ἐπιλέγων· ταῦτα δὲ πέμπων ἔλεγε ἐκ διδαχῆς τοῦ Ἰσαγόρεω. οἱ μὲν γὰρ Ἀλκμεωνίδαι καὶ οἱ συστασιῶται αὐτῶν εἶχον αἰτίην τοῦ φόνου τούτου, αὐτὸς δὲ οὐ μετεῖχε οὐδ’ οἱ φίλοι αὐτοῦ.", "st": "5.70"}, {"sp": "N", "t": "οἱ δ’ ἐναγέες Ἀθηναίων ὧδε ὠνομάσθησαν. ἦν Κύλων τῶν Ἀθηναίων ἀνὴρ Ὀλυμπιονίκης· οὗτος ἐπὶ τυραννίδι ἐκόμησε, προσποιησάμενος δὲ ἑταιρηίην τῶν ἡλικιωτέων καταλαβεῖν τὴν ἀκρόπολιν ἐπειρήθη, οὐ δυνάμενος δὲ ἐπικρατῆσαι ἱκέτης ἵζετο πρὸς τὸ ἄγαλμα. τούτους ἀνιστᾶσι μὲν οἱ πρυτάνιες τῶν ναυκράρων, οἵ περ ἔνεμον τότε τὰς Ἀθήνας, ὑπεγγύους πλὴν θανάτου· φονεῦσαι δὲ αὐτοὺς αἰτίη ἔχει Ἀλκμεωνίδας. ταῦτα πρὸ τῆς Πεισιστράτου ἡλικίης ἐγένετο.", "st": "5.71"}, {"sp": "N", "t": "Κλεομένης δὲ ὡς πέμπων ἐξέβαλλε Κλεισθένεα καὶ τοὺς ἐναγέας, Κλεισθένης μὲν αὐτὸς ὑπεξέσχε, μετὰ δὲ οὐδὲν ἧσσον παρῆν ἐς τὰς Ἀθήνας ὁ Κλεομένης οὐ σὺν μεγάλῃ χειρί, ἀπικόμενος δὲ ἀγηλατέει ἑπτακόσια ἐπίστια Ἀθηναίων, τά οἱ ὑπέθετο ὁ Ἰσαγόρης. ταῦτα δὲ ποιήσας δεύτερα τὴν βουλὴν καταλύειν ἐπειρᾶτο, τριηκοσίοισι δὲ τοῖσι Ἰσαγόρεω στασιώτῃσι τὰς ἀρχὰς ἐνεχείριζε. ἀντισταθείσης δὲ τῆς βουλῆς καὶ οὐ βουλομένης πείθεσθαι, ὅ τε Κλεομένης καὶ ὁ Ἰσαγόρης καὶ οἱ στασιῶται αὐτοῦ καταλαμβάνουσι τὴν ἀκρόπολιν. Ἀθηναίων δὲ οἱ λοιποὶ τὰ αὐτὰ φρονήσαντες ἐπολιόρκεον αὐτοὺς ἡμέρας δύο· τῇ δὲ τρίτῃ ὑπόσπονδοι ἐξέρχονται ἐκ τῆς χώρης ὅσοι ἦσαν αὐτῶν Λακεδαιμόνιοι. ἐπετελέετο δὲ τῷ Κλεομένεϊ ἡ φήμη. ὡς γὰρ ἀνέβη ἐς τὴν ἀκρόπολιν μέλλων δὴ αὐτὴν κατασχήσειν, ἤιε ἐς τὸ ἄδυτον τῆς θεοῦ ὡς προσερέων· ἡ δὲ ἱρείη ἐξαναστᾶσα ἐκ τοῦ θρόνου, πρὶν ἢ τὰς θύρας αὐτὸν ἀμεῖψαι, εἶπε ὦ ξεῖνε Λακεδαιμόνιε, πάλιν χώρεε μηδὲ ἔσιθι ἐς τὸ ἱρόν· οὐ γὰρ θεμιτὸν Δωριεῦσι παριέναι ἐνθαῦτα. ὁ δὲ εἶπε ὦ γύναι, ἀλλ’ οὐ Δωριεύς εἰμι ἀλλ’ Ἀχαιός. ὃ μὲν δὴ τῇ κλεηδόνι οὐδὲν χρεώμενος ἐπεχείρησέ τε καὶ τότε πάλιν ἐξέπιπτε μετὰ τῶν Λακεδαιμονίων· τοὺς δὲ ἄλλους Ἀθηναῖοι κατέδησαν τὴν ἐπὶ θανάτῳ, ἐν δὲ αὐτοῖσι καὶ Τιμησίθεον τὸν Δελφόν, τοῦ ἔργα χειρῶν τε καὶ λήματος ἔχοιμ’ ἂν μέγιστα καταλέξαι.", "st": "5.72"}, {"sp": "N", "t": "οὗτοι μέν νυν δεδεμένοι ἐτελεύτησαν. Ἀθηναῖοι δὲ μετὰ ταῦτα Κλεισθένεα καὶ τὰ ἑπτακόσια ἐπίστια τὰ διωχθέντα ὑπὸ Κλεομένεος μεταπεμψάμενοι πέμπουσι ἀγγέλους ἐς Σάρδις, συμμαχίην βουλόμενοι ποιήσασθαι πρὸς Πέρσας· ἠπιστέατο γὰρ σφίσι Λακεδαιμονίους τε καὶ Κλεομένεα ἐκπεπολεμῶσθαι. ἀπικομένων δὲ τῶν ἀγγέλων ἐς τὰς Σάρδις καὶ λεγόντων τὰ ἐντεταλμένα, Ἀρταφρένης ὁ Ὑστάσπεος Σαρδίων ὕπαρχος ἐπειρώτα τίνες ἐόντες ἄνθρωποι καὶ κοῦ γῆς οἰκημένοι δεοίατο Περσέων σύμμαχοι γενέσθαι, πυθόμενος δὲ πρὸς τῶν ἀγγέλων ἀπεκορύφου σφι τάδε· εἰ μὲν διδοῦσι βασιλέι Δαρείῳ Ἀθηναῖοι γῆν τε καὶ ὕδωρ, ὁ δὲ συμμαχίην σφι συνετίθετο, εἰ δὲ μὴ διδοῦσι, ἀπαλλάσσεσθαι αὐτοὺς ἐκέλευε. οἱ δὲ ἄγγελοι ἐπὶ σφέων αὐτῶν βαλόμενοι διδόναι ἔφασαν, βουλόμενοι τὴν συμμαχίην ποιήσασθαι. οὗτοι μὲν δὴ ἀπελθόντες ἐς τὴν ἑωυτῶν αἰτίας μεγάλας εἶχον.", "st": "5.73"}, {"sp": "N", "t": "Κλεομένης δὲ ἐπιστάμενος περιυβρίσθαι ἔπεσι καὶ ἔργοισι ὑπ’ Ἀθηναίων συνέλεγε ἐκ πάσης Πελοποννήσου στρατόν, οὐ φράζων ἐς τὸ συλλέγει, τίσασθαι τε ἐθέλων τὸν δῆμον τὸν Ἀθηναίων καὶ Ἰσαγόρην βουλόμενος τύραννον καταστῆσαι· συνεξῆλθε γάρ οἱ οὗτος ἐκ τῆς ἀκροπόλιος. Κλεομένης τε δὴ στόλῳ μεγάλῳ ἐσέβαλε ἐς Ἐλευσῖνα, καὶ οἱ Βοιωτοὶ ἀπὸ συνθήματος Οἰνόην αἱρέουσι καὶ Ὑσιὰς δήμους τοὺς ἐσχάτους τῆς Ἀττικῆς, Χαλκιδέες τε ἐπὶ τὰ ἕτερα ἐσίνοντο ἐπιόντες χώρους τῆς Ἀττικῆς. Ἀθηναῖοι δέ, καίπερ ἀμφιβολίῃ ἐχόμενοι, Βοιωτῶν μὲν καὶ Χαλκιδέων ἐς ὕστερον ἔμελλον μνήμην ποιήσεσθαι, Πελοποννησίοισι δὲ ἐοῦσι ἐν Ἐλευσῖνι ἀντία ἔθεντο τὰ ὅπλα.", "st": "5.74"}, {"sp": "N", "t": "μελλόντων δὲ συνάψειν τὰ στρατόπεδα ἐς μάχην, Κορίνθιοι μὲν πρῶτοι σφίσι αὐτοῖσι δόντες λόγον ὡς οὐ ποιέοιεν δίκαια μετεβάλλοντό τε καὶ ἀπαλλάσσοντο, μετὰ δὲ Δημάρητος ὁ Ἀρίστωνος, ἐὼν καὶ οὗτος βασιλεὺς Σπαρτιητέων καὶ συνεξαγαγών τε τὴν στρατιὴν ἐκ Λακεδαίμονος καὶ οὐκ ἐὼν διάφορος ἐν τῷ πρόσθε χρόνῳ Κλεομένεϊ. ἀπὸ δὲ ταύτης τῆς διχοστασίης ἐτέθη νόμος ἐν Σπάρτῃ μὴ ἐξεῖναι ἕπεσθαι ἀμφοτέρους τοὺς βασιλέας ἐξιούσης στρατιῆς· τέως γὰρ ἀμφότεροι εἵποντο· παραλυομένου δὲ τούτων τοῦ ἑτέρου καταλείπεσθαι καὶ τῶν Τυνδαριδέων τὸν ἕτερον· πρὸ τοῦ γὰρ δὴ καὶ οὗτοι ἀμφότεροι ἐπίκλητοί σφι ἐόντες εἵποντο. τότε δὴ ἐν τῇ Ἐλευσῖνι ὁρῶντες οἱ λοιποὶ τῶν συμμάχων τούς τε βασιλέας τῶν Λακεδαιμονίων οὐκ ὁμολογέοντας καὶ Κορινθίους ἐκλιπόντας τὴν τάξιν, οἴχοντο καὶ αὐτοὶ ἀπαλλασσόμενοι,", "st": "5.75"}, {"sp": "N", "t": "τέταρτον δὴ τοῦτο ἐπὶ τὴν Ἀττικὴν ἀπικόμενοι Δωριέες, δίς τε ἐπὶ πολέμῳ ἐσβαλόντες καὶ δὶς ἐπ’ ἀγαθῷ τοῦ πλήθεος τοῦ Ἀθηναίων, πρῶτον μὲν ὅτε καὶ Μέγαρα κατοίκισαν· οὗτος ὁ στόλος ἐπὶ Κόδρου βασιλεύοντος Ἀθηναίων ὀρθῶς ἂν καλέοιτο· δεύτερον δὲ καὶ τρίτον ὅτε ἐπὶ Πεισιστρατιδέων ἐξέλασιν ὁρμηθέντες ἐκ Σπάρτης ἀπίκοντο, τέταρτον δὲ τότε ὅτε ἐς Ἐλευσῖνα Κλεομένης ἄγων Πελοποννησίους ἐσέβαλε. οὕτω τέταρτον τότε Δωριέες ἐσέβαλον ἐς Ἀθήνας.", "st": "5.76"}, {"sp": "N", "t": "διαλυθέντος ὦν τοῦ στόλου τούτου ἀκλεῶς, ἐνθαῦτα Ἀθηναῖοι τίνυσθαι βουλόμενοι πρῶτα στρατηίην ποιεῦνται ἐπὶ Χαλκιδέας. Βοιωτοὶ δὲ τοῖσι Χαλκιδεῦσι βοηθέουσι ἐπὶ τὸν Εὔριπον. Ἀθηναίοισι δὲ ἰδοῦσι τοὺς Βοιωτοὺς ἔδοξε πρότερον τοῖσι Βοιωτοῖσι ἢ τοῖσι Χαλκιδεῦσι ἐπιχειρέειν. συμβάλλουσί τε δὴ τοῖσι Βοιωτοῖσι οἱ Ἀθηναῖοι καὶ πολλῷ ἐκράτησαν, κάρτα δὲ πολλοὺς φονεύσαντες ἑπτακοσίους αὐτῶν ἐζώγρησαν. τῆς δὲ αὐτῆς ταύτης ἡμέρης οἱ Ἀθηναῖοι διαβάντες ἐς τὴν Εὔβοιαν συμβάλλουσι καὶ τοῖσι Χαλκιδεῦσι, νικήσαντες δὲ καὶ τούτους τετρακισχιλίους κληρούχους ἐπὶ τῶν ἱπποβοτέων τῇ χώρῃ λείπουσι. οἱ δὲ ἱπποβόται ἐκαλέοντο οἱ παχέες τῶν Χαλκιδέων. ὅσους δὲ καὶ τούτων ἐζώγρησαν, ἅμα τοῖσι Βοιωτῶν ἐζωγρημένοισι εἶχον ἐν φυλακῇ ἐς πέδας δήσαντες· χρόνῳ δὲ ἔλυσαν σφέας δίμνεως ἀποτιμησάμενοι. τὰς δὲ πέδας αὐτῶν, ἐν τῇσι ἐδεδέατο, ἀνεκρέμασαν ἐς τὴν ἀκρόπολιν· αἵ περ ἔτι καὶ ἐς ἐμὲ ἦσαν περιεοῦσαι, κρεμάμεναι ἐκ τειχέων περιπεφλευσμένων πυρὶ ὑπὸ τοῦ Μήδου, ἀντίον δὲ τοῦ μεγάρου τοῦ πρὸς ἑσπέρην τετραμμένου. καὶ τῶν λύτρων τὴν δεκάτην ἀνέθηκαν ποιησάμενοι τέθριππον χάλκεον· τὸ δὲ ἀριστερῆς χειρὸς ἕστηκε πρῶτον ἐσιόντι ἐς τὰ προπύλαια τὰ ἐν τῇ ἀκροπόλι· ἐπιγέγραπται δέ οἱ τάδε.", "st": "5.77"}, {"sp": "N", "t": "ἔθνεα Βοιωτῶν καὶ Χαλκιδέων δαμάσαντες<br>παῖδες Ἀθηναίων ἔργμασιν ἐν πολέμου,<br>δεσμῷ ἐν ἀχλυόεντι σιδηρέῳ ἔσβεσαν ὕβριν·<br>τῶν ἵππους δεκάτην Παλλάδι τάσδ’ ἔθεσαν.", "st": "5.77b"}, {"sp": "N", "t": "Ἀθηναῖοι μέν νυν ηὔξηντο. δηλοῖ δὲ οὐ κατ’ ἓν μοῦνον ἀλλὰ πανταχῇ ἡ ἰσηγορίη ὡς ἔστι χρῆμα σπουδαῖον, εἰ καὶ Ἀθηναῖοι τυραννευόμενοι μὲν οὐδαμῶν τῶν σφέας περιοικεόντων ἦσαν τὰ πολέμια ἀμείνους, ἀπαλλαχθέντες δὲ τυράννων μακρῷ πρῶτοι ἐγένοντο. δηλοῖ ὦν ταῦτα ὅτι κατεχόμενοι μὲν ἐθελοκάκεον ὡς δεσπότῃ ἐργαζόμενοι, ἐλευθερωθέντων δὲ αὐτὸς ἕκαστος ἑωυτῷ προεθυμέετο κατεργάζεσθαι.", "st": "5.78"}, {"sp": "N", "t": "οὗτοι μέν νυν ταῦτα ἔπρησσον. Θῃβαῖοι δὲ μετὰ ταῦτα ἐς θεὸν ἔπεμπον, βουλόμενοι τίσασθαι Ἀθηναίους. ἡ δὲ Πυθίη ἀπὸ σφέων μὲν αὐτῶν οὐκ ἔφη αὐτοῖσι εἶναι τίσιν, ἐς πολύφημον δὲ ἐξενείκαντας ἐκέλευε τῶν ἄγχιστα δέεσθαι. ἀπελθόντων ὦν τῶν θεοπρόπων, ἐξέφερον τὸ χρηστήριον ἁλίην ποιησάμενοι· ὡς ἐπυνθάνοντο δὲ λεγόντων αὐτῶν τῶν ἄγχιστα δέεσθαι, εἶπαν οἱ Θηβαῖοι ἀκούσαντες τούτων οὐκ ὦν ἄγχιστα ἡμέων οἰκέουσι Ταναγραῖοί τε καὶ Κορωναῖοι καὶ Θεσπιέες; καὶ οὗτοί γε ἅμα ἡμῖν αἰεὶ μαχόμενοι προθύμως συνδιαφέρουσι τὸν πόλεμον· τί δεῖ τούτων γε δέεσθαι; ἀλλὰ μᾶλλον μὴ οὐ τοῦτο ᾖ τὸ χρηστήριον.", "st": "5.79"}, {"sp": "N", "t": "τοιαῦτα ἐπιλεγομένων εἶπε δή κοτε μαθών τις ἐγώ μοι δοκέω συνιέναι τὸ θέλει λέγειν ἡμῖν τὸ μαντήιον. Ἀσωποῦ λέγονται γενέσθαι θυγατέρες Θήβη τε καὶ Αἴγινα· τουτέων ἀδελφεῶν ἐουσέων, δοκέω ἡμῖν Αἰγινητέων δέεσθαι τὸν θεὸν χρῇσαι τιμωρητήρων γενέσθαι. καὶ οὐ γάρ τις ταύτης ἀμείνων γνώμη ἐδόκεε φαίνεσθαι, αὐτίκα πέμψαντες ἐδέοντο Αἰγινητέων ἐπικαλεόμενοι κατὰ τὸ χρηστήριόν σφι βοηθέειν, ὡς ἐόντων ἀγχίστων· οἳ δέ σφι αἰτέουσι ἐπικουρίην τοὺς Αἰακίδας συμπέμπειν ἔφασαν.", "st": "5.80"}, {"sp": "N", "t": "πειρησαμένων δὲ τῶν Θηβαίων κατὰ τὴν συμμαχίην τῶν Αἰακιδέων καὶ τρηχέως περιεφθέντων ὑπὸ τῶν Ἀθηναίων, αὖτις οἱ Θηβαῖοι πέμψαντες τοὺς μὲν Αἰακίδας σφι ἀπεδίδοσαν, τῶν δὲ ἀνδρῶν ἐδέοντο. Αἰγινῆται δὲ εὐδαιμονίῃ τε μεγάλῃ ἐπαερθέντες καὶ ἔχθρης παλαιῆς ἀναμνησθέντες ἐχούσης ἐς Ἀθηναίους, τότε Θηβαίων δεηθέντων πόλεμον ἀκήρυκτον Ἀθηναίοισι ἐπέφερον· ἐπικειμένων γὰρ αὐτῶν Βοιωτοῖσι, ἐπιπλώσαντες μακρῇσι νηυσὶ ἐς τὴν Ἀττικὴν κατὰ μὲν ἔσυραν Φάληρον κατὰ δὲ τῆς ἄλλης παραλίης πολλοὺς δήμους, ποιεῦντες δὲ ταῦτα μεγάλως Ἀθηναίους ἐσικνέοντο.", "st": "5.81"}, {"sp": "N", "t": "ἡ δὲ ἔχθρη ἡ προοφειλομένη ἐς Ἀθηναίους ἐκ τῶν Αἰγινητέων ἐγένετο ἐξ ἀρχῆς τοιῆσδε. Ἐπιδαυρίοισι ἡ γῆ καρπὸν οὐδένα ἀνεδίδου. περὶ ταύτης ὦν τῆς συμφορῆς οἱ Ἐπιδαύριοι ἐχρέωντο ἐν Δελφοῖσι· ἡ δὲ Πυθίη σφέας ἐκέλευε Δαμίης τε καὶ Αὐξησίης ἀγάλματα ἱδρύσασθαι καί σφι ἱδρυσαμένοισι ἄμεινον συνοίσεσθαι. ἐπειρώτεον ὦν οἱ Ἐπιδαύριοι κότερα χαλκοῦ ποιέωνται τὰ ἀγάλματα ἢ λίθου· ἡ δὲ Πυθίη οὐδέτερα τούτων ἔα, ἀλλὰ ξύλου ἡμέρης ἐλαίης. ἐδέοντο ὦν οἱ Ἐπιδαύριοι Ἀθηναίων ἐλαίην σφι δοῦναι ταμέσθαι, ἱρωτάτας δὴ κείνας νομίζοντες εἶναι. λέγεται δὲ καὶ ὡς ἐλαῖαι ἦσαν ἄλλοθι γῆς οὐδαμοῦ κατὰ χρόνον ἐκεῖνον ἢ ἐν Ἀθήνῃσι. οἳ δὲ ἐπὶ τοῖσιδε δώσειν ἔφασαν ἐπ’ ᾧ ἀπάξουσι ἔτεος ἑκάστου τῇ Ἀθηναίῃ τε τῇ Πολιάδι ἱρὰ καὶ τῷ Ἐρεχθέι. καταινέσαντες δὲ ἐπὶ τούτοισι οἱ Ἐπιδαύριοι τῶν τε ἐδέοντο ἔτυχον καὶ ἀγάλματα ἐκ τῶν ἐλαιέων τουτέων ποιησάμενοι ἱδρύσαντο· καὶ ἥ τε γῆ σφι ἔφερε καρπὸν καὶ Ἀθηναίοισι ἐπετέλεον τὰ συνέθεντο.", "st": "5.82"}, {"sp": "N", "t": "τοῦτον δ’ ἔτι τὸν χρόνον καὶ πρὸ τοῦ Αἰγινῆται Ἐπιδαυρίων ἤκουον τά τε ἄλλα καὶ δίκας διαβαίνοντες ἐς Ἐπίδαυρον ἐδίδοσάν τε καὶ ἐλάμβανον παρ’ ἀλλήλων οἱ Αἰγινῆται· τὸ δὲ ἀπὸ τοῦδε νέας τε πηξάμενοι καὶ ἀγνωμοσύνῃ χρησάμενοι ἀπέστησαν ἀπὸ τῶν Ἐπιδαυρίων. ἅτε δὲ ἐόντες διάφοροι ἐδηλέοντο αὐτούς, ὥστε θαλασσοκράτορες ἐόντες, καὶ δὴ καὶ τὰ ἀγάλματα ταῦτα τῆς τε Δαμίης καὶ τῆς Αὐξησίης ὑπαιρέονται αὐτῶν, καί σφεα ἐκόμισάν τε καὶ ἱδρύσαντο τῆς σφετέρης χώρης ἐς τὴν μεσόγαιαν, τῇ Οἴη μὲν ἐστὶ οὔνομα, στάδια δὲ μάλιστά κῃ ἀπὸ τῆς πόλιος ὡς εἴκοσι ἀπέχει. ἱδρυσάμενοι δὲ ἐν τούτῳ τῷ χώρῳ θυσίῃσί τε σφέα καὶ χοροῖσι γυναικηίοισι κερτομίοισι ἱλάσκοντο, χορηγῶν ἀποδεικνυμένων ἑκατέρῃ τῶν δαιμόνων δέκα ἀνδρῶν· κακῶς δὲ ἠγόρευον οἱ χοροὶ ἄνδρα μὲν οὐδένα, τὰς δὲ ἐπιχωρίας γυναῖκας. ἦσαν δὲ καὶ τοῖσι Ἐπιδαυρίοισι αἱ αὐταὶ ἱροεργίαι· εἰσὶ δέ σφι καὶ ἄρρητοι ἱρουργίαι.", "st": "5.83"}, {"sp": "N", "t": "κλεφθέντων δὲ τῶνδε τῶν ἀγαλμάτων οἱ Ἐπιδαύριοι τοῖσι Ἀθηναίοισι τὰ συνέθεντο οὐκ ἐπετέλεον. πέμψαντες δὲ οἱ Ἀθηναῖοι ἐμήνιον τοῖσι Ἐπιδαυρίοισι· οἳ δὲ ἀπέφαινον λόγῳ ὡς οὐκ ἀδικέοιεν· ὅσον μὲν γὰρ χρόνον εἶχον τὰ ἀγάλματα ἐν τῇ χώρῃ, ἐπιτελέειν τὰ συνέθεντο, ἐπεὶ δὲ ἐστερῆσθαι αὐτῶν, οὐ δίκαιον εἶναι ἀποφέρειν ἔτι, ἀλλὰ τοὺς ἔχοντας αὐτὰ Αἰγινήτας πρήσσεσθαι ἐκέλευον. πρὸς ταῦτα οἱ Ἀθηναῖοι ἐς Αἴγιναν πέμψαντες ἀπαίτεον τὰ ἀγάλματα· οἱ δὲ Αἰγινῆται ἔφασαν σφίσι τε καὶ Ἀθηναίοισι εἶναι οὐδὲν πρῆγμα.", "st": "5.84"}, {"sp": "N", "t": "Ἀθηναῖοι μέν νυν λέγουσι μετὰ τὴν ἀπαίτησιν ἀποσταλῆναι τριήρεϊ μιῇ τῶν ἀστῶν τούτους οἳ ἀποπεμφθέντες ἀπὸ τοῦ κοινοῦ καὶ ἀπικόμενοι ἐς Αἴγιναν τὰ ἀγάλματα ταῦτα ὡς σφετέρων ξύλων ἐόντα ἐπειρῶντο ἐκ τῶν βάθρων ἐξανασπᾶν, ἵνα σφέα ἀνακομίσωνται. οὐ δυναμένους δὲ τούτῳ τῷ τρόπῳ αὐτῶν κρατῆσαι, περιβαλόντας σχοινία ἕλκειν τὰ ἀγάλματα, καί σφι ἕλκουσι βροντήν τε καὶ ἅμα τῇ βροντῇ σεισμὸν ἐπιγενέσθαι· τοὺς δὲ τριηρίτας τοὺς ἕλκοντας ὑπὸ τούτων ἀλλοφρονῆσαι, παθόντας δὲ τοῦτο κτείνειν ἀλλήλους ἅτε πολεμίους, ἐς ὃ ἐκ πάντων ἕνα λειφθέντα ἀνακομισθῆναι αὐτὸν ἐς Φάληρον.", "st": "5.85"}, {"sp": "N", "t": "Ἀθηναῖοι μὲν οὕτω γενέσθαι λέγουσι, Αἰγινῆται δὲ οὐ μιῇ νηὶ ἀπικέσθαι Ἀθηναίους· μίαν μὲν γὰρ καὶ ὀλίγῳ πλεῦνας μιῆς, καὶ εἰ σφίσι μὴ ἔτυχον ἐοῦσαι νέες, ἀπαμύνεσθαι ἂν εὐπετέως· ἀλλὰ πολλῇσι νηυσὶ ἐπιπλέειν σφίσι ἐπὶ τὴν χώρην, αὐτοὶ δέ σφι εἶξαι καὶ οὐ ναυμαχῆσαι. οὐκ ἔχουσι δὲ τοῦτο διασημῆναι ἀτρεκέως, οὔτε εἰ ἥσσονες συγγινωσκόμενοι εἶναι τῇ ναυμαχίῃ κατὰ τοῦτο εἶξαν, οὔτε εἰ βουλόμενοι ποιῆσαι οἷόν τι καὶ ἐποίησαν. Ἀθηναίους μέν νυν, ἐπείτε σφι οὐδεὶς ἐς μάχην κατίστατο, ἀποβάντας ἀπὸ τῶν νεῶν τραπέσθαι πρὸς τὰ ἀγάλματα, οὐ δυναμένους δὲ ἀνασπάσαι ἐκ τῶν βάθρων αὐτὰ οὕτω δὴ περιβαλομένους σχοινία ἕλκειν, ἐς οὗ ἑλκόμενα τὰ ἀγάλματα ἀμφότερα τὠυτὸ ποιῆσαι, ἐμοὶ μὲν οὐ πιστὰ λέγοντες, ἄλλῳ δὲ τεῷ· ἐς γούνατα γάρ σφι αὐτὰ πεσεῖν, καὶ τὸν ἀπὸ τούτου χρόνον διατελέειν οὕτω ἔχοντα. Ἀθηναίους μὲν δὴ ταῦτα ποιέειν· σφέας δὲ Αἰγινῆται λέγουσι πυθομένους τοὺς Ἀθηναίους ὡς μέλλοιεν ἐπὶ σφέας στρατεύεσθαι, ἑτοίμους Ἀργείους ποιέεσθαι. τούς τε δὴ Ἀθηναίους ἀποβεβάναι ἐς τὴν Αἰγιναίην, καὶ ἥκειν βοηθέοντας σφίσι τοὺς Ἀργείους καὶ λαθεῖν τε ἐξ Ἐπιδαύρου διαβάντας ἐς τὴν νῆσον καὶ οὐ προακηκοόσι τοῖσι Ἀθηναίοισι ἐπιπεσεῖν ὑποταμομένους τὸ ἀπὸ τῶν νεῶν, ἅμα τε ἐν τούτῳ τὴν βροντήν τε γενέσθαι καὶ τὸν σεισμὸν αὐτοῖσι.", "st": "5.86"}, {"sp": "N", "t": "λέγεται μέν νυν ὑπ’ Ἀργείων τε καὶ Αἰγινητέων τάδε, ὁμολογέεται δὲ καὶ ὑπ’ Ἀθηναίων ἕνα μοῦνον τὸν ἀποσωθέντα αὐτῶν ἐς τὴν Ἀττικὴν γενέσθαι· πλὴν Ἀργεῖοι μὲν λέγουσι αὐτῶν τὸ Ἀττικὸν στρατόπεδον διαφθειράντων τὸν ἕνα τοῦτον περιγενέσθαι, Ἀθηναῖοι δὲ τοῦ δαιμονίου· περιγενέσθαι μέντοι οὐδὲ τοῦτον τὸν ἕνα, ἀλλ’ ἀπολέσθαι τρόπῳ τοιῷδε. κομισθεὶς ἄρα ἐς τὰς Ἀθήνας ἀπήγγελλε τὸ πάθος· πυθομένας δὲ τὰς γυναῖκας τῶν ἐπ’ Αἴγιναν στρατευσαμένων ἀνδρῶν, δεινόν τι ποιησαμένας κεῖνον μοῦνον ἐξ ἁπάντων σωθῆναι, πέριξ τὸν ἄνθρωπον τοῦτον λαβούσας καὶ κεντεύσας τῇσι περόνῃσι τῶν ἱματίων εἰρωτᾶν ἑκάστην αὐτέων ὅκου εἴη ὁ ἑωυτῆς ἀνήρ. καὶ τοῦτον μὲν οὕτω διαφθαρῆναι, Ἀθηναίοισι δὲ ἔτι τοῦ πάθεος δεινότερόν τι δόξαι εἶναι τὸ τῶν γυναικῶν ἔργον. ἄλλῳ μὲν δὴ οὐκ ἔχειν ὅτεῳ ζημιώσωσι τὰς γυναῖκας, τὴν δὲ ἐσθῆτα μετέβαλον αὐτέων ἐς τὴν Ἰάδα· ἐφόρεον γὰρ δὴ πρὸ τοῦ αἱ τῶν Ἀθηναίων γυναῖκες ἐσθῆτα Δωρίδα, τῇ Κορινθίῃ παραπλησιωτάτην· μετέβαλον ὦν ἐς τὸν λίνεον κιθῶνα, ἵνα δὴ περόνῃσι μὴ χρέωνται.", "st": "5.87"}, {"sp": "N", "t": "ἔστι δὲ ἀληθέι λόγῳ χρεωμένοισι οὐκ Ἰὰς αὕτη ἡ ἐσθὴς τὸ παλαιὸν ἀλλὰ Κάειρα, ἐπεὶ ἥ γε Ἑλληνικὴ ἐσθὴς πᾶσα ἡ ἀρχαίη τῶν γυναικῶν ἡ αὐτὴ ἦν τὴν νῦν Δωρίδα καλέομεν. τοῖσι δὲ Ἀργείοισι καὶ τοῖσι Αἰγινήτῃσι καὶ πρὸς ταῦτα ἔτι τόδε ποιῆσαι νόμον εἶναι παρὰ σφίσι ἑκατέροισι τὰς περόνας ἡμιολίας ποιέεσθαι τοῦ τότε κατεστεῶτος μέτρου, καὶ ἐς τὸ ἱρὸν τῶν θεῶν τουτέων περόνας μάλιστα ἀνατιθέναι τὰς γυναῖκας, Ἀττικὸν δὲ μήτε τι ἄλλο προσφέρειν πρὸς τὸ ἱρὸν μήτε κέραμον, ἀλλ’ ἐκ χυτρίδων ἐπιχωριέων νόμον τὸ λοιπὸν αὐτόθι εἶναι πίνειν.", "st": "5.88"}, {"sp": "N", "t": "Ἀργείων μέν νυν καὶ Αἰγινητέων αἱ γυναῖκες ἐκ τόσου κατ’ ἔριν τὴν Ἀθηναίων περόνας ἔτι καὶ ἐς ἐμὲ ἐφόρεον μέζονας ἢ πρὸ τοῦ, τῆς δὲ ἔχθρης τῆς πρὸς Αἰγινήτας ἐξ Ἀθηναίων γενομένης ἀρχὴ κατὰ τὰ εἴρηται ἐγένετο. τότε δὲ Θηβαίων ἐπικαλεομένων, προθύμως τῶν περὶ τὰ ἀγάλματα γενομένων ἀναμιμνησκόμενοι οἱ Αἰγινῆται ἐβοήθεον τοῖσι Βοιωτοῖσι. Αἰγινῆταί τε δὴ ἐδηίουν τῆς Ἀττικῆς τὰ παραθαλάσσια, καὶ Ἀθηναίοισι ὁρμημένοισι ἐπ’ Αἰγινήτας στρατεύεσθαι ἦλθε μαντήιον ἐκ Δελφῶν, ἐπισχόντας ἀπὸ τοῦ Αἰγινητέων ἀδικίου τριήκοντα ἔτεα, τῷ ἑνὶ καὶ τριηκοστῷ Αἰακῷ τέμενος ἀποδέξαντας ἄρχεσθαι τοῦ πρὸς Αἰγινήτας πολέμου, καί σφι χωρήσειν τὰ βούλονται· ἢν δὲ αὐτίκα ἐπιστρατεύωνται, πολλὰ μὲν σφέας ἐν τῷ μεταξὺ τοῦ χρόνου πείσεσθαι πολλὰ δὲ καὶ ποιήσειν, τέλος μέντοι καταστρέψεσθαι. ταῦτα ὡς ἀπενειχθέντα ἤκουσαν οἱ Ἀθηναῖοι, τῷ μὲν Αἰακῷ τέμενος ἀπέδεξαν τοῦτο τὸ νῦν ἐπὶ τῆς ἀγορῆς ἵδρυται, τριήκοντα δὲ ἔτεα οὐκ ἀνέσχοντο ἀκούσαντες ὅκως χρεὸν εἴη ἐπισχεῖν πεπονθότας ὑπ’ Αἰγινητέων ἀνάρσια.", "st": "5.89"}, {"sp": "N", "t": "ἐς τιμωρίην δὲ παρασκευαζομένοισι αὐτοῖσι ἐκ Λακεδαιμονίων πρῆγμα ἐγειρόμενον ἐμπόδιον ἐγένετο. πυθόμενοι γὰρ Λακεδαιμόνιοι τὰ ἐκ τῶν Ἀλκμεωνιδέων ἐς τὴν Πυθίην μεμηχανημένα καὶ τὰ ἐκ τῆς Πυθίης ἐπὶ σφέας τε καὶ τοὺς Πεισιστρατίδας συμφορὴν ἐποιεῦντο διπλῆν, ὅτι τε ἄνδρας ξείνους σφίσι ἐόντας ἐξεληλάκεσαν ἐκ τῆς ἐκείνων, καὶ ὅτι ταῦτα ποιήσασι χάρις οὐδεμία ἐφαίνετο πρὸς Ἀθηναίων. ἔτι τε πρὸς τούτοισι ἐνῆγον σφέας οἱ χρησμοὶ λέγοντες πολλά τε καὶ ἀνάρσια ἔσεσθαι αὐτοῖσι ἐξ Ἀθηναίων, τῶν πρότερον μὲν ἦσαν ἀδαέες, τότε δὲ Κλεομένεος κομίσαντος ἐς Σπάρτην ἐξέμαθον. ἐκτήσατο δὲ ὁ Κλεομένης ἐκ τῆς Ἀθηναίων ἀκροπόλιος τοὺς χρησμούς, τοὺς ἔκτηντο μὲν πρότερον οἱ Πεισιστρατίδαι, ἐξελαυνόμενοι δὲ ἔλιπον ἐν τῷ ἱρῷ, καταλειφθέντας δὲ ὁ Κλεομένης ἀνέλαβε.", "st": "5.90"}, {"sp": "N", "t": "τότε δὲ ὡς ἀνέλαβον οἱ Λακεδαιμόνιοι τοὺς χρησμοὺς καὶ τοὺς Ἀθηναίους ὥρων αὐξομένους καὶ οὐδαμῶς ἑτοίμους ἐόντας πείθεσθαι σφίσι, νόῳ λαβόντες ὡς ἐλεύθερον μὲν ἐὸν τὸ γένος τὸ Ἀττικὸν ἰσόρροπον ἂν τῷ ἑωυτῶν γίνοιτο, κατεχόμενον δὲ ὑπὸ τυραννίδος ἀσθενὲς καὶ πειθαρχέεσθαι ἕτοιμον· μαθόντες δὲ τούτων ἕκαστα μετεπέμποντο Ἱππίην τὸν Πεισιστράτου ἀπὸ Σιγείου τοῦ ἐν Ἑλλησπόντῳ ἐς ὃ καταφεύγουσι οἱ Πεισιστρατίδαι. ἐπείτε δέ σφι Ἱππίης καλεόμενος ἧκε, μεταπεμψάμενοι καὶ τῶν ἄλλων συμμάχων ἀγγέλους ἔλεγόν σφι Σπαρτιῆται τάδε. ἄνδρες σύμμαχοι, συγγινώσκομεν αὐτοῖσι ἡμῖν οὐ ποιήσασι ὀρθῶς· ἐπαερθέντες γὰρ κιβδήλοισι μαντηίοισι ἄνδρας ξείνους ἐόντας ἡμῖν τὰ μάλιστα καὶ ἀναδεκομένους ὑποχειρίας παρέξειν τὰς Ἀθήνας, τούτους ἐκ τῆς πατρίδος ἐξηλάσαμεν, καὶ ἔπειτα ποιήσαντες ταῦτα δήμῳ ἀχαρίστῳ παρεδώκαμεν τὴν πόλιν· ὃς ἐπείτε δι’ ἡμέας ἐλευθερωθεὶς ἀνέκυψε, ἡμέας μὲν καὶ τὸν βασιλέα ἡμέων περιυβρίσας ἐξέβαλε, δόξαν δὲ φύσας αὐξάνεται, ὥστε ἐκμεμαθήκασι μάλιστα μὲν οἱ περίοικοι αὐτῶν Βοιωτοὶ καὶ Χαλκιδέες, τάχα δέ τις καὶ ἄλλος ἐκμαθήσεται ἁμαρτών. ἐπείτε δὲ ἐκεῖνα ποιήσαντες ἡμάρτομεν, νῦν πειρησόμεθα σφέας ἅμα ὑμῖν ἀπικόμενοι τίσασθαι· αὐτοῦ γὰρ τούτου εἵνεκεν τόνδε τε Ἱππίην μετεπεμψάμεθα καὶ ὑμέας ἀπὸ τῶν πολίων, ἵνα κοινῷ τε λόγῳ καὶ κοινῷ στόλῳ ἐσαγαγόντες αὐτὸν ἐς τὰς Ἀθήνας ἀποδῶμεν τὰ καὶ ἀπειλόμεθα.", "st": "5.91"}, {"sp": "N", "t": "οἳ μὲν ταῦτα ἔλεγον, τῶν δὲ συμμάχων τὸ πλῆθος οὐκ ἐνεδέκετο τοὺς λόγους. οἱ μέν νυν ἄλλοι ἡσυχίην ἦγον, Κορίνθιος δὲ Σωκλέης ἔλεξε τάδε. ἦ δὴ ὅ τε οὐρανὸς ἔνερθε ἔσται τῆς γῆς καὶ ἡ γῆ μετέωρος ὑπὲρ τοῦ οὐρανοῦ, καὶ ἄνθρωποι νομὸν ἐν θαλάσσῃ ἕξουσι καὶ ἰχθύες τὸν πρότερον ἄνθρωποι, ὅτε γε ὑμεῖς ὦ Λακεδαιμόνιοι ἰσοκρατίας καταλύοντες τυραννίδας ἐς τὰς πόλις κατάγειν παρασκευάζεσθε, τοῦ οὔτε ἀδικώτερον ἐστὶ οὐδὲν κατ’ ἀνθρώπους οὔτε μιαιφονώτερον. εἰ γὰρ δὴ τοῦτό γε δοκέει ὑμῖν εἶναι χρηστὸν ὥστε τυραννεύεσθαι τὰς πόλις, αὐτοὶ πρῶτοι τύραννον καταστησάμενοι παρὰ σφίσι αὐτοῖσι οὕτω καὶ τοῖσι ἄλλοισι δίζησθε κατιστάναι· νῦν δὲ αὐτοὶ τυράννων ἄπειροι ἐόντες, καὶ φυλάσσοντες τοῦτο δεινότατα ἐν τῇ Σπάρτῃ μὴ γενέσθαι, παραχρᾶσθε ἐς τοὺς συμμάχους. εἰ δὲ αὐτοῦ ἔμπειροι ἔατε κατά περ ἡμεῖς, εἴχετε ἂν περὶ αὐτοῦ γνώμας ἀμείνονας συμβαλέσθαι ἤ περ νῦν. Κορινθίοισι γὰρ ἦν πόλιος κατάστασις τοιήδε· ἦν ὀλιγαρχίη, καὶ οὗτοι Βακχιάδαι καλεόμενοι ἔνεμον τὴν πόλιν, ἐδίδοσαν δὲ καὶ ἤγοντο ἐξ ἀλλήλων. Ἀμφίονι δὲ ἐόντι τούτων τῶν ἀνδρῶν γίνεται θυγάτηρ χωλή· οὔνομα δέ οἱ ἦν Λάβδα. ταύτην Βακχιαδέων γὰρ οὐδεὶς ἤθελε γῆμαι, ἴσχει Ἠετίων ὁ Ἐχεκράτεος, δήμου μὲν ἐὼν ἐκ Πέτρης, ἀτὰρ τὰ ἀνέκαθεν Λαπίθης τε καὶ Καινείδης. ἐκ δέ οἱ ταύτης τῆς γυναικὸς οὐδ’ ἐξ ἄλλης παῖδες ἐγίνοντο. ἐστάλη ὦν ἐς Δελφοὺς περὶ γόνου. ἐσιόντα δὲ αὐτὸν ἰθέως ἡ Πυθίη προσαγορεύει τοῖσιδε τοῖσι ἔπεσι.<br>Ἠετίων, οὔτις σε τίει πολύτιτον ἐόντα.", "st": "5.92"}, {"sp": "N", "t": "Λάβδα κύει, τέξει δ’ ὀλοοίτροχον· ἐν δὲ πεσεῖται<br>ἀνδράσι μουνάρχοισι, δικαιώσει δὲ Κόρινθον.", "st": "5.92b"}, {"sp": "N", "t": "ταῦτα χρησθέντα τῷ Ἠετίωνι ἐξαγγέλλεταί κως τοῖσι Βακχιάδῃσι, τοῖσι τὸ μὲν πρότερον γενόμενον χρηστήριον ἐς Κόρινθον ἦν ἄσημον, φέρον τε ἐς τὠυτὸ καὶ τὸ τοῦ Ἠετίωνος καὶ λέγον ὧδε.", "st": "5.92b.3"}, {"sp": "N", "t": "αἰετὸς ἐν πέτρῃσι κύει, τέξει δὲ λέοντα<br>καρτερὸν ὠμηστήν· πολλῶν δ’ ὑπὸ γούνατα λύσει.<br>ταῦτά νυν εὖ φράζεσθε, Κορίνθιοι, οἳ περὶ καλήν<br>Πειρήνην οἰκεῖτε καὶ ὀφρυόεντα Κόρινθον.", "st": "5.92b.3b"}, {"sp": "N", "t": "τοῦτο μὲν δὴ τοῖσι Βακχιάδῃσι πρότερον γενόμενον ἦν ἀτέκμαρτον· τότε δὲ τὸ Ἠετίωνι γενόμενον ὡς ἐπύθοντο, αὐτίκα καὶ τὸ πρότερον συνῆκαν ἐὸν συνῳδὸν τῷ Ἠετίωνος. συνέντες δὲ καὶ τοῦτο εἶχον ἐν ἡσυχίῃ, ἐθέλοντες τὸν μέλλοντα Ἠετίωνι γίνεσθαι γόνον διαφθεῖραι. ὡς δ’ ἔτεκε ἡ γυνὴ τάχιστα, πέμπουσι σφέων αὐτῶν δέκα ἐς τὸν δῆμον ἐν τῷ κατοίκητο ὁ Ἠετίων ἀποκτενέοντας τὸ παιδίον. ἀπικόμενοι δὲ οὗτοι ἐς τὴν Πέτρην καὶ παρελθόντες ἐς τὴν αὐλὴν τὴν Ἠετίωνος αἴτεον τὸ παιδίον· ἡ δὲ Λάβδα εἰδυῖά τε οὐδὲν τῶν εἵνεκα ἐκεῖνοι ἀπικοίατο, καὶ δοκέουσα σφέας φιλοφροσύνης τοῦ πατρὸς εἵνεκα αἰτέειν, φέρουσα ἐνεχείρισε αὐτῶν ἑνί. τοῖσι δὲ ἄρα ἐβεβούλευτο κατ’ ὁδὸν τὸν πρῶτον αὐτῶν λαβόντα τὸ παιδίον προσουδίσαι. ἐπεὶ ὦν ἔδωκε φέρουσα ἡ Λάβδα, τὸν λαβόντα τῶν ἀνδρῶν θείῃ τύχῃ προσεγέλασε τὸ παιδίον, καὶ τὸν φρασθέντα τοῦτο οἶκτός τις ἴσχει ἀποκτεῖναι, κατοικτείρας δὲ παραδιδοῖ τῷ δευτέρῳ, ὁ δὲ τῷ τρίτῳ. οὕτω δὴ διεξῆλθε διὰ πάντων τῶν δέκα παραδιδόμενον, οὐδενὸς βουλομένου διεργάσασθαι. ἀποδόντες ὦν ὀπίσω τῇ τεκούσῃ τὸ παιδίον καὶ ἐξελθόντες ἔξω, ἑστεῶτες ἐπὶ τῶν θυρέων ἀλλήλων ἅπτοντο καταιτιώμενοι, καὶ μάλιστα τοῦ πρώτου λαβόντος, ὅτι οὐκ ἐποίησε κατὰ τὰ δεδογμένα, ἐς ὃ δή σφι χρόνου ἐγγινομένου ἔδοξε αὖτις παρελθόντας πάντας τοῦ φόνου μετίσχειν. ἔδει δὲ ἐκ τοῦ Ἠετίωνος γόνου Κορίνθῳ κακὰ ἀναβλαστεῖν. ἡ Λάβδα γὰρ πάντα ταῦτα ἤκουε ἑστεῶσα πρὸς αὐτῇσι τῇσι θύρῃσι· δείσασα δὲ μή σφι μεταδόξῃ καὶ τὸ δεύτερον λαβόντες τὸ παιδίον ἀποκτείνωσι, φέρουσα κατακρύπτει ἐς τὸ ἀφραστότατόν οἱ ἐφαίνετο εἶναι, ἐς κυψέλην, ἐπισταμένη ὡς εἰ ὑποστρέψαντες ἐς ζήτησιν ἀπικνεοίατο πάντα ἐρευνήσειν μέλλοιεν· τὰ δὴ καὶ ἐγίνετο. ἐλθοῦσι δὲ καὶ διζημένοισι αὐτοῖσι ὡς οὐκ ἐφαίνετο, ἐδόκεε ἀπαλλάσσεσθαι καὶ λέγειν πρὸς τοὺς ἀποπέμψαντας ὡς πάντα ποιήσειαν τὰ ἐκεῖνοι ἐνετείλαντο. οἳ μὲν δὴ ἀπελθόντες ἔλεγον ταῦτα.", "st": "5.92c.1"}, {"sp": "N", "t": "Ἠετίωνι δὲ μετὰ ταῦτα ὁ παῖς ηὐξάνετο, καί οἱ διαφυγόντι τοῦτον τὸν κίνδυνον ἀπὸ τῆς κυψέλης ἐπωνυμίην Κύψελος οὔνομα ἐτέθη. ἀνδρωθέντι δὲ καὶ μαντευομένῳ Κυψέλῳ ἐγένετο ἀμφιδέξιον χρηστήριον ἐν Δελφοῖσι, τῷ πίσυνος γενόμενος ἐπεχείρησέ τε καὶ ἔσχε Κόρινθον. ὁ δὲ χρησμὸς ὅδε ἦν. ὄλβιος οὗτος ἀνὴρ ὃς ἐμὸν δόμον ἐσκαταβαίνει,<br>Κύψελος Ἠετίδης, βασιλεὺς κλειτοῖο Κορίνθου<br>αὐτὸς καὶ παῖδες, παίδων γε μὲν οὐκέτι παῖδες.<br>τὸ μὲν δὴ χρηστήριον τοῦτο ἦν, τυραννεύσας δὲ ὁ Κύψελος τοιοῦτος δή τις ἀνὴρ ἐγένετο· πολλοὺς μὲν Κορινθίων ἐδίωξε, πολλοὺς δὲ χρημάτων ἀπεστέρησε, πολλῷ δέ τι πλείστους τῆς ψυχῆς.", "st": "5.92e.1"}, {"sp": "N", "t": "ἄρξαντος δὲ τούτου ἐπὶ τριήκοντα ἔτεα καὶ διαπλέξαντος τὸν βίον εὖ, διάδοχός οἱ τῆς τυραννίδος ὁ παῖς Περίανδρος γίνεται. ὁ τοίνυν Περίανδρος κατ’ ἀρχὰς μὲν ἦν ἠπιώτερος τοῦ πατρός, ἐπείτε δὲ ὡμίλησε δι’ ἀγγέλων Θρασυβούλῳ τῷ Μιλήτου τυράννῳ, πολλῷ ἔτι ἐγένετο Κυψέλου μιαιφονώτερος. πέμψας γὰρ παρὰ Θρασύβουλον κήρυκα ἐπυνθάνετο ὅντινα ἂν τρόπον ἀσφαλέστατον καταστησάμενος τῶν πρηγμάτων κάλλιστα τὴν πόλιν ἐπιτροπεύοι. Θρασύβουλος δὲ τὸν ἐλθόντα παρὰ τοῦ Περιάνδρου ἐξῆγε ἔξω τοῦ ἄστεος, ἐσβὰς δὲ ἐς ἄρουραν ἐσπαρμένην ἅμα τε διεξήιε τὸ λήιον ἐπειρωτῶν τε καὶ ἀναποδίζων τὸν κήρυκα κατὰ τὴν ἀπὸ Κορίνθου ἄπιξιν, καὶ ἐκόλουε αἰεὶ ὅκως τινὰ ἴδοι τῶν ἀσταχύων ὑπερέχοντα, κολούων δὲ ἔρριπτε, ἐς ὃ τοῦ ληίου τὸ κάλλιστόν τε καὶ βαθύτατον διέφθειρε τρόπῳ τοιούτῳ· διεξελθὼν δὲ τὸ χωρίον καὶ ὑποθέμενος ἔπος οὐδὲν ἀποπέμπει τὸν κήρυκα. νοστήσαντος δὲ τοῦ κήρυκος ἐς τὴν Κόρινθον ἦν πρόθυμος πυνθάνεσθαι τὴν ὑποθήκην ὁ Περίανδρος· ὁ δὲ οὐδέν οἱ ἔφη Θρασύβουλον ὑποθέσθαι, θωμάζειν τε αὐτοῦ παρ’ οἷόν μιν ἄνδρα ἀποπέμψειε, ὡς παραπλῆγά τε καὶ τῶν ἑωυτοῦ σινάμωρον, ἀπηγεόμενος τά περ πρὸς Θρασυβούλου ὀπώπεε. Περίανδρος δὲ συνιεὶς τὸ ποιηθὲν καὶ νόῳ ἴσχων ὥς οἱ ὑπετίθετο Θρασύβουλος τοὺς ὑπειρόχους τῶν ἀστῶν φονεύειν, ἐνθαῦτα δὴ πᾶσαν κακότητα ἐξέφαινε ἐς τοὺς πολιήτας. ὅσα γὰρ Κύψελος ἀπέλιπε κτείνων τε καὶ διώκων, Περίανδρος σφέα ἀπετέλεσε, μιῇ δὲ ἡμέρῃ ἀπέδυσε πάσας τὰς Κορινθίων γυναῖκας διὰ τὴν ἑωυτοῦ γυναῖκα Μέλισσαν. πέμψαντι γάρ οἱ ἐς Θεσπρωτοὺς ἐπ’ Ἀχέροντα ποταμὸν ἀγγέλους ἐπὶ τὸ νεκυομαντήιον παρακαταθήκης πέρι ξεινικῆς οὔτε σημανέειν ἔφη ἡ Μέλισσα ἐπιφανεῖσα οὔτε κατερέειν ἐν τῷ κέεται χώρῳ ἡ παρακαταθήκη· ῥιγοῦν τε γὰρ καὶ εἶναι γυμνή· τῶν γάρ οἱ συγκατέθαψε ἱματίων ὄφελος εἶναι οὐδὲν οὐ κατακαυθέντων· μαρτύριον δέ οἱ εἶναι ὡς ἀληθέα ταῦτα λέγει, ὅτι ἐπὶ ψυχρὸν τὸν ἰπνὸν Περίανδρος τοὺς ἄρτους ἐπέβαλε. ταῦτα δὲ ὡς ὀπίσω ἀπηγγέλθη τῷ Περιάνδρῳ, πιστὸν γάρ οἱ ἦν τὸ συμβόλαιον ὃς νεκρῷ ἐούσῃ Μελίσσῃ ἐμίγη, ἰθέως δὴ μετὰ τὴν ἀγγελίην κήρυγμα ἐποιήσατο ἐς τὸ Ἥραιον ἐξιέναι πάσας τὰς Κορινθίων γυναῖκας. αἳ μὲν δὴ ὡς ἐς ὁρτὴν ἤισαν κόσμῳ τῷ καλλίστῳ χρεώμεναι, ὃ δ’ ὑποστήσας τοὺς δορυφόρους ἀπέδυσε σφέας πάσας ὁμοίως, τάς τε ἐλευθέρας καὶ τὰς ἀμφιπόλους, συμφορήσας δὲ ἐς ὄρυγμα Μελίσσῃ ἐπευχόμενος κατέκαιε. ταῦτα δέ οἱ ποιήσαντι καὶ τὸ δεύτερον πέμψαντι ἔφρασε τὸ εἴδωλον τὸ Μελίσσης ἐς τὸν κατέθηκε χῶρον τοῦ ξείνου τὴν παρακαταθήκην.", "st": "5.92f.1"}, {"sp": "N", "t": "τοιοῦτο μὲν ὑμῖν ἐστὶ ἡ τυραννίς, ὦ Λακεδαιμόνιοι, καὶ τοιούτων ἔργων. ἡμέας δὲ τοὺς Κορινθίους τότε αὐτίκα θῶμα μέγα εἶχε ὅτε ὑμέας εἴδομεν μεταπεμπομένους Ἱππίην, νῦν τε δὴ καὶ μεζόνως θωμάζομεν λέγοντας ταῦτα, ἐπιμαρτυρόμεθά τε ἐπικαλεόμενοι ὑμῖν θεοὺς τοὺς Ἑλληνίους μὴ κατιστάναι τυραννίδας ἐς τὰς πόλις. οὔκων παύσεσθε ἀλλὰ πειρήσεσθε παρὰ τὸ δίκαιον κατάγοντες Ἱππίην· ἴστε ὑμῖν Κορινθίους γε οὐ συναινέοντας.", "st": "5.92g.5"}, {"sp": "N", "t": "Σωκλέης μὲν ἀπὸ Κορίνθου πρεσβεύων ἔλεξε τάδε, Ἱππίης δὲ αὐτὸν ἀμείβετο τοὺς αὐτοὺς ἐπικαλέσας θεοὺς ἐκείνῳ, ἦ μὲν Κορινθίους μάλιστα πάντων ἐπιποθήσειν Πεισιστρατίδας, ὅταν σφι ἥκωσι ἡμέραι αἱ κύριαι ἀνιᾶσθαι ὑπ’ Ἀθηναίων. Ἱππίης μὲν τούτοισι ἀμείψατο οἷα τοὺς χρησμοὺς ἀτρεκέστατα ἀνδρῶν ἐξεπιστάμενος· οἱ δὲ λοιποὶ τῶν συμμάχων τέως μὲν εἶχον ἐν ἡσυχίῃ σφέας αὐτούς, ἐπείτε δὲ Σωκλέος ἤκουσαν εἴπαντος ἐλευθέρως, ἅπας τις αὐτῶν φωνὴν ῥήξας αἱρέετο τοῦ Κορινθίου τὴν γνώμην, Λακεδαιμονίοισί τε ἐπεμαρτυρέοντο μὴ ποιέειν μηδὲν νεώτερον περὶ πόλιν Ἑλλάδα.", "st": "5.93"}, {"sp": "N", "t": "οὕτω μὲν τοῦτο ἐπαύσθη. Ἱππίῃ δὲ ἐνθεῦτεν ἀπελαυνομένῳ ἐδίδου μὲν Ἀμύντης ὁ Μακεδόνων βασιλεὺς Ἀνθεμοῦντα, ἐδίδοσαν δὲ Θεσσαλοὶ Ἰωλκόν. ὁ δὲ τούτων μὲν οὐδέτερα αἱρέετο, ἀνεχώρεε δὲ ὀπίσω ἐς Σίγειον, τὸ εἷλε Πεισίστρατος αἰχμῇ παρὰ Μυτιληναίων, κρατήσας δὲ αὐτοῦ κατέστησε τύραννον εἶναι παῖδα τὸν ἑωυτοῦ νόθον Ἡγησίστρατον, γεγονότα ἐξ Ἀργείης γυναικός, ὃς οὐκ ἀμαχητὶ εἶχε τὰ παρέλαβε παρὰ Πεισιστράτου. ἐπολέμεον γὰρ ἔκ τε Ἀχιλληίου πόλιος ὁρμώμενοι καὶ Σιγείου ἐπὶ χρόνον συχνὸν Μυτιληναῖοί τε καὶ Ἀθηναῖοι, οἳ μὲν ἀπαιτέοντες τὴν χώρην, Ἀθηναῖοι δὲ οὔτε συγγινωσκόμενοι ἀποδεικνύντες τε λόγῳ οὐδὲν μᾶλλον Αἰολεῦσι μετεὸν τῆς Ἰλιάδος χώρης ἢ οὐ καὶ σφίσι καὶ τοῖσι ἄλλοισι, ὅσοι Ἑλλήνων συνεπρήξαντο Μενέλεῳ τὰς Ἑλένης ἁρπαγάς.", "st": "5.94"}, {"sp": "N", "t": "πολεμεόντων δὲ σφέων παντοῖα καὶ ἄλλα ἐγένετο ἐν τῇσι μάχῃσι, ἐν δὲ δὴ καὶ Ἀλκαῖος ὁ ποιητὴς συμβολῆς γενομένης καὶ νικώντων Ἀθηναίων αὐτὸς μὲν φεύγων ἐκφεύγει, τὰ δέ οἱ ὅπλα ἴσχουσι Ἀθηναῖοι, καί σφεα ἀνεκρέμασαν πρὸς τὸ Ἀθήναιον τὸ ἐν Σιγείῳ. ταῦτα δὲ Ἀλκαῖος ἐν μέλεϊ ποιήσας ἐπιτιθεῖ ἐς Μυτιλήνην, ἐξαγγελλόμενος τὸ ἑωυτοῦ πάθος Μελανίππῳ ἀνδρὶ ἑταίρῳ. Μυτιληναίους δὲ καὶ Ἀθηναίους κατήλλαξε Περίανδρος ὁ Κυψέλου· τούτῳ γὰρ διαιτητῇ ἐπετράποντο· κατήλλαξε δὲ ὧδε, νέμεσθαι ἑκατέρους τὴν ἔχουσι.", "st": "5.95"}, {"sp": "N", "t": "Σίγειον μέν νυν οὕτω ἐγένετο ὑπ’ Ἀθηναίοισι. Ἱππίης δὲ ἐπείτε ἀπίκετο ἐκ τῆς Λακεδαίμονος ἐς τὴν Ἀσίην, πᾶν χρῆμα ἐκίνεε, διαβάλλων τε τοὺς Ἀθηναίους πρὸς τὸν Ἀρταφρένεα καὶ ποιέων ἅπαντα ὅκως αἱ Ἀθῆναι γενοίατο ὑπ’ ἑωυτῷ τε καὶ Δαρείῳ. Ἱππίης τε δὴ ταῦτα ἔπρησσε, καὶ οἱ Ἀθηναῖοι πυθόμενοι ταῦτα πέμπουσι ἐς Σάρδις ἀγγέλους, οὐκ ἐῶντες τοὺς Πέρσας πείθεσθαι Ἀθηναίων τοῖσι φυγάσι. ὁ δὲ Ἀρταφρένης ἐκέλευε σφέας, εἰ βουλοίατο σόοι εἶναι, καταδέκεσθαι ὀπίσω Ἱππίην. οὔκων δὴ ἐνεδέκοντο τοὺς λόγους ἀποφερομένους οἱ Ἀθηναῖοι· οὐκ ἐνδεκομένοισι δέ σφι ἐδέδοκτο ἐκ τοῦ φανεροῦ τοῖσι Πέρσῃσι πολεμίους εἶναι.", "st": "5.96"}, {"sp": "N", "t": "νομίζουσι δὲ ταῦτα καὶ διαβεβλημένοισι ἐς τοὺς Πέρσας, ἐν τούτῳ δὴ τῷ καιρῷ ὁ Μιλήσιος Ἀρισταγόρης, ὑπὸ Κλεομένεος τοῦ Λακεδαιμονίου ἐξελασθεὶς ἐκ τῆς Σπάρτης, ἀπίκετο ἐς Ἀθήνας· αὕτη γὰρ ἡ πόλις τῶν λοιπέων ἐδυνάστευε μέγιστον. ἐπελθὼν δὲ ἐπὶ τὸν δῆμον ὁ Ἀρισταγόρης ταὐτὰ ἔλεγε τὰ καὶ ἐν τῇ Σπάρτῃ περὶ τῶν ἀγαθῶν τῶν ἐν τῇ Ἀσίῃ καὶ τοῦ πολέμου τοῦ Περσικοῦ, ὡς οὔτε ἀσπίδα οὔτε δόρυ νομίζουσι εὐπετέες τε χειρωθῆναι εἴησαν. ταῦτά τε δὴ ἔλεγε καὶ πρὸς τοῖσι τάδε, ὡς οἱ Μιλήσιοι τῶν Ἀθηναίων εἰσὶ ἄποικοι, καὶ οἰκός σφεας εἴη ῥύεσθαι δυναμένους μέγα· καὶ οὐδὲν ὅ τι οὐκ ὑπίσχετο οἷα κάρτα δεόμενος, ἐς ὃ ἀνέπεισε σφέας. πολλοὺς γὰρ οἶκε εἶναι εὐπετέστερον διαβάλλειν ἢ ἕνα, εἰ Κλεομένεα μὲν τὸν Λακεδαιμόνιον μοῦνον οὐκ οἷός τε ἐγένετο διαβάλλειν, τρεῖς δὲ μυριάδας Ἀθηναίων ἐποίησε τοῦτο. Ἀθηναῖοι μὲν δὴ ἀναπεισθέντες ἐψηφίσαντο εἴκοσι νέας ἀποστεῖλαι βοηθοὺς Ἴωσι, στρατηγὸν ἀποδέξαντες αὐτῶν εἶναι Μελάνθιον ἄνδρα τῶν ἀστῶν ἐόντα τὰ πάντα δόκιμον· αὗται δὲ αἱ νέες ἀρχὴ κακῶν ἐγένοντο Ἕλλησί τε καὶ βαρβάροισι.", "st": "5.97"}, {"sp": "N", "t": "Ἀρισταγόρης δὲ προπλώσας καὶ ἀπικόμενος ἐς τὴν Μίλητον, ἐξευρὼν βούλευμα ἀπ’ οὗ Ἴωσι μὲν οὐδεμία ἔμελλε ὠφελίη ἔσεσθαι, οὐδ’ ὦν οὐδὲ τούτου εἵνεκα ἐποίεε ἀλλ’ ὅκως βασιλέα Δαρεῖον λυπήσειε, ἔπεμψε ἐς τὴν Φρυγίην ἄνδρα ἐπὶ τοὺς Παίονας τοὺς ἀπὸ Στρυμόνος ποταμοῦ αἰχμαλώτους γενομένους ὑπὸ Μεγαβάζου, οἰκέοντας δὲ τῆς Φρυγίης χῶρόν τε καὶ κώμην ἐπ’ ἑωυτῶν· ὃς ἐπειδὴ ἀπίκετο ἐς τοὺς Παίονας, ἔλεγε τάδε. ἄνδρες Παίονες, ἔπεμψέ με Ἀρισταγόρης ὁ Μιλήτου τύραννος σωτηρίην ὑποθησόμενον ὑμῖν, ἤν περ βούλησθε πείθεσθαι. νῦν γὰρ Ἰωνίη πᾶσα ἀπέστηκε ἀπὸ βασιλέος, καὶ ὑμῖν παρέχει σώζεσθαι ἐπὶ τὴν ὑμετέρην αὐτῶν· μέχρι μὲν θαλάσσης αὐτοῖσι ὑμῖν, τὸ δὲ ἀπὸ τούτου ἡμῖν ἤδη μελήσει. ταῦτα δὲ ἀκούσαντες οἱ Παίονες κάρτα τε ἀσπαστὸν ἐποιήσαντο καὶ ἀναλαβόντες παῖδας καὶ γυναῖκας ἀπεδίδρησκον ἐπὶ θάλασσαν, οἳ δὲ τινὲς αὐτῶν καὶ κατέμειναν ἀρρωδήσαντες αὐτοῦ. ἐπείτε δὲ οἱ Παίονες ἀπίκοντο ἐπὶ θάλασσαν, ἐνθεῦτεν ἐς Χίον διέβησαν. ἐόντων δὲ ἤδη ἐν Χίῳ, κατὰ πόδας ἐληλύθεε Περσέων ἵππος πολλὴ διώκουσα τοὺς Παίονας. ὡς δὲ οὐ κατέλαβον, ἐπηγγέλλοντο ἐς τὴν Χίον τοῖσι Παίοσι ὅκως ἂν ὀπίσω ἀπέλθοιεν. οἱ δὲ Παίονες τοὺς λόγους οὐκ ἐνεδέκοντο, ἀλλ’ ἐκ Χίου μὲν Χῖοι σφέας ἐς Λέσβον ἤγαγον, Λέσβιοι δὲ ἐς Δορίσκον ἐκόμισαν, ἐνθεῦτεν δὲ πεζῇ κομιζόμενοι ἀπίκοντο ἐς Παιονίην.", "st": "5.98"}, {"sp": "N", "t": "Ἀρισταγόρης δέ, ἐπειδὴ οἵ τε Ἀθηναῖοι ἀπίκοντο εἴκοσι νηυσί, ἅμα ἀγόμενοι Ἐρετριέων πέντε τριήρεας, οἳ οὐ τὴν Ἀθηναίων χάριν ἐστρατεύοντο ἀλλὰ τὴν αὐτῶν Μιλησίων, ὀφειλόμενά σφι ἀποδιδόντες· οἱ γὰρ δὴ Μιλήσιοι πρότερον τοῖσι Ἐρετριεῦσι τὸν πρὸς Χαλκιδέας πόλεμον συνδιήνεικαν, ὅτε περ καὶ Χαλκιδεῦσι ἀντία Ἐρετριέων καὶ Μιλησίων Σάμιοι ἐβοήθεον· οὗτοι ὦν ἐπείτε σφι ἀπίκοντο καὶ οἱ ἄλλοι σύμμαχοι παρῆσαν, ἐποιέετο στρατηίην ὁ Ἀρισταγόρης ἐς Σάρδις. αὐτὸς μὲν δὴ οὐκ ἐστρατεύετο ἀλλ’ ἔμενε ἐν Μιλήτῳ, στρατηγοὺς δὲ ἄλλους ἀπέδεξε Μιλησίων εἶναι, τὸν ἑωυτοῦ τε ἀδελφεὸν Χαροπῖνον καὶ τῶν ἀστῶν ἄλλον Ἑρμόφαντον.", "st": "5.99"}, {"sp": "N", "t": "ἀπικόμενοι δὲ τῷ στόλῳ τούτῳ Ἴωνες ἐς Ἔφεσον πλοῖα μὲν κατέλιπον ἐν Κορησῷ τῆς Ἐφεσίης, αὐτοὶ δὲ ἀνέβαινον χειρὶ πολλῇ, ποιεύμενοι Ἐφεσίους ἡγεμόνας τῆς ὁδοῦ. πορευόμενοι δὲ παρὰ ποταμὸν Καΰστριον, ἐνθεῦτεν ἐπείτε ὑπερβάντες τὸν Τμῶλον ἀπίκοντο, αἱρέουσι Σάρδις οὐδενός σφι ἀντιωθέντος, αἱρέουσι δὲ χωρὶς τῆς ἀκροπόλιος τἆλλα πάντα· τὴν δὲ ἀκρόπολιν ἐρρύετο αὐτὸς Ἀρταφρένης ἔχων ἀνδρῶν δύναμιν οὐκ ὀλίγην.", "st": "5.100"}, {"sp": "N", "t": "τὸ δὲ μὴ λεηλατῆσαι ἑλόντας σφέας τὴν πόλιν ἔσχε τόδε. ἦσαν ἐν τῇσι Σάρδισι οἰκίαι αἱ μὲν πλεῦνες καλάμιναι, ὅσαι δ’ αὐτέων καὶ πλίνθιναι ἦσαν, καλάμου εἶχον τὰς ὀροφάς· τουτέων δὴ μίαν τῶν τις στρατιωτέων ὡς ἐνέπρησε, αὐτίκα ἀπ’ οἰκίης ἐπ’ οἰκίην ἰὸν τὸ πῦρ ἐπενέμετο τὸ ἄστυ πᾶν. καιομένου δὲ τοῦ ἄστεος οἱ Λυδοί τε καὶ ὅσοι Περσέων ἐνῆσαν ἐν τῇ πόλι, ἀπολαμφθέντες πάντοθεν ὥστε τὰ περιέσχατα νεμομένου τοῦ πυρός, καὶ οὐκ ἔχοντες ἐξήλυσιν ἐκ τοῦ ἄστεος, συνέρρεον ἔς τε τὴν ἀγορὴν καὶ ἐπὶ τὸν Πακτωλὸν ποταμόν, ὅς σφι ψῆγμα χρυσοῦ καταφορέων ἐκ τοῦ Τμώλου διὰ μέσης τῆς ἀγορῆς ῥέει καὶ ἔπειτα ἐς τὸν Ἕρμον ποταμὸν ἐκδιδοῖ, ὁ δὲ ἐς θάλασσαν· ἐπὶ τοῦτον δὴ τὸν Πακτωλὸν καὶ ἐς τὴν ἀγορὴν ἀθροιζόμενοι οἵ τε Λυδοὶ καὶ οἱ Πέρσαι ἠναγκάζοντο ἀμύνεσθαι. οἱ δὲ Ἴωνες ὁρέοντες τοὺς μὲν ἀμυνομένους τῶν πολεμίων τοὺς δὲ σὺν πλήθεϊ πολλῷ προσφερομένους, ἐξανεχώρησαν δείσαντες πρὸς τὸ ὄρος τὸν Τμῶλον καλεόμενον, ἐνθεῦτεν δὲ ὑπὸ νύκτα ἀπαλλάσσοντο ἐπὶ τὰς νέας.", "st": "5.101"}, {"sp": "N", "t": "καὶ Σάρδιες μὲν ἐνεπρήσθησαν, ἐν δὲ αὐτῇσι καὶ ἱρὸν ἐπιχωρίης θεοῦ Κυβήβης· τὸ σκηπτόμενοι οἱ Πέρσαι ὕστερον ἀντενεπίμπρασαν τὰ ἐν Ἕλλησι ἱρά. τότε δὲ οἱ Πέρσαι οἱ ἐντὸς Ἅλυος ποταμοῦ νομοὺς ἔχοντες, προπυνθανόμενοι ταῦτα, συνηλίζοντο καὶ ἐβοήθεον τοῖσι Λυδοῖσι. καὶ κως ἐν μὲν Σάρδισι οὐκέτι ἐόντας τοὺς Ἴωνας εὑρίσκουσι, ἑπόμενοι δὲ κατὰ στίβον αἱρέουσι αὐτοὺς ἐν Ἐφέσῳ. καὶ ἀντετάχθησαν μὲν οἱ Ἴωνες, συμβαλόντες δὲ πολλὸν ἑσσώθησαν. καὶ πολλοὺς αὐτῶν οἱ Πέρσαι φονεύουσι ἄλλους τε ὀνομαστούς, ἐν δὲ δὴ καὶ Εὐαλκίδην στρατηγέοντα Ἐρετριέων, στεφανηφόρους τε ἀγῶνας ἀναραιρηκότα καὶ ὑπὸ Σιμωνίδεω τοῦ Κηίου πολλὰ αἰνεθέντα· οἳ δὲ αὐτῶν ἀπέφυγον τὴν μάχην, ἐσκεδάσθησαν ἀνὰ τὰς πόλιας.", "st": "5.102"}, {"sp": "N", "t": "τότε μὲν δὴ οὕτω ἠγωνίσαντο. μετὰ δὲ Ἀθηναῖοι μὲν τὸ παράπαν ἀπολιπόντες τοὺς Ἴωνας, ἐπικαλεομένου σφέας πολλὰ δι’ ἀγγέλων Ἀρισταγόρεω, οὐκ ἔφασαν τιμωρήσειν σφι· Ἴωνες δὲ τῆς Ἀθηναίων συμμαχίης στερηθέντες, οὕτω γάρ σφι ὑπῆρχε πεποιημένα ἐς Δαρεῖον, οὐδὲν δὴ ἧσσον τὸν πρὸς βασιλέα πόλεμον ἐσκευάζοντο. πλώσαντες δὲ ἐς τὸν Ἑλλήσποντον Βυζάντιόν τε καὶ τὰς ἄλλας πόλιας πάσας τὰς ταύτῃ ὑπ’ ἑωυτοῖσι ἐποιήσαντο, ἐκπλώσαντές τε ἔξω τὸν Ἑλλήσποντον Καρίης τὴν πολλὴν προσεκτήσαντο σφίσι σύμμαχον εἶναι· καὶ γὰρ τὴν Καῦνον πρότερον οὐ βουλομένην συμμαχέειν, ὡς ἐνέπρησαν τὰς Σάρδις, τότε σφι καὶ αὕτη προσεγένετο.", "st": "5.103"}, {"sp": "N", "t": "Κύπριοι δὲ ἐθελονταί σφι πάντες προσεγένοντο πλὴν Ἀμαθουσίων· ἀπέστησαν γὰρ καὶ οὗτοι ὧδε ἀπὸ Μήδων. ἦν Ὀνήσιλος Γόργου μὲν τοῦ Σαλαμινίων βασιλέος ἀδελφεὸς νεώτερος, Χέρσιος δὲ τοῦ Σιρώμου τοῦ Εὐέλθοντος παῖς. οὗτος ὡνὴρ πολλάκις μὲν καὶ πρότερον τὸν Γόργον παρηγορέετο ἀπίστασθαι ἀπὸ βασιλέος, τότε δέ, ὡς καὶ τοὺς Ἴωνας ἐπύθετο ἀπεστάναι, πάγχυ ἐπικείμενος ἐνῆγε· ὡς δὲ οὐκ ἔπειθε τὸν Γόργον, ἐνθαῦτά μιν φυλάξας ἐξελθόντα τὸ ἄστυ τὸ Σαλαμινίων ὁ Ὀνήσιλος ἅμα τοῖσι ἑωυτοῦ στασιώτῃσι ἀπεκλήισε τῶν πυλέων. Γόργος μὲν δὴ στερηθεὶς τῆς πόλιος ἔφευγε ἐς Μήδους, Ὀνήσιλος δὲ ἦρχε Σαλαμῖνος καὶ ἀνέπειθε πάντας Κυπρίους συναπίστασθαι. τοὺς μὲν δὴ ἄλλους ἀνέπεισε, Ἀμαθουσίους δὲ οὐ βουλομένους οἱ πείθεσθαι ἐπολιόρκεε προσκατήμενος.", "st": "5.104"}, {"sp": "N", "t": "Ὀνήσιλος μέν νυν ἐπολιόρκεε Ἀμαθοῦντα. βασιλέι δὲ Δαρείῳ ὡς ἐξαγγέλθη Σάρδις ἁλούσας ἐμπεπρῆσθαι ὑπό τε Ἀθηναίων καὶ Ἰώνων, τὸν δὲ ἡγεμόνα γενέσθαι τῆς συλλογῆς ὥστε ταῦτα συνυφανθῆναι τὸν Μιλήσιον Ἀρισταγόρην, πρῶτα μὲν λέγεται αὐτόν, ὡς ἐπύθετο ταῦτα, Ἰώνων οὐδένα λόγον ποιησάμενον, εὖ εἰδότα ὡς οὗτοί γε οὐ καταπροΐξονται ἀποστάντες, εἰρέσθαι οἵτινες εἶεν οἱ Ἀθηναῖοι, μετὰ δὲ πυθόμενον αἰτῆσαι τὸ τόξον, λαβόντα δὲ καὶ ἐπιθέντα δὲ ὀιστὸν ἄνω πρὸς τὸν οὐρανὸν ἀπεῖναι, καί μιν ἐς τὸν ἠέρα βάλλοντα εἰπεῖν ὦ Ζεῦ, ἐκγενέσθαι μοι Ἀθηναίους τίσασθαι, εἴπαντα δὲ ταῦτα προστάξαι ἑνὶ τῶν θεραπόντων δείπνου προκειμένου αὐτῷ ἐς τρὶς ἑκάστοτε εἰπεῖν δέσποτα, μέμνεο τῶν Ἀθηναίων.", "st": "5.105"}, {"sp": "N", "t": "προστάξας δὲ ταῦτα εἶπε, καλέσας ἐς ὄψιν Ἱστιαῖον τὸν Μιλήσιον, τὸν ὁ Δαρεῖος κατεῖχε χρόνον ἤδη πολλόν, πυνθάνομαι Ἱστιαῖε ἐπίτροπον τὸν σόν, τῷ σὺ Μίλητον ἐπέτρεψας, νεώτερα ἐς ἐμὲ πεποιηκέναι πρήγματα· ἄνδρας γάρ μοι ἐκ τῆς ἑτέρης ἠπείρου ἐπαγαγών, καὶ Ἴωνας σὺν αὐτοῖσι τοὺς δώσοντας ἐμοὶ δίκην τῶν ἐποίησαν, τούτους ἀναγνώσας ἅμα ἐκείνοισι ἕπεσθαι, Σαρδίων με ἀπεστέρησε. νῦν ὦν κῶς τοι ταῦτα φαίνεται ἔχειν καλῶς; κῶς δὲ ἄνευ τῶν σῶν βουλευμάτων τούτων τι ἐπρήχθη; ὅρα μὴ ἐξ ὑστέρης σεωυτὸν ἐν αἰτίῃ σχῇς. εἶπε πρὸς ταῦτα Ἱστιαῖος βασιλεῦ, κοῖον ἐφθέγξαο ἔπος, ἐμὲ βουλεῦσαι πρῆγμα ἐκ τοῦ σοί τι ἢ μέγα ἢ σμικρὸν ἔμελλε λυπηρὸν ἀνασχήσειν; τί δ’ ἂν ἐπιδιζήμενος ποιέοιμι ταῦτα, τεῦ δὲ ἐνδεὴς ἐών; τῷ πάρα μὲν πάντα ὅσα περ σοί, πάντων δὲ πρὸς σέο βουλευμάτων ἐπακούειν ἀξιοῦμαι. ἀλλ’ εἴ περ τι τοιοῦτον οἷον σὺ εἴρηκας πρήσσει ὁ ἐμὸς ἐπίτροπος, ἴσθι αὐτὸν ἐπ’ ἑωυτοῦ βαλόμενον πεποιηκέναι. ἀρχὴν δὲ ἔγωγε οὐδὲ ἐνδέκομαι τὸν λόγον, ὅκως τι Μιλήσιοι καὶ ὁ ἐμὸς ἐπίτροπος νεώτερον πρήσσουσι περὶ πρήγματα τὰ σά. εἰ δ’ ἄρα τι τοιοῦτο ποιεῦσι καὶ σὺ τὸ ἐὸν ἀκήκοας ὦ βασιλεῦ, μάθε οἷον πρῆγμα ἐργάσαο ἐμὲ ἀπὸ θαλάσσης ἀνάσπαστον ποιήσας. Ἴωνες γὰρ οἴκασι ἐμεῦ ἐξ ὀφθαλμῶν σφι γενομένου ποιῆσαι τῶν πάλαι ἵμερον εἶχον· ἐμέο δ’ ἂν ἐόντος ἐν Ἰωνίῃ οὐδεμία πόλις ὑπεκίνησε. νῦν ὦν ὡς τάχος ἄπες με πορευθῆναι ἐς Ἰωνίην, ἵνα τοι κεῖνά τε πάντα καταρτίσω ἐς τὠυτὸ καὶ τὸν Μιλήτου ἐπίτροπον τοῦτον τὸν ταῦτα μηχανησάμενον ἐγχειρίθετον παραδῶ. ταῦτα δὲ κατὰ νόον τὸν σὸν ποιήσας, θεοὺς ἐπόμνυμι τοὺς βασιληίους μὴ μὲν πρότερον ἐκδύσασθαι τὸν ἔχων κιθῶνα καταβήσομαι ἐς Ἰωνίην, πρὶν ἄν τοι Σαρδὼ νῆσον τὴν μεγίστην δασμοφόρον ποιήσω.", "st": "5.106"}, {"sp": "N", "t": "Ἱστιαῖος μὲν λέγων ταῦτα διέβαλλε, Δαρεῖος δὲ ἐπείθετο καί μιν ἀπίει, ἐντειλάμενος, ἐπεὰν τὰ ὑπέσχετό οἱ ἐπιτελέα ποιήσῃ, παραγίνεσθαί οἱ ὀπίσω ἐς τὰ Σοῦσα.", "st": "5.107"}, {"sp": "N", "t": "ἐν ᾧ δὲ ἡ ἀγγελίη τε περὶ τῶν Σαρδίων παρὰ βασιλέα ἀνήιε καὶ Δαρεῖος τὰ περὶ τὸ τόξον ποιήσας Ἱστιαίῳ ἐς λόγους ἦλθε καὶ Ἱστιαῖος μεμετιμένος ὑπὸ Δαρείου ἐκομίζετο ἐπὶ θάλασσαν, ἐν τούτῳ παντὶ τῷ χρόνῳ ἐγίνετο τάδε. πολιορκέοντι τῷ Σαλαμινίῳ Ὀνησίλῳ Ἀμαθουσίους ἐξαγγέλλεται νηυσὶ στρατιὴν πολλὴν ἄγοντα Περσικὴν Ἀρτύβιον ἄνδρα Πέρσην προσδόκιμον ἐς τὴν Κύπρον εἶναι· πυθόμενος δὲ ταῦτα ὁ Ὀνήσιλος κήρυκας διέπεμπε ἐς τὴν Ἰωνίην ἐπικαλεύμενος σφέας, Ἴωνες δὲ οὐκ ἐς μακρὴν βουλευσάμενοι ἧκον πολλῷ στόλῳ. Ἴωνές τε δὴ παρῆσαν ἐς τὴν Κύπρον καὶ οἱ Πέρσαι νηυσὶ διαβάντες ἐκ τῆς Κιλικίης ἤισαν ἐπὶ τὴν Σαλαμῖνα πεζῇ. τῇσι δὲ νηυσὶ οἱ Φοίνικες περιέπλεον τὴν ἄκρην αἳ καλεῦνται Κληῖδες τῆς Κύπρου.", "st": "5.108"}, {"sp": "N", "t": "τούτου δὲ τοιούτου γινομένου ἔλεξαν οἱ τύραννοι τῆς Κύπρου, συγκαλέσαντες τῶν Ἰώνων τοὺς στρατηγούς, ἄνδρες Ἴωνες, αἵρεσιν ὑμῖν δίδομεν ἡμεῖς οἱ Κύπριοι ὁκοτέροισι βούλεσθε προσφέρεσθαι, ἢ Πέρσῃσι ἢ Φοίνιξι. εἰ μὲν γὰρ πεζῇ βούλεσθε ταχθέντες Περσέων διαπειρᾶσθαι, ὥρη ἂν εἴη ὑμῖν ἐκβάντας ἐκ τῶν νεῶν τάσσεσθαι πεζῇ, ἡμέας δὲ ἐς τὰς νέας ἐσβαίνειν τὰς ὑμετέρας Φοίνιξι ἀνταγωνιευμένους· εἰ δὲ Φοινίκων μᾶλλον βούλεσθε διαπειρᾶσθαι, ποιέειν χρεόν ἐστι ὑμέας, ὁκότερα ἂν δὴ τούτων ἕλησθε, ὅκως τὸ κατ’ ὑμέας ἔσται ἥ τε Ἰωνίη καὶ ἡ Κύπρος ἐλευθέρη. εἶπαν Ἴωνες πρὸς ταῦτα ἡμέας δὲ ἀπέπεμψε τὸ κοινὸν τῶν Ἰώνων φυλάξοντας τὴν θάλασσαν, ἀλλ’ οὐκ ἵνα Κυπρίοισι τὰς νέας παραδόντες αὐτοὶ πεζῇ Πέρσῃσι προσφερώμεθα. ἡμεῖς μέν νυν ἐπ’ οὗ ἐτάχθημεν, ταύτῃ πειρησόμεθα εἶναι χρηστοί· ὑμέας δὲ χρεόν ἐστι ἀναμνησθέντας οἷα ἐπάσχετε δουλεύοντες πρὸς τῶν Μήδων, γίνεσθαι ἄνδρας ἀγαθούς.", "st": "5.109"}, {"sp": "N", "t": "Ἴωνες μὲν τούτοισι ἀμείψαντο· μετὰ δὲ ἡκόντων ἐς τὸ πεδίον τὸ Σαλαμινίων τῶν Περσέων, διέτασσον οἱ βασιλέες τῶν Κυπρίων, τοὺς μὲν ἄλλους Κυπρίους κατὰ τοὺς ἄλλους στρατιώτας ἀντιτάσσοντες, Σαλαμινίων δὲ καὶ Σολίων ἀπολέξαντες τὸ ἄριστον ἀντέτασσον Πέρσῃσι· Ἀρτυβίῳ δὲ τῷ στρατηγῷ τῶν Περσέων ἐθελοντὴς ἀντετάσσετο Ὀνήσιλος.", "st": "5.110"}, {"sp": "N", "t": "ἤλαυνε δὲ ἵππον ὁ Ἀρτύβιος δεδιδαγμένον πρὸς ὁπλίτην ἵστασθαι ὀρθόν. πυθόμενος ὦν ταῦτα ὁ Ὀνήσιλος, ἦν γάρ οἱ ὑπασπιστὴς γένος μὲν Κὰρ τὰ δὲ πολέμια κάρτα δόκιμος καὶ ἄλλως λήματος πλέος, εἶπε πρὸς τοῦτον πυνθάνομαι τὸν Ἀρτυβίου ἵππον ἱστάμενον ὀρθὸν καὶ ποσὶ καὶ στόματι κατεργάζεσθαι πρὸς τὸν ἂν προσενειχθῇ· σὺ ὦν βουλευσάμενος εἰπὲ αὐτίκα ὁκότερον βούλεαι φυλάξας πλῆξαι, εἴτε τὸν ἵππον εἴτε αὐτὸν Ἀρτύβιον. εἶπε πρὸς ταῦτα ὁ ὀπάων αὐτοῦ ὦ βασιλεῦ, ἕτοιμος μὲν ἐγώ εἰμι ποιέειν καὶ ἀμφότερα καὶ τὸ ἕτερον αὐτῶν, καὶ πάντως τὸ ἂν σὺ ἐπιτάσσῃς· ὡς μέντοι ἔμοιγε δοκέει εἶναι τοῖσι σοῖσι πρήγμασι προσφερέστερον, φράσω. βασιλέα μὲν καὶ στρατηγὸν χρεὸν εἶναι φημὶ βασιλέι τε καὶ στρατηγῷ προσφέρεσθαι. ἤν τε γὰρ κατέλῃς ἄνδρα στρατηγόν, μέγα τοι γίνεται, καὶ δεύτερα, ἢν σὲ ἐκεῖνος, τὸ μὴ γένοιτο, ὑπὸ ἀξιοχρέου καὶ ἀποθανεῖν ἡμίσεα συμφορή· ἡμέας δὲ τοὺς ὑπηρέτας ἑτέροισί τε ὑπηρέτῃσι προσφέρεσθαι καὶ πρὸς ἵππον· τοῦ σὺ τὰς μηχανὰς μηδὲν φοβηθῇς· ἐγὼ γάρ τοι ὑποδέκομαι μή μιν ἀνδρὸς ἔτι γε μηδενὸς στήσεσθαι ἐναντίον.", "st": "5.111"}, {"sp": "N", "t": "ταῦτα εἶπε, καὶ μεταυτίκα συνέμισγε τὰ στρατόπεδα πεζῇ καὶ νηυσί. νηυσὶ μέν νυν Ἴωνες ἄκροι γενόμενοι ταύτην τὴν ἡμέρην ὑπερεβάλοντο τοὺς Φοίνικας, καὶ τούτων Σάμιοι ἠρίστευσαν· πεζῇ δέ, ὡς συνῆλθε τὰ στρατόπεδα, συμπεσόντα ἐμάχοντο. κατὰ δὲ τοὺς στρατηγοὺς ἀμφοτέρους τάδε ἐγίνετο· ὡς προσεφέρετο πρὸς τὸν Ὀνήσιλον ὁ Ἀρτύβιος ἐπὶ τοῦ ἵππου κατήμενος, ὁ Ὀνήσιλος κατὰ τὰ συνεθήκατο τῷ ὑπασπιστῇ παίει προσφερόμενον αὐτὸν τὸν Ἀρτύβιον· ἐπιβαλόντος δὲ τοῦ ἵππου τοὺς πόδας ἐπὶ τὴν Ὀνησίλου ἀσπίδα, ἐνθαῦτα ὁ Κὰρ δρεπάνῳ πλήξας ἀπαράσσει τοῦ ἵππου τοὺς πόδας.", "st": "5.112"}, {"sp": "N", "t": "Ἀρτύβιος μὲν δὴ ὁ στρατηγὸς τῶν Περσέων ὁμοῦ τῷ ἵππῳ πίπτει αὐτοῦ ταύτῃ. μαχομένων δὲ καὶ τῶν ἄλλων, Στησήνωρ τύραννος ἐὼν Κουρίου προδιδοῖ ἔχων δύναμιν ἀνδρῶν περὶ ἑωυτὸν οὐ σμικρήν. οἱ δὲ Κουριέες οὗτοι λέγονται εἶναι Ἀργείων ἄποικοι. προδόντων δὲ τῶν Κουριέων αὐτίκα καὶ τὰ Σαλαμινίων πολεμιστήρια ἅρματα τὠυτὸ τοῖσι Κουριεῦσι ἐποίεε. γινομένων δὲ τούτων κατυπέρτεροι ἦσαν οἱ Πέρσαι τῶν Κυπρίων. τετραμμένου δὲ τοῦ στρατοπέδου ἄλλοι τε ἔπεσον πολλοὶ καὶ δὴ καὶ Ὀνήσιλός τε ὁ Χέρσιος, ὅς περ τὴν Κυπρίων ἀπόστασιν ἔπρηξε, καὶ ὁ Σολίων βασιλεὺς Ἀριστόκυπρος ὁ Φιλοκύπρου, Φιλοκύπρου δὲ τούτου τὸν Σόλων ὁ Ἀθηναῖος ἀπικόμενος ἐς Κύπρον ἐν ἔπεσι αἴνεσε τυράννων μάλιστα.", "st": "5.113"}, {"sp": "N", "t": "Ὀνησίλου μέν νυν Ἀμαθούσιοι, ὅτι σφέας ἐπολιόρκησε, ἀποταμόντες τὴν κεφαλὴν ἐκόμισαν ἐς Ἀμαθοῦντα καί μιν ἀνεκρέμασαν ὑπὲρ τῶν πυλέων· κρεμαμένης δὲ τῆς κεφαλῆς καὶ ἤδη ἐούσης κοίλης, ἐσμὸς μελισσέων ἐσδὺς ἐς αὐτὴν κηρίων μιν ἐνέπλησε. τούτου δὲ γενομένου τοιούτου, ἐχρέωντο γὰρ περὶ αὐτῆς οἱ Ἀμαθούσιοι, ἐμαντεύθη σφι τὴν μὲν κεφαλὴν κατελόντας θάψαι, Ὀνησίλῳ δὲ θύειν ὡς ἥρωϊ ἀνὰ πᾶν ἔτος, καί σφι ποιεῦσι ταῦτα ἄμεινον συνοίσεσθαι.", "st": "5.114"}, {"sp": "N", "t": "Ἀμαθούσιοι μέν νυν ἐποίευν ταῦτα καὶ τὸ μέχρι ἐμεῦ· Ἴωνες δὲ οἱ ἐν Κύπρῳ ναυμαχήσαντες ἐπείτε ἔμαθον τὰ πρήγματα τὰ Ὀνησίλου διεφθαρμένα καὶ τὰς πόλις τῶν Κυπρίων πολιορκευμένας τὰς ἄλλας πλὴν Σαλαμῖνος, ταύτην δὲ Γόργῳ τῷ προτέρῳ βασιλέι τοὺς Σαλαμινίους παραδόντας, αὐτίκα μαθόντες οἱ Ἴωνες ταῦτα ἀπέπλεον ἐς τὴν Ἰωνίην. τῶν δὲ ἐν Κύπρῳ πολίων ἀντέσχε χρόνον ἐπὶ πλεῖστον πολιορκευμένη Σόλοι, τὴν πέριξ ὑπορύσσοντες τὸ τεῖχος πέμπτῳ μηνὶ εἷλον οἱ Πέρσαι.", "st": "5.115"}, {"sp": "N", "t": "Κύπριοι μὲν δὴ ἐνιαυτὸν ἐλεύθεροι γενόμενοι αὖτις ἐκ νέης κατεδεδούλωντο. Δαυρίσης δὲ ἔχων Δαρείου θυγατέρα καὶ Ὑμαίης τε καὶ Ὀτάνης ἄλλοι Πέρσαι στρατηγοί, ἔχοντες καὶ οὗτοι Δαρείου θυγατέρας, ἐπιδιώξαντες τοὺς ἐς Σάρδις στρατευσαμένους Ἰώνων καὶ ἐσαράξαντες σφέας ἐς τὰς νέας, τῇ μάχῃ ὡς ἐπεκράτησαν, τὸ ἐνθεῦτεν ἐπιδιελόμενοι τὰς πόλις ἐπόρθεον.", "st": "5.116"}, {"sp": "N", "t": "Δαυρίσης μὲν τραπόμενος πρὸς τὰς ἐν Ἑλλησπόντῳ πόλις εἷλε μὲν Δάρδανον, εἷλε δὲ Ἄβυδόν τε καὶ Περκώτην καὶ Λάμψακον καὶ Παισόν. ταύτας μὲν ἐπ’ ἡμέρῃ ἑκάστῃ αἵρεε, ἀπὸ δὲ Παισοῦ ἐλαύνοντί οἱ ἐπὶ Πάριον πόλιν ἦλθε ἀγγελίη τοὺς Κᾶρας τὠυτὸ Ἴωσι φρονήσαντας ἀπεστάναι ἀπὸ Περσέων. ἀποστρέψας ὦν ἐκ τοῦ Ἑλλησπόντου ἤλαυνε τὸν στρατὸν ἐπὶ τὴν Καρίην. καί κως ταῦτα τοῖσι Καρσὶ ἐξαγγέλθη πρότερον ἢ τὸν Δαυρίσην ἀπικέσθαι· πυθόμενοι δὲ οἱ Κᾶρες συνελέγοντο ἐπὶ Λευκάς τε στήλας καλεομένας καὶ ποταμὸν Μαρσύην, ὃς ῥέων ἐκ τῆς Ἰδριάδος χώρης ἐς τὸν Μαίανδρον ἐκδιδοῖ. συλλεχθέντων δὲ τῶν Καρῶν ἐνθαῦτα ἐγίνοντο βουλαὶ ἄλλαι τε πολλαὶ καὶ ἀρίστη γε δοκέουσα εἶναι ἐμοὶ Πιξωδάρου τοῦ Μαυσώλου ἀνδρὸς Κινδυέος, ὃς τοῦ Κιλίκων βασιλέος Συεννέσιος εἶχε θυγατέρα· τούτου τοῦ ἀνδρὸς ἡ γνώμη ἔφερε διαβάντας τὸν Μαίανδρον τοὺς Κᾶρας καὶ κατὰ νώτου ἔχοντας τὸν ποταμὸν οὕτω συμβάλλειν, ἵνα μὴ ἔχοντες ὀπίσω φεύγειν οἱ Κᾶρες αὐτοῦ τε μένειν ἀναγκαζόμενοι γινοίατο ἔτι ἀμείνονες τῆς φύσιος. αὕτη μέν νυν οὐκ ἐνίκα ἡ γνώμη, ἀλλὰ τοῖσι Πέρσῃσι κατὰ νώτου γίνεσθαι τὸν Μαίανδρον μᾶλλον ἢ σφίσι, δηλαδὴ ἢν φυγὴ τῶν Περσέων γένηται καὶ ἑσσωθέωσι τῇ συμβολῇ, ὡς οὐκ ἀπονοστήσουσι ἐς τὸν ποταμὸν ἐσπίπτοντες.", "st": "5.117"}, {"sp": "N", "t": "μετὰ δὲ παρεόντων καὶ διαβάντων τὸν Μαίανδρον τῶν Περσέων, ἐνθαῦτα ἐπὶ τῷ Μαρσύῃ ποταμῷ συνέβαλόν τε τοῖσι Πέρσῃσι οἱ Κᾶρες καὶ μάχην ἐμαχέσαντο ἰσχυρὴν καὶ ἐπὶ χρόνον πολλόν, τέλος δὲ ἑσσώθησαν διὰ πλῆθος. Περσέων μὲν δὴ ἔπεσον ἄνδρες ἐς δισχιλίους, Καρῶν δὲ ἐς μυρίους. ἐνθεῦτεν δὲ οἱ διαφυγόντες αὐτῶν κατειλήθησαν ἐς Λάβραυνδα ἐς Διὸς στρατίου ἱρόν, μέγα τε καὶ ἅγιον ἄλσος πλατανίστων. μοῦνοι δὲ τῶν ἡμεῖς ἴδμεν Κᾶρες εἰσὶ οἳ Διὶ στρατίῳ θυσίας ἀνάγουσι. κατειληθέντες δὲ ὦν οὗτοι ἐνθαῦτα ἐβουλεύοντο περὶ σωτηρίης, ὁκότερα ἢ παραδόντες σφέας αὐτοὺς Πέρσῃσι ἢ ἐκλιπόντες τὸ παράπαν τὴν Ἀσίην ἄμεινον πρήξουσι.", "st": "5.119"}, {"sp": "N", "t": "βουλευομένοισι δέ σφι ταῦτα παραγίνονται βοηθέοντες Μιλήσιοί τε καὶ οἱ τούτων σύμμαχοι· ἐνθαῦτα δὲ τὰ μὲν πρότερον οἱ Κᾶρες ἐβουλεύοντο μετῆκαν, οἳ δὲ αὖτις πολεμέειν ἐξ ἀρχῆς ἀρτέοντο. καὶ ἐπιοῦσί τε τοῖσι Πέρσῃσι συμβάλλουσι καὶ μαχεσάμενοι ἐπὶ πλέον ἢ πρότερον ἑσσώθησαν· πεσόντων δὲ τῶν πάντων πολλῶν μάλιστα Μιλήσιοι ἐπλήγησαν.", "st": "5.120"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο τὸ τρῶμα ἀνέλαβόν τε καὶ ἀνεμαχέσαντο οἱ Κᾶρες· πυθόμενοι γὰρ ὡς στρατεύεσθαι ὁρμέαται οἱ Πέρσαι ἐπὶ τὰς πόλις σφέων, ἐλόχησαν τὴν ἐν Πηδάσῳ ὁδόν, ἐς τὴν ἐμπεσόντες οἱ Πέρσαι νυκτὸς διεφθάρησαν καὶ αὐτοὶ καὶ οἱ στρατηγοὶ αὐτῶν Δαυρίσης καὶ Ἀμόργης καὶ Σισιμάκης· σὺν δέ σφι ἀπέθανε καὶ Μύρσος ὁ Γύγεω. τοῦ δὲ λόχου τούτου ἡγεμὼν ἦν Ἡρακλείδης Ἰβανώλλιος ἀνὴρ Μυλασσεύς.", "st": "5.121"}, {"sp": "N", "t": "οὗτοι μέν νυν τῶν Περσέων οὕτω διεφθάρησαν· Ὑμαίης δὲ καὶ αὐτὸς ἐὼν τῶν ἐπιδιωξάντων τοὺς ἐς Σάρδις στρατευσαμένους Ἰώνων, τραπόμενος ἐς τὸν Προποντίδα εἷλε Κίον τὴν Μυσίην· ταύτην δὲ ἐξελών, ὡς ἐπύθετο τὸν Ἑλλήσποντον ἐκλελοιπέναι Δαυρίσην καὶ στρατεύεσθαι ἐπὶ Καρίης, καταλιπὼν τὴν Προποντίδα ἐπὶ τὸν Ἑλλήσποντον ἦγε τὸν στρατόν, καὶ εἷλε μὲν Αἰολέας πάντας ὅσοι τὴν Ἰλιάδα νέμονται, εἷλε δὲ Γέργιθας τοὺς ὑπολειφθέντας τῶν ἀρχαίων Τευκρῶν· αὐτός τε Ὑμαίης αἱρέων ταῦτα τὰ ἔθνεα νούσῳ τελευτᾷ ἐν τῇ Τρῳάδι.", "st": "5.122"}, {"sp": "N", "t": "οὗτος μὲν δὴ οὕτω ἐτελεύτησε, Ἀρταφρένης δὲ ὁ Σαρδίων ὕπαρχος καὶ Ὀτάνης ὁ τρίτος στρατηγὸς ἐτάχθησαν ἐπὶ τὴν Ἰωνίην καὶ τὴν προσεχέα Αἰολίδα στρατεύεσθαι. Ἰωνίης μέν νυν Κλαζομενὰς αἱρέουσι, Αἰολέων δὲ Κύμην.", "st": "5.123"}, {"sp": "N", "t": "ἁλισκομενέων δὲ τῶν πολίων, ἦν γὰρ ὡς διέδεξε Ἀρισταγόρης ὁ Μιλήσιος ψυχὴν οὐκ ἄκρος, ὃς ταράξας τὴν Ἰωνίην καὶ ἐγκερασάμενος πρήγματα μεγάλα δρησμὸν ἐβούλευε ὁρέων ταῦτα· πρὸς δέ οἱ καὶ ἀδύνατα ἐφάνη βασιλέα Δαρεῖον ὑπερβαλέσθαι· πρὸς ταῦτα δὴ ὦν συγκαλέσας τοὺς συστασιώτας ἐβουλεύετο, λέγων ὡς ἄμεινον σφίσι εἴη κρησφύγετόν τι ὑπάρχον εἶναι, ἢν ἄρα ἐξωθέωνται ἐκ τῆς Μιλήτου, εἴτε δὴ ὦν ἐς Σαρδὼ ἐκ τοῦ τόπου τούτου ἄγοι ἐς ἀποικίην, εἴτε ἐς Μύρκινον τὴν Ἠδωνῶν, τὴν Ἱστιαῖος ἐτείχεε παρὰ Δαρείου δωρεὴν λαβών. ταῦτα ἐπειρώτα ὁ Ἀρισταγόρης.", "st": "5.124"}, {"sp": "N", "t": "Ἑκαταίου μέν νυν τοῦ Ἡγησάνδρου, ἀνδρὸς λογοποιοῦ, τουτέων μὲν ἐς οὐδετέρην στέλλειν ἔφερε ἡ γνώμη, ἐν Λέρῳ δὲ τῇ νήσῳ τεῖχος οἰκοδομησάμενον ἡσυχίην ἄγειν, ἢν ἐκπέσῃ ἐκ τῆς Μιλήτου· ἔπειτα δὲ ἐκ ταύτης ὁρμώμενον κατελεύσεσθαι ἐς τὴν Μίλητον.", "st": "5.125"}, {"sp": "N", "t": "ταῦτα μὲν δὴ Ἑκαταῖος συνεβούλευε, αὐτῷ δὲ Ἀρισταγόρῃ ἡ πλείστη γνώμη ἦν ἐς τὴν Μύρκινον ἀπάγειν. τὴν μὲν δὴ Μίλητον ἐπιτράπει Πυθαγόρῃ ἀνδρὶ τῶν ἀστῶν δοκίμῳ, αὐτὸς δὲ παραλαβὼν πάντα τὸν βουλόμενον ἔπλεε ἐς τὴν Θρηίκην, καὶ ἔσχε τὴν χώρην ἐπ’ ἣν ἐστάλη·", "st": "5.126"}, {"sp": "N", "t": "ἐκ δὲ ταύτης ὁρμώμενος ἀπόλλυται ὑπὸ Θρηίκων αὐτός τε ὁ Ἀρισταγόρης καὶ ὁ στρατὸς αὐτοῦ, πόλιν περικατήμενος καὶ βουλομένων τῶν Θρηίκων ὑποσπόνδων ἐξιέναι.", "st": "5.126.2"}, {"sp": "HDR", "t": "Ἱστοριῶν Ϛ· Ἐρατώ", "st": "6"}, {"sp": "N", "t": "Ἀρισταγόρης μέν νυν Ἰωνίην ἀποστήσας οὕτω τελευτᾷ. Ἱστιαῖος δὲ ὁ Μιλήτου τύραννος μεμετιμένος ὑπὸ Δαρείου παρῆν ἐς Σάρδις· ἀπιγμένον δὲ αὐτὸν ἐκ τῶν Σούσων εἴρετο Ἀρταφρένης ὁ Σαρδίων ὕπαρχος κατὰ κοῖόν τι δοκέοι Ἴωνας ἀπεστάναι. ὁ δὲ οὔτε εἰδέναι ἔφη ἐθώμαζέ τε τὸ γεγονός, ὡς οὐδὲν δῆθεν τῶν παρεόντων πρηγμάτων ἐπιστάμενος. ὁ δὲ Ἀρταφρένης ὁρέων αὐτὸν τεχνάζοντα εἶπε, εἰδὼς τὴν ἀτρεκείην τῆς ἀποστάσιος, οὕτω τοι Ἱστιαῖε ἔχει κατὰ ταῦτα τὰ πρήγματα· τοῦτο τὸ ὑπόδημα ἔρραψας μὲν σύ, ὑπεδήσατο δὲ Ἀρισταγόρης.", "st": "6.1"}, {"sp": "N", "t": "Ἀρταφρένης μὲν ταῦτα ἐς τὴν ἀπόστασιν ἔχοντα εἶπε. Ἱστιαῖος δὲ δείσας ὡς συνιέντα Ἀρταφρένεα ὑπὸ τὴν πρώτην ἐπελθοῦσαν νύκτα ἀπέδρη ἐπὶ θάλασσαν, βασιλέα Δαρεῖον ἐξηπατηκώς· ὃς Σαρδὼ νῆσον τὴν μεγίστην ὑποδεξάμενος κατεργάσασθαι ὑπέδυνε τῶν Ἰώνων τὴν ἡγεμονίην τοῦ πρὸς Δαρεῖον πολέμου. διαβὰς δὲ ἐς Χίον ἐδέθη ὑπὸ Χίων, καταγνωσθεὶς πρὸς αὐτῶν νεώτερα πρήσσειν πρήγματα ἐς αὐτοὺς ἐκ Δαρείου. μαθόντες μέντοι οἱ Χῖοι τὸν πάντα λόγον, ὡς πολέμιος εἴη βασιλέι, ἔλυσαν αὐτόν.", "st": "6.2"}, {"sp": "N", "t": "ἐνθαῦτα δὴ εἰρωτώμενος ὑπὸ τῶν Ἰώνων ὁ Ἱστιαῖος κατ’ ὅ τι προθύμως οὕτω ἐπέστειλε τῷ Ἀρισταγόρῃ ἀπίστασθαι ἀπὸ βασιλέος καὶ κακὸν τοσοῦτον εἴη Ἴωνας ἐξεργασμένος, τὴν μὲν γενομένην αὐτοῖσι αἰτίην οὐ μάλα ἐξέφαινε, ὁ δὲ ἔλεγέ σφι ὡς βασιλεὺς Δαρεῖος ἐβουλεύσατο Φοίνικας μὲν ἐξαναστήσας ἐν τῇ Ἰωνίῃ κατοικίσαι, Ἴωνας δὲ ἐν τῇ Φοινίκῃ, καὶ τούτων εἵνεκα ἐπιστείλειε. οὐδέν τι πάντως ταῦτα βασιλέος βουλευσαμένου ἐδειμάτου τοὺς Ἴωνας.", "st": "6.3"}, {"sp": "N", "t": "μετὰ δὲ ὁ Ἱστιαῖος δι’ ἀγγέλου ποιεύμενος Ἑρμίππου ἀνδρὸς Ἀταρνίτεω τοῖσι ἐν Σάρδισι ἐοῦσι Περσέων ἔπεμπε βυβλία, ὡς προλελεσχηνευμένων αὐτῷ ἀποστάσιος πέρι. ὁ δὲ Ἕρμιππος πρὸς τοὺς μὲν ἀπεπέμφθη οὐ διδοῖ, φέρων δὲ ἐνεχείρισε τὰ βυβλία Ἀρταφρένεϊ· ὁ δὲ μαθὼν πᾶν τὸ γινόμενον ἐκέλευε τὸν Ἕρμιππον τὰ μὲν παρὰ τοῦ Ἱστιαίου δοῦναι φέροντα τοῖσί περ ἔφερε, τὰ δὲ ἀμοιβαῖα τὰ παρὰ τῶν Περσέων ἀντιπεμπόμενα Ἱστιαίῳ ἑωυτῷ δοῦναι. τούτων δὲ γενομένων φανερῶν ἀπέκτεινε ἐνθαῦτα πολλοὺς Περσέων ὁ Ἀρταφρένης.", "st": "6.4"}, {"sp": "N", "t": "περὶ Σάρδις μὲν δὴ ἐγίνετο ταραχή. Ἱστιαῖον δὲ ταύτης ἀποσφαλέντα τῆς ἐλπίδος Χῖοι κατῆγον ἐς Μίλητον, αὐτοῦ Ἱστιαίου δεηθέντος. οἱ δὲ Μιλήσιοι, ἄσμενοι ἀπαλλαχθέντες καὶ Ἀρισταγόρεω, οὐδαμῶς πρόθυμοι ἦσαν ἄλλον τύραννον δέκεσθαι ἐς τὴν χώρην, οἷα ἐλευθερίης γευσάμενοι. καὶ δὴ νυκτὸς γὰρ ἐούσης βίῃ ἐπειρᾶτο κατιὼν ὁ Ἱστιαῖος ἐς τὴν Μίλητον, τιτρώσκεται τὸν μηρὸν ὑπό τευ τῶν Μιλησίων. ὃ μὲν δὴ ὡς ἀπωστὸς τῆς ἑωυτοῦ γίνεται, ἀπικνέεται ὀπίσω ἐς τὴν Χίον· ἐνθεῦτεν δέ, οὐ γὰρ ἔπειθε τοὺς Χίους ὥστε ἑωυτῷ δοῦναι νέας, διέβη ἐς Μυτιλήνην καὶ ἔπεισε Λεσβίους δοῦναί οἱ νέας. οἳ δὲ πληρώσαντες ὀκτὼ τριήρεας ἔπλεον ἅμα Ἱστιαίῳ ἐς Βυζάντιον, ἐνθαῦτα δὲ ἱζόμενοι τὰς ἐκ τοῦ Πόντου ἐκπλεούσας τῶν νεῶν ἐλάμβανον, πλὴν ἢ ὅσοι αὐτῶν Ἱστιαίῳ ἔφασαν ἕτοιμοι εἶναι πείθεσθαι.", "st": "6.5"}, {"sp": "N", "t": "Ἱστιαῖος μέν νυν καὶ Μυτιληναῖοι ἐποίευν ταῦτα. ἐπὶ δὲ Μίλητον αὐτὴν ναυτικὸς πολλὸς καὶ πεζὸς ἦν στρατὸς προσδόκιμος· συστραφέντες γὰρ οἱ στρατηγοὶ τῶν Περσέων καὶ ἓν ποιήσαντες στρατόπεδον ἤλαυνον ἐπὶ τὴν Μίλητον, τἆλλα πολίσματα περὶ ἐλάσσονος ποιησάμενοι. τοῦ δὲ ναυτικοῦ Φοίνικες μὲν ἦσαν προθυμότατοι, συνεστρατεύοντο δὲ καὶ Κύπριοι νεωστὶ κατεστραμμένοι καὶ Κίλικές τε καὶ Αἰγύπτιοι.", "st": "6.6"}, {"sp": "N", "t": "οἳ μὲν δὴ ἐπὶ τὴν Μίλητον καὶ τὴν ἄλλην Ἰωνίην ἐστρατεύοντο, Ἴωνες δὲ πυνθανόμενοι ταῦτα ἔπεμπον προβούλους σφέων αὐτῶν ἐς Πανιώνιον. ἀπικομένοισι δὲ τούτοισι ἐς τοῦτον τὸν χῶρον καὶ βουλευομένοισι ἔδοξε πεζὸν μὲν στρατὸν μηδένα συλλέγειν ἀντίξοον Πέρσῃσι, ἀλλὰ τὰ τείχεα ῥύεσθαι αὐτοὺς Μιλησίους, τὸ δὲ ναυτικὸν πληροῦν ὑπολιπομένους μηδεμίαν τῶν νεῶν πληρώσαντας δὲ συλλέγεσθαι τὴν ταχίστην ἐς Λάδην προναυμαχήσοντας τῆς Μιλήτου. ἡ δὲ Λάδη ἐστὶ νῆσος μικρὴ ἐπὶ τῇ πόλι τῇ Μιλησίων κειμένη.", "st": "6.7"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα πεπληρωμένῃσι τῇσι νηυσὶ παρῆσαν οἱ Ἴωνες, σὺν δέ σφι καὶ Αἰολέων ὅσοι τὴν Λέσβον νέμονται. ἐτάσσοντο δὲ ὧδε. τὸ μὲν πρὸς τὴν ἠῶ εἶχον κέρας αὐτοὶ Μιλήσιοι, νέας παρεχόμενοι ὀγδώκοντα· εἴχοντο δὲ τούτων Πριηνέες δυώδεκα νηυσὶ καὶ Μυήσιοι τρισὶ νηυσί, Μυησίων δὲ Τήιοι εἴχοντο ἑπτακαίδεκα νηυσί, Τηίων δὲ εἴχοντο Χῖοι ἑκατὸν νηυσί· πρὸς δὲ τούτοισι Ἐρυθραῖοί τε ἐτάσσοντο καὶ Φωκαέες, Ἐρυθραῖοι μὲν ὀκτὼ νέας παρεχόμενοι, Φωκαέες δὲ τρεῖς· Φωκαέων δὲ εἴχοντο Λέσβιοι νηυσὶ ἑβδομήκοντα· τελευταῖοι δὲ ἐτάσσοντο ἔχοντες τὸ πρὸς ἑσπέρην κέρας Σάμιοι ἑξήκοντα νηυσί. πάντων δὲ τούτων ὁ σύμπας ἀριθμὸς ἐγένετο τρεῖς καὶ πεντήκοντα καὶ τριηκόσιαι τριήρεες.", "st": "6.8"}, {"sp": "N", "t": "αὗται μὲν Ἰώνων ἦσαν, τῶν δὲ βαρβάρων τὸ πλῆθος τῶν νεῶν ἦσαν ἑξακόσιαι. ὡς δὲ καὶ αὗται ἀπίκατο πρὸς τὴν Μιλησίην καὶ ὁ πεζός σφι ἅπας παρῆν, ἐνθαῦτα οἱ Περσέων στρατηγοὶ πυθόμενοι τὸ πλῆθος τῶν Ἰάδων νεῶν καταρρώδησαν μὴ οὐ δυνατοὶ γένωνται ὑπερβαλέσθαι, καὶ οὕτω οὔτε τὴν Μίλητον οἷοί τε ἔωσι ἐξελεῖν μὴ οὐκ ἐόντες ναυκράτορες, πρός τε Δαρείου κινδυνεύσωσι κακόν τι λαβεῖν. ταῦτα ἐπιλεγόμενοι, συλλέξαντες τῶν Ἰώνων τοὺς τυράννους, οἳ ὑπ’ Ἀρισταγόρεω μὲν τοῦ Μιλησίου καταλυθέντες τῶν ἀρχέων ἔφευγον ἐς Μήδους, ἐτύγχανον δὲ τότε συστρατευόμενοι ἐπὶ τὴν Μίλητον, τούτων τῶν ἀνδρῶν τοὺς παρεόντας συγκαλέσαντες ἔλεγόν σφι τάδε. ἄνδρες Ἴωνες, νῦν τις ὑμέων εὖ ποιήσας φανήτω τὸν βασιλέος οἶκον· τοὺς γὰρ ἑωυτοῦ ἕκαστος ὑμέων πολιήτας πειράσθω ἀποσχίζων ἀπὸ τοῦ λοιποῦ συμμαχικοῦ. προϊσχόμενοι δὲ ἐπαγγείλασθε τάδε, ὡς πείσονταί τε ἄχαρι οὐδὲν διὰ τὴν ἀπόστασιν, οὐδέ σφι οὔτε τὰ ἱρὰ οὔτε τὰ ἴδια ἐμπεπρήσεται, οὐδὲ βιαιότερον ἕξουσι οὐδὲν ἢ πρότερον εἶχον. εἰ δὲ ταῦτα μὲν οὐ ποιήσουσι, οἳ δὲ πάντως διὰ μάχης ἐλεύσονται, τάδε ἤδη σφι λέγετε ἐπηρεάζοντες, τά περ σφέας κατέξει, ὡς ἑσσωθέντες τῇ μάχῃ ἐξανδραποδιεῦνται, καὶ ὡς σφέων τοὺς παῖδας ἐκτομίας ποιήσομεν, τὰς δὲ παρθένους ἀνασπάστους ἐς Βάκτρα, καὶ ὡς τὴν χώρην ἄλλοισι παραδώσομεν.", "st": "6.9"}, {"sp": "N", "t": "οἳ μὲν δὴ ἔλεγον τάδε. τῶν δὲ Ἰώνων οἱ τύραννοι διέπεμπον νυκτὸς ἕκαστος ἐς τοὺς ἑωυτοῦ ἐξαγγελλόμενος. οἱ δὲ Ἴωνες, ἐς τοὺς καὶ ἀπίκοντο αὗται αἱ ἀγγελίαι, ἀγνωμοσύνῃ τε διεχρέωντο καὶ οὐ προσίεντο τὴν προδοσίην· ἑωυτοῖσι δὲ ἕκαστοι ἐδόκεον μούνοισι ταῦτα τοὺς Πέρσας ἐξαγγέλλεσθαι.", "st": "6.10"}, {"sp": "N", "t": "ταῦτα μέν νυν ἰθέως ἀπικομένων ἐς τὴν Μίλητον τῶν Περσέων ἐγίνετο· μετὰ δὲ τῶν Ἰώνων συλλεχθέντων ἐς τὴν Λάδην ἐγίνοντο ἀγοραί, καὶ δή κού σφι καὶ ἄλλοι ἠγορόωντο, ἐν δὲ δὴ καὶ ὁ Φωκαεὺς στρατηγὸς Διονύσιος λέγων τάδε. ἐπὶ ξυροῦ γὰρ ἀκμῆς ἔχεται ἡμῖν τὰ πρήγματα, ἄνδρες Ἴωνες, ἢ εἶναι ἐλευθέροισι ἢ δούλοισι, καὶ τούτοισι ὡς δρηπέτῃσι· νῦν ὦν ὑμεῖς ἢν μὲν βούλησθε ταλαιπωρίας ἐνδέκεσθαι, τὸ παραχρῆμα μὲν πόνος ὑμῖν ἔσται, οἷοί τε δὲ ἔσεσθε ὑπερβαλόμενοι τοὺς ἐναντίους εἶναι ἐλεύθεροι· εἰ δὲ μαλακίῃ τε καὶ ἀταξίῃ διαχρήσησθε, οὐδεμίαν ὑμέων ἔχω ἐλπίδα μὴ οὐ δώσειν ὑμέας δίκην βασιλέι τῆς ἀποστάσιος. ἀλλ’ ἐμοί τε πείθεσθε καὶ ἐμοὶ ὑμέας αὐτοὺς ἐπιτρέψατε· καὶ ὑμῖν ἐγώ, θεῶν τὰ ἴσα νεμόντων, ὑποδέκομαι ἢ οὐ συμμίξειν τοὺς πολεμίους ἢ συμμίσγοντας πολλὸν ἐλασσωθήσεσθαι.", "st": "6.11"}, {"sp": "N", "t": "ταῦτα ἀκούσαντες οἱ Ἴωνες ἐπιτρέπουσι σφέας αὐτοὺς τῷ Διονυσίῳ. ὁ δὲ ἀνάγων ἑκάστοτε ἐπὶ κέρας τὰς νέας, ὅκως τοῖσι ἐρέτῃσι χρήσαιτο διέκπλοον ποιεύμενος τῇσι νηυσὶ δι’ ἀλληλέων καὶ τοὺς ἐπιβάτας ὁπλίσειε, τὸ λοιπὸν τῆς ἡμέρης τὰς νέας ἔχεσκε ἐπ’ ἀγκυρέων, παρεῖχέ τε τοῖσι Ἴωσι πόνον δι’ ἡμέρης. μέχρι μέν νυν ἡμερέων ἑπτὰ ἐπείθοντό τε καὶ ἐποίευν τὸ κελευόμενον· τῇ δὲ ἐπὶ ταύτῃσι οἱ Ἴωνες, οἷα ἀπαθέες ἐόντες πόνων τοιούτων τετρυμένοι τε ταλαιπωρίῃσί τε καὶ ἡλίῳ, ἔλεξαν πρὸς ἑωυτοὺς τάδε. τίνα δαιμόνων παραβάντες τάδε ἀναπίμπλαμεν; οἵτινες παραφρονήσαντες καὶ ἐκπλώσαντες ἐκ τοῦ νόου ἀνδρὶ Φωκαέι ἀλαζόνι, παρεχομένῳ νέας τρεῖς, ἐπιτρέψαντες ἡμέας αὐτοὺς ἔχομεν· ὁ δὲ παραλαβὼν ἡμέας λυμαίνεται λύμῃσι ἀνηκέστοισι, καὶ δὴ πολλοὶ μὲν ἡμέων ἐς νούσους πεπτώκασι, πολλοὶ δὲ ἐπίδοξοι τὠυτὸ τοῦτο πείσεσθαι εἰσί, πρό τε τούτων τῶν κακῶν ἡμῖν γε κρέσσον καὶ ὅ τι ὦν ἄλλο παθεῖν ἐστι καὶ τὴν μέλλουσαν δουληίην ὑπομεῖναι ἥτις ἔσται, μᾶλλον ἢ τῇ παρεούσῃ συνέχεσθαι. φέρετε, τοῦ λοιποῦ μὴ πειθώμεθα αὐτοῦ. ταῦτα ἔλεξαν, καὶ μετὰ ταῦτα αὐτίκα πείθεσθαι οὐδεὶς ἤθελε, ἀλλ’ οἷα στρατιὴ σκηνάς τε πηξάμενοι ἐν τῇ νήσῳ ἐσκιητροφέοντο καὶ ἐσβαίνειν οὐκ ἐθέλεσκον ἐς τὰς νέας οὐδ’ ἀναπειρᾶσθαι.", "st": "6.12"}, {"sp": "N", "t": "μαθόντες δὲ ταῦτα τὰ γινόμενα ἐκ τῶν Ἰώνων οἱ στρατηγοὶ τῶν Σαμίων ἐνθαῦτα δὴ παρ’ Αἰάκεος τοῦ Συλοσῶντος κείνους τοὺς πρότερον ἔπεμπε λόγους ὁ Αἰάκης κελευόντων τῶν Περσέων, δεόμενος σφέων ἐκλιπεῖν τὴν Ἰώνων συμμαχίην· οἱ Σάμιοι ὦν ὁρῶντες ἐοῦσαν ἅμα μὲν ἀταξίην πολλὴν ἐκ τῶν Ἰώνων ἐδέκοντο τοὺς λόγους, ἅμα δὲ κατεφαίνετό σφι εἶναι ἀδύνατα τὰ βασιλέος πρήγματα ὑπερβαλέσθαι, εὖ δὲ ἐπιστάμενοι ὡς εἰ καὶ τὸ παρεὸν ναυτικὸν ὑπερβαλοίατο τὸν Δαρεῖον, ἄλλο σφι παρέσται πενταπλήσιον. προφάσιος ὦν ἐπιλαβόμενοι, ἐπείτε τάχιστα εἶδον τοὺς Ἴωνας οὐ βουλομένους εἶναι χρηστούς, ἐν κέρδεϊ ἐποιεῦντο περιποιῆσαι τά τε ἱρὰ τὰ σφέτερα καὶ τὰ ἴδια. ὁ δὲ Αἰάκης, παρ’ ὅτευ τοὺς λόγους ἐδέκοντο οἱ Σάμιοι, παῖς μὲν ἦν Συλοσῶντος τοῦ Αἰάκεος, τύραννος δὲ ἐὼν Σάμου ὑπὸ τοῦ Μιλησίου Ἀρισταγόρεω ἀπεστέρητο τὴν ἀρχὴν κατά περ οἱ ἄλλοι τῆς Ἰωνίης τύραννοι.", "st": "6.13"}, {"sp": "N", "t": "τότε ὦν ἐπεὶ ἐπέπλεον οἱ Φοίνικες, οἱ Ἴωνες ἀντανῆγον καὶ αὐτοὶ τὰς νέας ἐπὶ κέρας. ὡς δὲ καὶ ἀγχοῦ ἐγίνοντο καὶ συνέμισγον ἀλλήλοισι, τὸ ἐνθεῦτεν οὐκ ἔχω ἀτρεκέως συγγράψαι οἵτινες τῶν Ἰώνων ἐγίνοντο ἄνδρες κακοὶ ἢ ἀγαθοὶ ἐν τῇ ναυμαχίῃ ταύτῃ· ἀλλήλους γὰρ καταιτιῶνται. λέγονται δὲ Σάμιοι ἐνθαῦτα κατὰ τὰ συγκείμενα πρὸς τὸν Αἰάκεα ἀειράμενοι τὰ ἱστία ἀποπλῶσαι ἐκ τῆς τάξιος ἐς τὴν Σάμον, πλὴν ἕνδεκα νεῶν· τουτέων δὲ οἱ τριήραρχοι παρέμενον καὶ ἐναυμάχεον ἀνηκουστήσαντες τοῖσι στρατηγοῖσι· καί σφι τὸ κοινὸν τῶν Σαμίων ἔδωκε διὰ τοῦτο τὸ πρῆγμα ἐν στήλῃ ἀναγραφῆναι πατρόθεν ὡς ἀνδράσι ἀγαθοῖσι γενομένοισι, καὶ ἔστι αὕτη ἡ στήλη ἐν τῇ ἀγορῇ. ἰδόμενοι δὲ καὶ Λέσβιοι τοὺς προσεχέας φεύγοντας τὠυτὸ ἐποίευν τοῖσι Σαμίοισι· ὣς δὲ καὶ οἱ πλεῦνες τῶν Ἰώνων ἐποίευν τὰ αὐτὰ ταῦτα.", "st": "6.14"}, {"sp": "N", "t": "τῶν δὲ παραμεινάντων ἐν τῇ ναυμαχίῃ περιέφθησαν τρηχύτατα Χῖοι ὡς ἀποδεικνύμενοί τε ἔργα λαμπρὰ καὶ οὐκ ἐθελοκακέοντες. παρείχοντο μὲν γάρ, ὥσπερ καὶ πρότερον εἰρέθη, νέας ἑκατόν, καὶ ἐπ’ ἑκάστης αὐτέων ἄνδρας τεσσεράκοντα τῶν ἀστῶν λογάδας ἐπιβατεύοντας. ὁρέοντες δὲ τοὺς πολλοὺς τῶν συμμάχων προδιδόντας οὐκ ἐδικαίευν γίνεσθαι τοῖσι κακοῖσι αὐτῶν ὅμοιοι, ἀλλὰ μετ’ ὀλίγων συμμάχων μεμουνωμένοι διεκπλέοντες ἐναυμάχεον, ἐς ὃ τῶν πολεμίων ἑλόντες νέας συχνὰς ἀπέβαλον τῶν σφετερέων τὰς πλεῦνας.", "st": "6.15"}, {"sp": "N", "t": "Χῖοι μὲν δὴ τῇσι λοιπῇσι τῶν νεῶν ἀποφεύγουσι ἐς τὴν ἑωυτῶν· ὅσοισι δὲ τῶν Χίων ἀδύνατοι ἦσαν αἱ νέες ὑπὸ τρωμάτων, οὗτοι δὲ ὡς ἐδιώκοντο καταφυγγάνουσι πρὸς τὴν Μυκάλην. νέας μὲν δὴ αὐτοῦ ταύτῃ ἐποκείλαντες κατέλιπον, οἳ δὲ πεζῇ ἐκομίζοντο διὰ τῆς ἠπείρου. ἐπειδὴ δὲ ἐσέβαλον ἐς τὴν Ἐφεσίην κομιζόμενοι οἱ Χῖοι, νυκτός τε γὰρ ἀπίκατο ἐς αὐτὴν καὶ ἐόντων τῇσι γυναιξὶ αὐτόθι θεσμοφορίων, ἐνθαῦτα δὴ οἱ Ἐφέσιοι, οὔτε προακηκοότες ὡς εἶχε περὶ τῶν Χίων ἰδόντες τε στρατὸν ἐς τὴν χώρην ἐσβεβληκότα, πάγχυ σφέας καταδόξαντες εἶναι κλῶπας καὶ ἰέναι ἐπὶ τὰς γυναῖκας, ἐξεβοήθεον πανδημεὶ καὶ ἔκτεινον τοὺς Χίους.", "st": "6.16"}, {"sp": "N", "t": "οὗτοι μὲν τοίνυν τοιαύτῃσι περιέπιπτον τύχῃσι. Διονύσιος δὲ ὁ Φωκαεὺς ἐπείτε ἔμαθε τῶν Ἰώνων τὰ πρήγματα διεφθαρμένα, νέας ἑλὼν τρεῖς τῶν πολεμίων ἀπέπλεε ἐς μὲν Φώκαιαν οὐκέτι, εὖ εἰδὼς ὡς ἀνδραποδιεῖται σὺν τῇ ἄλλῃ Ἰωνίῃ· ὁ δὲ ἰθέως ὡς εἶχε ἔπλεε ἐς Φοινίκην, γαύλους δὲ ἐνθαῦτα καταδύσας καὶ χρήματα λαβὼν πολλὰ ἔπλεε ἐς Σικελίην, ὁρμώμενος δὲ ἐνθεῦτεν ληιστὴς κατεστήκεε Ἑλλήνων μὲν οὐδενός, Καρχηδονίων δὲ καὶ Τυρσηνῶν.", "st": "6.17"}, {"sp": "N", "t": "οἱ δὲ Πέρσαι ἐπείτε τῇ ναυμαχίῃ ἐνίκων τοὺς Ἴωνας, τὴν Μίλητον πολιορκέοντες ἐκ γῆς καὶ θαλάσσης καὶ ὑπορύσσοντες τὰ τείχεα καὶ παντοίας μηχανὰς προσφέροντες, αἱρέουσι κατ’ ἄκρης ἕκτῳ ἔτεϊ ἀπὸ τῆς ἀποστάσιος τῆς Ἀρισταγόρεω καὶ ἠνδραποδίσαντο τὴν πόλιν, ὥστε συμπεσεῖν τὸ πάθος τῷ χρηστηρίῳ τῷ ἐς Μίλητον γενομένῳ.", "st": "6.18"}, {"sp": "N", "t": "χρεωμένοισι γὰρ Ἀργείοισι ἐν Δελφοῖσι περὶ σωτηρίης τῆς πόλιος τῆς σφετέρης ἐχρήσθη ἐπίκοινον χρηστήριον, τὸ μὲν ἐς αὐτοὺς τοὺς Ἀργείους φέρον, τὴν δὲ παρενθήκην ἔχρησε ἐς Μιλησίους. τὸ μέν νυν ἐς τοὺς Ἀργείους ἔχον, ἐπεὰν κατὰ τοῦτο γένωμαι τοῦ λόγου, τότε μνησθήσομαι· τὰ δὲ τοῖσι Μιλησίοισι οὐ παρεοῦσι ἔχρησε, ἔχει ὧδε.", "st": "6.19"}, {"sp": "N", "t": "καὶ τότε δή, Μίλητε κακῶν ἐπιμήχανε ἔργων,<br>πολλοῖσιν δεῖπνόν τε καὶ ἀγλαὰ δῶρα γενήσῃ,<br>σαὶ δ’ ἄλοχοι πολλοῖσι πόδας νίψουσι κομήταις,<br>νηοῦ δ’ ἡμετέρου Διδύμοις ἄλλοισι μελήσει.", "st": "6.19b"}, {"sp": "N", "t": "τότε δὴ ταῦτα τοὺς Μιλησίους κατελάμβανε, ὁκότε ἄνδρες μὲν οἱ πλεῦνες ἐκτείνοντο ὑπὸ τῶν Περσέων ἐόντων κομητέων, γυναῖκες δὲ καὶ τέκνα ἐν ἀνδραπόδων λόγῳ ἐγίνοντο, ἱρὸν δὲ τὸ ἐν Διδύμοισι καὶ ὁ νηός τε καὶ τὸ χρηστήριον συληθέντα ἐνεπίμπρατο. τῶν δ’ ἐν τῷ ἱρῷ τούτῳ χρημάτων πολλάκις μνήμην ἑτέρωθι τοῦ λόγου ἐποιησάμην.", "st": "6.19.3"}, {"sp": "N", "t": "ἐνθεῦτεν οἱ ζωγρηθέντες τῶν Μιλησίων ἤγοντο ἐς Σοῦσα. βασιλεὺς δὲ σφέας Δαρεῖος κακὸν οὐδὲν ἄλλο ποιήσας κατοίκισε ἐπὶ τῇ Ἐρυθρῇ καλεομένῃ θαλάσσῃ ἐν Ἄμπῃ πόλι, παρ’ ἣν Τίγρης ποταμὸς παραρρέων ἐς θάλασσαν ἐξιεῖ. τῆς δὲ Μιλησίων χώρης αὐτοὶ μὲν οἱ Πέρσαι εἶχον τὰ περὶ τὴν πόλιν καὶ τὸ πεδίον, τὰ δὲ ὑπεράκρια ἔδοσαν Καρσὶ Πηδασεῦσι ἐκτῆσθαι.", "st": "6.20"}, {"sp": "N", "t": "παθοῦσι δὲ ταῦτα Μιλησίοισι πρὸς Περσέων οὐκ ἀπέδοσαν τὴν ὁμοίην Συβαρῖται, οἳ Λᾶόν τε καὶ Σκίδρον οἴκεον τῆς πόλιος ἀπεστερημένοι. Συβάριος γὰρ ἁλούσης ὑπὸ Κροτωνιητέων Μιλήσιοι πάντες ἡβηδὸν ἀπεκείραντο τὰς κεφαλὰς καὶ πένθος μέγα προσεθήκαντο· πόλιες γὰρ αὗται μάλιστα δὴ τῶν ἡμεῖς ἴδμεν ἀλλήλῃσι ἐξεινώθησαν· οὐδὲν ὁμοίως καὶ Ἀθηναῖοι. Ἀθηναῖοι μὲν γὰρ δῆλον ἐποίησαν ὑπεραχθεσθέντες τῇ Μιλήτου ἁλώσι τῇ τε ἄλλῃ πολλαχῇ, καὶ δὴ καὶ ποιήσαντι Φρυνίχῳ δρᾶμα Μιλήτου ἅλωσιν καὶ διδάξαντι ἐς δάκρυά τε ἔπεσε τὸ θέητρον, καὶ ἐζημίωσάν μιν ὡς ἀναμνήσαντα οἰκήια κακὰ χιλίῃσι δραχμῇσι, καὶ ἐπέταξαν μηδένα χρᾶσθαι τούτῳ τῷ δράματι.", "st": "6.21"}, {"sp": "N", "t": "Μίλητος μέν νυν Μιλησίων ἠρήμωτο. Σαμίων δὲ τοῖσί τι ἔχουσι τὸ μὲν ἐς τοὺς Μήδους ἐκ τῶν στρατηγῶν τῶν σφετέρων ποιηθὲν οὐδαμῶς ἤρεσκε, ἐδόκεε δὲ μετὰ τὴν ναυμαχίην αὐτίκα βουλευομένοισι, πρὶν ἤ σφι ἐς τὴν χώρην ἀπικέσθαι τὸν τύραννον Αἰάκεα, ἐς ἀποικίην ἐκπλέειν μηδὲ μένοντας Μήδοισί τε καὶ Αἰάκεϊ δουλεύειν. Ζαγκλαῖοι γὰρ οἱ ἀπὸ Σικελίης τὸν αὐτὸν χρόνον τοῦτον πέμποντες ἐς τὴν Ἰωνίην ἀγγέλους ἐπεκαλέοντο τοὺς Ἴωνας ἐς Καλὴν ἀκτήν, βουλόμενοι αὐτόθι πόλιν κτίσαι Ἰώνων. ἡ δὲ Καλὴ αὕτη ἀκτὴ καλεομένη ἔστι μὲν Σικελῶν, πρὸς δὲ Τυρσηνίην τετραμμένη τῆς Σικελίης. τούτων ὦν ἐπικαλεομένων οἱ Σάμιοι μοῦνοι Ἰώνων ἐστάλησαν, σὺν δέ σφι Μιλησίων οἱ ἐκπεφευγότες· ἐν ᾧ τοιόνδε δή τι συνήνεικε γενέσθαι.", "st": "6.22"}, {"sp": "N", "t": "Σάμιοι γὰρ κομιζόμενοι ἐς Σικελίην ἐγίνοντο ἐν Λοκροῖσι τοῖσι Ἐπιζεφυρίοισι, καὶ Ζαγκλαῖοι αὐτοί τε καὶ ὁ βασιλεὺς αὐτῶν, τῷ οὔνομα ἦν Σκύθης, περικατέατο πόλιν τῶν Σικελῶν ἐξελεῖν βουλόμενοι. μαθὼν δὲ ταῦτα ὁ Ῥηγίου τύραννος Ἀναξίλεως, τότε ἐὼν διάφορος τοῖσι Ζαγκλαίοισι, συμμίξας τοῖσι Σαμίοισι ἀναπείθει ὡς χρεὸν εἴη Καλὴν μὲν ἀκτήν, ἐπ’ ἣν ἔπλεον, ἐᾶν χαίρειν, τὴν δὲ Ζάγκλην σχεῖν ἐοῦσαν ἔρημον ἀνδρῶν. πειθομένων δὲ τῶν Σαμίων καὶ σχόντων τὴν Ζάγκλην, ἐνθαῦτα οἱ Ζαγκλαῖοι, ὡς ἐπύθοντο ἐχομένην τὴν πόλιν ἑωυτῶν, ἐβοήθεον αὐτῇ καὶ ἐπεκαλέοντο Ἱπποκράτεα τὸν Γέλης τύραννον· ἦν γὰρ δή σφι οὗτος σύμμαχος. ἐπείτε δὲ αὐτοῖσι καὶ ὁ Ἱπποκράτης σὺν τῇ στρατιῇ ἧκε βοηθέων, Σκύθην μὲν τὸν μούναρχον τῶν Ζαγκλαίων ὡς ἀποβαλόντα τὴν πόλιν ὁ Ἱπποκράτης πεδήσας καὶ τὸν ἀδελφεὸν αὐτοῦ Πυθογένεα ἐς Ἴνυκα πόλιν ἀπέπεμψε, τοὺς δὲ λοιποὺς Ζαγκλαίους κοινολογησάμενος τοῖσι Σαμίοισι καὶ ὅρκους δοὺς καὶ δεξάμενος προέδωκε. μισθὸς δέ οἱ ἦν εἰρημένος ὅδε ὑπὸ τῶν Σαμίων, πάντων τῶν ἐπίπλων καὶ ἀνδραπόδων τὰ ἡμίσεα μεταλαβεῖν τῶν ἐν τῇ πόλι, τὰ δ’ ἐπὶ τῶν ἀγρῶν πάντα Ἱπποκράτεα λαγχάνειν. τοὺς μὲν δὴ πλεῦνας τῶν Ζαγκλαίων αὐτὸς ἐν ἀνδραπόδων λόγῳ εἶχε δήσας, τοὺς δὲ κορυφαίους αὐτῶν τριηκοσίους ἔδωκε τοῖσι Σαμίοισι κατασφάξαι· οὐ μέντοι οἵ γε Σάμιοι ἐποίησαν ταῦτα.", "st": "6.23"}, {"sp": "N", "t": "Σκύθης δὲ ὁ τῶν Ζαγκλαίων μούναρχος ἐκ τῆς Ἴνυκος ἐκδιδρήσκει ἐς Ἱμέρην, ἐκ δὲ ταύτης παρῆν ἐς τὴν Ἀσίην καὶ ἀνέβη παρὰ βασιλέα Δαρεῖον· καί μιν ἐνόμισε Δαρεῖος πάντων ἀνδρῶν δικαιότατον εἶναι, ὅσοι ἐκ τῆς Ἑλλάδος παρ’ ἑωυτὸν ἀνέβησαν. καὶ γὰρ παραιτησάμενος βασιλέα ἐς Σικελίην ἀπίκετο καὶ αὖτις ἐκ τῆς Σικελίης ὀπίσω παρὰ βασιλέα, ἐς ὃ γήραϊ μέγα ὄλβιος ἐὼν ἐτελεύτησε ἐν Πέρσῃσι. Σάμιοι δὲ ἀπαλλαχθέντες Μήδων ἀπονητὶ πόλιν καλλίστην Ζάγκλην περιεβεβλέατο.", "st": "6.24"}, {"sp": "N", "t": "μετὰ δὲ τὴν ναυμαχίην τὴν ὑπὲρ Μιλήτου γενομένην Φοίνικες κελευσάντων Περσέων κατῆγον ἐς Σάμον Αἰάκεα τὸν Συλοσῶντος ὡς πολλοῦ τε ἄξιον γενόμενον σφίσι καὶ μεγάλα κατεργασάμενον· καὶ Σαμίοισι μούνοισι τῶν ἀποστάντων ἀπὸ Δαρείου διὰ τὴν ἔκλειψιν τῶν νεῶν ἐν τῇ ναυμαχίῃ οὔτε ἡ πόλις οὔτε τὰ ἱρὰ ἐνεπρήσθη. Μιλήτου δὲ ἁλούσης αὐτίκα Καρίην ἔσχον οἱ Πέρσαι, τὰς μὲν ἐθελοντὴν τῶν πολίων ὑποκυψάσας, τὰς δὲ ἀνάγκῃ προσηγάγοντο.", "st": "6.25"}, {"sp": "N", "t": "ταῦτα μὲν δὴ οὕτω ἐγίνετο. Ἱστιαίῳ δὲ τῷ Μιλησίῳ ἐόντι περὶ Βυζάντιον καὶ συλλαμβάνοντι τὰς Ἰώνων ὁλκάδας ἐκπλεούσας ἐκ τοῦ Πόντου ἐξαγγέλλεται τὰ περὶ τὴν Μίλητον γενόμενα. τὰ μὲν δὴ περὶ Ἑλλήσποντον ἔχοντα πρήγματα ἐπιτράπει Βισάλτῃ Ἀπολλοφάνεος παιδὶ Ἀβυδηνῷ, αὐτὸς δὲ ἔχων Λεσβίους ἐς Χίον ἔπλεε, καὶ Χίων φρουρῇ οὐ προσιεμένῃ μιν συνέβαλε ἐν Κοίλοισι καλεομένοισι τῆς Χίης χώρης. τούτων τε δὴ ἐφόνευσε συχνούς, καὶ τῶν λοιπῶν Χίων, οἷα δὴ κεκακωμένων ἐκ τῆς ναυμαχίης, ὁ Ἱστιαῖος ἔχων τοὺς Λεσβίους ἐπεκράτησε, ἐκ Πολίχνης τῆς Χίων ὁρμώμενος.", "st": "6.26"}, {"sp": "N", "t": "φιλέει δέ κως προσημαίνειν, εὖτ’ ἂν μέλλῃ μεγάλα κακὰ ἢ πόλι ἢ ἔθνεϊ ἔσεσθαι· καὶ γὰρ Χίοισι πρὸ τούτων σημήια μεγάλα ἐγένετο· τοῦτο μέν σφι πέμψασι ἐς Δελφοὺς χορὸν νεηνιέων ἑκατὸν δύο μοῦνοι τούτων ἀπενόστησαν, τοὺς δὲ ὀκτώ τε καὶ ἐνενήκοντα αὐτῶν λοιμὸς ὑπολαβὼν ἀπήνεικε· τοῦτο δὲ ἐν τῇ πόλι τὸν αὐτὸν τοῦτον χρόνον, ὀλίγον πρὸ τῆς ναυμαχίης, παισὶ γράμματα διδασκομένοισι ἐνέπεσε ἡ στέγη, ὥστε ἀπ’ ἑκατὸν καὶ εἴκοσι παίδων εἷς μοῦνος ἀπέφυγε. ταῦτα μὲν σφι σημήια ὁ θεὸς προέδεξε, μετὰ δὲ ταῦτα ἡ ναυμαχίη ὑπολαβοῦσα ἐς γόνυ τὴν πόλιν ἔβαλε, ἐπὶ δὲ τῇ ναυμαχίῃ ἐπεγένετο Ἱστιαῖος Λεσβίους ἄγων· κεκακωμένων δὲ τῶν Χίων, καταστροφὴν εὐπετέως αὐτῶν ἐποιήσατο.", "st": "6.27"}, {"sp": "N", "t": "ἐνθεῦτεν δὲ ὁ Ἱστιαῖος ἐστρατεύετο ἐπὶ Θάσον ἄγων Ἰώνων καὶ Αἰολέων συχνούς. περικατημένῳ δέ οἱ Θάσον ἦλθε ἀγγελίη ὡς οἱ Φοίνικες ἀναπλέουσι ἐκ τῆς Μιλήτου ἐπὶ τὴν ἄλλην Ἰωνίην. πυθόμενος δὲ ταῦτα Θάσον μὲν ἀπόρθητον λείπει, αὐτὸς δὲ ἐς τὴν Λέσβον ἠπείγετο ἄγων πᾶσαν τὴν στρατιήν. ἐκ Λέσβου δὲ λιμαινούσης οἱ τῆς στρατιῆς πέρην διαβαίνει, ἐκ τοῦ Ἀταρνέος ὡς ἀμήσων τὸν σῖτον τόν τε ἐνθεῦτεν καὶ τὸν ἐκ Καΐκου πεδίου τὸν τῶν Μυσῶν. ἐν δὲ τούτοισι τοῖσι χωρίοισι ἐτύγχανε ἐὼν Ἅρπαγος ἀνὴρ Πέρσης στρατηγὸς στρατιῆς οὐκ ὀλίγης· ὅς οἱ ἀποβάντι συμβαλὼν αὐτόν τε Ἱστιαῖον ζωγρίῃ ἔλαβε καὶ τὸν στρατὸν αὐτοῦ τὸν πλέω διέφθειρε.", "st": "6.28"}, {"sp": "N", "t": "ἐζωγρήθη δὲ ὁ Ἱστιαῖος ὧδε. ὡς ἐμάχοντο οἱ Ἕλληνες τοῖσι Πέρσῃσι ἐν τῇ Μαλήνῃ τῆς Ἀταρνείτιδος χώρης, οἳ μὲν συνέστασαν χρόνον ἐπὶ πολλόν, ἡ δὲ ἵππος ὕστερον ὁρμηθεῖσα ἐπιπίπτει τοῖσι Ἕλλησι. τό τε δὴ ἔργον τῆς ἵππου τοῦτο ἐγένετο, καὶ τετραμμένων τῶν Ἑλλήνων ὁ Ἱστιαῖος ἐλπίζων οὐκ ἀπολέεσθαι ὑπὸ βασιλέος διὰ τὴν παρεοῦσαν ἁμαρτάδα φιλοψυχίην τοιήνδε τινὰ ἀναιρέεται· ὡς φεύγων τε κατελαμβάνετο ὑπὸ ἀνδρὸς Πέρσεω καὶ ὡς καταιρεόμενος ὑπ’ αὐτοῦ ἔμελλε συγκεντηθήσεσθαι, Περσίδα γλῶσσαν μετεὶς καταμηνύει ἑωυτὸν ὡς εἴη Ἱστιαῖος ὁ Μιλήσιος.", "st": "6.29"}, {"sp": "N", "t": "εἰ μέν νυν, ὡς ἐζωγρήθη, ἄχθη ἀγόμενος παρὰ βασιλέα Δαρεῖον, ὁ δὲ οὔτ’ ἂν ἔπαθε κακὸν οὐδὲν δοκέειν ἐμοί, ἀπῆκέ τ’ ἂν αὐτῷ τὴν αἰτίην· νῦν δέ μιν αὐτῶν τε τούτων εἵνεκα καὶ ἵνα μὴ διαφυγὼν αὖτις μέγας παρὰ βασιλέι γένηται, Ἀρταφρένης τε ὁ Σαρδίων ὕπαρχος καὶ ὁ λαβὼν Ἅρπαγος, ὡς ἀπίκετο ἀγόμενος ἐς Σάρδις, τὸ μὲν αὐτοῦ σῶμα αὐτοῦ ταύτῃ ἀνεσταύρωσαν, τὴν δὲ κεφαλὴν ταριχεύσαντες ἀνήνεικαν παρὰ βασιλέα Δαρεῖον ἐς Σοῦσα. Δαρεῖος δὲ πυθόμενος ταῦτα καὶ ἐπαιτιησάμενος τοὺς ταῦτα ποιήσαντας ὅτι μιν οὐ ζώοντα ἀνήγαγον ἐς ὄψιν τὴν ἑωυτοῦ, τὴν κεφαλὴν τὴν Ἱστιαίου λούσαντάς τε καὶ περιστείλαντας εὖ ἐνετείλατο θάψαι ὡς ἀνδρὸς μεγάλως ἑωυτῷ τε καὶ Πέρσῃσι εὐεργέτεω.", "st": "6.30"}, {"sp": "N", "t": "τὰ μὲν περὶ Ἱστιαῖον οὕτω ἔσχε. ὁ δὲ ναυτικὸς στρατὸς ὁ Περσέων χειμερίσας περὶ Μίλητον, τῷ δευτέρῳ ἔτεϊ ὡς ἀνέπλωσε, αἱρέει εὐπετέως τὰς νήσους τὰς πρὸς τῇ ἠπείρῳ κειμένας, Χίον καὶ Λέσβον καὶ Τένεδον. ὅκως δὲ λάβοι τινὰ τῶν νήσων, ὡς ἑκάστην αἱρέοντες οἱ βάρβαροι ἐσαγήνευον τοὺς ἀνθρώπους. σαγηνεύουσι δὲ τόνδε τὸν τρόπον· ἀνὴρ ἀνδρὸς ἁψάμενος τῆς χειρὸς ἐκ θαλάσσης τῆς βορηίης ἐπὶ τὴν νοτίην διήκουσι, καὶ ἔπειτα διὰ πάσης τῆς νήσου διέρχονται ἐκθηρεύοντες τοὺς ἀνθρώπους. αἵρεον δὲ καὶ τὰς ἐν τῇ ἠπείρῳ πόλιας τὰς Ἰάδας κατὰ ταὐτά, πλὴν οὐκ ἐσαγήνευον τοὺς ἀνθρώπους· οὐ γὰρ οἷά τ’ ἦν.", "st": "6.31"}, {"sp": "N", "t": "ἐνθαῦτα Περσέων οἱ στρατηγοὶ οὐκ ἐψεύσαντο τὰς ἀπειλὰς τὰς ἐπηπείλησαν τοῖσι Ἴωσι στρατοπεδευομένοισι ἐναντία σφίσι. ὡς γὰρ δὴ ἐπεκράτησαν τῶν πολίων, παῖδάς τε τοὺς εὐειδεστάτους ἐκλεγόμενοι ἐξέταμνον καὶ ἐποίευν ἀντὶ εἶναι ἐνόρχιας εὐνούχους καὶ παρθένους τὰς καλλιστευούσας ἀνασπάστους παρὰ βασιλέα· ταῦτά τε δὴ ἐποίευν καὶ τὰς πόλιας ἐνεπίμπρασαν αὐτοῖσι τοῖσι ἱροῖσι. οὕτω τε τὸ τρίτον Ἴωνες κατεδουλώθησαν, πρῶτον μὲν ὑπὸ Λυδῶν, δὶς δὲ ἐπεξῆς τότε ὑπὸ Περσέων.", "st": "6.32"}, {"sp": "N", "t": "ἀπὸ δὲ Ἰωνίης ἀπαλλασσόμενος ὁ ναυτικὸς στρατὸς τὰ ἐπ’ ἀριστερὰ ἐσπλέοντι τοῦ Ἑλλησπόντου αἵρεε πάντα· τὰ γὰρ ἐπὶ δεξιὰ αὐτοῖσι τοῖσι Πέρσῃσι ὑποχείρια ἦν γεγονότα κατ’ ἤπειρον. εἰσὶ δὲ αἱ ἐν τῇ Εὐρώπῃ αἵδε τοῦ Ἑλλησπόντου, Χερσόνησός τε, ἐν τῇ πόλιες συχναὶ ἔνεισι, καὶ Πέρινθος καὶ τὰ τείχεα τὰ ἐπὶ Θρηίκης καὶ Σηλυμβρίη τε καὶ Βυζάντιον. Βυζάντιοι μέν νυν καὶ οἱ πέρηθε Καλχηδόνιοι οὐδ’ ὑπέμειναν ἐπιπλέοντας τοὺς Φοίνικας, ἀλλ’ οἴχοντο ἀπολιπόντες τὴν σφετέρην ἔσω ἐς τὸν Εὔξεινον πόντον, καὶ ἐνθαῦτα πόλιν Μεσαμβρίην οἴκησαν. οἱ δὲ Φοίνικες κατακαύσαντες ταύτας τὰς χώρας τὰς καταλεχθείσας τρέπονται ἐπί τε Προκόννησον καὶ Ἀρτάκην, πυρὶ δὲ καὶ ταύτας νείμαντες ἔπλεον αὖτις ἐς τὴν Χερσόνησον ἐξαιρήσοντες τὰς ἐπιλοίπους τῶν πολίων, ὅσας πρότερον προσσχόντες οὐ κατέσυραν. ἐπὶ δὲ Κύζικον οὐδὲ ἔπλωσαν ἀρχήν· αὐτοὶ γὰρ Κυζικηνοὶ ἔτι πρότερον τοῦ Φοινίκων ἐσπλόου ἐγεγόνεσαν ὑπὸ βασιλέϊ, Οἰβάρεϊ τῷ Μεγαβάζου ὁμολογήσαντες τῷ ἐν Δασκυλείῳ ὑπάρχῳ.", "st": "6.33"}, {"sp": "N", "t": "τῆς δὲ Χερσονήσου πλὴν Καρδίης πόλιος τὰς ἄλλας πάσας ἐχειρώσαντο οἱ Φοίνικες. ἐτυράννευε δὲ αὐτέων μέχρι τότε Μιλτιάδης ὁ Κίμωνος τοῦ Στησαγόρεω, κτησαμένου τὴν ἀρχὴν ταύτην πρότερον Μιλτιάδεω τοῦ Κυψέλου τρόπῳ τοιῷδε. εἶχον Δόλογκοι Θρήικες τὴν Χερσόνησον ταύτην. οὗτοι ὦν οἱ Δόλογκοι πιεσθέντες πολέμῳ ὑπὸ Ἀψινθίων ἐς Δελφοὺς ἔπεμψαν τοὺς βασιλέας περὶ τοῦ πολέμου χρησομένους. ἡ δὲ Πυθίη σφι ἀνεῖλε οἰκιστὴν ἐπάγεσθαι ἐπὶ τὴν χώρην τοῦτον ὃς ἂν σφέας ἀπιόντας ἐκ τοῦ ἱροῦ πρῶτος ἐπὶ ξείνια καλέσῃ. ἰόντες δὲ οἱ Δόλογκοι τὴν ἱρὴν ὁδὸν διὰ Φωκέων τε καὶ Βοιωτῶν ἤισαν· καί σφεας ὡς οὐδεὶς ἐκάλεε, ἐκτρέπονται ἐπ’ Ἀθηνέων.", "st": "6.34"}, {"sp": "N", "t": "ἐν δὲ τῇσι Ἀθήνῃσι τηνικαῦτα εἶχε μὲν τὸ πᾶν κράτος Πεισίστρατος, ἀτὰρ ἐδυνάστευέ γε καὶ Μιλτιάδης ὁ Κυψέλου ἐὼν οἰκίης τεθριπποτρόφου, τὰ μὲν ἀνέκαθεν ἀπ’ Αἰακοῦ τε καὶ Αἰγίνης γεγονώς, τὰ δὲ νεώτερα Ἀθηναῖος, Φιλαίου τοῦ Αἴαντος παιδὸς γενομένου πρώτου τῆς οἰκίης ταύτης Ἀθηναίου. οὗτος ὁ Μιλτιάδης κατήμενος ἐν τοῖσι προθύροισι τοῖσι ἑωυτοῦ, ὁρέων τοὺς Δολόγκους παριόντας ἐσθῆτα ἔχοντας οὐκ ἐγχωρίην καὶ αἰχμὰς προσεβώσατο καί σφι προσελθοῦσι ἐπηγγείλατο καταγωγὴν καὶ ξείνια. οἳ δὲ δεξάμενοι καὶ ξεινισθέντες ὑπ’ αὐτοῦ ἐξέφαινον πᾶν τὸ μαντήιον, ἐκφήναντες δὲ ἐδέοντο αὐτοῦ τῷ θεῷ μιν πείθεσθαι. Μιλτιάδεα δὲ ἀκούσαντα παραυτίκα ἔπεισε ὁ λόγος οἷα ἀχθόμενόν τε τῇ Πεισιστράτου ἀρχῇ καὶ βουλόμενον ἐκποδὼν εἶναι. αὐτίκα δὲ ἐστάλη ἐς Δελφούς, ἐπειρησόμενος τὸ χρηστήριον εἰ ποιοίη τά περ αὐτοῦ οἱ Δόλογκοι προσεδέοντο.", "st": "6.35"}, {"sp": "N", "t": "κελευούσης δὲ καὶ τῆς Πυθίης, οὕτω δὴ Μιλτιάδης ὁ Κυψέλου, Ὀλύμπια ἀναραιρηκὼς πρότερον τούτων τεθρίππῳ, τότε παραλαβὼν Ἀθηναίων πάντα τὸν βουλόμενον μετέχειν τοῦ στόλου ἔπλεε ἅμα τοῖσι Δολόγκοισι, καὶ ἔσχε τὴν χώρην· καί μιν οἱ ἐπαγαγόμενοι τύραννον κατεστήσαντο. ὁ δὲ πρῶτον μὲν ἀπετείχισε τὸν ἰσθμὸν τῆς Χερσονήσου ἐκ Καρδίης πόλιος ἐς Πακτύην, ἵνα μὴ ἔχοιεν σφέας οἱ Ἀψίνθιοι δηλέεσθαι ἐσβάλλοντες ἐς τὴν χώρην. εἰσὶ δὲ οὗτοι στάδιοι ἕξ τε καὶ τριήκοντα τοῦ ἰσθμοῦ· ἀπὸ δὲ τοῦ ἰσθμοῦ τούτου ἡ Χερσόνησος ἔσω πᾶσα ἐστὶ σταδίων εἴκοσι καὶ τετρακοσίων τὸ μῆκος.", "st": "6.36"}, {"sp": "N", "t": "ἀποτειχίσας ὦν τὸν αὐχένα τῆς Χερσονήσου ὁ Μιλτιάδης καὶ τοὺς Ἀψινθίους τρόπῳ τοιούτῳ ὠσάμενος, τῶν λοιπῶν πρώτοισι ἐπολέμησε Λαμψακηνοῖσι· καί μιν οἱ Λαμψακηνοὶ λοχήσαντες αἱρέουσι ζωγρίῃ. ἦν δὲ ὁ Μιλτιάδης Κροίσῳ τῷ Λυδῷ ἐν γνώμῃ γεγονώς· πυθόμενος ὦν ὁ Κροῖσος ταῦτα, πέμπων προηγόρευε τοῖσι Λαμψακηνοῖσι μετιέναι Μιλτιάδεα· εἰ δὲ μή σφεας πίτυος τρόπον ἀπείλεε ἐκτρίψειν. πλανωμένων δὲ τῶν Λαμψακηνῶν ἐν τοῖσι λόγοισι τὸ θέλει τὸ ἔπος εἶναι τό σφι ἀπείλησε ὁ Κροῖσος, πίτυος τρόπον ἐκτρίψειν, μόγις κοτὲ μαθὼν τῶν τις πρεσβυτέρων εἶπε τὸ ἐόν, ὅτι πίτυς μούνη πάντων δενδρέων ἐκκοπεῖσα βλαστὸν οὐδένα μετιεῖ ἀλλὰ πανώλεθρος ἐξαπόλλυται. δείσαντες ὦν οἱ Λαμψακηνοὶ Κροῖσον λύσαντες μετῆκαν Μιλτιάδεα.", "st": "6.37"}, {"sp": "N", "t": "οὗτος μὲν δὴ διὰ Κροῖσον ἐκφεύγει, μετὰ δὲ τελευτᾷ ἄπαις, τὴν ἀρχήν τε καὶ τὰ χρήματα παραδοὺς Στησαγόρῃ τῷ Κίμωνος ἀδελφεοῦ παιδὶ ὁμομητρίου. καί οἱ τελευτήσαντι Χερσονησῖται θύουσι ὡς νόμος οἰκιστῇ, καὶ ἀγῶνα ἱππικόν τε καὶ γυμνικὸν ἐπιστᾶσι, ἐν τῷ Λαμψακηνῶν οὐδενὶ ἐγγίνεται ἀγωνίζεσθαι. πολέμου δὲ ἐόντος πρὸς Λαμψακηνοὺς καὶ Στησαγόρεα κατέλαβε ἀποθανεῖν ἄπαιδα, πληγέντα τὴν κεφαλὴν πελέκεϊ ἐν τῷ πρυτανηίῳ πρὸς ἀνδρὸς αὐτομόλου μὲν τῷ λόγῳ πολεμίου δὲ καὶ ὑποθερμοτέρου τῷ ἔργῳ.", "st": "6.38"}, {"sp": "N", "t": "τελευτήσαντος δὲ καὶ Στησαγόρεω τρόπῳ τοιῷδε, ἐνθαῦτα Μιλτιάδεα τὸν Κίμωνος, Στησαγόρεω δὲ τοῦ τελευτήσαντος ἀδελφεόν, καταλαμψόμενον τὰ πρήγματα ἐπὶ Χερσονήσου ἀποστέλλουσι τριήρεϊ οἱ Πεισιστρατίδαι, οἵ μιν καὶ ἐν Ἀθήνῃσι ἐποίευν εὖ ὡς οὐ συνειδότες δῆθεν τοῦ πατρὸς Κίμωνος αὐτοῦ τὸν θάνατον, τὸν ἐγὼ ἐν ἄλλῳ λόγῳ σημανέω ὡς ἐγένετο. Μιλτιάδης δὲ ἀπικόμενος ἐς τὴν Χερσόνησον εἶχε κατ’ οἴκους, τὸν ἀδελφεὸν Στησαγόρεα δηλαδὴ ἐπιτιμέων. οἱ δὲ Χερσονησῖται πυνθανόμενοι ταῦτα συνελέχθησαν ἀπὸ πασέων τῶν πολίων οἱ δυναστεύοντες πάντοθεν, κοινῷ δὲ στόλῳ ἀπικόμενοι ὡς συλλυπηθησόμενοι ἐδέθησαν ὑπ’ αὐτοῦ. Μιλτιάδης τε δὴ ἴσχει τὴν Χερσόνησον, πεντακοσίους βόσκων ἐπικούρους, καὶ γαμέει Ὀλόρου τοῦ Θρηίκων βασιλέος τὴν θυγατέρα Ἡγησιπύλην.", "st": "6.39"}, {"sp": "N", "t": "οὗτος δὲ ὁ Κίμωνος Μιλτιάδης νεωστὶ μὲν ἐληλύθεε ἐς τὴν Χερσόνησον, κατελάμβανε δέ μιν ἐλθόντα ἄλλα τῶν καταλαβόντων πρηγμάτων χαλεπώτερα. τρίτῳ μὲν γὰρ ἔτεϊ πρὸ τούτων Σκύθας ἐκφεύγει. Σκύθαι γὰρ οἱ νομάδες ἐρεθισθέντες ὑπὸ βασιλέος Δαρείου συνεστράφησαν καὶ ἤλασαν μέχρι τῆς Χερσονήσου ταύτης· τούτους ἐπιόντας οὐκ ὑπομείνας ὁ Μιλτιάδης ἔφευγε Χερσόνησον, ἐς ὃ οἵ τε Σκύθαι ἀπαλλάχθησαν καὶ ἐκεῖνον Δόλογκοι κατήγαγον ὀπίσω. ταῦτα μὲν δὴ τρίτῳ ἔτεϊ πρότερον ἐγεγόνεε τῶν τότε μιν κατεχόντων.", "st": "6.40"}, {"sp": "N", "t": "τότε δὲ πυνθανόμενος εἶναι τοὺς Φοίνικας ἐν Τενέδῳ, πληρώσας τριήρεας πέντε χρημάτων τῶν παρεόντων ἀπέπλεε ἐς τὰς Ἀθήνας. καὶ ὥσπερ ὁρμήθη ἐκ Καρδίης πόλιος ἔπλεε διὰ τοῦ Μέλανος κόλπου· παραμείβετό τε τὴν Χερσόνησον καὶ οἱ Φοίνικές οἱ περιπίπτουσι τῇσι νηυσί. αὐτὸς μὲν δὴ Μιλτιάδης σὺν τῇσι τέσσερσι τῶν νεῶν καταφεύγει ἐς Ἴμβρον, τὴν δέ οἱ πέμπτην τῶν νεῶν κατεῖλον διώκοντες οἱ Φοίνικες. τῆς δὲ νεὸς ταύτης ἔτυχε τῶν Μιλτιάδεω παίδων ὁ πρεσβύτατος ἄρχων Μητίοχος, οὐκ ἐκ τῆς Ὀλόρου τοῦ Θρήικος ἐὼν θυγατρὸς ἀλλ’ ἐξ ἄλλης· καὶ τοῦτον ἅμα τῇ νηὶ εἷλον οἱ Φοίνικες, καί μιν πυθόμενοι ὡς εἴη Μιλτιάδεω παῖς ἀνήγαγον παρὰ βασιλέα, δοκέοντες χάριτα μεγάλην καταθήσεσθαι, ὅτι δὴ Μιλτιάδης γνώμην ἀπεδέξατο ἐν τοῖσι Ἴωσι πείθεσθαι κελεύων τοῖσι Σκύθῃσι, ὅτε οἱ Σκύθαι προσεδέοντο λύσαντας τὴν σχεδίην ἀποπλέειν ἐς τὴν ἑωυτῶν. Δαρεῖος δέ, ὡς οἱ Φοίνικες Μητίοχον τὸν Μιλτιάδεω ἀνήγαγον, ἐποίησε κακὸν μὲν οὐδὲν Μητίοχον, ἀγαθὰ δὲ συχνά· καὶ γὰρ οἶκον καὶ κτῆσιν ἔδωκε καὶ Περσίδα γυναῖκα, ἐκ τῆς οἱ τέκνα ἐγένετο τὰ ἐς Πέρσας κεκοσμέαται. Μιλτιάδης δὲ ἐξ Ἴμβρου ἀπικνέεται ἐς τὰς Ἀθήνας.", "st": "6.41"}, {"sp": "N", "t": "καὶ κατὰ τὸ ἔτος τοῦτο ἐκ τῶν Περσέων οὐδὲν ἐπὶ πλέον ἐγένετο τούτων ἐς νεῖκος φέρον Ἴωσι, ἀλλὰ τάδε μὲν χρήσιμα κάρτα τοῖσι Ἴωσι ἐγένετο τούτου τοῦ ἔτεος· Ἀρταφρένης ὁ Σαρδίων ὕπαρχος μεταπεμψάμενος ἀγγέλους ἐκ τῶν πολίων συνθήκας σφίσι αὐτοῖσι τοὺς Ἴωνας ἠνάγκασε ποιέεσθαι, ἵνα δωσίδικοι εἶεν καὶ μὴ ἀλλήλους φέροιέν τε καὶ ἄγοιεν. ταῦτά τε ἠνάγκασε ποιέειν, καὶ τὰς χώρας μετρήσας σφέων κατὰ παρασάγγας, τοὺς καλέουσι οἱ Πέρσαι τὰ τριήκοντα στάδια, κατὰ δὴ τούτους μετρήσας φόρους ἔταξε ἑκάστοισι, οἳ κατὰ χώρην διατελέουσι ἔχοντες ἐκ τούτου τοῦ χρόνου αἰεὶ ἔτι καὶ ἐς ἐμὲ ὡς ἐτάχθησαν ἐξ Ἀρταφρένεος· ἐτάχθησαν δὲ σχεδὸν κατὰ ταὐτὰ καὶ πρότερον εἶχον. καί σφι ταῦτα μὲν εἰρηναῖα ἦν.", "st": "6.42"}, {"sp": "N", "t": "ἅμα δὲ τῷ ἔαρι, τῶν ἄλλων καταλελυμένων στρατηγῶν ἐκ βασιλέος, Μαρδόνιος ὁ Γοβρύεω κατέβαινε ἐπὶ θάλασσαν, στρατὸν πολλὸν μὲν κάρτα πεζὸν ἅμα ἀγόμενος πολλὸν δὲ ναυτικόν, ἡλικίην τε νέος ἐὼν καὶ νεωστὶ γεγαμηκὼς βασιλέος Δαρείου θυγατέρα Ἀρτοζώστρην· ἄγων δὲ τὸν στρατὸν τοῦτον ὁ Μαρδόνιος ἐπείτε ἐγένετο ἐν τῇ Κιλικίῃ, αὐτὸς μὲν ἐπιβὰς ἐπὶ νεὸς ἐκομίζετο ἅμα τῇσι ἄλλῃσι νηυσί, στρατιὴν δὲ τὴν πεζὴν ἄλλοι ἡγεμόνες ἦγον ἐπὶ τὸν Ἑλλήσποντον. ὡς δὲ παραπλέων τὴν Ἀσίην ἀπίκετο ὁ Μαρδόνιος ἐς τὴν Ἰωνίην, ἐνθαῦτα μέγιστον θῶμα ἐρέω τοῖσι μὴ ἀποδεκομένοισι Ἑλλήνων Περσέων τοῖσι ἑπτὰ Ὀτάνεα γνώμην ἀποδέξασθαι ὡς χρεὸν εἴη δημοκρατέεσθαι Πέρσας· τοὺς γὰρ τυράννους τῶν Ἰώνων καταπαύσας πάντας ὁ Μαρδόνιος δημοκρατίας κατίστα ἐς τὰς πόλιας. ταῦτα δὲ ποιήσας ἠπείγετο ἐς τὸν Ἑλλήσποντον. ὡς δὲ συνελέχθη μὲν χρῆμα πολλὸν νεῶν συνελέχθη δὲ καὶ πεζὸς στρατὸς πολλός, διαβάντες τῇσι νηυσὶ τὸν Ἑλλήσποντον ἐπορεύοντο διὰ τῆς Εὐρώπης, ἐπορεύοντο δὲ ἐπί τε Ἐρέτριαν καὶ Ἀθήνας.", "st": "6.43"}, {"sp": "N", "t": "αὗται μὲν ὦν σφι πρόσχημα ἦσαν τοῦ στόλου· ἀτὰρ ἐν νόῳ ἔχοντες ὅσας ἂν πλείστας δύνωνται καταστρέφεσθαι τῶν Ἑλληνίδων πολίων, τοῦτο μὲν δὴ τῇσι νηυσὶ Θασίους οὐδὲ χεῖρας ἀνταειραμένους κατεστρέψαντο, τοῦτο δὲ τῷ πεζῷ Μακεδόνας πρὸς τοῖσι ὑπάρχουσι δούλους προσεκτήσαντο· τὰ γὰρ ἐντὸς Μακεδόνων ἔθνεα πάντα σφι ἦν ἤδη ὑποχείρια γεγονότα. ἐκ μὲν δὴ Θάσου διαβαλόντες πέρην ὑπὸ τὴν ἤπειρον ἐκομίζοντο μέχρι Ἀκάνθου, ἐκ δὲ Ἀκάνθου ὁρμώμενοι τὸν Ἄθων περιέβαλλον. ἐπιπεσὼν δέ σφι περιπλέουσι βορέης ἄνεμος μέγας τε καὶ ἄπορος κάρτα τρηχέως περιέσπε, πλήθεϊ πολλὰς τῶν νεῶν ἐκβάλλων πρὸς τὸν Ἄθων. λέγεται γὰρ τριηκοσίας μὲν τῶν νεῶν τὰς διαφθαρείσας εἶναι, ὑπὲρ δὲ δύο μυριάδας ἀνθρώπων. ὥστε γὰρ θηριωδεστάτης ἐούσης τῆς θαλάσσης ταύτης τῆς περὶ τὸν Ἄθων, οἳ μὲν ὑπὸ τῶν θηρίων διεφθείροντο ἁρπαζόμενοι, οἳ δὲ πρὸς τὰς πέτρας ἀρασσόμενοι· οἳ δὲ αὐτῶν νέειν οὐκ ἐπιστέατο καὶ κατὰ τοῦτο διεφθείροντο, οἳ δὲ ῥίγεϊ.", "st": "6.44"}, {"sp": "N", "t": "ὁ μὲν δὴ ναυτικὸς στρατὸς οὕτω ἔπρησσε, Μαρδονίῳ δὲ καὶ τῷ πεζῷ στρατοπεδευομένῳ ἐν Μακεδονίῃ νυκτὸς Βρύγοι Θρήικες ἐπεχείρησαν· καί σφεων πολλοὺς φονεύουσι οἱ Βρύγοι, Μαρδόνιον δὲ αὐτὸν τρωματίζουσι. οὐ μέντοι οὐδὲ αὐτοὶ δουλοσύνην διέφυγον πρὸς Περσέων· οὐ γὰρ δὴ πρότερον ἀπανέστη ἐκ τῶν χωρέων τουτέων Μαρδόνιος πρὶν ἤ σφεας ὑποχειρίους ἐποιήσατο. τούτους μέντοι καταστρεψάμενος ἀπῆγε τὴν στρατιὴν ὀπίσω, ἅτε τῷ πεζῷ τε προσπταίσας πρὸς τοὺς Βρύγους καὶ τῷ ναυτικῷ μεγάλως περὶ Ἄθων. οὗτος μέν νυν ὁ στόλος αἰσχρῶς ἀγωνισάμενος ἀπαλλάχθη ἐς τὴν Ἀσίην.", "st": "6.45"}, {"sp": "N", "t": "δευτέρῳ δὲ ἔτεϊ τούτων ὁ Δαρεῖος πρῶτα μὲν Θασίους διαβληθέντας ὑπὸ τῶν ἀστυγειτόνων ὡς ἀπόστασιν μηχανῴατο, πέμψας ἄγγελον ἐκέλευε σφέας τὸ τεῖχος περιαιρέειν καὶ τὰς νέας ἐς Ἄβδηρα κομίζειν. οἱ γὰρ δὴ Θάσιοι, οἷα ὑπὸ Ἱστιαίου τε τοῦ Μιλησίου πολιορκηθέντες καὶ προσόδων ἐουσέων μεγαλέων, ἐχρέωντο τοῖσι χρήμασι νέας τε ναυπηγεύμενοι μακρὰς καὶ τεῖχος ἰσχυρότερον περιβαλλόμενοι. ἡ δὲ πρόσοδός σφι ἐγίνετο ἔκ τε τῆς ἠπείρου καὶ ἀπὸ τῶν μετάλλων· ἐκ μέν γε τῶν ἐκ Σκαπτησύλης τῶν χρυσέων μετάλλων τὸ ἐπίπαν ὀγδώκοντα τάλαντα προσήιε, ἐκ δὲ τῶν ἐν αὐτῇ Θάσῳ ἐλάσσω μὲν τούτων, συχνὰ δὲ οὕτω ὥστε τὸ ἐπίπαν Θασίοισι ἐοῦσι καρπῶν ἀτελέσι προσήιε ἀπό τε τῆς ἠπείρου καὶ τῶν μετάλλων ἔτεος ἑκάστου διηκόσια τάλαντα, ὅτε δὲ τὸ πλεῖστον προσῆλθε, τριηκόσια.", "st": "6.46"}, {"sp": "N", "t": "εἶδον δὲ καὶ αὐτὸς τὰ μέταλλα ταῦτα, καὶ μακρῷ ἦν αὐτῶν θωμασιώτατα τὰ οἱ Φοίνικες ἀνεῦρον οἱ μετὰ Θάσου κτίσαντες τὴν νῆσον ταύτην, ἥτις νῦν ἀπὸ τοῦ Θάσου τούτου τοῦ Φοίνικος τὸ οὔνομα ἔσχε. τὰ δὲ μέταλλα τὰ Φοινικικὰ ταῦτα ἐστὶ τῆς Θάσου μεταξὺ Αἰνύρων τε χώρου καλεομένου καὶ Κοινύρων, ἀντίον δὲ Σαμοθρηίκης, ὄρος μέγα ἀνεστραμμένον ἐν τῇ ζητήσι. τοῦτο μέν νυν ἐστὶ τοιοῦτον. οἱ δὲ Θάσιοι τῷ βασιλέι κελεύσαντι καὶ τὸ τεῖχος τὸ σφέτερον κατεῖλον καὶ τὰς νέας τὰς πάσας ἐκόμισαν ἐς Ἄβδηρα.", "st": "6.47"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο ἀπεπειρᾶτο ὁ Δαρεῖος τῶν Ἑλλήνων ὅ τι ἐν νόῳ ἔχοιεν, κότερα πολεμέειν ἑωυτῷ ἢ παραδιδόναι σφέας αὐτούς. διέπεμπε ὦν κήρυκας ἄλλους ἄλλῃ τάξας ἀνὰ τὴν Ἑλλάδα, κελεύων αἰτέειν βασιλέι γῆν τε καὶ ὕδωρ. τούτους μὲν δὴ ἐς τὴν Ἑλλάδα ἔπεμπε, ἄλλους δὲ κήρυκας διέπεμπε ἐς τὰς ἑωυτοῦ δασμοφόρους πόλιας τὰς παραθαλασσίους, κελεύων νέας τε μακρὰς καὶ ἱππαγωγὰ πλοῖα ποιέεσθαι.", "st": "6.48"}, {"sp": "N", "t": "οὗτοί τε δὴ παρεσκευάζοντο ταῦτα, καὶ τοῖσι ἥκουσι ἐς τὴν Ἑλλάδα κήρυξι πολλοὶ μὲν ἠπειρωτέων ἔδοσαν τὰ προΐσχετο αἰτέων ὁ Πέρσης, πάντες δὲ νησιῶται ἐς τοὺς ἀπικοίατο αἰτήσοντες. οἵ τε δὴ ἄλλοι νησιῶται διδοῦσι γῆν τε καὶ ὕδωρ Δαρείῳ καὶ δὴ καὶ Αἰγινῆται. ποιήσασι δέ σφι ταῦτα ἰθέως Ἀθηναῖοι ἐπεκέατο, δοκέοντές τε ἐπὶ σφίσι ἐπέχοντας τοὺς Αἰγινήτας δεδωκέναι ὡς ἅμα τῷ Πέρσῃ ἐπὶ σφέας στρατεύωνται, καὶ ἄσμενοι προφάσιος ἐπελάβοντο, φοιτέοντές τε ἐς τὴν Σπάρτην κατηγόρεον τῶν Αἰγινητέων τὰ πεποιήκοιεν προδόντες τὴν Ἑλλάδα.", "st": "6.49"}, {"sp": "N", "t": "πρὸς ταύτην δὲ τὴν κατηγορίην Κλεομένης ὁ Ἀναξανδρίδεω βασιλεὺς ἐὼν Σπαρτιητέων διέβη ἐς Αἴγιναν, βουλόμενος συλλαβεῖν Αἰγινητέων τοὺς αἰτιωτάτους. ὡς δὲ ἐπειρᾶτο συλλαμβάνων, ἄλλοι τε δὴ ἐγίνοντο αὐτῷ ἀντίξοοι τῶν Αἰγινητέων, ἐν δὲ δὴ καὶ Κριὸς ὁ Πολυκρίτου μάλιστα, ὃς οὐκ ἔφη αὐτὸν οὐδένα ἄξειν χαίροντα Αἰγινητέων· ἄνευ γάρ μιν Σπαρτιητέων τοῦ κοινοῦ ποιέειν ταῦτα, ὑπ’ Ἀθηναίων ἀναγνωσθέντα χρήμασι· ἅμα γὰρ ἄν μιν τῷ ἑτέρῳ βασιλέι ἐλθόντα συλλαμβάνειν. ἔλεγε δὲ ταῦτα ἐξ ἐπιστολῆς τῆς Δημαρήτου. Κλεομένης δὲ ἀπελαυνόμενος ἐκ τῆς Αἰγίνης εἴρετο τὸν Κριὸν ὅ τι οἱ εἴη τὸ οὔνομα· ὁ δέ οἱ τὸ ἐὸν ἔφρασε. ὁ δὲ Κλεομένης πρὸς αὐτὸν ἔφη ἤδη νῦν καταχαλκοῦ ὦ κριὲ τὰ κέρεα, ὡς συνοισόμενος μεγάλῳ κακῷ.", "st": "6.50"}, {"sp": "N", "t": "ἐν δὲ τῇ Σπάρτῃ τοῦτον τὸν χρόνον ὑπομένων Δημάρητος ὁ Ἀρίστωνος διέβαλλε τὸν Κλεομένεα, ἐὼν βασιλεὺς καὶ οὗτος Σπαρτιητέων, οἰκίης δὲ τῆς ὑποδεεστέρης, κατ’ ἄλλο μὲν οὐδὲν ὑποδεεστέρης· ἀπὸ γὰρ τοῦ αὐτοῦ γεγόνασι· κατὰ πρεσβυγενείην δέ κως τετίμηται μᾶλλον ἡ Εὐρυσθένεος.", "st": "6.51"}, {"sp": "N", "t": "Λακεδαιμόνιοι γὰρ ὁμολογέοντες οὐδενὶ ποιητῇ λέγουσι αὐτὸν Ἀριστόδημον τὸν Ἀριστομάχου τοῦ Κλεοδαίου τοῦ Ὕλλου βασιλεύοντα ἀγαγεῖν σφεας ἐς ταύτην τὴν χώρην τὴν νῦν ἐκτέαται, ἀλλ’ οὐ τοὺς Ἀριστοδήμου παῖδας. μετὰ δὲ χρόνον οὐ πολλὸν Ἀριστοδήμῳ τεκεῖν τὴν γυναῖκα, τῇ οὔνομα εἶναι Ἀργείην· θυγατέρα δὲ αὐτὴν λέγουσι εἶναι Αὐτεσίωνος τοῦ Τισαμενοῦ τοῦ Θερσάνδρου τοῦ Πολυνείκεος· ταύτην δὴ τεκεῖν δίδυμα, ἐπιδόντα δὲ τὸν Ἀριστόδημον τὰ τέκνα νούσῳ τελευτᾶν. Λακεδαιμονίους δὲ τοὺς τότε ἐόντας βουλεῦσαι κατὰ νόμον βασιλέα τῶν παίδων τὸν πρεσβύτερον ποιήσασθαι. οὔκων δή σφεας ἔχειν ὁκότερον ἕλωνται ὥστε καὶ ὁμοίων καὶ ἴσων ἐόντων· οὐ δυναμένους δὲ γνῶναι, ἢ καὶ πρὸ τούτου, ἐπειρωτᾶν τὴν τεκοῦσαν. τὴν δὲ οὐδὲ αὐτὴν φάναι διαγινώσκειν. εἰδυῖαν μὲν καὶ τὸ κάρτα λέγειν ταῦτα, βουλομένην δὲ εἴ κως ἀμφότεροι γενοίατο βασιλέες. τοὺς ὦν δὴ Λακεδαιμονίους ἀπορέειν, ἀπορέοντας δὲ πέμπειν ἐς Δελφοὺς ἐπειρησομένους ὅ τι χρήσωνται τῷ πρήγματι. τὴν δὲ Πυθίην σφέας κελεύειν ἀμφότερα τὰ παιδία ἡγήσασθαι βασιλέας, τιμᾶν δὲ μᾶλλον τὸν γεραίτερον. τὴν μὲν δὴ Πυθίην ταῦτά σφι ἀνελεῖν, τοῖσι δὲ Λακεδαιμονίοισι ἀπορέουσι οὐδὲν ἧσσον ὅκως ἐξεύρωσι αὐτῶν τὸν πρεσβύτερον, ὑποθέσθαι ἄνδρα Μεσσήνιον τῷ οὔνομα εἶναι Πανίτην· ὑποθέσθαι δὲ τοῦτον τὸν Πανίτην τάδε τοῖσι Λακεδαιμονίοισι, φυλάξαι τὴν γειναμένην ὁκότερον τῶν παίδων πρότερον λούει καὶ σιτίζει· καὶ ἢν μὲν κατὰ ταὐτὰ φαίνηται αἰεὶ ποιεῦσα, τοὺς δὲ πᾶν ἕξειν ὅσον τι καὶ δίζηνται καὶ θέλουσι ἐξευρεῖν, ἢν δὲ πλανᾶται καὶ ἐκείνη ἐναλλὰξ ποιεῦσα, δῆλά σφι ἔσεσθαι ὡς οὐδὲ ἐκείνη πλέον οὐδὲν οἶδε, ἐπ’ ἄλλην τε τραπέσθαι σφέας ὁδόν. ἐνθαῦτα δὴ τοὺς Σπαρτιήτας κατὰ τὰς τοῦ Μεσσηνίου ὑποθήκας φυλάξαντας τὴν μητέρα τῶν Ἀριστοδήμου παίδων λαβεῖν κατὰ ταὐτὰ τιμῶσαν τὸν πρότερον καὶ σίτοισι καὶ λουτροῖσι, οὐκ εἰδυῖαν τῶν εἵνεκεν ἐφυλάσσετο. λαβόντας δὲ τὸ παιδίον τὸ τιμώμενον πρὸς τῆς γειναμένης ὡς ἐὸν πρότερον τρέφειν ἐν τῷ δημοσίῳ· καί οἱ οὔνομα τεθῆναι Εὐρυσθένεα, τῷ δὲ Προκλέα. τούτους ἀνδρωθέντας αὐτούς τε ἀδελφεοὺς ἐόντας λέγουσι διαφόρους εἶναι τὸν πάντα χρόνον τῆς ζόης ἀλλήλοισι, καὶ τοὺς ἀπὸ τούτων γενομένους ὡσαύτως διατελέειν.", "st": "6.52"}, {"sp": "N", "t": "ταῦτα μὲν Λακεδαιμόνιοι λέγουσι μοῦνοι Ἑλλήνων· τάδε δὲ κατὰ τὰ λεγόμενα ὑπ’ Ἑλλήνων ἐγὼ γράφω, τούτους τοὺς Δωριέων βασιλέας μέχρι μὲν δὴ Περσέος τοῦ Δανάης, τοῦ θεοῦ ἀπεόντος, καταλεγομένους ὀρθῶς ὑπ’ Ἑλλήνων καὶ ἀποδεικνυμένους ὡς εἰσὶ Ἕλληνες· ἤδη γὰρ τηνικαῦτα ἐς Ἕλληνας οὗτοι ἐτέλεον. ἔλεξα δὲ μέχρι Περσέος τοῦδε εἵνεκα, ἀλλ’ οὐκ ἀνέκαθεν ἔτι ἔλαβον, ὅτι οὐκ ἔπεστι ἐπωνυμίη Περσέι οὐδεμία πατρὸς θνητοῦ, ὥσπερ Ἡρακλέι Ἀμφιτρύων. ἤδη ὦν ὀρθῷ χρεωμένῳ μέχρι Περσέος ὀρθῶς εἴρηταί μοι· ἀπὸ δὲ Δανάης τῆς Ἀκρισίου καταλέγοντι τοὺς ἄνω αἰεὶ πατέρας αὐτῶν φαινοίατο ἂν ἐόντες οἱ τῶν Δωριέων ἡγεμόνες Αἰγύπτιοι ἰθαγενέες.", "st": "6.53"}, {"sp": "N", "t": "ταῦτα μέν νυν κατὰ τὰ Ἕλληνες λέγουσι γεγενεηλόγηται· ὡς δὲ ὁ παρὰ Περσέων λόγος λέγεται, αὐτὸς ὁ Περσεὺς ἐὼν Ἀσσύριος ἐγένετο Ἕλλην, ἀλλ’ οὐκ οἱ Περσέος πρόγονοι· τοὺς δὲ Ἀκρισίου γε πατέρας ὁμολογέοντας κατ’ οἰκηιότητα Περσέι οὐδέν, τούτους δὲ εἶναι, κατά περ Ἕλληνες λέγουσι, Αἰγυπτίους.", "st": "6.54"}, {"sp": "N", "t": "καὶ ταῦτα μέν νυν περὶ τούτων εἰρήσθω. ὅ τι δὲ ἐόντες Αἰγύπτιοι καὶ ὅ τι ἀποδεξάμενοι ἔλαβον τὰς Δωριέων βασιληίας, ἄλλοισι γὰρ περὶ αὐτῶν εἴρηται, ἐάσομεν αὐτά· τὰ δὲ ἄλλοι οὐ κατελάβοντο, τούτων μνήμην ποιήσομαι.", "st": "6.55"}, {"sp": "N", "t": "γέρεά τε δὴ τάδε τοῖσι βασιλεῦσι Σπαρτιῆται δεδώκασι, ἱρωσύνας δύο, Διός τε Λακεδαίμονος καὶ Διὸς οὐρανίου, καὶ πόλεμον ἐκφέρειν ἐπ’ ἣν ἂν βούλωνται χώρην, τούτου δὲ μηδένα εἶναι Σπαρτιητέων διακωλυτήν, εἰ δὲ μὴ αὐτὸν ἐν τῷ ἄγεϊ ἐνέχεσθαι. στρατευομένων δὲ πρώτους ἰέναι τοὺς βασιλέας, ὑστάτους δὲ ἀπιέναι· ἑκατὸν δὲ ἄνδρας λογάδας ἐπὶ στρατιῆς φυλάσσειν αὐτούς· προβάτοισι δὲ χρᾶσθαι ἐν τῇσι ἐξοδίῃσι ὁκόσοισι ἂν ὦν ἐθέλωσι, τῶν δὲ θυομένων πάντων τὰ δέρματά τε καὶ τὰ νῶτα λαμβάνειν σφεας.", "st": "6.56"}, {"sp": "N", "t": "ταῦτα μὲν τὰ ἐμπολέμια, τὰ δὲ ἄλλα τὰ εἰρηναῖα κατὰ τάδε σφι δέδοται. ἢν θυσίη τις δημοτελὴς ποιέηται, πρώτους ἐπὶ τὸ δεῖπνον ἵζειν τοὺς βασιλέας, καὶ ἀπὸ τούτων πρῶτον ἄρχεσθαι διπλήσια νέμοντας ἑκατέρῳ τὰ πάντα ἢ τοῖσι ἄλλοισι δαιτυμόνεσι, καὶ σπονδαρχίας εἶναι τούτων καὶ τῶν τυθέντων τὰ δέρματα. νεομηνίας δὲ πάσας καὶ ἑβδόμας ἱσταμένου τοῦ μηνὸς δίδοσθαι ἐκ τοῦ δημοσίου ἱρήιον τέλεον ἑκατέρῳ ἐς Ἀπόλλωνος καὶ μέδιμνον ἀλφίτων καὶ οἴνου τετάρτην Λακωνικήν, καὶ ἐν τοῖσι ἀγῶσι πᾶσι προεδρίας ἐξαιρέτους. καὶ προξείνους ἀποδεικνύναι τούτοισι προσκεῖσθαι τοὺς ἂν ἐθέλωσι τῶν ἀστῶν, καὶ Πυθίους αἱρέεσθαι δύο ἑκάτερον. οἱ δὲ Πύθιοι εἰσὶ θεοπρόποι ἐς Δελφούς, σιτεόμενοι μετὰ τῶν βασιλέων τὰ δημόσια. μὴ ἐλθοῦσι δὲ τοῖσι βασιλεῦσι ἐπὶ τὸ δεῖπνον ἀποπέμπεσθαί σφι ἐς τὰ οἰκία ἀλφίτων τε δύο χοίνικας ἑκατέρῳ καὶ οἴνου κοτύλην, παρεοῦσι δὲ διπλήσια πάντα δίδοσθαι· τὠυτὸ δὲ τοῦτο καὶ πρὸς ἰδιωτέων κληθέντας ἐπὶ δεῖπνον τιμᾶσθαι. τὰς δὲ μαντηίας τὰς γινομένας τούτους φυλάσσειν, συνειδέναι δὲ καὶ τοὺς Πυθίους. δικάζειν δὲ μούνους τοὺς βασιλέας τοσάδε μοῦνα, πατρούχου τε παρθένου πέρι, ἐς τὸν ἱκνέεται ἔχειν, ἢν μή περ ὁ πατὴρ αὐτὴν ἐγγυήσῃ, καὶ ὁδῶν δημοσιέων πέρι· καὶ ἤν τις θετὸν παῖδα ποιέεσθαι ἐθέλῃ, βασιλέων ἐναντίον ποιέεσθαι. καὶ παρίζειν βουλεύουσι τοῖσι γέρουσι ἐοῦσι δυῶν δέουσι τριήκοντα· ἢν δὲ μὴ ἔλθωσι, τοὺς μάλιστά σφι τῶν γερόντων προσήκοντας ἔχειν τὰ τῶν βασιλέων γέρεα, δύο ψήφους τιθεμένους, τρίτην δὲ τὴν ἑωυτῶν.", "st": "6.57"}, {"sp": "N", "t": "ταῦτα μὲν ζῶσι τοῖσι βασιλεῦσι δέδοται ἐκ τοῦ κοινοῦ τῶν Σπαρτιητέων, ἀποθανοῦσι δὲ τάδε. ἱππέες περιαγγέλλουσι τὸ γεγονὸς κατὰ πᾶσαν τὴν Λακωνικήν, κατὰ δὲ τὴν πόλιν γυναῖκες περιιοῦσαι λέβητα κροτέουσι. ἐπεὰν ὦν τοῦτο γίνηται τοιοῦτο, ἀνάγκη ἐξ οἰκίης ἑκάστης ἐλευθέρους δύο καταμιαίνεσθαι, ἄνδρα τε καὶ γυναῖκα· μὴ ποιήσασι δὲ τοῦτο ζημίαι μεγάλαι ἐπικέαται. νόμος δὲ τοῖσι Λακεδαιμονίοισι κατὰ τῶν βασιλέων τοὺς θανάτους ἐστὶ ὡυτὸς καὶ τοῖσι βαρβάροισι τοῖσι ἐν τῇ Ἀσίῃ· τῶν γὰρ ὦν βαρβάρων οἱ πλεῦνες τῷ αὐτῷ νόμῳ χρέωνται κατὰ τοὺς θανάτους τῶν βασιλέων. ἐπεὰν γὰρ ἀποθάνῃ βασιλεὺς Λακεδαιμονίων, ἐκ πάσης δεῖ Λακεδαίμονος, χωρὶς Σπαρτιητέων, ἀριθμῷ τῶν περιοίκων ἀναγκαστοὺς ἐς τὸ κῆδος ἰέναι. τούτων ὦν καὶ τῶν εἱλωτέων καὶ αὐτῶν Σπαρτιητέων ἐπεὰν συλλεχθέωσι ἐς τὠυτὸ πολλαὶ χιλιάδες σύμμιγα τῇσι γυναιξί, κόπτονταί τε τὰ μέτωπα προθύμως καὶ οἰμωγῇ διαχρέωνται ἀπλέτῳ, φάμενοι τὸν ὕστατον αἰεὶ ἀπογενόμενον τῶν βασιλέων, τοῦτον δὴ γενέσθαι ἄριστον. ὃς δ’ ἂν ἐν πολέμῳ τῶν βασιλέων ἀποθάνῃ, τούτῳ δὲ εἴδωλον σκευάσαντες ἐν κλίνῃ εὖ ἐστρωμένῃ ἐκφέρουσι. ἐπεὰν δὲ θάψωσι, ἀγορὴ δέκα ἡμερέων οὐκ ἵσταταί σφι οὐδ’ ἀρχαιρεσίη συνίζει, ἀλλὰ πενθέουσι ταύτας τὰς ἡμέρας.", "st": "6.58"}, {"sp": "N", "t": "συμφέρονται δὲ ἄλλο οὗτοι τόδε τοῖσι Πέρσῃσι· ἐπεὰν ἀποθανόντος τοῦ βασιλέος ἄλλος ἐνίστηται βασιλεύς, οὗτος ὁ ἐσιὼν ἐλευθεροῖ ὅστις τι Σπαρτιητέων τῷ βασιλέι ἢ τῷ δημοσίῳ ὤφειλε· ἐν δ’ αὖ Πέρσῃσι ὁ κατιστάμενος βασιλεὺς τὸν προοφειλόμενον φόρον μετιεῖ τῇσι πόλισι πάσῃσι.", "st": "6.59"}, {"sp": "N", "t": "συμφέρονται δὲ καὶ τάδε Αἰγυπτίοισι Λακεδαιμόνιοι· οἱ κήρυκες αὐτῶν καὶ αὐληταὶ καὶ μάγειροι ἐκδέκονται τὰς πατρωίας τέχνας, καὶ αὐλητής τε αὐλητέω γίνεται καὶ μάγειρος μαγείρου καὶ κῆρυξ κήρυκος· οὐ κατὰ λαμπροφωνίην ἐπιτιθέμενοι ἄλλοι σφέας παρακληίουσι, ἀλλὰ κατὰ τὰ πάτρια ἐπιτελέουσι.", "st": "6.60"}, {"sp": "N", "t": "ταῦτα μὲν δὴ οὕτω γίνεται. τότε δὲ τὸν Κλεομένεα ἐόντα ἐν τῇ Αἰγίνῃ καὶ κοινὰ τῇ Ἑλλάδι ἀγαθὰ προεργαζόμενον ὁ Δημάρητος διέβαλε, οὐκ Αἰγινητέων οὕτω κηδόμενος ὡς φθόνῳ καὶ ἄγῃ χρεώμενος. Κλεομένης δὲ νοστήσας ἀπ’ Αἰγίνης ἐβούλευε τὸν Δημάρητον παῦσαι τῆς βασιληίης, διὰ πρῆγμα τοιόνδε ἐπίβασιν ἐς αὐτὸν ποιεύμενος. Ἀρίστωνι βασιλεύοντι ἐν Σπάρτῃ καὶ γήμαντι γυναῖκας δύο παῖδες οὐκ ἐγίνοντο. καὶ οὐ γὰρ συνεγινώσκετο αὐτὸς τούτων εἶναι αἴτιος, γαμέει τρίτην γυναῖκα· ὧδε δὲ γαμέει. ἦν οἱ φίλος τῶν Σπαρτιητέων ἀνήρ, τῷ προσέκειτο τῶν ἀστῶν μάλιστα ὁ Ἀρίστων. τούτῳ τῷ ἀνδρὶ ἐτύγχανε ἐοῦσα γυνὴ καλλίστη μακρῷ τῶν ἐν Σπάρτῃ γυναικῶν, καὶ ταῦτα μέντοι καλλίστη ἐξ αἰσχίστης γενομένη. ἐοῦσαν γάρ μιν τὸ εἶδος φλαύρην ἡ τροφὸς αὐτῆς, οἷα ἀνθρώπων τε ὀλβίων θυγατέρα καὶ δυσειδέα ἐοῦσαν, πρὸς δὲ καὶ ὁρῶσα τοὺς γονέας συμφορὴν τὸ εἶδος αὐτῆς ποιευμένους, ταῦτα ἕκαστα μαθοῦσα ἐπιφράζεται τοιάδε· ἐφόρεε αὐτὴν ἀνὰ πᾶσαν ἡμέρην ἐς τὸ τῆς Ἑλένης ἱρόν. τὸ δ’ ἐστὶ ἐν τῇ Θεράπνῃ καλεομένῃ ὕπερθε τοῦ Φοιβηίου ἱροῦ. ὅκως δὲ ἐνείκειε ἡ τροφός, πρός τε τὤγαλμα ἵστα καὶ ἐλίσσετο τὴν θεὸν ἀπαλλάξαι τῆς δυσμορφίης τὸ παιδίον. καὶ δή κοτε ἀπιούσῃ ἐκ τοῦ ἱροῦ τῇ τροφῷ γυναῖκα λέγεται ἐπιφανῆναι, ἐπιφανεῖσαν δὲ ἐπειρέσθαι μιν ὅ τι φέρει ἐν τῇ ἀγκάλῃ, καὶ τὴν φράσαι ὡς παιδίον φορέει, τὴν δὲ κελεῦσαί οἱ δέξαι, τὴν δὲ οὐ φάναι· ἀπειρῆσθαι γάρ οἱ ἐκ τῶν γειναμένων μηδενὶ ἐπιδεικνύναι· τὴν δὲ πάντως ἑωυτῇ κελεύειν ἐπιδέξαι. ὁρῶσαν δὲ τὴν γυναῖκα περὶ πολλοῦ ποιευμένην ἰδέσθαι, οὕτω δὴ τὴν τροφὸν δέξαι τὸ παιδίον· τὴν δὲ καταψῶσαν τοῦ παιδίου τὴν κεφαλὴν εἶπαι ὡς καλλιστεύσει πασέων τῶν ἐν Σπάρτῃ γυναικῶν. ἀπὸ μὲν δὴ ταύτης τῆς ἡμέρης μεταπεσεῖν τὸ εἶδος. γαμέει δὲ δή μιν ἐς γάμου ὥρην ἀπικομένην Ἄγητος ὁ Ἀλκείδεω, οὗτος δὴ ὁ τοῦ Ἀρίστωνος φίλος.", "st": "6.61"}, {"sp": "N", "t": "τὸν δὲ Ἀρίστωνα ἔκνιζε ἄρα τῆς γυναικὸς ταύτης ὁ ἔρως· μηχανᾶται δὴ τοιάδε· αὐτός τε τῷ ἑταίρῳ, τοῦ ἦν ἡ γυνὴ αὕτη, ὑποδέκεται δωτίνην δώσειν τῶν ἑωυτοῦ πάντων ἕν, τὸ ἂν αὐτὸς ἐκεῖνος ἕληται, καὶ τὸν ἑταῖρον ἑωυτῷ ἐκέλευε ὡσαύτως τὴν ὁμοίην διδόναι· ὁ δὲ οὐδὲν φοβηθεὶς ἀμφὶ τῇ γυναικί, ὁρέων ἐοῦσαν καὶ Ἀρίστωνι γυναῖκα, καταινέει ταῦτα· ἐπὶ τούτοισι δὲ ὅρκους ἐπήλασαν. μετὰ δὲ αὐτός τε ὁ Ἀρίστων ἔδωκε τοῦτο, ὅ τι δὴ ἦν, τὸ εἵλετο τῶν κειμηλίων τῶν Ἀρίστωνος ὁ Ἄγητος, καὶ αὐτὸς τὴν ὁμοίην ζητέων φέρεσθαι παρ’ ἐκείνου, ἐνθαῦτα δὴ τοῦ ἑταίρου τὴν γυναῖκα ἐπειρᾶτο ἀπάγεσθαι. ὁ δὲ πλὴν τούτου μούνου τὰ ἄλλα ἔφη καταινέσαι· ἀναγκαζόμενος μέντοι τῷ τε ὅρκῳ καὶ τῆς ἀπάτης τῇ παραγωγῇ ἀπιεῖ ἀπάγεσθαι.", "st": "6.62"}, {"sp": "N", "t": "οὕτω μὲν δὴ τὴν τρίτην ἐσηγάγετο γυναῖκα ὁ Ἀρίστων, τὴν δευτέρην ἀποπεμψάμενος. ἐν δέ οἱ χρόνῳ ἐλάσσονι καὶ οὐ πληρώσασα τοὺς δέκα μῆνας ἡ γυνὴ αὕτη τίκτει τοῦτον δὴ τὸν Δημάρητον. καί τίς οἱ τῶν οἰκετέων ἐν θώκῳ κατημένῳ μετὰ τῶν ἐφόρων ἐξαγγέλλει ὥς οἱ παῖς γέγονε. ὁ δὲ ἐπιστάμενός τε τὸν χρόνον τῷ ἠγάγετο τὴν γυναῖκα καὶ ἐπὶ δακτύλων συμβαλλόμενος τοὺς μῆνας, εἶπε ἀπομόσας οὐκ ἂν ἐμὸς εἴη. τοῦτο ἤκουσαν μὲν οἱ ἔφοροι, πρῆγμα μέντοι οὐδὲν ἐποιήσαντο τὸ παραυτίκα. ὁ δὲ παῖς ηὔξετο, καὶ τῷ Ἀρίστωνι τὸ εἰρημένον μετέμελε· παῖδα γὰρ τὸν Δημάρητον ἐς τὰ μάλιστά οἱ ἐνόμισε εἶναι. Δημάρητον δὲ αὐτῷ οὔνομα ἔθετο διὰ τόδε· πρότερον τούτων πανδημεὶ Σπαρτιῆται Ἀρίστωνι, ὡς ἀνδρὶ εὐδοκιμέοντι διὰ πάντων δὴ τῶν βασιλέων τῶν ἐν Σπάρτῃ γενομένων, ἀρὴν ἐποιήσαντο παῖδα γενέσθαι.", "st": "6.63"}, {"sp": "N", "t": "διὰ τοῦτο μέν οἱ τὸ οὔνομα Δημάρητος ἐτέθη· χρόνου δὲ προϊόντος Ἀρίστων μὲν ἀπέθανε, Δημάρητος δὲ ἔσχε τὴν βασιληίην. ἔδεε δέ, ὡς ἔοικε, ἀνάπυστα γενόμενα ταῦτα καταπαῦσαι Δημάρητον τῆς βασιληίης διὰ τὰ … Κλεομένεϊ διεβλήθη μεγάλως πρότερόν τε ὁ Δημάρητος ἀπαγαγὼν τὴν στρατιὴν ἐξ Ἐλευσῖνος, καὶ δὴ καὶ τότε ἐπ’ Αἰγινητέων τοὺς μηδίσαντας διαβάντος Κλεομένεος.", "st": "6.64"}, {"sp": "N", "t": "ὁρμηθεὶς ὦν ἀποτίνυσθαι ὁ Κλεομένης συντίθεται Λευτυχίδῃ τῷ Μενάρεος τοῦ Ἄγιος, ἐόντι οἰκίης τῆς αὐτῆς Δημαρήτῳ, ἐπ’ ᾧ τε, ἢν αὐτὸν καταστήσῃ βασιλέα ἀντὶ Δημαρήτου, ἕψεταί οἱ ἐπ’ Αἰγινήτας. ὁ δὲ Λευτυχίδης ἦν ἐχθρὸς τῷ Δημαρήτῳ μάλιστα γεγονὼς διὰ πρῆγμα τοιόνδε· ἁρμοσαμένου Λευτυχίδεω Πέρκαλον τὴν Χίλωνος τοῦ Δημαρμένου θυγατέρα, ὁ Δημάρητος ἐπιβουλεύσας ἀποστερέει Λευτυχίδεα τοῦ γάμου, φθάσας αὐτὸς τὴν Πέρκαλον ἁρπάσας καὶ σχὼν γυναῖκα. κατὰ τοῦτο μὲν τῷ Λευτυχίδῃ ἡ ἔχθρη ἡ ἐς τὸν Δημάρητον ἐγεγόνεε, τότε δὲ ἐκ τῆς Κλεομένεος προθυμίης ὁ Λευτυχίδης κατόμνυται Δημαρήτῳ, φὰς αὐτὸν οὐκ ἱκνεομένως βασιλεύειν Σπαρτιητέων οὐκ ἐόντα παῖδα Ἀρίστωνος· μετὰ δὲ τὴν κατωμοσίην ἐδίωκε, ἀνασώζων ἐκεῖνο τὸ ἔπος τὸ εἶπε Ἀρίστων τότε ὅτε οἱ ἐξήγγειλε ὁ οἰκέτης παῖδα γεγονέναι, ὁ δὲ συμβαλόμενος τοὺς μῆνας ἀπώμοσε φὰς οὐκ ἑωυτοῦ μιν εἶναι. τούτου δὴ ἐπιβατεύων τοῦ ῥήματος ὁ Λευτυχίδης ἀπέφαινε τὸν Δημάρητον οὔτε ἐξ Ἀρίστωνος γεγονότα οὔτε ἱκνευμένως βασιλεύοντα Σπάρτης, τοὺς ἐφόρους μάρτυρας παρεχόμενος κείνους οἳ τότε ἐτύγχανον πάρεδροί τε ἐόντες καὶ ἀκούσαντες ταῦτα Ἀρίστωνος.", "st": "6.65"}, {"sp": "N", "t": "τέλος δὲ ἐόντων περὶ αὐτῶν νεικέων, ἔδοξε Σπαρτιήτῃσι ἐπειρέσθαι τὸ χρηστήριον τὸ ἐν Δελφοῖσι εἰ Ἀρίστωνος εἴη παῖς ὁ Δημάρητος. ἀνοίστου δὲ γενομένου ἐκ προνοίης τῆς Κλεομένεος ἐς τὴν Πυθίην, ἐνθαῦτα προσποιέεται Κλεομένης Κόβωνα τὸν Ἀριστοφάντου, ἄνδρα ἐν Δελφοῖσι δυναστεύοντα μέγιστον, ὁ δὲ Κόβων Περίαλλαν τὴν πρόμαντιν ἀναπείθει τὰ Κλεομένης ἐβούλετο λέγεσθαι λέγειν. οὕτω δὴ ἡ Πυθίη ἐπειρωτώντων τῶν θεοπρόπων ἔκρινε μὴ Ἀρίστωνος εἶναι Δημάρητον παῖδα. ὑστέρῳ μέντοι χρόνῳ ἀνάπυστα ἐγένετο ταῦτα, καὶ Κόβων τε ἔφυγε ἐκ Δελφῶν καὶ Περίαλλα ἡ πρόμαντις ἐπαύσθη τῆς τιμῆς.", "st": "6.66"}, {"sp": "N", "t": "κατὰ μὲν δὴ Δημαρήτου τὴν κατάπαυσιν τῆς βασιληίης οὕτω ἐγένετο, ἔφυγε δὲ Δημάρητος ἐκ Σπάρτης ἐς Μήδους ἐκ τοιοῦδε ὀνείδεος. μετὰ τῆς βασιληίης τὴν κατάπαυσιν ὁ Δημάρητος ἦρχε αἱρεθεὶς ἀρχήν. ἦσαν μὲν δὴ γυμνοπαιδίαι, θεωμένου δὲ τοῦ Δημαρήτου ὁ Λευτυχίδης γεγονὼς ἤδη βασιλεὺς αὐτὸς ἀντ’ ἐκείνου, πέμψας τὸν θεράποντα ἐπὶ γέλωτί τε καὶ λάσθῃ εἰρώτα τὸν Δημάρητον ὁκοῖόν τι εἴη τὸ ἄρχειν μετὰ τὸ βασιλεύειν. ὁ δὲ ἀλγήσας τῷ ἐπειρωτήματι εἶπε φὰς αὐτὸς μὲν ἀμφοτέρων ἤδη πεπειρῆσθαι, κεῖνον δὲ οὔ, τὴν μέντοι ἐπειρώτησιν ταύτην ἄρξειν Λακεδαιμονίοισι ἢ μυρίης κακότητος ἢ μυρίης εὐδαιμονίης. ταῦτα δὲ εἴπας καὶ κατακαλυψάμενος ἤιε ἐκ τοῦ θεήτρου ἐς τὰ ἑωυτοῦ οἰκία, αὐτίκα δὲ παρασκευασάμενος ἔθυε τῷ Διὶ βοῦν, θύσας δὲ τὴν μητέρα ἐκάλεσε.", "st": "6.67"}, {"sp": "N", "t": "ἀπικομένῃ δὲ τῇ μητρὶ ἐσθεὶς ἐς τὰς χεῖράς οἱ τῶν σπλάγχνων κατικέτευε, τοιάδε λέγων. ὦ μῆτερ, θεῶν σε τῶν τε ἄλλων καταπτόμενος ἱκετεύω καὶ τοῦ ἑρκείου Διὸς τοῦδε φράσαι μοι τὴν ἀληθείην, τίς μευ ἐστὶ πατὴρ ὀρθῷ λόγῳ. Λευτυχίδης μὲν γὰρ ἔφη ἐν τοῖσι νείκεσι λέγων κυέουσάν σε ἐκ τοῦ προτέρου ἀνδρὸς οὕτω ἐλθεῖν παρὰ Ἀρίστωνα· οἱ δὲ καὶ τὸν ματαιότερον λόγον λέγοντες φασί σε ἐλθεῖν παρὰ τῶν οἰκετέων τὸν ὀνοφορβόν, καὶ ἐμὲ ἐκείνου εἶναι παῖδα. ἐγώ σε ὦν μετέρχομαι τῶν θεῶν εἰπεῖν τὠληθές· οὔτε γάρ, εἴ περ πεποίηκάς τι τῶν λεγομένων, μούνη δὴ πεποίηκας, μετὰ πολλέων δέ· ὅ τε λόγος πολλὸς ἐν Σπάρτῃ ὡς Ἀρίστωνι σπέρμα παιδοποιὸν οὐκ ἐνῆν· τεκεῖν γὰρ ἄν οἱ καὶ τὰς προτέρας γυναῖκας.", "st": "6.68"}, {"sp": "N", "t": "ὃ μὲν δὴ τοιαῦτα ἔλεγε, ἣ δὲ ἀμείβετο τοῖσιδε. ὦ παῖ, ἐπείτε με λιτῇσι μετέρχεαι εἰπεῖν τὴν ἀληθείην, πᾶν ἐς σὲ κατειρήσεται τὠληθές. ὥς με ἠγάγετο Ἀρίστων ἐς ἑωυτοῦ, νυκτὶ τρίτῃ ἀπὸ τῆς πρώτης ἦλθέ μοι φάσμα εἰδόμενον Ἀρίστωνι, συνευνηθὲν δὲ τοὺς στεφάνους τοὺς εἶχε ἐμοὶ περιετίθεε. καὶ τὸ μὲν οἰχώκεε, ἧκε δὲ μετὰ ταῦτα Ἀρίστων. ὡς δέ με εἶδε ἔχουσαν στεφάνους, εἰρώτα τίς εἴη μοι ὁ δούς· ἐγὼ δὲ ἐφάμην ἐκεῖνον, ὁ δὲ οὐκ ὑπεδέκετο. ἐγὼ δὲ κατωμνύμην φαμένη αὐτὸν οὐ ποιέειν καλῶς ἀπαρνεόμενον· ὀλίγῳ γὰρ τι πρότερον ἐλθόντα καὶ συνευνηθέντα δοῦναί μοι τοὺς στεφάνους. ὁρέων δέ με κατομνυμένην ὁ Ἀρίστων ἔμαθε ὡς θεῖον εἴη τὸ πρῆγμα. καὶ τοῦτο μὲν οἱ στέφανοι ἐφάνησαν ἐόντες ἐκ τοῦ ἡρωίου τοῦ παρὰ τῇσι θύρῃσι τῇσι αὐλείῃσι ἱδρυμένου, τὸ καλέουσι Ἀστροβάκου, τοῦτο δὲ οἱ μάντιες τὸν αὐτὸν τοῦτον ἥρωα ἀναίρεον εἶναι. οὕτω ὦ παῖ ἔχεις πᾶν, ὅσον τι καὶ βούλεαι πυθέσθαι· ἢ γὰρ ἐκ τοῦ ἥρωος τούτου γέγονας, καί τοι πατήρ ἐστι Ἀστρόβακος ὁ ἥρως, ἢ Ἀρίστων· ἐν γάρ σε τῇ νυκτὶ ταύτῃ ἀναιρέομαι. τῇ δέ σευ μάλιστα κατάπτονται οἱ ἐχθροί, λέγοντες ὡς αὐτὸς ὁ Ἀρίστων, ὅτε αὐτῷ σὺ ἠγγέλθης γεγενημένος, πολλῶν ἀκουόντων οὐ φήσειέ σε ἑωυτοῦ εἶναι (τὸν χρόνον γάρ, τοὺς δέκα μῆνας, οὐδέκω ἐξήκειν), ἀιδρείῃ τῶν τοιούτων κεῖνος τοῦτο ἀπέρριψε τὸ ἔπος. τίκτουσι γὰρ γυναῖκες καὶ ἐννεάμηνα καὶ ἑπτάμηνα, καὶ οὐ πᾶσαι δέκα μῆνας ἐκτελέσασαι· ἐγὼ δὲ σὲ ὦ παῖ ἑπτάμηνον ἔτεκον. ἔγνω δὲ καὶ αὐτὸς ὁ Ἀρίστων οὐ μετὰ πολλὸν χρόνον ὡς ἀνοίῃ τὸ ἔπος ἐκβάλοι τοῦτο. λόγους δὲ ἄλλους περὶ γενέσιος τῆς σεωυτοῦ μὴ δέκεο· τὰ γὰρ ἀληθέστατα πάντα ἀκήκοας. ἐκ δὲ ὀνοφορβῶν αὐτῷ τε Λευτυχίδῃ καὶ τοῖσι ταῦτα λέγουσι τίκτοιεν αἱ γυναῖκες παῖδας.", "st": "6.69"}, {"sp": "N", "t": "ἣ μὲν δὴ ταῦτα ἔλεγε, ὁ δὲ πυθόμενός τε τὰ ἐβούλετο καὶ ἐπόδια λαβὼν ἐπορεύετο ἐς Ἦλιν, τῷ λόγῳ φὰς ὡς ἐς Δελφοὺς χρησόμενος τῷ χρηστηρίῳ πορεύεται. Λακεδαιμόνιοι δὲ ὑποτοπηθέντες Δημάρητον δρησμῷ ἐπιχειρέειν ἐδίωκον. καί κως ἔφθη ἐς Ζάκυνθον διαβὰς ὁ Δημάρητος ἐκ τῆς Ἤλιδος· ἐπιδιαβάντες δὲ οἱ Λακεδαιμόνιοι αὐτοῦ τε ἅπτοντο καὶ τοὺς θεράποντας αὐτοῦ ἀπαιρέονται. μετὰ δέ, οὐ γὰρ ἐξεδίδοσαν αὐτὸν οἱ Ζακύνθιοι, ἐνθεῦτεν διαβαίνει ἐς τὴν Ἀσίην παρὰ βασιλέα Δαρεῖον. ὁ δὲ ὑπεδέξατό τε αὐτὸν μεγαλωστὶ καὶ γῆν τε καὶ πόλιας ἔδωκε. οὕτω ἀπίκετο ἐς τὴν Ἀσίην Δημάρητος καὶ τοιαύτῃ χρησάμενος τύχῃ, ἄλλα τε Λακεδαιμονίοισι συχνὰ ἔργοισί τε καὶ γνώμῃσι ἀπολαμπρυνθείς, ἐν δὲ δὴ καὶ Ὀλυμπιάδα σφι ἀνελόμενος τεθρίππῳ προσέβαλε, μοῦνος τοῦτο πάντων δὴ τῶν γενομένων βασιλέων ἐν Σπάρτῃ ποιήσας.", "st": "6.70"}, {"sp": "N", "t": "Λευτυχίδης δὲ ὁ Μενάρεος Δημαρήτου καταπαυσθέντος διεδέξατο τὴν βασιληίην, καί οἱ γίνεται παῖς Ζευξίδημος, τὸν δὴ Κυνίσκον μετεξέτεροι Σπαρτιητέων ἐκάλεον. οὗτος ὁ Ζευξίδημος οὐκ ἐβασίλευσε Σπάρτης· πρὸ Λευτυχίδεω γὰρ τελευτᾷ, λιπὼν παῖδα Ἀρχίδημον. Δευτυχίδης δὲ στερηθεὶς Ζευξιδήμου γαμέει δευτέρην γυναῖκα Εὐρυδάμην τὴν ἐοῦσαν Μενίου ἀδελφεὴν Διακτορίδεω δὲ θυγατέρα, ἐκ τῆς οἱ ἔρσεν μὲν γίνεται οὐδέν, θυγάτηρ δὲ Λαμπιτώ, τὴν Ἀρχίδημος ὁ Ζευξιδήμου γαμέει δόντος αὐτῷ Λευτυχίδεω.", "st": "6.71"}, {"sp": "N", "t": "οὐ μὲν οὐδὲ Λευτυχίδης κατεγήρα ἐν Σπάρτῃ, ἀλλὰ τίσιν τοιήνδε τινὰ Δημαρήτῳ ἐξέτισε. ἐστρατήγησε Λακεδαιμονίοισι ἐς Θεσσαλίην, παρεὸν δέ οἱ πάντα ὑποχείρια ποιήσασθαι ἐδωροδόκησε ἀργύριον πολλόν· ἐπ’ αὐτοφώρῳ δὲ ἁλοὺς αὐτοῦ ἐν τῷ στρατοπέδῳ, ἐπικατήμενος χειρίδι πλέῃ ἀργυρίου, ἔφυγε ἐκ Σπάρτης ὑπὸ δικαστήριον ὑπαχθείς, καὶ τὰ οἰκία οἱ κατεσκάφη· ἔφυγε δὲ ἐς Τεγέην καὶ ἐτελεύτησε ἐν ταύτῃ.", "st": "6.72"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἐγένετο χρόνῳ ὕστερον· τότε δὲ ὡς τῷ Κλεομένεϊ ὡδώθη τὸ ἐς τὸν Δημάρητον πρῆγμα, αὐτίκα παραλαβὼν Λευτυχίδεα ἤιε ἐπὶ τοὺς Αἰγινήτας, δεινόν τινά σφι ἔγκοτον διὰ τὸν προπηλακισμὸν ἔχων. οὕτω δὴ οὔτε οἱ Αἰγινῆται, ἀμφοτέρων τῶν βασιλέων ἡκόντων ἐπ’ αὐτούς, ἐδικαίευν ἔτι ἀντιβαίνειν, ἐκεῖνοί τε ἐπιλεξάμενοι ἄνδρας δέκα Αἰγινητέων τοὺς πλείστου ἀξίους καὶ πλούτῳ καὶ γένει· ἦγον καὶ ἄλλους καὶ δὴ καὶ Κριόν τε τὸν Πολυκρίτου καὶ Κάσαυβον τὸν Ἀριστοκράτεος, οἵ περ εἶχον μέγιστον κράτος· ἀγαγόντες δὲ σφέας ἐς γῆν τὴν Ἀττικὴν παραθήκην παρατίθενται ἐς τοὺς ἐχθίστους Αἰγινήτῃσι Ἀθηναίους.", "st": "6.73"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα Κλεομένεα ἐπάιστον γενόμενον κακοτεχνήσαντα ἐς Δημάρητον δεῖμα ἔλαβε Σπαρτιητέων, καὶ ὑπεξέσχε ἐς Θεσσαλίην. ἐνθεῦτεν δὲ ἀπικόμενος ἐς τὴν Ἀρκαδίην νεώτερα ἔπρησσε πρήγματα, συνιστὰς τοὺς Ἀρκάδας ἐπὶ τῇ Σπάρτῃ, ἄλλους τε ὅρκους προσάγων σφι ἦ μὲν ἕψεσθαι σφέας αὐτῷ τῇ ἂν ἐξηγέηται, καὶ δὴ καὶ ἐς Νώνακριν πόλιν πρόθυμος ἦν τῶν Ἀρκάδων τοὺς προεστεῶτας ἀγινέων ἐξορκοῦν τὸ Στυγὸς ὕδωρ. ἐν δὲ ταύτῃ τῇ πόλι λέγεται εἶναι ὑπὸ τῶν Ἀρκάδων τὸ Στυγὸς ὕδωρ, καὶ δὴ καὶ ἔστι τοιόνδε τι· ὕδωρ ὀλίγον φαινόμενον ἐκ πέτρης στάζει ἐς ἄγκος, τὸ δὲ ἄγκος αἱμασιῆς τις περιθέει κύκλος. ἡ δὲ Νώνακρις, ἐν τῇ ἡ πηγὴ αὕτη τυγχάνει ἐοῦσα, πόλις ἐστὶ τῆς Ἀρκαδίης πρὸς Φενεῷ.", "st": "6.74"}, {"sp": "N", "t": "μαθόντες δὲ Κλεομένεα Λακεδαιμόνιοι ταῦτα πρήσσοντα, κατῆγον αὐτὸν δείσαντες ἐπὶ τοῖσι αὐτοῖσι ἐς Σπάρτην τοῖσι καὶ πρότερον ἦρχε. κατελθόντα δὲ αὐτὸν αὐτίκα ὑπέλαβε μανίη νοῦσος, ἐόντα καὶ πρότερον ὑπομαργότερον· ὅκως γὰρ τεῷ ἐντύχοι Σπαρτιητέων, ἐνέχραυε ἐς τὸ πρόσωπον τὸ σκῆπτρον. ποιέοντα δὲ αὐτὸν ταῦτα καὶ παραφρονήσαντα ἔδησαν οἱ προσήκοντες ἐν ξύλω· ὁ δὲ δεθεὶς τὸν φύλακον μουνωθέντα ἰδὼν τῶν ἄλλων αἰτέει μάχαιραν· οὐ βουλομένου δὲ τὰ πρῶτα τοῦ φυλάκου διδόναι ἀπείλεε τά μιν αὖτις ποιήσει, ἐς ὁ δείσας τὰς ἀπειλὰς ὁ φύλακος (ἦν γὰρ τῶν τις εἱλωτέων) διδοῖ οἱ μάχαιραν. Κλεομένης δὲ παραλαβὼν τὸν σίδηρον ἄρχετο ἐκ τῶν κνημέων ἑωυτὸν λωβώμενος· ἐπιτάμνων γὰρ κατὰ μῆκος τὰς σάρκας προέβαινε ἐκ τῶν κνημέων ἐς τοὺς μηρούς, ἐκ δὲ τῶν μηρῶν ἔς τε τὰ ἰσχία καὶ τὰς λαπάρας, ἐς ὃ ἐς τὴν γαστέρα ἀπίκετο, καὶ ταύτην καταχορδεύων ἀπέθανε τρόπῳ τοιούτῳ, ὡς μὲν οἱ πολλοὶ λέγουσι Ἑλλήνων, ὅτι τὴν Πυθίην ἀνέγνωσε τὰ περὶ Δημαρήτου λέγειν γενόμενα, ὡς δὲ Ἀθηναῖοι μοῦνοι λέγουσι, διότι ἐς Ἐλευσῖνα ἐσβαλὼν ἔκειρε τὸ τέμενος τῶν θεῶν, ὡς δὲ Ἀργεῖοι, ὅτι ἐξ ἱροῦ αὐτῶν τοῦ Ἄργου Ἀργείων τοὺς καταφυγόντας ἐκ τῆς μάχης καταγινέων κατέκοπτε καὶ αὐτὸ τὸ ἄλσος ἐν ἀλογίῃ ἔχων ἐνέπρησε.", "st": "6.75"}, {"sp": "N", "t": "Κλεομένεϊ γὰρ μαντευομένῳ ἐν Δελφοῖσι ἐχρήσθη Ἄργος αἱρήσειν· ἐπείτε δὲ Σπαρτιήτας ἄγων ἀπίκετο ἐπὶ ποταμὸν Ἐρασῖνον, ὃς λέγεται ῥέειν ἐκ τῆς Στυμφαλίδος λίμνης· τὴν γὰρ δὴ λίμνην ταύτην ἐς χάσμα ἀφανὲς ἐκδιδοῦσαν ἀναφαίνεσθαι ἐν Ἄργεϊ, τὸ ἐνθεῦτεν δὲ τὸ ὕδωρ ἤδη τοῦτο ὑπ’ Ἀργείων Ἐρασῖνον καλέεσθαι· ἀπικόμενος δ’ ὦν ὁ Κλεομένης ἐπὶ τὸν ποταμὸν τοῦτον ἐσφαγιάζετο αὐτῷ· καὶ οὐ γὰρ ἐκαλλιέρεε οὐδαμῶς διαβαίνειν μιν, ἄγασθαι μὲν ἔφη τοῦ Ἐρασίνου οὐ προδιδόντος τοὺς πολιήτας, Ἀργείους μέντοι οὐδ’ ὣς χαιρήσειν. μετὰ δὲ ταῦτα ἐξαναχωρήσας τὴν στρατιὴν κατήγαγε ἐς Θυρέην, σφαγιασάμενος δὲ τῇ θαλάσσῃ ταῦρον πλοίοισι σφέας ἤγαγε ἔς τε τὴν Τιρυνθίην χώρην καὶ Ναυπλίην.", "st": "6.76"}, {"sp": "N", "t": "Ἀργεῖοι δὲ ἐβοήθεον πυνθανόμενοι ταῦτα ἐπὶ θάλασσαν· ὡς δὲ ἀγχοῦ μὲν ἐγίνοντο τῆς Τίρυνθος, χώρῳ δὲ ἐν τούτῳ τῷ κεῖται Ἡσίπεια οὔνομα, μεταίχμιον οὐ μέγα ἀπολιπόντες ἵζοντο ἀντίοι τοῖσι Λακεδαιμονίοισι. ἐνθαῦτα δὴ οἱ Ἀργεῖοι τὴν μὲν ἐκ τοῦ φανεροῦ μάχην οὐκ ἐφοβέοντο, ἀλλὰ μὴ δόλῳ αἱρεθέωσι· καὶ γὰρ δή σφι ἐς τοῦτο τὸ πρῆγμα εἶχε τὸ χρηστήριον τὸ ἐπίκοινα ἔχρησε ἡ Πυθίη τούτοισί τε καὶ Μιλησίοισι, λέγον ὧδε.", "st": "6.77"}, {"sp": "N", "t": "ἀλλ’ ὅταν ἡ θήλεια τὸν ἄρσενα νικήσασα<br>ἐξελάσῃ καὶ κῦδος ἐν Ἀργείοισιν ἄρηται,<br>πολλὰς Ἀργείων ἀμφιδρυφέας τότε θήσει.<br>ὧς ποτέ τις ἐρέει καὶ ἐπεσσομένων ἀνθρώπων<br>δεινὸς ὄφις τριέλικτος ἀπώλετο δουρὶ δαμασθείς.", "st": "6.77b"}, {"sp": "N", "t": "ταῦτα δὴ πάντα συνελθόντα τοῖσι Ἀργείοισι φόβον παρεῖχε. καὶ δή σφι πρὸς ταῦτα ἔδοξε τῷ κήρυκι τῶν πολεμίων χρᾶσθαι, δόξαν δέ σφι ἐποίεον τοιόνδε· ὅκως ὁ Σπαρτιήτης κῆρυξ προσημαίνοι τι Λακεδαιμονίοισι, ἐποίευν καὶ οἱ Ἀργεῖοι τὠυτὸ τοῦτο.", "st": "6.77.3"}, {"sp": "N", "t": "μαθὼν δὲ ὁ Κλεομένης ποιεῦντας τοὺς Ἀργείους ὁκοῖόν τι ὁ σφέτερος κῆρυξ σημήνειε, παραγγέλλει σφι, ὅταν σημήνῃ ὁ κῆρυξ ποιέεσθαι ἄριστον, τότε ἀναλαβόντας τὰ ὅπλα χωρέειν ἐς τοὺς Ἀργείους. ταῦτα καὶ ἐγένετο ἐπιτελέα ἐκ τῶν Λακεδαιμονίων· ἄριστον γὰρ ποιευμένοισι τοῖσι Ἀργείοισι ἐκ τοῦ κηρύγματος ἐπεκέατο, καὶ πολλοὺς μὲν ἐφόνευσαν αὐτῶν, πολλῷ δέ τι πλεῦνας ἐς τὸ ἄλσος τοῦ Ἄργου καταφυγόντας περιιζόμενοι ἐφύλασσον.", "st": "6.78"}, {"sp": "N", "t": "ἐνθεῦτεν δὲ ὁ Κλεομένης ἐποίεε τοιόνδε. ἔχων αὐτομόλους ἄνδρας καὶ πυνθανόμενος τούτων, ἐξεκάλεε πέμπων κήρυκα ὀνομαστὶ λέγων τῶν Ἀργείων τοὺς ἐν τῷ ἱρῷ ἀπεργμένους, ἐξεκάλεε δὲ φὰς αὐτῶν ἔχειν τὰ ἄποινα. ἄποινα δὲ ἐστὶ Πελοποννησίοισι δύο μνέαι τεταγμέναι κατ’ ἄνδρα αἰχμάλωτον ἐκτίνειν. κατὰ πεντήκοντα δὴ ὦν τῶν Ἀργείων ὡς ἑκάστους ἐκκαλεύμενος ὁ Κλεομένης ἔκτεινε. ταῦτα δέ κως γινόμενα ἐλελήθεε τοὺς λοιποὺς τοὺς ἐν τῷ τεμένεϊ· ἅτε γὰρ πυκνοῦ ἐόντος τοῦ ἄλσεος, οὐκ ὥρων οἱ ἐντὸς τοὺς ἐκτὸς ὅ τι ἔπρησσον, πρίν γε δὴ αὐτῶν τις ἀναβὰς ἐπὶ δένδρον κατεῖδε τὸ ποιεύμενον. οὔκων δὴ ἔτι καλεόμενοι ἐξήισαν.", "st": "6.79"}, {"sp": "N", "t": "ἐνθαῦτα δὴ ὁ Κλεομένης ἐκέλευε πάντα τινὰ τῶν εἱλωτέων περινέειν ὕλῃ τὸ ἄλσος, τῶν δὲ πειθομένων ἐνέπρησε τὸ ἄλσος. καιομένου δὲ ἤδη ἐπείρετο τῶν τινα αὐτομόλων τίνος εἴη θεῶν τὸ ἄλσος· ὁ δὲ ἔφη Ἄργου εἶναι. ὁ δὲ ὡς ἤκουσε, ἀναστενάξας μέγα εἶπε ὦ Ἄπολλον χρηστήριε, ἦ μεγάλως με ἠπάτηκας φάμενος Ἄργος αἱρήσειν· συμβάλλομαι δ’ ἐξήκειν μοι τὸ χρηστήριον.", "st": "6.80"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ὁ Κλεομένης τὴν μὲν πλέω στρατιὴν ἀπῆκε ἀπιέναι ἐς Σπάρτην, χιλίους δὲ αὐτὸς λαβὼν τοὺς ἀριστέας ἤιε ἐς τὸ Ἥραιον θύσων· βουλόμενον δὲ αὐτὸν θύειν ἐπὶ τοῦ βωμοῦ ὁ ἱρεὺς ἀπηγόρευε, φὰς οὐκ ὅσιον εἶναι ξείνῳ αὐτόθι θύειν. ὁ δὲ Κλεομένης τὸν ἱρέα ἐκέλευε τοὺς εἵλωτας ἀπὸ τοῦ βωμοῦ ἀπάγοντας μαστιγῶσαι, καὶ αὐτὸς ἔθυσε· ποιήσας δὲ ταῦτα ἀπήιε ἐς τὴν Σπάρτην.", "st": "6.81"}, {"sp": "N", "t": "νοστήσαντα δέ μιν ὑπῆγον οἱ ἐχθροὶ ὑπὸ τοὺς ἐφόρους, φάμενοί μιν δωροδοκήσαντα οὐκ ἑλεῖν τὸ Ἄργος, παρεὸν εὐπετέως μιν ἑλεῖν. ὁ δέ σφι ἔλεξε, οὔτε εἰ ψευδόμενος οὔτε εἰ ἀληθέα λέγων, ἔχω σαφηνέως εἶπαι, ἔλεξε δ’ ὦν φάμενος, ἐπείτε δὴ τὸ τοῦ Ἄργου ἱρὸν εἷλον, δοκέειν οἱ ἐξεληλυθέναι τὸν τοῦ θεοῦ χρησμόν· πρὸς ὦν ταῦτα οὐ δικαιοῦν πειρᾶν τῆς πόλιος, πρίν γε δὴ ἱροῖσι χρήσηται καὶ μάθῃ εἴτε οἱ ὁ θεὸς παραδιδοῖ εἴτε ἐμποδὼν ἕστηκε· καλλιερευμένῳ δὲ ἐν τῷ Ἡραίῳ ἐκ τοῦ ἀγάλματος τῶν στηθέων φλόγα πυρὸς ἐκλάμψαι, μαθεῖν δὲ αὐτὸς οὕτω τὴν ἀτρεκείην, ὅτι οὐκ αἱρέει τὸ Ἄργος· εἰ μὲν γὰρ ἐκ τῆς κεφαλῆς τοῦ ἀγάλματος ἐξέλαμψε, αἱρέειν ἂν κατ’ ἄκρης τὴν πόλιν, ἐκ τῶν στηθέων δὲ λάμψαντος πᾶν οἱ πεποιῆσθαι ὅσον ὁ θεὸς ἐβούλετο γενέσθαι. ταῦτα λέγων πιστά τε καὶ οἰκότα ἐδόκεε Σπαρτιήτῃσι λέγειν, καὶ διέφυγε πολλὸν τοὺς διώκοντας.", "st": "6.82"}, {"sp": "N", "t": "Ἄργος δὲ ἀνδρῶν ἐχηρώθη οὕτω ὥστε οἱ δοῦλοι αὐτῶν ἔσχον πάντα τὰ πρήγματα ἄρχοντές τε καὶ διέποντες, ἐς ὃ ἐπήβησαν οἱ τῶν ἀπολομένων παῖδες· ἔπειτα σφέας οὗτοι ἀνακτώμενοι ὀπίσω ἐς ἑωυτοὺς τὸ Ἄργος ἐξέβαλον· ἐξωθεύμενοι δὲ οἱ δοῦλοι μάχῃ ἔσχον Τίρυνθα. τέως μὲν δή σφι ἦν ἄρθμια ἐς ἀλλήλους, ἔπειτα δὲ ἐς τοὺς δούλους ἦλθε ἀνὴρ μάντις Κλέανδρος, γένος ἐὼν Φιγαλεὺς ἀπ’ Ἀρκαδίης· οὗτος τοὺς δούλους ἀνέγνωσε ἐπιθέσθαι τοῖσι δεσπότῃσι. ἐκ τούτου δὴ πόλεμός σφι ἦν ἐπὶ χρόνον συχνόν, ἐς ὃ δὴ μόγις οἱ Ἀργεῖοι ἐπεκράτησαν.", "st": "6.83"}, {"sp": "N", "t": "Ἀργεῖοι μέν νυν διὰ ταῦτα Κλεομένεα φασὶ μανέντα ἀπολέσθαι κακῶς· αὐτοὶ δὲ Σπαρτιῆται φασὶ ἐκ δαιμονίου μὲν οὐδενὸς μανῆναι Κλεομένεα, Σκύθῃσι δὲ ὁμιλήσαντά μιν ἀκρητοπότην γενέσθαι καὶ ἐκ τούτου μανῆναι. Σκύθας γὰρ τοὺς νομάδας, ἐπείτε σφι Δαρεῖον ἐμβαλεῖν ἐς τὴν χώρην, μετὰ ταῦτα μεμονέναι μιν τίσασθαι, πέμψαντας δὲ ἐς Σπάρτην συμμαχίην τε ποιέεσθαι καὶ συντίθεσθαι ὡς χρεὸν εἴη αὐτοὺς μὲν τοὺς Σκύθας παρὰ Φᾶσιν ποταμὸν πειρᾶν ἐς τὴν Μηδικὴν ἐσβάλλειν, σφέας δὲ τοὺς Σπαρτιήτας κελεύειν ἐξ Ἐφέσου ὁρμωμένους ἀναβαίνειν καὶ ἔπειτα ἐς τὠυτὸ ἀπαντᾶν. Κλεομένεα δὲ λέγουσι ἡκόντων τῶν Σκυθέων ἐπὶ ταῦτα ὁμιλέειν σφι μεζόνως, ὁμιλέοντα δὲ μᾶλλον τοῦ ἱκνεομένου μαθεῖν τὴν ἀκρητοποσίην παρ’ αὐτῶν· ἐκ τούτου δὲ μανῆναί μιν νομίζουσι Σπαρτιῆται. ἔκ τε τόσου, ὡς αὐτοὶ λέγουσι, ἐπεὰν ζωρότερον βούλωνται πιεῖν, Ἐπισκύθισον λέγουσι. οὕτω δὴ Σπαρτιῆται τὰ περὶ Κλεομένεα λέγουσι· ἐμοὶ δὲ δοκέει τίσιν ταύτην ὁ Κλεομένης Δημαρήτῳ ἐκτῖσαι.", "st": "6.84"}, {"sp": "N", "t": "τελευτήσαντος δὲ Κλεομένεος ὡς ἐπύθοντο Αἰγινῆται, ἔπεμπον ἐς Σπάρτην ἀγγέλους καταβωσομένους Λευτυχίδεω περὶ τῶν ἐν Ἀθήνῃσι ὁμήρων ἐχομένων. Λακεδαιμόνιοι δὲ δικαστήριον συναγαγόντες ἔγνωσαν περιυβρίσθαι Αἰγινήτας ὑπὸ Λευτυχίδεω, καί μιν κατέκριναν ἔκδοτον ἄγεσθαι ἐς Αἴγιναν ἀντὶ τῶν ἐν Ἀθήνῃσι ἐχομένων ἀνδρῶν. μελλόντων δὲ ἄγειν τῶν Αἰγινητέων τὸν Λευτυχίδεα, εἶπέ σφι Θεασίδης ὁ Λεωπρέπεος, ἐὼν ἐν Σπάρτῃ δόκιμος ἀνήρ, τί βουλεύεσθε ποιέειν, ἄνδρες Αἰγινῆται; τὸν βασιλέα τῶν Σπαρτιητέων ἔκδοτον γενόμενον ὑπὸ τῶν πολιητέων ἄγειν; εἰ νῦν ὀργῇ χρεώμενοι ἔγνωσαν οὕτω Σπαρτιῆται, ὅκως ἐξ ὑστέρης μή τι ὑμῖν, ἢν ταῦτα πρήσσητε, πανώλεθρον κακὸν ἐς τὴν χώρην ἐμβάλωσι. ταῦτα ἀκούσαντες οἱ Αἰγινῆται ἔσχοντο τῆς ἀγωγῆς, ὁμολογίῃ δὲ ἐχρήσαντο τοιῇδε, ἐπισπόμενον Λευτυχίδεα ἐς Ἀθήνας ἀποδοῦναι Αἰγινήτῃσι τοὺς ἄνδρας.", "st": "6.85"}, {"sp": "N", "t": "ὡς δὲ ἀπικόμενος Λευτυχίδης ἐς τὰς Ἀθήνας ἀπαίτεε τὴν παραθήκην, οἱ δ’ Ἀθηναῖοι προφάσιας εἷλκον οὐ βουλόμενοι ἀποδοῦναι, φάντες δύο σφέας ἐόντας βασιλέας παραθέσθαι καὶ οὐ δικαιοῦν τῷ ἑτέρῳ ἄνευ τοῦ ἑτέρου ἀποδιδόναι· οὐ φαμένων δὲ ἀποδώσειν τῶν Ἀθηναίων, ἔλεξέ σφι Λευτυχίδης τάδε. ὦ Ἀθηναῖοι, ποιέετε μὲν ὁκότερα βούλεσθε αὐτοί·", "st": "6.86"}, {"sp": "N", "t": "καὶ γὰρ ἀποδιδόντες ποιέετε ὅσια, καὶ μὴ ἀποδιδόντες τὰ ἐναντία τούτων· ὁκοῖον μέντοι τι ἐν τῇ Σπάρτῃ συνηνείχθη γενέσθαι περὶ παρακαταθήκης, βούλομαι ὑμῖν εἶπαι. λέγομεν ἡμεῖς οἱ Σπαρτιῆται γενέσθαι ἐν τῇ Λακεδαίμονι κατὰ τρίτην γενεὴν τὴν ἀπ’ ἐμέο Γλαῦκον Ἐπικύδεος παῖδα· τοῦτον τὸν ἄνδρα φαμὲν τά τε ἄλλα πάντα περιήκειν τὰ πρῶτα, καὶ δὴ καὶ ἀκούειν ἄριστα δικαιοσύνης πέρι πάντων ὅσοι τὴν Λακεδαίμονα τοῦτον τὸν χρόνον οἴκεον. συνενειχθῆναι δέ οἱ ἐν χρόνῳ ἱκνευμένῳ τάδε λέγομεν. ἄνδρα Μιλήσιον ἀπικόμενον ἐς Σπάρτην βούλεσθαί οἱ ἐλθεῖν ἐς λόγους προϊσχόμενον τοιάδε. εἰμὶ μὲν Μιλήσιος, ἥκω δὲ τῆς σῆς Γλαῦκε βουλόμενος δικαιοσύνης ἀπολαῦσαι. ὡς γὰρ δὴ ἀνὰ πᾶσαν μὲν τὴν ἄλλην Ἑλλάδα, ἐν δὲ καὶ περὶ Ἰωνίην τῆς σῆς δικαιοσύνης ἦν λόγος πολλός, ἐμεωυτῷ λόγους ἐδίδουν καὶ ὅτι ἐπικίνδυνος ἐστὶ αἰεί κοτε ἡ Ἰωνίη, ἡ δὲ Πελοπόννησος ἀσφαλέως ἱδρυμένη, καὶ διότι χρήματα οὐδαμὰ τοὺς αὐτούς ἐστι ὁρᾶν ἔχοντας. ταῦτά τε ὦν ἐπιλεγομένῳ καὶ βουλευομένῳ ἔδοξέ μοι τὰ ἡμίσεα πάσης τῆς οὐσίης ἐξαργυρώσαντα θέσθαι παρὰ σέ, εὖ ἐξεπισταμένῳ ὥς μοι κείμενα ἔσται παρὰ σοὶ σόα. σὺ δή μοι καὶ τὰ χρήματα δέξαι καὶ τάδε τὰ σύμβολα σῶζε λαβών· ὃς δ’ ἂν ἔχων ταῦτα ἀπαιτέῃ, τούτῳ ἀποδοῦναι. ὁ μὲν δὴ ἀπὸ Μιλήτου ἥκων ξεῖνος τοσαῦτα ἔλεξε, Γλαῦκος δὲ ἐδέξατο τὴν παρακαταθήκην ἐπὶ τῷ εἰρημένῳ λόγῳ. χρόνου δὲ πολλοῦ διελθόντος ἦλθον ἐς Σπάρτην τούτου τοῦ παραθεμένου τὰ χρήματα οἱ παῖδες, ἐλθόντες δὲ ἐς λόγους τῷ Γλαύκῳ καὶ ἀποδεικνύντες τὰ σύμβολα ἀπαίτεον τὰ χρήματα· ὁ δὲ διωθέετο ἀντυποκρινόμενος τοιάδε. οὔτε μέμνημαι τὸ πρῆγμα οὔτε με περιφέρει οὐδὲν εἰδέναι τούτων τῶν ὑμεῖς λέγετε, βούλομαί τε ἀναμνησθεὶς ποιέειν πᾶν τὸ δίκαιον· καὶ γὰρ εἰ ἔλαβον, ὀρθῶς ἀποδοῦναι, καὶ εἴ γε ἀρχὴν μὴ ἔλαβον, νόμοισι τοῖσι Ἑλλήνων χρήσομαι ἐς ὑμέας. ταῦτα ὦν ὑμῖν ἀναβάλλομαι κυρώσειν ἐς τέταρτον μῆνα ἀπὸ τοῦδε. οἱ μὲν δὴ Μιλήσιοι συμφορὴν ποιησάμενοι ἀπαλλάσσοντο ὡς ἀπεστερημένοι τῶν χρημάτων, Γλαῦκος δὲ ἐπορεύετο ἐς Δελφοὺς χρησόμενος τῷ χρηστηρίῳ. ἐπειρωτῶντα δὲ αὐτὸν τὸ χρηστήριον εἰ ὅρκῳ τὰ χρήματα ληίσηται, ἡ Πυθίη μετέρχεται τοῖσιδε τοῖσι ἔπεσι.", "st": "6.86a.2"}, {"sp": "N", "t": "γλαῦκ’ Ἐπικυδείδη, τὸ μὲν αὐτίκα κέρδιον οὕτω<br>ὅρκῳ νικῆσαι καὶ χρήματα ληίσσασθαι.<br>ὄμνυ, ἐπεὶ θάνατός γε καὶ εὔορκον μένει ἄνδρα.<br>ἀλλ’ ὅρκου πάις ἐστίν, ἀνώνυμος, οὐδ’ ἔπι χεῖρες<br>οὐδὲ πόδες· κραιπνὸς δὲ μετέρχεται, εἰς ὅ κε πᾶσαν<br>συμμάρψας ὀλέσῃ γενεὴν καὶ οἶκον ἅπαντα.<br>ἀνδρὸς δ’ εὐόρκου γενεὴ μετόπισθεν ἀμείνων.", "st": "6.86c.2"}, {"sp": "N", "t": "ταῦτα ἀκούσας ὁ Γλαῦκος συγγνώμην τὸν θεὸν παραιτέετο αὐτῷ ἴσχειν τῶν ῥηθέντων. ἡ δὲ Πυθίη ἔφη τὸ πειρηθῆναι τοῦ θεοῦ καὶ τὸ ποιῆσαι ἴσον δύνασθαι. Γλαῦκος μὲν δὴ μεταπεμψάμενος τοὺς Μιλησίους ξείνους ἀποδιδοῖ σφι τὰ χρήματα. τοῦ δὲ εἵνεκα ὁ λόγος ὅδε ὦ Ἀθηναῖοι ὁρμήθη λέγεσθαι ἐς ὑμέας, εἰρήσεται· Γλαύκου νῦν οὔτε τι ἀπόγονον ἐστὶ οὐδὲν οὔτ’ ἱστίη οὐδεμία νομιζομένη εἶναι Γλαύκου, ἐκτέτριπταί τε πρόρριζος ἐκ Σπάρτης. οὕτω ἀγαθὸν μηδὲ διανοέεσθαι περὶ παρακαταθήκης ἄλλο γε ἢ ἀπαιτεόντων ἀποδιδόναι.", "st": "6.86d.1"}, {"sp": "N", "t": "Λευτυχίδης μὲν εἴπας ταῦτα, ὥς οἱ οὐδὲ οὕτω ἐσήκουον οἱ Ἀθηναῖοι, ἀπαλλάσσετο· οἱ δὲ Αἰγινῆται, πρὶν τῶν πρότερον ἀδικημάτων δοῦναι δίκας τῶν ἐς Ἀθηναίους ὕβρισαν Θηβαίοισι χαριζόμενοι, ἐποίησαν τοιόνδε. μεμφόμενοι τοῖσι Ἀθηναίοισι καὶ ἀξιοῦντες ἀδικέεσθαι, ὡς τιμωρησόμενοι τοὺς Ἀθηναίους παρεσκευάζοντο· καὶ ἦν γὰρ δὴ τοῖσι Ἀθηναίοισι πεντετηρὶς ἐπὶ Σουνίῳ, λοχήσαντες ὦν τὴν θεωρίδα νέα εἷλον πλήρεα ἀνδρῶν τῶν πρώτων Ἀθηναίων, λαβόντες δὲ τοὺς ἄνδρας ἔδησαν.", "st": "6.87"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ παθόντες ταῦτα πρὸς Αἰγινητέων οὐκέτι ἀνεβάλλοντο μὴ οὐ τὸ πᾶν μηχανήσασθαι ἐπ’ Αἰγινήτῃσι. καὶ ἦν γὰρ Νικόδρομος Κνοίθου καλεόμενος ἐν τῇ Αἰγίνῃ ἀνὴρ δόκιμος, οὗτος μεμφόμενος μὲν τοῖσι Αἰγινήτῃσι προτέρην ἑωυτοῦ ἐξέλασιν ἐκ τῆς νήσου, μαθὼν δὲ τότε τοὺς Ἀθηναίους ἀναρτημένους ἔρδειν Αἰγινήτας κακῶς, συντίθεται Ἀθηναίοισι προδοσίην Αἰγίνης, φράσας ἐν τῇ τε ἡμέρῃ ἐπιχειρήσει καὶ ἐκείνους ἐς τὴν ἥκειν δεήσει βοηθέοντας.", "st": "6.88"}, {"sp": "N", "t": "μετὰ ταῦτα καταλαμβάνει μὲν κατὰ τὰ συνεθήκατο Ἀθηναίοισι ὁ Νικόδρομος τὴν παλαιὴν καλεομένην πόλιν, Ἀθηναῖοι δὲ οὐ παραγίνονται ἐς δέον· οὐ γὰρ ἔτυχον ἐοῦσαι νέες σφι ἀξιόμαχοι τῇσι Αἰγινητέων συμβαλεῖν. ἐν ᾧ ὦν Κορινθίων ἐδέοντο χρῆσαι σφίσι νέας, ἐν τούτῳ διεφθάρη τὰ πρήγματα. οἱ δὲ Κορίνθιοι, ἦσαν γάρ σφι τοῦτον τὸν χρόνον φίλοι ἐς τὰ μάλιστα, Ἀθηναίοισι διδοῦσι δεομένοισι εἴκοσι νέας, διδοῦσι δὲ πενταδράχμους ἀποδόμενοι· δωρεὴν γὰρ ἐν τῷ νόμῳ οὐκ ἐξῆν δοῦναι. ταύτας τε δὴ λαβόντες οἱ Ἀθηναῖοι καὶ τὰς σφετέρας, πληρώσαντες ἑβδομήκοντα νέας τὰς ἁπάσας, ἔπλεον ἐπὶ τὴν Αἴγιναν καὶ ὑστέρησαν ἡμέρῃ μιῇ τῆς συγκειμένης.", "st": "6.89"}, {"sp": "N", "t": "Νικόδρομος δέ, ὡς οἱ Ἀθηναῖοι ἐς τὸν καιρὸν οὐ παρεγίνοντο, ἐς πλοῖον ἐσβὰς ἐκδιδρήσκει ἐκ τῆς Αἰγίνης· σὺν δέ οἱ καὶ ἄλλοι ἐκ τῶν Αἰγινητέων εἵποντο, τοῖσι Ἀθηναῖοι Σούνιον οἰκῆσαι ἔδοσαν. ἐνθεῦτεν δὲ οὗτοι ὁρμώμενοι ἔφερόν τε καὶ ἦγον τοὺς ἐν τῇ νήσῳ Αἰγινήτας.", "st": "6.90"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ὕστερον ἐγίνετο. Αἰγινητέων δὲ οἱ παχέες ἐπαναστάντος τοῦ δήμου σφι ἅμα Νικοδρόμῳ ἐπεκράτησαν, καὶ ἔπειτα σφέας χειρωσάμενοι ἐξῆγον ἀπολέοντες. ἀπὸ τούτου δὲ καὶ ἄγος σφι ἐγένετο, τὸ ἐκθύσασθαι οὐκ οἶοί τε ἐγένοντο ἐπιμηχανώμενοι, ἀλλ’ ἔφθησαν ἐκπεσόντες πρότερον ἐκ τῆς νήσου ἤ σφι ἵλεον γενέσθαι τὴν θεόν. ἑπτακοσίους γὰρ δὴ τοῦ δήμου ζωγρήσαντες ἐξῆγον ὡς ἀπολέοντες, εἷς δέ τις τούτων ἐκφυγὼν τὰ δεσμὰ καταφεύγει πρὸς πρόθυρα Δήμητρος θεσμοφόρου, ἐπιλαμβανόμενος δὲ τῶν ἐπισπαστήρων εἴχετο· οἳ δὲ ἐπείτε μιν ἀποσπάσαι οὐκ οἷοί τε ἀπέλκοντες ἐγίνοντο, ἀποκόψαντες αὐτοῦ τὰς χεῖρας ἦγον οὕτω, αἱ χεῖρες δὲ ἐκεῖναι ἐμπεφυκυῖαι ἦσαν τοῖσι ἐπισπαστῆρσι.", "st": "6.91"}, {"sp": "N", "t": "ταῦτα μέν νυν σφέας αὐτοὺς οἱ Αἰγινῆται ἐργάσαντο, Ἀθηναίοισι δὲ ἥκουσι ἐναυμάχησαν νηυσὶ ἑβδομήκοντα, ἑσσωθέντες δὲ τῇ ναυμαχίῃ ἐπεκαλέοντο τοὺς αὐτοὺς καὶ πρότερον, Ἀργείους. καὶ δή σφι οὗτοι μὲν οὐκέτι βοηθέουσι, μεμφόμενοι ὅτι Αἰγιναῖαι νέες ἀνάγκῃ λαμφθεῖσαι ὑπὸ Κλεομένεος ἔσχον τε ἐς τὴν Ἀργολίδα χώρην καὶ συναπέβησαν Λακεδαιμονίοισι, συναπέβησαν δὲ καὶ ἀπὸ Σικυωνιέων νεῶν ἄνδρες τῇ αὐτῇ ταύτῃ ἐσβολῇ· καί σφι ὑπ’ Ἀργείων ἐπεβλήθη ζημίη χίλια τάλαντα ἐκτῖσαι, πεντακόσια ἑκατέρους. Σικυώνιοι μέν νυν συγγνόντες ἀδικῆσαι ὡμολόγησαν ἑκατὸν τάλαντα ἐκτίσαντες ἀζήμιοι εἶναι, Αἰγινῆται δὲ οὔτε συνεγινώσκοντο ἦσάν τε αὐθαδέστεροι. διὰ δὴ ὦν σφι ταῦτα δεομένοισι ἀπὸ μὲν τοῦ δημοσίου οὐδεὶς Ἀργείων ἔτι ἐβοήθεε, ἐθελονταὶ δὲ ἐς χιλίους· ἦγε δὲ αὐτοὺς στρατηγὸς ἀνὴρ ᾧ οὔνομα Εὐρυβάτης, ἀνὴρ πεντάεθλον ἐπασκήσας. τούτων οἱ πλεῦνες οὐκ ἀπενόστησαν ὀπίσω, ἀλλ’ ἐτελεύτησαν ὑπ’ Ἀθηναίων ἐν Αἰγίνῃ· αὐτὸς δὲ ὁ στρατηγὸς Εὐρυβάτης μουνομαχίην ἐπασκέων τρεῖς μὲν ἄνδρας τρόπῳ τοιούτῳ κτείνει, ὑπὸ δὲ τοῦ τετάρτου Σωφάνεος τοῦ Δεκελέος ἀποθνήσκει.", "st": "6.92"}, {"sp": "N", "t": "Αἰγινῆται δὲ ἐοῦσι ἀτάκτοισι τοῖσι Ἀθηναίοισι συμβαλόντες τῇσι νηυσὶ ἐνίκησαν, καί σφεων νέας τέσσερας αὐτοῖσι τοῖσι ἀνδράσι εἷλον.", "st": "6.93"}, {"sp": "N", "t": "Ἀθηναίοισι μὲν δὴ πόλεμος συνῆπτο πρὸς Αἰγινήτας. ὁ δὲ Πέρσης τὸ ἑωυτοῦ ἐποίεε, ὥστε ἀναμιμνήσκοντός τε αἰεὶ τοῦ θεράποντος μεμνῆσθαί μιν τῶν Ἀθηναίων, καὶ Πεισιστρατιδέων προσκατημένων καὶ διαβαλλόντων Ἀθηναίους, ἅμα δὲ βουλόμενος ὁ Δαρεῖος ταύτης ἐχόμενος τῆς προφάσιος καταστρέφεσθαι τῆς Ἑλλάδος τοὺς μὴ δόντας αὐτῷ γῆν τε καὶ ὕδωρ. Μαρδόνιον μὲν δὴ φλαύρως πρήξαντα τῷ στόλῳ παραλύει τῆς στρατηγίης, ἄλλους δὲ στρατηγοὺς ἀποδέξας ἀπέστειλε ἐπὶ τε Ἐρέτριαν καὶ Ἀθήνας, Δᾶτίν τε ἐόντα Μῆδον γένος καὶ Ἀρταφρένεα τὸν Ἀρταφρένεος παῖδα, ἀδελφιδέον ἑωυτοῦ· ἐντειλάμενος δὲ ἀπέπεμπε ἐξανδραποδίσαντας Ἀθήνας καὶ Ἐρέτριαν ἀνάγειν ἑωυτῷ ἐς ὄψιν τὰ ἀνδράποδα.", "st": "6.94"}, {"sp": "N", "t": "ὡς δὲ οἱ στρατηγοὶ οὗτοι οἱ ἀποδεχθέντες πορευόμενοι παρὰ βασιλέος ἀπίκοντο τῆς Κιλικίης ἐς τὸ Ἀλήιον πεδίον, ἅμα ἀγόμενοι πεζὸν στρατὸν πολλόν τε καὶ εὖ ἐσκευασμένον, ἐνθαῦτα στρατοπεδευομένοισι ἐπῆλθε μὲν ὁ ναυτικὸς πᾶς στρατὸς ὁ ἐπιταχθεὶς ἑκάστοισι, παρεγένοντο δὲ καὶ αἱ ἱππαγωγοὶ νέες, τὰς τῷ προτέρῳ ἔτεϊ προεῖπε τοῖσι ἑωυτοῦ δασμοφόροισι Δαρεῖος ἑτοιμάζειν. ἐσβαλόμενοι δὲ τοὺς ἵππους ἐς ταύτας καὶ τὸν πεζὸν στρατὸν ἐσβιβάσαντες ἐς τὰς νέας, ἔπλεον ἑξακοσίῃσι τριήρεσι ἐς τὴν Ἰωνίην. ἐνθεῦτεν δὲ οὐ παρὰ τὴν ἤπειρον εἶχον τὰς νέας ἰθὺ τοῦ τε Ἑλλησπόντου καὶ τῆς Θρηίκης, ἀλλ’ ἐκ Σάμου ὁρμώμενοι παρά τε Ἰκάριον καὶ διὰ νήσων τὸν πλόον ἐποιεῦντο, ὡς μὲν ἐμοὶ δοκέειν, δείσαντες μάλιστα τὸν περίπλοον τοῦ Ἄθω, ὅτι τῷ προτέρῳ ἔτεϊ ποιεύμενοι ταύτῃ τὴν κομιδὴν μεγάλως προσέπταισαν· πρὸς δὲ καὶ ἡ Νάξος σφέας ἠνάγκαζε πρότερον οὐκ ἁλοῦσα.", "st": "6.95"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐκ τοῦ Ἰκαρίου πελάγεος προσφερόμενοι προσέμιξαν τῇ Νάξῳ, ἐπὶ ταύτην γὰρ δὴ πρώτην ἐπεῖχον στρατεύεσθαι οἱ Πέρσαι μεμνημένοι τῶν πρότερον οἱ Νάξιοι πρὸς τὰ ὄρεα οἴχοντο φεύγοντες οὐδὲ ὑπέμειναν, οἱ δὲ Πέρσαι ἀνδραποδισάμενοι τοὺς κατέλαβον αὐτῶν, ἐνέπρησαν καὶ τὰ ἱρὰ καὶ τὴν πόλιν. ταῦτα δὲ ποιήσαντες ἐπὶ τὰς ἄλλας νήσους ἀνήγοντο.", "st": "6.96"}, {"sp": "N", "t": "ἐν ᾧ δὲ οὗτοι ταῦτα ἐποίευν, οἱ Δήλιοι ἐκλιπόντες καὶ αὐτοὶ τὴν Δῆλον οἴχοντο φεύγοντες ἐς Τῆνον. τῆς δὲ στρατιῆς καταπλεούσης ὁ Δᾶτις προπλώσας οὐκ ἔα τὰς νέας πρὸς τὴν Δῆλον προσορμίζεσθαι, ἀλλὰ πέρην ἐν τῇ Ῥηναίῃ· αὐτὸς δὲ πυθόμενος ἵνα ἦσαν οἱ Δήλιοι, πέμπων κήρυκα ἠγόρευέ σφι τάδε. ἄνδρες ἱροί, τί φεύγοντες οἴχεσθε, οὐκ ἐπιτήδεα καταγνόντες κατ’ ἐμεῦ; ἐγὼ γὰρ καὶ αὐτὸς ἐπὶ τοσοῦτό γε φρονέω καὶ μοι ἐκ βασιλέος ὧδε ἐπέσταλται, ἐν τῇ χώρῃ οἱ δύο θεοὶ ἐγένοντο, ταύτην μηδὲν σίνεσθαι, μήτε αὐτὴν τὴν χώρην μήτε τοὺς οἰκήτορας αὐτῆς. νῦν ὦν καὶ ἄπιτε ἐπὶ τὰ ὑμέτερα αὐτῶν καὶ τὴν νῆσον νέμεσθε. ταῦτα μὲν ἐπεκηρυκεύσατο τοῖσι Δηλίοισι, μετὰ δὲ λιβανωτοῦ τριηκόσια τάλαντα κατανήσας ἐπὶ τοῦ βωμοῦ ἐθυμίησε.", "st": "6.97"}, {"sp": "N", "t": "Δᾶτις μὲν δὴ ταῦτα ποιήσας ἔπλεε ἅμα τῷ στρατῷ ἐπὶ τὴν Ἐρέτριαν πρῶτα, ἅμα ἀγόμενος καὶ Ἴωνας καὶ Αἰολέας. μετὰ δὲ τοῦτον ἐνθεῦτεν ἐξαναχθέντα Δῆλος ἐκινήθη, ὡς ἔλεγον Δήλιοι, καὶ πρῶτα καὶ ὕστατα μέχρι ἐμεῦ σεισθεῖσα. καὶ τοῦτο μέν κου τέρας ἀνθρώποισι τῶν μελλόντων ἔσεσθαι κακῶν ἔφαινε ὁ θεός. ἐπὶ γὰρ Δαρείου τοῦ Ὑστάσπεος καὶ Ξέρξεω τοῦ Δαρείου καὶ Ἀρτοξέρξεω τοῦ Ξέρξεω, τριῶν τουτέων ἐπεξῆς γενεέων, ἐγένετο πλέω κακὰ τῇ Ἑλλάδι ἢ ἐπὶ εἴκοσι ἄλλας γενεὰς τὰς πρὸ Δαρείου γενομένας, τὰ μὲν ἀπὸ τῶν Περσέων αὐτῇ γενόμενα, τὰ δὲ ἀπ’ αὐτῶν τῶν κορυφαίων περὶ τῆς ἀρχῆς πολεμεόντων. οὕτω οὐδὲν ἦν ἀεικὲς κινηθῆναι Δῆλον τὸ πρὶν ἐοῦσαν ἀκίνητον. καὶ ἐν χρησμῷ ἦν γεγραμμένον περὶ αὐτῆς ὧδε.", "st": "6.98"}, {"sp": "N", "t": "κινήσω καὶ Δῆλον ἀκίνητόν περ ἐοῦσαν.", "st": "6.98b"}, {"sp": "N", "t": "δύναται δὲ κατὰ Ἑλλάδα γλῶσσαν ταῦτα τὰ οὐνόματα, Δαρεῖος ἐρξίης, Ξέρξης ἀρήιος, Ἀρτοξέρξης μέγας ἀρήιος. τούτους μὲν δὴ τοὺς βασιλέας ὧδε ἂν ὀρθῶς κατὰ γλῶσσαν τὴν σφετέρην Ἕλληνες καλέοιεν.", "st": "6.98c"}, {"sp": "N", "t": "οἱ δὲ βάρβαροι ὡς ἀπήειραν ἐκ τῆς Δήλου, προσῖσχον πρὸς τὰς νήσους, ἐνθεῦτεν δὲ στρατιήν τε παρελάμβανον καὶ ὁμήρους τῶν νησιωτέων παῖδας ἐλάμβανον. ὡς δὲ περιπλέοντες τὰς νήσους προσέσχον καὶ ἐς Κάρυστον, οὐ γὰρ δή σφι οἱ Καρύστιοι οὔτε ὁμήρους ἐδίδοσαν οὔτε ἔφασαν ἐπὶ πόλιας ἀστυγείτονας στρατεύεσθαι, λέγοντες Ἐρέτριάν τε καὶ Ἀθήνας, ἐνθαῦτα τούτους ἐπολιόρκεόν τε καὶ τὴν γῆν σφεων ἔκειρον, ἐς ὃ καὶ οἱ Καρύστιοι παρέστησαν ἐς τῶν Περσέων τὴν γνώμην.", "st": "6.99"}, {"sp": "N", "t": "Ἐρετριέες δὲ πυνθανόμενοι τὴν στρατιὴν τὴν Περσικὴν ἐπὶ σφέας ἐπιπλέουσαν Ἀθηναίων ἐδεήθησαν σφίσι βοηθοὺς γενέσθαι. Ἀθηναῖοι δὲ οὐκ ἀπείπαντο τὴν ἐπικουρίην, ἀλλὰ τοὺς τετρακισχιλίους τοὺς κληρουχέοντας τῶν ἱπποβοτέων Χαλκιδέων τὴν χώρην, τούτους σφι διδοῦσι τιμωρούς. τῶν δὲ Ἐρετριέων ἦν ἄρα οὐδὲν ὑγιὲς βούλευμα, οἳ μετεπέμποντο μὲν Ἀθηναίους, ἐφρόνεον δὲ διφασίας ἰδέας. οἳ μὲν γὰρ αὐτῶν ἐβουλεύοντο ἐκλιπεῖν τὴν πόλιν ἐς τὰ ἄκρα τῆς Εὐβοίης, ἄλλοι δὲ αὐτῶν ἴδια κέρδεα προσδεκόμενοι παρὰ τοῦ Πέρσεω οἴσεσθαι προδοσίην ἐσκευάζοντο. μαθὼν δὲ τούτων ἑκάτερα ὡς εἶχε Αἰσχίνης ὁ Νόθωνος, ἐὼν τῶν Ἐρετριέων τὰ πρῶτα, φράξει τοῖσι ἥκουσι Ἀθηναίων πάντα τὰ παρεόντα σφι πρήγματα, προσεδέετό τε ἀπαλλάσσεσθαι σφέας ἐς τὴν σφετέρην, ἵνα μὴ προσαπόλωνται. οἱ δὲ Ἀθηναῖοι ταῦτα Αἰσχίνῃ συμβουλεύσαντι πείθονται.", "st": "6.100"}, {"sp": "N", "t": "καὶ οὗτοι μὲν διαβάντες ἐς Ὠρωπὸν ἔσωζον σφέας αὐτούς· οἱ δὲ Πέρσαι πλέοντες κατέσχον τὰς νέας τῆς Ἐρετρικῆς χώρης κατὰ Τέμενος καὶ Χοιρέας καὶ Αἰγίλεα, κατασχόντες δὲ ταῦτα τὰ χωρία αὐτίκα ἵππους τε ἐξεβάλλοντο καὶ παρεσκευάζοντο ὡς προσοισόμενοι τοῖσι ἐχθροῖσι. οἱ δὲ Ἐρετριέες ἐπεξελθεῖν μὲν καὶ μαχέσασθαι οὐκ ἐποιεῦντο βουλήν, εἴ κως δὲ διαφυλάξαιεν τὰ τείχεα, τούτου σφι πέρι ἔμελε, ἐπείτε ἐνίκα μὴ ἐκλιπεῖν τὴν πόλιν. προσβολῆς δὲ γινομένης καρτερῆς πρὸς τὸ τεῖχος ἔπιπτον ἐπὶ ἓξ ἡμέρας πολλοὶ μὲν ἀμφοτέρων· τῇ δὲ ἑβδόμῃ Εὔφορβός τε ὁ Ἀλκιμάχου καὶ Φίλαγρος ὁ Κυνέου ἄνδρες τῶν ἀστῶν δόκιμοι προδιδοῦσι τοῖσι Πέρσῃσι. οἳ δὲ ἐσελθόντες ἐς τὴν πόλιν τοῦτο μὲν τὰ ἱρὰ συλήσαντες ἐνέπρησαν, ἀποτινύμενοι τῶν ἐν Σάρδισι κατακαυθέντων ἱρῶν, τοῦτο δὲ τοὺς ἀνθρώπους ἠνδραποδίσαντο κατὰ τὰς Δαρείου ἐντολάς.", "st": "6.101"}, {"sp": "N", "t": "χειρωσάμενοι δὲ τὴν Ἐρέτριαν καὶ ἐπισχόντες ὀλίγας ἡμέρας ἔπλεον ἐς γῆν τὴν Ἀττικήν, κατέργοντές τε πολλὸν καὶ δοκέοντες ταὐτὰ τοὺς Ἀθηναίους ποιήσειν τὰ καὶ τοὺς Ἐρετριέας ἐποίησαν. καὶ ἦν γὰρ ὁ Μαραθὼν ἐπιτηδεότατον χωρίον τῆς Ἀττικῆς ἐνιππεῦσαι καὶ ἀγχοτάτω τῆς Ἐρετρίης, ἐς τοῦτό σφι κατηγέετο Ἱππίης ὁ Πεισιστράτου.", "st": "6.102"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ ὡς ἐπύθοντο ταῦτα, ἐβοήθεον καὶ αὐτοὶ ἐς τὸν Μαραθῶνα. ἦγον δὲ σφέας στρατηγοὶ δέκα, τῶν ὁ δέκατος ἦν Μιλτιάδης· τοῦ τὸν πατέρα Κίμωνα τὸν Στησαγόρεω κατέλαβε φυγεῖν ἐξ Ἀθηνέων Πεισίστρατον τὸν Ἱπποκράτεος. καὶ αὐτῷ φεύγοντι Ὀλυμπιάδα ἀνελέσθαι τεθρίππῳ συνέβη, καὶ ταύτην μὲν τὴν νίκην ἀνελόμενόν μιν τὠυτὸ ἐξενείκασθαι τῷ ὁμομητρίῳ ἀδελφεῷ Μιλτιάδῃ· μετὰ δὲ τῇ ὑστέρῃ Ὀλυμπιάδι τῇσι αὐτῇσι ἵπποισι νικῶν παραδιδοῖ Πεισιστράτῳ ἀνακηρυχθῆναι, καὶ τὴν νίκην παρεὶς τούτῳ κατῆλθε ἐπὶ τὰ ἑωυτοῦ ὑπόσπονδος. καί μιν ἀνελόμενον τῇσι αὐτῇσι ἵπποισι ἄλλην Ὀλυμπιάδα κατέλαβε ἀποθανεῖν ὑπὸ τῶν Πεισιστράτου παίδων, οὐκέτι περιεόντος αὐτοῦ Πεισιστράτου· κτείνουσι δὲ οὗτοί μιν κατὰ τὸ πρυτανήιον νυκτὸς ὑπείσαντες ἄνδρας. τέθαπται δὲ Κίμων πρὸ τοῦ ἄστεος, πέρην τῆς διὰ Κοίλης καλεομένης ὁδοῦ· καταντίον δ’ αὐτοῦ αἱ ἵπποι τεθάφαται αὗται αἱ τρεῖς Ὀλυμπιάδας ἀνελόμεναι. ἐποίησαν δὲ καὶ ἄλλαι ἵπποι ἤδη τὠυτὸ τοῦτο Εὐαγόρεω Λάκωνος, πλέω δὲ τουτέων οὐδαμαί. ὁ μὲν δὴ πρεσβύτερος τῶν παίδων τῷ Κίμωνι Στησαγόρης ἦν τηνικαῦτα παρὰ τῷ πάτρῳ Μιλτιάδῃ τρεφόμενος ἐν τῇ Χερσονήσῳ, ὁ δὲ νεώτερος παρ’ αὐτῷ Κίμωνι ἐν Ἀθήνῃσι, οὔνομα ἔχων ἀπὸ τοῦ οἰκιστέω τῆς Χερσονήσου Μιλτιάδεω Μιλτιάδης.", "st": "6.103"}, {"sp": "N", "t": "οὗτος δὴ ὦν τότε ὁ Μιλτιάδης ἥκων ἐκ τῆς Χερσονήσου καὶ ἐκπεφευγὼς διπλόον θάνατον ἐστρατήγεε Ἀθηναίων. ἅμα μὲν γὰρ οἱ Φοίνικες αὐτὸν οἱ ἐπιδιώξαντες μέχρι Ἴμβρου περὶ πολλοῦ ἐποιεῦντο λαβεῖν τε καὶ ἀναγαγεῖν παρὰ βασιλέα· ἅμα δὲ ἐκφυγόντα τε τούτους καὶ ἀπικόμενον ἐς τὴν ἑωυτοῦ δοκέοντά τε εἶναι ἐν σωτηρίῃ ἤδη, τὸ ἐνθεῦτέν μιν οἱ ἐχθροὶ ὑποδεξάμενοι ὑπὸ δικαστήριον αὐτὸν ἀγαγόντες ἐδίωξαν τυραννίδος τῆς ἐν Χερσονήσῳ. ἀποφυγὼν δὲ καὶ τούτους στρατηγὸς οὕτω Ἀθηναίων ἀπεδέχθη, αἱρεθεὶς ὑπὸ τοῦ δήμου.", "st": "6.104"}, {"sp": "N", "t": "καὶ πρῶτα μὲν ἐόντες ἔτι ἐν τῷ ἄστεϊ οἱ στρατηγοὶ ἀποπέμπουσι ἐς Σπάρτην κήρυκα Φειδιππίδην Ἀθηναῖον μὲν ἄνδρα, ἄλλως δὲ ἡμεροδρόμην τε καὶ τοῦτο μελετῶντα· τῷ δή, ὡς αὐτός τε ἔλεγε Φειδιππίδης καὶ Ἀθηναίοισι ἀπήγγελλε, περὶ τὸ Παρθένιον ὄρος τὸ ὑπὲρ Τεγέης ὁ Πὰν περιπίπτει· βώσαντα δὲ τὸ οὔνομα τοῦ Φειδιππίδεω τὸν Πᾶνα Ἀθηναίοισι κελεῦσαι ἀπαγγεῖλαι, δι’ ὅ τι ἑωυτοῦ οὐδεμίαν ἐπιμελείην ποιεῦνται ἐόντος εὐνόου Ἀθηναίοισι καὶ πολλαχῇ γενομένου σφι ἤδη χρησίμου, τὰ δ’ ἔτι καὶ ἐσομένου. καὶ ταῦτα μὲν Ἀθηναῖοι, καταστάντων σφι εὖ ἤδη τῶν πρηγμάτων, πιστεύσαντες εἶναι ἀληθέα ἱδρύσαντο ὑπὸ τῇ ἀκροπόλι Πανὸς ἱρόν, καὶ αὐτὸν ἀπὸ ταύτης τῆς ἀγγελίης θυσίῃσι ἐπετείοισι καὶ λαμπάδι ἱλάσκονται.", "st": "6.105"}, {"sp": "N", "t": "τότε δὲ πεμφθεὶς ὑπὸ τῶν στρατηγῶν ὁ Φειδιππίδης οὗτος, ὅτε πέρ οἱ ἔφη καὶ τὸν Πᾶνα φανῆναι, δευτεραῖος ἐκ τοῦ Ἀθηναίων ἄστεος ἦν ἐν Σπάρτῃ, ἀπικόμενος δὲ ἐπὶ τοὺς ἄρχοντας ἔλεγε ὦ Λακεδαιμόνιοι, Ἀθηναῖοι ὑμέων δέονται σφίσι βοηθῆσαι καὶ μὴ περιιδεῖν πόλιν ἀρχαιοτάτην ἐν τοῖσι Ἕλλησι δουλοσύνῃ περιπεσοῦσαν πρὸς ἀνδρῶν βαρβάρων· καὶ γὰρ νῦν Ἐρέτριά τε ἠνδραπόδισται καὶ πόλι λογίμῳ ἡ Ἑλλὰς γέγονε ἀσθενεστέρη. ὃ μὲν δή σφι τὰ ἐντεταλμένα ἀπήγγελλε, τοῖσι δὲ ἕαδε μὲν βοηθέειν Ἀθηναίοισι, ἀδύνατα δέ σφι ἦν τὸ παραυτίκα ποιέειν ταῦτα, οὐ βουλομένοισι λύειν τὸν νόμον· ἦν γὰρ ἱσταμένου τοῦ μηνὸς εἰνάτη, εἰνάτῃ δὲ οὐκ ἐξελεύσεσθαι ἔφασαν μὴ οὐ πλήρεος ἐόντος τοῦ κύκλου.", "st": "6.106"}, {"sp": "N", "t": "οὗτοι μέν νυν τὴν πανσέληνον ἔμενον. τοῖσι δὲ βαρβάροισι κατηγέετο Ἱππίης ὁ Πεισιστράτου ἐς τὸν Μαραθῶνα, τῆς παροιχομένης νυκτὸς ὄψιν ἰδὼν τοιήνδε· ἐδόκεε ὁ Ἱππίης τῇ μητρὶ τῇ ἑωυτοῦ συνευνηθῆναι. συνεβάλετο ὦν ἐκ τοῦ ὀνείρου κατελθὼν ἐς τὰς Ἀθήνας καὶ ἀνασωσάμενος τὴν ἀρχὴν τελευτήσειν ἐν τῇ ἑωυτοῦ γηραιός. ἐκ μὲν δὴ τῆς ὄψιος συνεβάλετο ταῦτα, τότε δὲ κατηγεόμενος τοῦτο μὲν τὰ ἀνδράποδα τὰ ἐξ Ἐρετρίης ἀπέβησε ἐς τὴν νῆσον τὴν Στυρέων, καλεομένην δὲ Αἰγλείην, τοῦτο δὲ καταγομένας ἐς τὸν Μαραθῶνα τὰς νέας ὅρμιζε οὗτος, ἐκβάντας τε ἐς γῆν τοὺς βαρβάρους διέτασσε. καί οἱ ταῦτα διέποντι ἐπῆλθε πταρεῖν τε καὶ βῆξαι μεζόνως ἢ ὡς ἐώθεε· οἷα δέ οἱ πρεσβυτέρῳ ἐόντι τῶν ὀδόντων οἱ πλεῦνες ἐσείοντο· τούτων ὦν ἕνα τῶν ὀδόντων ἐκβάλλει ὑπὸ βίης βήξας· ἐκπεσόντος δὲ ἐς τὴν ψάμμον αὐτοῦ ἐποιέετο σπουδὴν πολλὴν ἐξευρεῖν. ὡς δὲ οὐκ ἐφαίνετό οἱ ὁ ὀδών, ἀναστενάξας εἶπε πρὸς τοὺς παραστάτας ἡ γῆ ἥδε οὐκ ἡμετέρη ἐστί, οὐδέ μιν δυνησόμεθα ὑποχειρίην ποιήσασθαι· ὁκόσον δέ τι μοι μέρος μετῆν, ὁ ὀδὼν μετέχει.", "st": "6.107"}, {"sp": "N", "t": "Ἱππίης μὲν δὴ ταύτῃ τὴν ὄψιν συνεβάλετο ἐξεληλυθέναι. Ἀθηναίοισι δὲ τεταγμένοισι ἐν τεμένεϊ Ἡρακλέος ἐπῆλθον βοηθέοντες Πλαταιέες πανδημεί. καὶ γὰρ καὶ ἐδεδώκεσαν σφέας αὐτοὺς τοῖσι Ἀθηναίοισι οἱ Πλαταιέες, καὶ πόνους ὑπὲρ αὐτῶν οἱ Ἀθηναῖοι συχνοὺς ἤδη ἀναραιρέατο· ἔδοσαν δὲ ὧδε. πιεζεύμενοι ὑπὸ Θηβαίων οἱ Πλαταιέες ἐδίδοσαν πρῶτα παρατυχοῦσι Κλεομένεΐ τε τῷ Ἀναξανδρίδεω καὶ Λακεδαιμονίοισι σφέας αὐτούς. οἳ δὲ οὐ δεκόμενοι ἔλεγόν σφι τάδε. ἡμεῖς μὲν ἑκαστέρω τε οἰκέομεν, καὶ ὑμῖν τοιήδε τις γίνοιτ’ ἂν ἐπικουρίη ψυχρή· φθαίητε γὰρ ἂν πολλάκις ἐξανδραποδισθέντες ἤ τινα πυθέσθαι ἡμέων. συμβουλεύομεν δὲ ὑμῖν δοῦναι ὑμέας αὐτοὺς Ἀθηναίοισι, πλησιοχώροισι τε ἀνδράσι καὶ τιμωρέειν ἐοῦσι οὐ κακοῖσι. ταῦτα συνεβούλευον οἱ Λακεδαιμόνιοι οὐ κατὰ τὴν εὐνοίην οὕτω τῶν Πλαταιέων ὡς βουλόμενοι τοὺς Ἀθηναίους ἔχειν πόνους συνεστεῶτας Βοιωτοῖσι. Λακεδαιμόνιοι μέν νυν Πλαταιεῦσι ταῦτα συνεβούλευον, οἳ δὲ οὐκ ἠπίστησαν, ἀλλ’ Ἀθηναίων ἱρὰ ποιεύντων τοῖσι δυώδεκα θεοῖσι ἱκέται ἱζόμενοι ἐπὶ τὸν βωμὸν ἐδίδοσαν σφέας αὐτούς. Θηβαῖοι δὲ πυθόμενοι ταῦτα ἐστρατεύοντο ἐπὶ τοὺς Πλαταιέας, Ἀθηναῖοι δέ σφι ἐβοήθεον. μελλόντων δὲ συνάπτειν μάχην Κορίνθιοι οὐ περιεῖδον, παρατυχόντες δὲ καὶ καταλλάξαντες ἐπιτρεψάντων ἀμφοτέρων οὔρισαν τὴν χώρην ἐπὶ τοῖσιδε, ἐᾶν Θηβαίους Βοιωτῶν τοὺς μὴ βουλομένους ἐς Βοιωτοὺς τελέειν. Κορίνθιοι μὲν δὴ ταῦτα γνόντες ἀπαλλάσσοντο, Ἀθηναίοισι δὲ ἀπιοῦσι ἐπεθήκαντο Βοιωτοί, ἐπιθέμενοι δὲ ἑσσώθησαν τῇ μάχῃ. ὑπερβάντες δὲ οἱ Ἀθηναῖοι τοὺς οἱ Κορίνθιοι ἔθηκαν Πλαταιεῦσι εἶναι οὔρους, τούτους ὑπερβάντες τὸν Ἀσωπὸν αὐτὸν ἐποιήσαντο οὖρον Θηβαίοισι πρὸς Πλαταιέας εἶναι καὶ Ὑσιάς. ἔδοσαν μὲν δὴ οἱ Πλαταιέες σφέας αὐτοὺς Ἀθηναίοισι τρόπῳ τῷ εἰρημένῳ, ἧκον δὲ τότε ἐς Μαραθῶνα βοηθέοντες.", "st": "6.108"}, {"sp": "N", "t": "τοῖσι δὲ Ἀθηναίων στρατηγοῖσι ἐγίνοντο δίχα αἱ γνῶμαι, τῶν μὲν οὐκ ἐώντων συμβαλεῖν (ὀλίγους γὰρ εἶναι στρατιῇ τῇ Μήδων συμβάλλειν) τῶν δὲ καὶ Μιλτιάδεω κελευόντων. ὡς δὲ δίχα τε ἐγίνοντο καὶ ἐνίκα ἡ χείρων τῶν γνωμέων, ἐνθαῦτα, ἦν γὰρ ἑνδέκατος ψηφιδοφόρος ὁ τῷ κυάμῳ λαχὼν Ἀθηναίων πολεμαρχέειν (τὸ παλαιὸν γὰρ Ἀθηναῖοι ὁμόψηφον τὸν πολέμαρχον ἐποιεῦντο τοῖσι στρατηγοῖσι), ἦν δὲ τότε πολέμαρχος Καλλίμαχος Ἀφιδναῖος· πρὸς τοῦτον ἐλθὼν Μιλτιάδης ἔλεγε τάδε. ἐν σοὶ νῦν Καλλίμαχε ἐστὶ ἢ καταδουλῶσαι Ἀθήνας ἢ ἐλευθέρας ποιήσαντα μνημόσυνα λιπέσθαι ἐς τὸν ἅπαντα ἀνθρώπων βίον οἷα οὐδὲ Ἁρμόδιός τε καὶ Ἀριστογείτων λείπουσι. νῦν γὰρ δὴ ἐξ οὗ ἐγένοντο Ἀθηναῖοι ἐς κίνδυνον ἥκουσι μέγιστον, καὶ ἢν μέν γε ὑποκύψωσι τοῖσι Μήδοισι, δέδοκται τὰ πείσονται παραδεδομένοι Ἱππίῃ, ἢν δὲ περιγένηται αὕτη ἡ πόλις, οἵη τε ἐστὶ πρώτη τῶν Ἑλληνίδων πολίων γενέσθαι. κῶς ὦν δὴ ταῦτα οἷά τε ἐστὶ γενέσθαι, καὶ κῶς ἐς σέ τοι τούτων ἀνήκει τῶν πρηγμάτων τὸ κῦρος ἔχειν, νῦν ἔρχομαι φράσων. ἡμέων τῶν στρατηγῶν ἐόντων δέκα δίχα γίνονται αἱ γνῶμαι, τῶν μὲν κελευόντων τῶν δὲ οὒ συμβάλλειν. ἢν μέν νυν μὴ συμβάλωμεν, ἔλπομαι τινὰ στάσιν μεγάλην διασείσειν ἐμπεσοῦσαν τὰ Ἀθηναίων φρονήματα ὥστε μηδίσαι· ἢν δὲ συμβάλωμεν πρίν τι καὶ σαθρὸν Ἀθηναίων μετεξετέροισι ἐγγενέσθαι, θεῶν τὰ ἴσα νεμόντων οἷοί τε εἰμὲν περιγενέσθαι τῇ συμβολῇ. ταῦτα ὦν πάντα ἐς σὲ νῦν τείνει καὶ ἐκ σέο ἤρτηται. ἢν γὰρ σὺ γνώμῃ τῇ ἐμῇ προσθῇ, ἔστι τοι πατρίς τε ἐλευθέρη καὶ πόλις πρώτη τῶν ἐν τῇ Ἑλλάδι· ἢν δὲ τὴν τῶν ἀποσπευδόντων τὴν συμβολὴν ἕλῃ, ὑπάρξει τοι τῶν ἐγὼ κατέλεξα ἀγαθῶν τὰ ἐναντία.", "st": "6.109"}, {"sp": "N", "t": "ταῦτα λέγων ὁ Μιλτιάδης προσκτᾶται τὸν Καλλίμαχον· προσγενομένης δὲ τοῦ πολεμάρχου τῆς γνώμης ἐκεκύρωτο συμβάλλειν. μετὰ δὲ οἱ στρατηγοὶ τῶν ἡ γνώμη ἔφερε συμβάλλειν, ὡς ἑκάστου αὐτῶν ἐγίνετο πρυτανηίη τῆς ἡμέρης, Μιλτιάδῃ παρεδίδοσαν· ὁ δὲ δεκόμενος οὔτι κω συμβολὴν ἐποιέετο, πρίν γε δὴ αὐτοῦ πρυτανηίη ἐγένετο.", "st": "6.110"}, {"sp": "N", "t": "ὡς δὲ ἐς ἐκεῖνον περιῆλθε, ἐνθαῦτα δὴ ἐτάσσοντο ὧδε οἱ Ἀθηναῖοι ὡς συμβαλέοντες· τοῦ μὲν δεξιοῦ κέρεος ἡγέετο ὁ πολέμαρχος Καλλίμαχος· ὁ γὰρ νόμος τότε εἶχε οὕτω τοῖσι Ἀθηναίοισι, τὸν πολέμαρχον ἔχειν κέρας τὸ δεξιόν· ἡγεομένου δὲ τούτου ἐξεδέκοντο ὡς ἀριθμέοντο αἱ φυλαὶ ἐχόμεναι ἀλληλέων, τελευταῖοι δὲ ἐτάσσοντο ἔχοντες τὸ εὐώνυμον κέρας Πλαταιέες. ἀπὸ ταύτης [γάρ] σφι τῆς μάχης, Ἀθηναίων θυσίας ἀναγόντων ἐς τὰς πανηγύριας τὰς ἐν τῇσι πεντετηρίσι γινομένας, κατεύχεται ὁ κῆρυξ ὁ Ἀθηναῖος ἅμα τε Ἀθηναίοισι λέγων γίνεσθαι τὰ ἀγαθὰ καὶ Πλαταιεῦσι. τότε δὲ τασσομένων τῶν Ἀθηναίων ἐν τῷ Μαραθῶνι ἐγίνετο τοιόνδε τι· τὸ στρατόπεδον ἐξισούμενον τῷ Μηδικῷ στρατοπέδῳ, τὸ μὲν αὐτοῦ μέσον ἐγίνετο ἐπὶ τάξιας ὀλίγας, καὶ ταύτῃ ἦν ἀσθενέστατον τὸ στρατόπεδον, τὸ δὲ κέρας ἑκάτερον ἔρρωτο πλήθεϊ.", "st": "6.111"}, {"sp": "N", "t": "ὡς δέ σφι διετέτακτο καὶ τὰ σφάγια ἐγίνετο καλά, ἐνθαῦτα ὡς ἀπείθησαν οἱ Ἀθηναῖοι δρόμῳ ἵεντο ἐς τοὺς βαρβάρους. ἦσαν δὲ στάδιοι οὐκ ἐλάσσονες τὸ μεταίχμιον αὐτῶν ἢ ὀκτώ. οἱ δὲ Πέρσαι ὁρέοντες δρόμῳ ἐπιόντας παρεσκευάζοντο ὡς δεξόμενοι, μανίην τε τοῖσι Ἀθηναίοισι ἐπέφερον καὶ πάγχυ ὀλεθρίην, ὁρέοντες αὐτοὺς ὀλίγους καὶ τούτους δρόμῳ ἐπειγομένους, οὔτε ἵππου ὑπαρχούσης σφι οὔτε τοξευμάτων. ταῦτα μέν νυν οἱ βάρβαροι κατείκαζον· Ἀθηναῖοι δὲ ἐπείτε ἀθρόοι προσέμιξαν τοῖσι βαρβάροισι, ἐμάχοντο ἀξίως λόγου. πρῶτοι μὲν γὰρ Ἑλλήνων πάντων τῶν ἡμεῖς ἴδμεν δρόμῳ ἐς πολεμίους ἐχρήσαντο, πρῶτοι δὲ ἀνέσχοντο ἐσθῆτά τε Μηδικὴν ὁρέοντες καὶ τοὺς ἄνδρας ταύτην ἐσθημένους· τέως δὲ ἦν τοῖσι Ἕλλησι καὶ τὸ οὔνομα τὸ Μήδων φόβος ἀκοῦσαι.", "st": "6.112"}, {"sp": "N", "t": "μαχομένων δὲ ἐν τῷ Μαραθῶνι χρόνος ἐγίνετο πολλός, καὶ τὸ μὲν μέσον τοῦ στρατοπέδου ἐνίκων οἱ βάρβαροι, τῇ Πέρσαι τε αὐτοὶ καὶ Σάκαι ἐτετάχατο· κατὰ τοῦτο μὲν δὴ ἐνίκων οἱ βάρβαροι καὶ ῥήξαντες ἐδίωκον ἐς τὴν μεσόγαιαν, τὸ δὲ κέρας ἑκάτερον ἐνίκων Ἀθηναῖοί τε καὶ Πλαταιέες· νικῶντες δὲ τὸ μὲν τετραμμένον τῶν βαρβάρων φεύγειν ἔων, τοῖσι δὲ τὸ μέσον ῥήξασι αὐτῶν συναγαγόντες τὰ κέρεα ἀμφότερα ἐμάχοντο, καὶ ἐνίκων Ἀθηναῖοι. φεύγουσι δὲ τοῖσι Πέρσῃσι εἵποντο κόπτοντες, ἐς ὃ ἐς τὴν θάλασσαν ἀπικόμενοι πῦρ τε αἴτεον καὶ ἐπελαμβάνοντο τῶν νεῶν.", "st": "6.113"}, {"sp": "N", "t": "καὶ τοῦτο μὲν ἐν τούτῳ τῷ πόνῳ ὁ πολέμαρχος διαφθείρεται, ἀνὴρ γενόμενος ἀγαθός, ἀπὸ δ’ ἔθανε τῶν στρατηγῶν Στησίλεως ὁ Θρασύλεω· τοῦτο δὲ Κυνέγειρος ὁ Εὐφορίωνος ἐνθαῦτα ἐπιλαμβανόμενος τῶν ἀφλάστων νεός, τὴν χεῖρα ἀποκοπεὶς πελέκεϊ πίπτει, τοῦτο δὲ ἄλλοι Ἀθηναίων πολλοί τε καὶ ὀνομαστοί.", "st": "6.114"}, {"sp": "N", "t": "ἑπτὰ μὲν δὴ τῶν νεῶν ἐπεκράτησαν τρόπῳ τοιῷδε Ἀθηναῖοι· τῇσι δὲ λοιπῇσι οἱ βάρβαροι ἐξανακρουσάμενοι, καὶ ἀναλαβόντες ἐκ τῆς νήσου ἐν τῇ ἔλιπον τὰ ἐξ Ἐρετρίης ἀνδράποδα, περιέπλεον Σούνιον βουλόμενοι φθῆναι τοὺς Ἀθηναίους ἀπικόμενοι ἐς τὸ ἄστυ. αἰτίην δὲ ἔσχε ἐν Ἀθηναίοισι ἐξ Ἀλκμεωνιδέων μηχανῆς αὐτοὺς ταῦτα ἐπινοηθῆναι· τούτους γὰρ συνθεμένους τοῖσι Πέρσῃσι ἀναδέξαι ἀσπίδα ἐοῦσι ἤδη ἐν τῇσι νηυσί.", "st": "6.115"}, {"sp": "N", "t": "οὗτοι μὲν δὴ περιέπλεον Σούνιον· Ἀθηναῖοι δὲ ὡς ποδῶν εἶχον τάχιστα ἐβοήθεον ἐς τὸ ἄστυ, καὶ ἔφθησάν τε ἀπικόμενοι πρὶν ἢ τοὺς βαρβάρους ἥκειν, καὶ ἐστρατοπεδεύσαντο ἀπιγμένοι ἐξ Ἡρακλείου τοῦ ἐν Μαραθῶνι ἐν ἄλλῳ Ἡρακλείῳ τῷ ἐν Κυνοσάργεϊ. οἱ δὲ βάρβαροι τῇσι νηυσὶ ὑπεραιωρηθέντες Φαλήρου, τοῦτο γὰρ ἦν ἐπίνειον τότε τῶν Ἀθηναίων, ὑπὲρ τούτου ἀνακωχεύσαντες τὰς νέας ἀπέπλεον ὀπίσω ἐς τὴν Ἀσίην.", "st": "6.116"}, {"sp": "N", "t": "ἐν ταύτῃ τῇ ἐν Μαραθῶνι μάχῃ ἀπέθανον τῶν βαρβάρων κατὰ ἑξακισχιλίους καὶ τετρακοσίους ἄνδρας, Ἀθηναίων δὲ ἑκατὸν καὶ ἐνενήκοντα καὶ δύο. ἔπεσον μὲν ἀμφοτέρων τοσοῦτοι. συνήνεικε δὲ αὐτόθι θῶμα γενέσθαι τοιόνδε, Ἀθηναῖον ἄνδρα Ἐπίζηλον τὸν Κουφαγόρεω ἐν τῇ συστάσι μαχόμενόν τε καὶ ἄνδρα γινόμενον ἀγαθὸν τῶν ὀμμάτων στερηθῆναι οὔτε πληγέντα οὐδὲν τοῦ σώματος οὔτε βληθέντα, καὶ τὸ λοιπὸν τῆς ζόης διατελέειν ἀπὸ τούτου τοῦ χρόνου ἐόντα τυφλόν. λέγειν δὲ αὐτὸν περὶ τοῦ πάθεος ἤκουσα τοιόνδε τινὰ λόγον, ἄνδρα οἱ δοκέειν ὁπλίτην ἀντιστῆναι μέγαν, τοῦ τὸ γένειον τὴν ἀσπίδα πᾶσαν σκιάζειν· τὸ δὲ φάσμα τοῦτο ἑωυτὸν μὲν παρεξελθεῖν, τὸν δὲ ἑωυτοῦ παραστάτην ἀποκτεῖναι. ταῦτα μὲν δὴ Ἐπίζηλον ἐπυθόμην λέγειν.", "st": "6.117"}, {"sp": "N", "t": "Δᾶτις δὲ πορευόμενος ἅμα τῷ στρατῷ ἐς τὴν Ἀσίην, ἐπείτε ἐγένετο ἐν Μυκόνῳ, εἶδε ὄψιν ἐν τῷ ὕπνῳ. καὶ ἥτις μὲν ἦν ἡ ὄψις, οὐ λέγεται· ὁ δέ, ὡς ἡμέρη τάχιστα ἐπέλαμψε, ζήτησιν ἐποιέετο τῶν νεῶν, εὑρὼν δὲ ἐν νηὶ Φοινίσσῃ ἄγαλμα Ἀπόλλωνος κεχρυσωμένον ἐπυνθάνετο ὁκόθεν σεσυλημένον εἴη, πυθόμενος δὲ ἐξ οὗ ἦν ἱροῦ, ἔπλεε τῇ ἑωυτοῦ νηὶ ἐς Δῆλον· καὶ ἀπίκατο γὰρ τηνικαῦτα οἱ Δήλιοι ὀπίσω ἐς τὴν νῆσον, κατατίθεταί τε ἐς τὸ ἱρὸν τὸ ἄγαλμα καὶ ἐντέλλεται τοῖσι Δηλίοισι ἀπαγαγεῖν τὸ ἄγαλμα ἐς Δήλιον τὸ Θηβαίων· τὸ δ’ ἔστι ἐπὶ θαλάσσῃ Χαλκίδος καταντίον. Δᾶτις μὲν δὴ ταῦτα ἐντειλάμενος ἀπέπλεε, τὸν δὲ ἀνδριάντα τοῦτον Δήλιοι οὐκ ἀπήγαγον, ἀλλά μιν δι’ ἐτέων εἴκοσι Θηβαῖοι αὐτοὶ ἐκ θεοπροπίου ἐκομίσαντο ἐπὶ Δήλιον.", "st": "6.118"}, {"sp": "N", "t": "τοὺς δὲ τῶν Ἐρετριέων ἀνδραποδισμένους Δᾶτίς τε καὶ Ἀρταφρένης, ὡς προσέσχον πρὸς τὴν Ἀσίην πλέοντες, ἀνήγαγον ἐς Σοῦσα. βασιλεὺς δὲ Δαρεῖος, πρὶν μὲν αἰχμαλώτους γενέσθαι τοὺς Ἐρετριέας, ἐνεῖχέ σφι δεινὸν χόλον, οἷα ἀρξάντων ἀδικίης προτέρων τῶν Ἐρετριέων· ἐπείτε δὲ εἶδε σφέας ἀπαχθέντας παρ’ ἑωυτὸν καὶ ἑωυτῷ ὑποχειρίους ἐόντας, ἐποίησε κακὸν ἄλλο οὐδέν, ἀλλὰ σφέας τῆς Κισσίης χώρης κατοίκισε ἐν σταθμῷ ἑωυτοῦ τῷ οὔνομα ἐστὶ Ἀρδέρικκα, ἀπὸ μὲν Σούσων δέκα καὶ διηκοσίους σταδίους ἀπέχοντι, τεσσεράκοντα δὲ ἀπὸ τοῦ φρέατος τὸ παρέχεται τριφασίας ἰδέας· καὶ γὰρ ἄσφαλτον καὶ ἅλας καὶ ἔλαιον ἀρύσσονται ἐξ αὐτοῦ τρόπῳ τοιῷδε· ἀντλέεται μὲν κηλωνηίῳ, ἀντὶ δὲ γαυλοῦ ἥμισυ ἀσκοῦ οἱ προσδέδεται· ὑποτύψας δὲ τούτῳ ἀντλέει καὶ ἔπειτα ἐγχέει ἐς δεξαμενήν· ἐκ δὲ ταύτης ἐς ἄλλο διαχεόμενον τρέπεται τριφασίας ὁδούς. καὶ ἡ μὲν ἄσφαλτος καὶ οἱ ἅλες πήγνυνται παραυτίκα· τὸ δὲ ἔλαιον οἱ Πέρσαι καλέουσι τοῦτο ῥαδινάκην, ἔστι δὲ μέλαν καὶ ὀδμὴν παρεχόμενον βαρέαν. ἐνθαῦτα τοὺς Ἐρετριέας κατοίκισε βασιλεὺς Δαρεῖος, οἳ καὶ μέχρι ἐμέο εἶχον τὴν χώρην ταύτην, φυλάσοντες τὴν ἀρχαίην γλῶσσαν. τὰ μὲν δὴ περὶ Ἐρετριέας ἔσχε οὕτω.", "st": "6.119"}, {"sp": "N", "t": "Λακεδαιμονίων δὲ ἧκον ἐς τὰς Ἀθήνας δισχίλιοι μετὰ τὴν πανσέληνον, ἔχοντες σπουδὴν πολλὴν καταλαβεῖν, οὕτω ὥστε τριταῖοι ἐκ Σπάρτης ἐγένοντο ἐν τῇ Ἀττικῇ. ὕστεροι δὲ ἀπικόμενοι τῆς συμβολῆς ἱμείροντο ὅμως θεήσασθαι τοὺς Μήδους· ἐλθόντες δὲ ἐς τὸν Μαραθῶνα ἐθεήσαντο. μετὰ δὲ αἰνέοντες Ἀθηναίους καὶ τὸ ἔργον αὐτῶν ἀπαλλάσσοντο ὀπίσω.", "st": "6.120"}, {"sp": "N", "t": "θῶμα δέ μοι καὶ οὐκ ἐνδέκομαι τὸν λόγον Ἀλκμεωνίδας ἄν κοτε ἀναδέξαι Πέρσῃσι ἐκ συνθήματος ἀσπίδα, βουλομένους ὑπὸ βαρβάροισί τε εἶναι Ἀθηναίους καὶ ὑπὸ Ἱππίῃ· οἵτινες μᾶλλον ἢ ὁμοίως Καλλίῃ τῷ Φαινίππου, Ἱππονίκου δὲ πατρί, φαίνονται μισοτύραννοι ἐόντες. Καλλίης τε γὰρ μοῦνος Ἀθηναίων ἁπάντων ἐτόλμα, ὅκως Πεισίστρατος ἐκπέσοι ἐκ τῶν Ἀθηνέων, τὰ χρήματα αὐτοῦ κηρυσσόμενα ὑπὸ τοῦ δημοσίου ὠνέεσθαι, καὶ τἆλλα τὰ ἔχθιστα ἐς αὐτὸν πάντα ἐμηχανᾶτο.", "st": "6.121"}, {"sp": "N", "t": "[Καλλίεω δὲ τούτου ἄξιον πολλαχοῦ μνήμην ἐστὶ πάντα τινὰ ἔχειν. τοῦτο μὲν γὰρ τὰ προλελεγμένα, ὡς ἀνὴρ ἄκρος ἐλευθερῶν τὴν πατρίδα· τοῦτο δὲ τὰ ἐν Ὀλυμπίῃ ἐποίησε· ἵππῳ νικήσας, τεθρίππῳ δὲ δεύτερος γενόμενος, Πύθια δὲ πρότερον ἀνελόμενος, ἐφανερώθη ἐς τοὺς Ἕλληνας πάντας δαπάνῃσι μεγίστῃσι. τοῦτο δὲ κατὰ τὰς ἑωυτοῦ θυγατέρας ἐούσας τρεῖς οἷός τις ἀνὴρ ἐγένετο· ἐπειδὴ γὰρ ἐγίνοντο γάμου ὡραῖαι, ἔδωκέ σφι δωρεὴν μεγαλοπρεπεστάτην ἐκείνῃσί τε ἐχαρίσατο· ἐκ γὰρ πάντων τῶν Ἀθηναίων τὸν ἑκάστη ἐθέλοι ἄνδρα ἑωυτῇ ἐκλέξασθαι, ἔδωκε τούτῳ τῷ ἀνδρί.]", "st": "6.122"}, {"sp": "N", "t": "καὶ οἱ Ἀλκμεωνίδαι ὁμοίως ἢ οὐδὲν ἧσσον τούτου ἦσαν μισοτύραννοι. θῶμα ὦν μοι καὶ οὐ προσίεμαι τὴν διαβολὴν τούτους γε ἀναδέξαι ἀσπίδα, οἵτινες ἔφευγόν τε τὸν πάντα χρόνον τοὺς τυράννους, ἐκ μηχανῆς τε τῆς τούτων ἐξέλιπον Πεισιστρατίδαι τὴν τυραννίδα, καὶ οὕτω τὰς Ἀθήνας οὗτοι ἦσαν οἱ ἐλευθερώσαντες πολλῷ μᾶλλον ἤ περ Ἁρμόδιός τε καὶ Ἀριστογείτων, ὡς ἐγὼ κρίνω. οἳ μὲν γὰρ ἐξηγρίωσαν τοὺς ὑπολοίπους Πεισιστρατιδέων Ἵππαρχον ἀποκτείναντες, οὐδέ τι μᾶλλον ἔπαυσαν τοὺς λοιποὺς τυραννεύοντας· Ἀλκμεωνίδαι δὲ ἐμφανέως ἠλευθέρωσαν, εἰ δὴ οὗτοί γε ἀληθέως ἦσαν οἱ τὴν Πυθίην ἀναπείσαντες προσημαίνειν Λακεδαιμονίοισι ἐλευθεροῦν τὰς Ἀθήνας, ὥς μοι πρότερον δεδήλωται.", "st": "6.123"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἴσως τι ἐπιμεμφόμενοι Ἀθηναίων τῷ δήμῳ προεδίδοσαν τὴν πατρίδα. οὐ μὲν ὦν ἦσαν σφέων ἄλλοι δοκιμώτεροι ἔν γε Ἀθηναίοισι ἄνδρες οὐδ’ οἳ μᾶλλον ἐτετιμέατο. οὕτω οὐδὲ λόγος αἱρέει ἀναδεχθῆναι ἔκ γε ἂν τούτων ἀσπίδα ἐπὶ τοιούτῳ λόγῳ. ἀνεδέχθη μὲν γὰρ ἀσπίς, καὶ τοῦτο οὐκ ἔστι ἄλλως εἰπεῖν· ἐγένετο γάρ· ὃς μέντοι ἦν ὁ ἀναδέξας, οὐκ ἔχω προσωτέρω εἰπεῖν τούτων.", "st": "6.124"}, {"sp": "N", "t": "οἱ δὲ Ἀλκμεωνίδαι ἦσαν μὲν καὶ τὰ ἀνέκαθεν λαμπροὶ ἐν τῇσι Ἀθήνῃσι, ἀπὸ δὲ Ἀλκμέωνος καὶ αὖτις Μεγακλέος ἐγένοντο καὶ κάρτα λαμπροί. τοῦτο μὲν γὰρ Ἀλκμέων ὁ Μεγακλέος τοῖσι ἐκ Σαρδίων Λυδοῖσι παρὰ Κροίσου ἀπικνεομένοισι ἐπὶ τὸ χρηστήριον τὸ ἐν Δελφοῖσι συμπρήκτωρ τε ἐγίνετο καὶ συνελάμβανε προθύμως, καί μιν Κροῖσος πυθόμενος τῶν Λυδῶν τῶν ἐς τὰ χρηστήρια φοιτεόντων ἑωυτὸν εὖ ποιέειν μεταπέμπεται ἐς Σάρδις, ἀπικόμενον δὲ δωρέεται χρυσῷ τὸν ἂν δύνηται τῷ ἑωυτοῦ σώματι ἐξενείκασθαι ἐσάπαξ. ὁ δὲ Ἀλκμέων πρὸς τὴν δωρεὴν ἐοῦσαν τοιαύτην τοιάδε ἐπιτηδεύσας προσέφερε· ἐνδὺς κιθῶνα μέγαν καὶ κόλπον βαθὺν καταλιπόμενος τοῦ κιθῶνος, κοθόρνους τε τοὺς εὕρισκε εὐρυτάτους ἐόντας ὑποδησάμενος, ἤιε ἐς τὸν θησαυρὸν ἐς τόν οἱ κατηγέοντο. ἐσπεσὼν δὲ ἐς σωρὸν ψήγματος πρῶτα μὲν παρέσαξε παρὰ τὰς κνήμας τοῦ χρυσοῦ ὅσον ἐχώρεον οἱ κόθορνοι, μετὰ δὲ τὸν κόλπον πάντα πλησάμενος τοῦ χρυσοῦ καὶ ἐς τὰς τρίχας τῆς κεφαλῆς διαπάσας τοῦ ψήγματος καὶ ἄλλο λαβὼν ἐς τὸ στόμα, ἐξήιε ἐκ τοῦ θησαυροῦ ἕλκων μὲν μόγις τοὺς κοθόρνους, παντὶ δὲ τεῷ οἰκὼς μᾶλλον ἢ ἀνθρώπῳ· τοῦ τό τε στόμα ἐβέβυστο καὶ πάντα ἐξώγκωτο. ἰδόντα δὲ τὸν Κροῖσον γέλως ἐσῆλθε, καί οἱ πάντα τε ἐκεῖνα διδοῖ καὶ πρὸς ἕτερα δωρέεται οὐκ ἐλάσσω ἐκείνων. οὕτω μὲν ἐπλούτησε ἡ οἰκίη αὕτη μεγάλως, καὶ ὁ Ἀλκμέων οὗτος οὕτω τεθριπποτροφήσας Ὀλυμπιάδα ἀναιρέεται.", "st": "6.125"}, {"sp": "N", "t": "μετὰ δὲ γενεῇ δευτέρῃ ὕστερον Κλεισθένης αὐτὴν ὁ Σικυώνιος τύραννος ἐξήειρε, ὥστε πολλῷ ὀνομαστοτέρην γενέσθαι ἐν τοῖσι Ἕλλησι ἢ πρότερον ἦν. Κλεισθένεϊ γὰρ τῷ Ἀριστωνύμου τοῦ Μύρωνος τοῦ Ἀνδρέω γίνεται θυγάτηρ τῇ οὔνομα ἦν Ἀγαρίστη. ταύτην ἠθέλησε, Ἑλλήνων ἁπάντων ἐξευρὼν τὸν ἄριστον, τούτῳ γυναῖκα προσθεῖναι. Ὀλυμπίων ὦν ἐόντων καὶ νικῶν ἐν αὐτοῖσι τεθρίππῳ ὁ Κλεισθένης κήρυγμα ἐποιήσατο, ὅστις Ἑλλήνων ἑωυτὸν ἀξιοῖ Κλεισθένεος γαμβρὸν γενέσθαι, ἥκειν ἐς ἑξηκοστὴν ἡμέρην ἢ καὶ πρότερον ἐς Σικυῶνα, ὡς κυρώσοντος Κλεισθένεος τὸν γάμον ἐν ἐνιαυτῷ, ἀπὸ τῆς ἑξηκοστῆς ἀρξαμένου ἡμέρης. ἐνθαῦτα Ἑλλήνων ὅσοι σφίσι τε αὐτοῖσι ἦσαν καὶ πάτρῃ ἐξωγκωμένοι, ἐφοίτεον μνηστῆρες· τοῖσι Κλεισθένης καὶ δρόμον καὶ παλαίστρην ποιησάμενος ἐπ’ αὐτῷ τούτῳ εἶχε.", "st": "6.126"}, {"sp": "N", "t": "ἀπὸ μὲν δὴ Ἰταλίης ἦλθε Σμινδυρίδης ὁ Ἱπποκράτεος Συβαρίτης, ὃς ἐπὶ πλεῖστον δὴ χλιδῆς εἷς ἀνὴρ ἀπίκετο (ἡ δὲ Σύβαρις ἤκμαζε τοῦτον τὸν χρόνον μάλιστα), καὶ Σιρίτης Δάμασος Ἀμύριος τοῦ σοφοῦ λεγομένου παῖς. οὗτοι μὲν ἀπὸ Ἰταλίης ἦλθον, ἐκ δὲ τοῦ κόλπου τοῦ Ἰονίου Ἀμφίμνηστος Ἐπιστρόφου Ἐπιδάμνιος· οὗτος δὲ ἐκ τοῦ Ἰονίου κόλπου. Αἰτωλὸς δὲ ἦλθε Τιτόρμου τοῦ ὑπερφύντος τε Ἕλληνας ἰσχύι καὶ φυγόντος ἀνθρώπους ἐς τὰς ἐσχατιὰς τῆς Αἰτωλίδος χώρης, τούτου τοῦ Τιτόρμου ἀδελφεὸς Μάλης. ἀπὸ δὲ Πελοποννήσου Φείδωνος τοῦ Ἀργείων τυράννου παῖς Λεωκήδης, Φείδωνος δὲ τοῦ τὰ μέτρα ποιήσαντος Πελοποννησίοισι καὶ ὑβρίσαντος μέγιστα δὴ Ἑλλήνων πάντων, ὃς ἐξαναστήσας τοὺς Ἠλείων ἀγωνοθέτας αὐτὸς τὸν ἐν Ὀλυμπίῃ ἀγῶνα ἔθηκε· τούτου τε δὴ παῖς καὶ Ἀμίαντος Λυκούργου Ἀρκὰς ἐκ Τραπεζοῦντος, καὶ Ἀζὴν ἐκ Παίου πόλιος Λαφάνης Εὐφορίωνος τοῦ δεξαμένου τε, ὡς λόγος ἐν Ἀρκαδίῃ λέγεται, τοὺς Διοσκούρους οἰκίοισι καὶ ἀπὸ τούτου ξεινοδοκέοντος πάντας ἀνθρώπους, καὶ Ἠλεῖος Ὀνόμαστος Ἀγαίου. οὗτοι μὲν δὴ ἐξ αὐτῆς Πελοποννήσου ἦλθον, ἐκ δὲ Ἀθηνέων ἀπίκοντο Μεγακλέης τε ὁ Ἀλκμέωνος τούτου τοῦ παρὰ Κροῖσον ἀπικομένου, καὶ ἄλλος Ἱπποκλείδης Τισάνδρου, πλούτῳ καὶ εἴδεϊ προφέρων Ἀθηναίων. ἀπὸ δὲ Ἐρετρίης ἀνθεύσης τοῦτον τὸν χρόνον Λυσανίης· οὗτος δὲ ἀπ’ Εὐβοίης μοῦνος. ἐκ δὲ Θεσσαλίης ἦλθε τῶν Σκοπαδέων Διακτορίδης Κραννώνιος, ἐκ δὲ Μολοσσῶν Ἄλκων.", "st": "6.127"}, {"sp": "N", "t": "τοσοῦτοι μὲν ἐγένοντο οἱ μνηστῆρες. ἀπικομένων δὲ τούτων ἐς τὴν προειρημένην ἡμέρην, ὁ Κλεισθένης πρῶτα μὲν τὰς πάτρας τε αὐτῶν ἀνεπύθετο καὶ γένος ἑκάστου, μετὰ δὲ κατέχων ἐνιαυτὸν διεπειρᾶτο αὐτῶν τῆς τε ἀνδραγαθίης καὶ τῆς ὀργῆς καὶ παιδεύσιός τε καὶ τρόπου, καὶ ἑνὶ ἑκάστῳ ἰὼν ἐς συνουσίην καὶ συνάπασι, καὶ ἐς γυμνάσιά τε ἐξαγινέων ὅσοι ἦσαν αὐτῶν νεώτεροι, καὶ τό γε μέγιστον, ἐν τῇ συνεστίῃ διεπειρᾶτο· ὅσον γὰρ κατεῖχε χρόνον αὐτούς, τοῦτον πάντα ἐποίεε καὶ ἅμα ἐξείνιζε μεγαλοπρεπέως. καὶ δή κου μάλιστα τῶν μνηστήρων ἠρέσκοντο οἱ ἀπ’ Ἀθηνέων ἀπιγμένοι, καὶ τούτων μᾶλλον Ἱπποκλείδης ὁ Τισάνδρου καὶ κατ’ ἀνδραγαθίην ἐκρίνετο καὶ ὅτι τὸ ἀνέκαθεν τοῖσι ἐν Κορίνθῳ Κυψελίδῃσι ἦν προσήκων.", "st": "6.128"}, {"sp": "N", "t": "ὡς δὲ ἡ κυρίη ἐγένετο τῶν ἡμερέων τῆς τε κατακλίσιος τοῦ γάμου καὶ ἐκφάσιος αὐτοῦ Κλεισθένεος τὸν κρίνοι ἐκ πάντων, θύσας βοῦς ἑκατὸν ὁ Κλεισθένης εὐώχεε αὐτούς τε τοὺς μνηστῆρας καὶ Σικυωνίους πάντας. ὡς δὲ ἀπὸ δείπνου ἐγίνοντο, οἱ μνηστῆρες ἔριν εἶχον ἀμφί τε μουσικῇ καὶ τῷ λεγομένῳ ἐς τὸ μέσον. προϊούσης δὲ τῆς πόσιος κατέχων πολλὸν τοὺς ἄλλους ὁ Ἱπποκλείδης ἐκέλευσέ οἱ τὸν αὐλητὴν αὐλῆσαι ἐμμελείην, πειθομένου δὲ τοῦ αὐλητέω ὀρχήσατο. καί κως ἑωυτῷ μὲν ἀρεστῶς ὀρχέετο, ὁ Κλεισθένης δὲ ὁρέων ὅλον τὸ πρῆγμα ὑπώπτευε. μετὰ δὲ ἐπισχὼν ὁ Ἱπποκλείδης χρόνον ἐκέλευσε τινὰ τράπεζαν ἐσενεῖκαι, ἐσελθούσης δὲ τῆς τραπέζης πρῶτα μὲν ἐπ’ αὐτῆς ὀρχήσατο Λακωνικὰ σχημάτια, μετὰ δὲ ἄλλα Ἀττικά, τὸ τρίτον δὲ τὴν κεφαλὴν ἐρείσας ἐπὶ τὴν τράπεζαν τοῖσι σκέλεσι ἐχειρονόμησε. Κλεισθένης δὲ τὰ μὲν πρῶτα καὶ τὰ δεύτερα ὀρχεομένου, ἀποστυγέων γαμβρὸν ἄν οἱ ἔτι γενέσθαι Ἱπποκλείδεα διὰ τήν τε ὄρχησιν καὶ τὴν ἀναιδείην, κατεῖχε ἑωυτόν, οὐ βουλόμενος ἐκραγῆναι ἐς αὐτόν· ὡς δὲ εἶδε τοῖσι σκέλεσι χειρονομήσαντα, οὐκέτι κατέχειν δυνάμενος εἶπε ὦ παῖ Τισάνδρου, ἀπορχήσαό γε μὲν τὸν γάμον. ὁ δὲ Ἱπποκλείδης ὑπολαβὼν εἶπε οὐ φροντὶς Ἱπποκλείδῃ. ἀπὸ τούτου μὲν τοῦτο ὀνομάζεται.", "st": "6.129"}, {"sp": "N", "t": "Κλεισθένης δὲ σιγὴν ποιησάμενος ἔλεξε ἐς μέσον τάδε. ἄνδρες παιδὸς τῆς ἐμῆς μνηστῆρες, ἐγὼ καὶ πάντας ὑμέας ἐπαινέω καὶ πᾶσι ὑμῖν, εἰ οἷόν τε εἴη, χαριζοίμην ἄν, μήτ’ ἕνα ὑμέων ἐξαίρετον ἀποκρίνων μήτε τοὺς λοιποὺς ἀποδοκιμάζων. ἀλλ’ οὐ γὰρ οἷά τε ἐστὶ μιῆς πέρι παρθένου βουλεύοντα πᾶσι κατὰ νόον ποιέειν, τοῖσι μὲν ὑμέων ἀπελαυνομένοισι τοῦδε τοῦ γάμου τάλαντον ἀργυρίου ἑκάστῳ δωρεὴν δίδωμι τῆς ἀξιώσιος εἵνεκα τῆς ἐξ ἐμεῦ γῆμαι καὶ τῆς ἐξ οἴκου ἀποδημίης, τῷ δὲ Ἀλκμέωνος Μεγακλέι ἐγγυῶ παῖδα τὴν ἐμὴν Ἀγαρίστην νόμοισι τοῖσι Ἀθηναίων. φαμένου δὲ ἐγγυᾶσθαι Μεγακλέος ἐκεκύρωτο ὁ γάμος Κλεισθένεϊ.", "st": "6.130"}, {"sp": "N", "t": "ἀμφὶ μὲν κρίσιος τῶν μνηστήρων τοσαῦτα ἐγένετο καὶ οὕτω Ἀλκμεωνίδαι ἐβώσθησαν ἀνὰ τὴν Ἑλλάδα. τούτων δὲ συνοικησάντων γίνεται Κλεισθένης τε ὁ τὰς φυλὰς καὶ τὴν δημοκρατίην Ἀθηναίοισι καταστήσας, ἔχων τὸ οὔνομα ἀπὸ τοῦ μητροπάτορος τοῦ Σικυωνίου· οὗτός τε δὴ γίνεται Μεγακλέϊ καὶ Ἱπποκράτης, ἐκ δὲ Ἱπποκράτεος Μεγακλέης τε ἄλλος καὶ Ἀγαρίστη ἄλλη ἀπὸ τῆς Κλεισθένεος Ἀγαρίστης ἔχουσα τὸ οὔνομα· ἣ συνοικήσασά τε Ξανθίππῳ τῷ Ἀρίφρονος καὶ ἔγκυος ἐοῦσα εἶδε ὄψιν ἐν τῷ ὕπνῳ, ἐδόκεε δὲ λέοντα τεκεῖν, καὶ μετ’ ὀλίγας ἡμέρας τίκτει Περικλέα Ξανθίππῳ.", "st": "6.131"}, {"sp": "N", "t": "μετὰ δὲ τὸ ἐν Μαραθῶνι τρῶμα γενόμενον Μιλτιάδης, καὶ πρότερον εὐδοκιμέων παρὰ Ἀθηναίοισι, τότε μᾶλλον αὔξετο. αἰτήσας δὲ νέας ἑβδομήκοντα καὶ στρατιήν τε καὶ χρήματα Ἀθηναίους, οὐ φράσας σφι ἐπ’ ἣν ἐπιστρατεύσεται χώρην, ἀλλὰ φὰς αὐτοὺς καταπλουτιεῖν ἤν οἱ ἕπωνται· ἐπὶ γὰρ χώρην τοιαύτην δή τινα ἄξειν ὅθεν χρυσὸν εὐπετέως ἄφθονον οἴσονται· λέγων τοιαῦτα αἴτεε τὰς νέας. Ἀθηναῖοι δὲ τούτοισι ἐπαερθέντες παρέδοσαν.", "st": "6.132"}, {"sp": "N", "t": "παραλαβὼν δὲ ὁ Μιλτιάδης τὴν στρατιὴν ἔπλεε ἐπὶ Πάρον, πρόφασιν ἔχων ὡς οἱ Πάριοι ὑπῆρξαν πρότεροι στρατευόμενοι τριήρεσι ἐς Μαραθῶνα ἅμα τῷ Πέρσῃ. τοῦτο μὲν δὴ πρόσχημα λόγων ἦν, ἀτάρ τινα καὶ ἔγκοτον εἶχε τοῖσι Παρίοισι διὰ Λυσαγόρεα τὸν Τισίεω, ἐόντα γένος Πάριον, διαβαλόντα μιν πρὸς Ὑδάρνεα τὸν Πέρσην. ἀπικόμενος δὲ ἐπ’ ἣν ἔπλεε ὁ Μιλτιάδης τῇ στρατιῇ ἐπολιόρκεε Παρίους κατειλημένους ἐντὸς τείχεος, καὶ ἐσπέμπων κήρυκα αἴτεε ἑκατὸν τάλαντα, φάς, ἢν μιν οὐ δῶσι, οὐκ ἀπονοστήσειν τὴν στρατιὴν πρὶν ἢ ἐξέλῃ σφέας. οἱ δὲ Πάριοι ὅκως μέν τι δώσουσι Μιλτιάδῃ ἀργύριον οὐδὲ διενοεῦντο, οἳ δὲ ὅκως διαφυλάξουσι τὴν πόλιν τοῦτο ἐμηχανῶντο, ἄλλα τε ἐπιφραζόμενοι καὶ τῇ μάλιστα ἔσκε ἑκάστοτε ἐπίμαχον τοῦ τείχεος, τοῦτο ἅμα νυκτὶ ἐξηείρετο διπλήσιον τοῦ ἀρχαίου.", "st": "6.133"}, {"sp": "N", "t": "ἐς μὲν δὴ τοσοῦτο τοῦ λόγου οἱ πάντες Ἕλληνες λέγουσι, τὸ ἐνθεῦτεν δὲ αὐτοὶ Πάριοι γενέσθαι ὧδε λέγουσι. Μιλτιάδῃ ἀπορέοντι ἐλθεῖν ἐς λόγους αἰχμάλωτον γυναῖκα, ἐοῦσαν μὲν Παρίην γένος, οὔνομα δέ οἱ εἶναι Τιμοῦν, εἶναι δὲ ὑποζάκορον τῶν χθονίων θεῶν· ταύτην ἐλθοῦσαν ἐς ὄψιν Μιλτιάδεω συμβουλεῦσαι, εἰ περὶ πολλοῦ ποιέεται Πάρον ἑλεῖν, τὰ ἂν αὐτὴ ὑποθῆται, ταῦτα ποιέειν. μετὰ δὲ τὴν μὲν ὑποθέσθαι, τὸν δὲ διερχόμενον ἐπὶ τὸν κολωνὸν τὸν πρὸ τῆς πόλιος ἐόντα ἕρκος θεσμοφόρου Δήμητρος ὑπερθορεῖν, οὐ δυνάμενον τὰς θύρας ἀνοῖξαι, ὑπερθορόντα δὲ ἰέναι ἐπὶ τὸ μέγαρον ὅ τι δὴ ποιήσοντα ἐντός, εἴτε κινήσοντά τι τῶν ἀκινήτων εἴτε ὅ τι δή κοτε πρήξοντα· πρὸς τῇσι θύρῃσί τε γενέσθαι καὶ πρόκατε φρίκης αὐτὸν ὑπελθούσης ὀπίσω τὴν αὐτὴν ὁδὸν ἵεσθαι, καταθρώσκοντα δὲ τὴν αἱμασιὴν τὸν μηρὸν σπασθῆναι· οἳ δὲ αὐτὸν τὸ γόνυ προσπταῖσαι λέγουσι.", "st": "6.134"}, {"sp": "N", "t": "Μιλτιάδης μέν νυν φλαύρως ἔχων ἀπέπλεε ὀπίσω, οὔτε χρήματα Ἀθηναίοισι ἄγων οὔτε Πάρον προσκτησάμενος, ἀλλὰ πολιορκήσας τε ἓξ καὶ εἴκοσι ἡμέρας καὶ δηιώσας τὴν νῆσον. Πάριοι δὲ πυθόμενοι ὡς ἡ ὑποζάκορος τῶν θεῶν Τιμὼ Μιλτιάδῃ κατηγήσατο, βουλόμενοί μιν ἀντὶ τούτων τιμωρήσασθαι, θεοπρόπους πέμπουσι ἐς Δελφούς ὥς σφεας ἡσυχίη τῆς πολιορκίης ἔσχε· ἔπεμπον δὲ ἐπειρησομένους εἰ καταχρήσωνται τὴν ὑποζάκορον τῶν θεῶν τὴν ἐξηγησαμένην τοῖσι ἐχθροῖσι τῆς πατρίδος ἅλωσιν καὶ τὰ ἐς ἔρσενα γόνον ἄρρητα ἱρὰ ἐκφήνασαν Μιλτιάδῃ. ἡ δὲ Πυθίη οὐκ ἔα, φᾶσα οὐ Τιμοῦν εἶναι τὴν αἰτίην τούτων, ἀλλὰ δεῖν γὰρ Μιλτιάδεα τελευτᾶν μὴ εὖ, φανῆναί οἱ τῶν κακῶν κατηγεμόνα.", "st": "6.135"}, {"sp": "N", "t": "παρίοισι μὲν δὴ ταῦτα ἡ Πυθίη ἔχρησε· Ἀθηναῖοι δὲ ἐκ Πάρου Μιλτιάδεα ἀπονοστήσαντα ἔσχον ἐν στόμασι οἵ τε ἄλλοι καὶ μάλιστα Ξάνθιππος ὁ Ἀρίφρονος, ὃς θανάτου ὑπαγαγὼν ὑπὸ τὸν δῆμον Μιλτιάδεα ἐδίωκε τῆς Ἀθηναίων ἀπάτης εἵνεκεν. Μιλτιάδης δὲ αὐτὸς μὲν παρεὼν οὐκ ἀπελογέετο· ἦν γὰρ ἀδύνατος ὥστε σηπομένου τοῦ μηροῦ· προκειμένου δὲ αὐτοῦ ἐν κλίνῃ ὑπεραπελογέοντο οἱ φίλοι, τῆς μάχης τε τῆς ἐν Μαραθῶνι γενομένης πολλὰ ἐπιμεμνημένοι καὶ τὴν Λήμνου αἵρεσιν, ὡς ἑλὼν Λῆμνόν τε καὶ τισάμενος τοὺς Πελασγοὺς παρέδωκε Ἀθηναίοισι. προσγενομένου δὲ τοῦ δήμου αὐτῷ κατὰ τὴν ἀπόλυσιν τοῦ θανάτου, ζημιώσαντος δὲ κατὰ τὴν ἀδικίην πεντήκοντα ταλάντοισι, Μιλτιάδης μὲν μετὰ ταῦτα σφακελίσαντός τε τοῦ μηροῦ καὶ σαπέντος τελευτᾷ, τὰ δὲ πεντήκοντα τάλαντα ἐξέτισε ὁ παῖς αὐτοῦ Κίμων.", "st": "6.136"}, {"sp": "N", "t": "Λῆμνον δὲ Μιλτιάδης ὁ Κίμωνος ὧδε ἔσχε. Πελασγοὶ ἐπείτε ἐκ τῆς Ἀττικῆς ὑπὸ Ἀθηναίων ἐξεβλήθησαν, εἴτε ὦν δὴ δικαίως εἴτε ἀδίκως· τοῦτο γὰρ οὐκ ἔχω φράσαι, πλὴν τὰ λεγόμενα, ὅτι Ἑκαταῖος μὲν ὁ Ἡγησάνδρου ἔφησε ἐν τοῖσι λόγοισι λέγων ἀδίκως· ἐπείτε γὰρ ἰδεῖν τοὺς Ἀθηναίους τὴν χώρην, τὴν σφίσι αὐτοῖσι ὑπὸ τὸν Ὑμησσὸν ἐοῦσαν ἔδοσαν Πελασγοῖσι οἰκῆσαι μισθὸν τοῦ τείχεος τοῦ περὶ τὴν ἀκρόπολιν κοτὲ ἐληλαμένου, ταύτην ὡς ἰδεῖν τοὺς Ἀθηναίους ἐξεργασμένην εὖ, τὴν πρότερον εἶναι κακήν τε καὶ τοῦ μηδενὸς ἀξίην, λαβεῖν φθόνον τε καὶ ἵμερον τῆς γῆς, καὶ οὕτω ἐξελαύνειν αὐτοὺς οὐδεμίαν ἄλλην πρόφασιν προϊσχομένους τοὺς Ἀθηναίους. ὡς δὲ αὐτοὶ Ἀθηναῖοι λέγουσι, δικαίως ἐξελάσαι. κατοικημένους γὰρ τοὺς Πελασγοὺς ὑπὸ τῷ Ὑμησσῷ, ἐνθεῦτεν ὁρμωμένους ἀδικέειν τάδε. φοιτᾶν γὰρ αἰεὶ τὰς σφετέρας θυγατέρας τε καὶ τοὺς παῖδας ἐπ’ ὕδωρ ἐπὶ τὴν Ἐννεάκρουνον· οὐ γὰρ εἶναι τοῦτον τὸν χρόνον σφίσι κω οὐδὲ τοῖσι ἄλλοισι Ἕλλησι οἰκέτας· ὅκως δὲ ἔλθοιεν αὗται, τοὺς Πελασγοὺς ὑπὸ ὕβριός τε καὶ ὀλιγωρίης βιᾶσθαι σφέας. καὶ ταῦτα μέντοι σφι οὐκ ἀποχρᾶν ποιέειν, ἀλλὰ τέλος καὶ ἐπιβουλεύοντας ἐπιχείρησιν φανῆναι ἐπ’ αὐτοφώρῳ. ἑωυτοὺς δὲ γενέσθαι τοσούτῳ ἐκείνων ἄνδρας ἀμείνονας, ὅσῳ, παρεὸν ἑωυτοῖσι ἀποκτεῖναι τοὺς Πελασγούς, ἐπεί σφεας ἔλαβον ἐπιβουλεύοντας, οὐκ ἐθελῆσαι, ἀλλά σφι προειπεῖν ἐκ τῆς γῆς ἐξιέναι. τοὺς δὲ οὕτω δὴ ἐκχωρήσαντας ἄλλα τε σχεῖν χωρία καὶ δὴ καὶ Λῆμνον. ἐκεῖνα μὲν δὴ Ἑκαταῖος ἔλεξε, ταῦτα δὲ Ἀθηναῖοι λέγουσι.", "st": "6.137"}, {"sp": "N", "t": "οἱ δὲ Πελασγοὶ οὗτοι Λῆμνον τότε νεμόμενοι καὶ βουλόμενοι τοὺς Ἀθηναίους τιμωρήσασθαι, εὖ τε ἐξεπιστάμενοι τὰς Ἀθηναίων ὁρτάς, πεντηκοντέρους κτησάμενοι ἐλόχησαν Ἀρτέμιδι ἐν Βραυρῶνι ἀγούσας ὁρτὴν τὰς τῶν Ἀθηναίων γυναῖκας, ἐνθεῦτεν δὲ ἁρπάσαντες τουτέων πολλὰς οἴχοντο ἀποπλέοντες, καί σφεας ἐς Λῆμνον ἀγαγόντες παλλακὰς εἶχον. ὡς δὲ τέκνων αὗται αἱ γυναῖκες ὑπεπλήσθησαν, γλῶσσάν τε τὴν Ἀττικὴν καὶ τρόπους τοὺς Ἀθηναίων ἐδίδασκον τοὺς παῖδας. οἳ δὲ οὔτε συμμίσγεσθαι τοῖσι ἐκ τῶν Πελασγίδων γυναικῶν παισὶ ἤθελον, εἴ τε τύπτοιτό τις αὐτῶν τινός, ἐβοήθεόν τε πάντες καὶ ἐτιμώρεον ἀλλήλοισι· καὶ δὴ καὶ ἄρχειν τε τῶν παίδων οἱ παῖδες ἐδικαίευν καὶ πολλῷ ἐπεκράτεον. μαθόντες δὲ ταῦτα οἱ Πελασγοὶ ἑωυτοῖσι λόγους ἐδίδοσαν· καί σφι βουλευομένοισι δεινόν τι ἐσέδυνε, εἰ δὴ διαγινώσκοιεν σφίσι τε βοηθέειν οἱ παῖδες πρὸς τῶν κουριδιέων γυναικῶν τοὺς παῖδας καὶ τούτων αὐτίκα ἄρχειν πειρῴατο, τί δὴ ἀνδρωθέντες δῆθεν ποιήσουσι. ἐνθαῦτα ἔδοξέ σφι κτείνειν τοὺς παῖδας τοὺς ἐκ τῶν Ἀττικέων γυναικῶν. ποιεῦσι δὴ ταῦτα, προσαπολλύουσι δὲ σφέων καὶ τὰς μητέρας. ἀπὸ τούτου δὲ τοῦ ἔργου καὶ τοῦ προτέρου τούτων, τὸ ἐργάσαντο αἱ γυναῖκες τοὺς ἅμα Θόαντι ἄνδρας σφετέρους ἀποκτείνασαι, νενόμισται ἀνὰ τὴν Ἑλλάδα τὰ σχέτλια ἔργα πάντα Λήμνια καλέεσθαι.", "st": "6.138"}, {"sp": "N", "t": "ἀποκτείνασι δὲ τοῖσι Πελασγοῖσι τοὺς σφετέρους παῖδάς τε καὶ γυναῖκας οὔτε γῆ καρπὸν ἔφερε οὔτε γυναῖκές τε καὶ ποῖμναι ὁμοίως ἔτικτον καὶ πρὸ τοῦ. πιεζόμενοι δὲ λιμῷ καὶ ἀπαιδίῃ ἐς Δελφοὺς ἔπεμπον λύσιν τινὰ αἰτησόμενοι τῶν παρεόντων κακῶν. ἡ δὲ Πυθίη σφέας ἐκέλευε Ἀθηναίοισι δίκας διδόναι ταύτας τὰς ἂν αὐτοὶ Ἀθηναῖοι δικάσωσι. ἦλθόν τε δὴ ἐς τὰς Ἀθήνας οἱ Πελασγοὶ καὶ δίκας ἐπαγγέλλοντο βουλόμενοι διδόναι παντὸς τοῦ ἀδικήματος. Ἀθηναῖοι δὲ ἐν τῷ πρυτανηίῳ κλίνην στρώσαντες ὡς εἶχον κάλλιστα καὶ τράπεζαν ἐπιπλέην ἀγαθῶν πάντων παραθέντες, ἐκέλευον τοὺς Πελασγοὺς τὴν χώρην σφίσι παραδιδόναι οὕτω ἔχουσαν. οἱ δὲ Πελασγοὶ ὑπολαβόντες εἶπαν ἐπεὰν βορέῃ ἀνέμῳ αὐτημερὸν ἐξανύσῃ νηῦς ἐκ τῆς ὑμετέρης ἐς τὴν ἡμετέρην, τότε παραδώσομεν, ἐπιστάμενοι τοῦτο εἶναι ἀδύνατον γενέσθαι. ἡ γὰρ Ἀττικὴ πρὸς νότον κεῖται πολλὸν τῆς Λήμνου.", "st": "6.139"}, {"sp": "N", "t": "τότε μὲν τοιαῦτα· ἔτεσι δὲ κάρτα πολλοῖσι ὕστερον τούτων, ὡς ἡ Χερσόνησος ἡ ἐπ’ Ἑλλησπόντῳ ἐγένετο ὑπὸ Ἀθηναίοισι, Μιλτιάδης ὁ Κίμωνος ἐτησιέων ἀνέμων κατεστηκότων νηὶ κατανύσας ἐξ Ἐλαιοῦντος τοῦ ἐν Χερσονήσῳ ἐς Λῆμνον προηγόρευε ἐξιέναι ἐκ τῆς νήσου τοῖσι Πελασγοῖσι, ἀναμιμνήσκων σφέας τὸ χρηστήριον, τὸ οὐδαμὰ ἤλπισαν σφίσι οἱ Πελασγοὶ ἐπιτελέεσθαι. Ἡφαιστιέες μέν νυν ἐπείθοντο, Μυριναῖοι δὲ οὐ συγγινωσκόμενοι εἶναι τὴν Χερσόνησον Ἀττικὴν ἐπολιορκέοντο, ἐς ὃ καὶ οὗτοι παρέστησαν. οὕτω δὴ τὴν Λῆμνον ἔσχον Ἀθηναῖοί τε καὶ Μιλτιάδης.", "st": "6.140"}], []);})();
